#if (SYSTEM_OS_TYPE == POSIX_COMPLIANT)
static eEXEC_CODE MutexTake(void)
{
    struct timespec s_timeout;
    clock_gettime(CLOCK_REALTIME, &s_timeout);
    util_TimespecAddms(&s_timeout, SEMPHORE_WAIT_DELAY);
    if(pthread_mutex_timedlock(&m_sAppDataMgrInfo.xMutex, &s_timeout) != 0)
    {
        LOG_MSG(db_ASSERT, "008 %s pthread_mutex_timedlock fail [%s]\n", __FUNCTION__ , strerror(errno));
        return eEXEC_CODE_FAIL;
    }

    return eEXEC_CODE_PASS;  //pass
}

static eEXEC_CODE MutexGive(void)
{
    if(pthread_mutex_unlock(&m_sAppDataMgrInfo.xMutex) != 0)
    {
        LOG_MSG(db_ASSERT, "%s pthread_mutex_unlock fail [%s]\n", __FUNCTION__ , strerror(errno));
        return eEXEC_CODE_FAIL;
    }

    return eEXEC_CODE_PASS;  //pass
}
#endif

