eEXEC_CODE palDataMgr_Access_Brightness(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = palDataMgr_ColorSetting_Get(eDFS_COLOR_BRIGHTNESS);
    UINT8 NewVal = *((UINT8*)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
    	*((UINT8*)pValue) = CurVal;
    }
    else  //Write Function
    {
        //Update RAM
    	palDataMgr_ColorSetting_Set(eDFS_COLOR_BRIGHTNESS, NewVal);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        	palDataMgr_ColorSetting_toEEPROM(eDFS_COLOR_BRIGHTNESS, NewVal);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palImgMgr_Brightness_Set(eSOURCE_WINDOW_MAIN, NewVal);
        }
    }

    return eEXEC_CODE_PASS;
}


