eEXEC_CODE palDataMgr_Access_SubColorSpace(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = palDataMgr_SubColorSetting_Get(eDFS_COLOR_CS);
    UINT8 NewVal = *((UINT8*)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
    	*((UINT8*)pValue) = CurVal;
    }
    else  //Write Function
    {
        //Update RAM
        palDataMgr_SubColorSetting_Set(eDFS_COLOR_CS, NewVal);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            palDataMgr_SubColorSetting_toEEPROM(eDFS_COLOR_CS, NewVal);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palImgMgr_ColorSpace_Set(eSOURCE_WINDOW_SUB, NewVal);
            palImgMgr_ConfigureColorSpace(eSOURCE_WINDOW_SUB, FALSE);
            palImgMgr_ConfigureForDisplay(eSOURCE_WINDOW_SUB,1);
        }

        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_AUTO);
        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_RGB);
        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_YUV);
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_SubColorSpaceAuto(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 ucValue = 0;
    UINT8 NewVal = *((UINT8*)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
        palDataMgr_Access_SubColorSpace(edaREAD, &ucValue);

        if(ucValue == eCM_COLOR_SPACE_AUTO)
            *((UINT8*)pValue) = ets_ON;
        else
            *((UINT8*)pValue) = ets_OFF;
    }
    else  //Write Function
    {
        //Update RAM
        ucValue = NewVal;

        if(ucValue == ets_ON)
		{
            ucValue = eCM_COLOR_SPACE_AUTO;
	    }
        else
		{
#ifdef SCALER_FPGA_F34
		    if(palImgMgr_PixModIsYUV420(eSOURCE_WINDOW_SUB, palImgMgr_InputSource_Get(eSOURCE_WINDOW_SUB)) == TRUE)
            {
                ucValue = eCM_COLOR_SPACE_YUV_REC709;
            }
            else
            {
                ucValue = eCM_COLOR_SPACE_RGB_FULL;
            }
#else
            ucValue = eCM_COLOR_SPACE_RGB_FULL;
#endif
	    }

        palDataMgr_Access_SubColorSpace(eAccessMode, &ucValue);
        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_RGB);
        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_YUV);
    }

    return eEXEC_CODE_PASS;
}


eEXEC_CODE palDataMgr_Access_SubColorSpaceRGB(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = 0;
    palDataMgr_Access_SubColorSpace(edaREAD, &CurVal);

    UINT8 NewVal = *((UINT8*)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
        //H2 wait review //need data mappings
        switch(CurVal)
        {
            case eCM_COLOR_SPACE_RGB_FULL:
                *((UINT8*)pValue) = eCS_RGB_RGB_FULL;
                break;

            case eCM_COLOR_SPACE_RGB_LIMITED:
                *((UINT8*)pValue) = eCS_RGB_RGB_VIDEO;
                break;

            default:
                *((UINT8*)pValue) = eCS_RGB_OFF;
                break;
        }

    }
    else  //Write Function
    {
        //Update RAM
        //H2 wait review //need data mappings
        UINT8 ucValue = NewVal;

        switch(NewVal)
        {
            case eCS_RGB_RGB_FULL:
                ucValue = eCM_COLOR_SPACE_RGB_FULL;
                palDataMgr_Access_SubColorSpace(eAccessMode,&ucValue); //A70LV_Larry_0406
                break;

            case eCS_RGB_RGB_VIDEO:
                ucValue = eCM_COLOR_SPACE_RGB_LIMITED;
                palDataMgr_Access_SubColorSpace(eAccessMode,&ucValue); //A70LV_Larry_0406
                break;
        }

        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_AUTO);
        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_YUV); //A70LV_Larry_0406
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_SubColorSpaceYUV(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = 0;
    palDataMgr_Access_SubColorSpace(edaREAD, &CurVal);

    UINT8 NewVal = *((UINT8*)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
        //H2 wait review //need data mappings
        switch(CurVal)
        {
            case eCM_COLOR_SPACE_YUV_REC709:
                *((UINT8*)pValue) = eCS_YUV_REC709;
                break;

            case eCM_COLOR_SPACE_YUV_REC601:
                *((UINT8*)pValue) = eCS_YUV_REC601;
                break;

            default:
                *((UINT8*)pValue) = eCS_YUV_OFF;
                break;
        }

    }
    else  //Write Function
    {
        //Update RAM
        //H2 wait review //need data mappings
        UINT8 ucValue = NewVal;

        switch(ucValue)
        {
            case eCS_YUV_REC709:
                ucValue = eCM_COLOR_SPACE_YUV_REC709;
                palDataMgr_Access_SubColorSpace(eAccessMode,&ucValue); //A70LV_Larry_0406
                break;

            case eCS_YUV_REC601:
                ucValue = eCM_COLOR_SPACE_YUV_REC601;
                palDataMgr_Access_SubColorSpace(eAccessMode,&ucValue); //A70LV_Larry_0406
                break;
        }

        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_AUTO);
        palLANProcSendToLAN(edcSUB_IMAGE_COLOR_SPACE_RGB); //A70LV_Larry_0406
    }

    return eEXEC_CODE_PASS;
}

