eEXEC_CODE palDataMgr_Access_Language(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLanguage;
    UINT8 NewVal = *((UINT8*)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = CurVal;
    }
    else  //Write Function
    {
        //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLanguage = NewVal;

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_LANGUAGE, (UINT8 *)&NewVal);

            if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag)
            {
                //#if defined(CUSTOM_CHRISTIE) || defined(CUSTOM_BARCO) //A35G2_Coda_0059
                if(sGlobalCfg.sDataCode_CFG.Language_RemoveFirstStartupFlag)
                {
                    UINT8 ucVal = (UINT8)ets_OFF;
                    m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag = ucVal;
                    utilDataMgr_CommonSet_CM(eDF_FIRSTSTARTUPFLAG, &ucVal);
                }
                //#endif
            }
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

        }
    }

    return eEXEC_CODE_PASS;
}

//G100_Owen_0006 Start
eEXEC_CODE palDataMgr_Access_SecurityTimer_TotalRemainMin(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT32 ulTotalRemainHour, ulTotalRemainDay;

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT32 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin; //H30K_Doulas_0021
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin = *((UINT32*)pValue);

		m_sAppDataMgrInfo.sSystemValues.ucSecurityPollCount = 0;// HICC2_Bruce_0016
        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_SECURITY_TOTALREMAINMIN, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            ulTotalRemainHour = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin / 60;
            m_sAppDataMgrInfo.sSystemValues.ucSecurityHour = ulTotalRemainHour % 24;
            ulTotalRemainDay = ulTotalRemainHour / 24;
            m_sAppDataMgrInfo.sSystemValues.ucSecurityDay = ulTotalRemainDay % 30;
            m_sAppDataMgrInfo.sSystemValues.ucSecurityMonth = ulTotalRemainDay / 30;

			palLANProcSendToLAN(edcSECURITY_TIMER_MONTH);// HICC2_Bruce_0016
			palLANProcSendToLAN(edcSECURITY_TIMER_DAY);// HICC2_Bruce_0016
			palLANProcSendToLAN(edcSECURITY_TIMER_HOUR);// HICC2_Bruce_0016

            if((m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPINProtect == ets_ON) &&
                (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin == 0))
            {
                UINT8 ucValue = ePASSWORD_PROTECT_LOCKED;

                if(palDataMgr_CurTestPatternGet() != eTID_OFF)
                {
                    UINT8 ucTP = eTID_OFF;
                    palDataMgr_Access_ServiceTestPattern(edaWRITE_THROUGH_WITH_ACTION, &ucTP) ;
                    palLANProcSendToLAN((UINT16)edcSERVICE_TEST_PATTERN);
                }

                palDataMgr_UI_EventSend(edcUI_EVENT_PIN_PROTECT_ENABLE, TRUE, NULL);
                palDataMgr_Access_System_Protect_Status(edaWRITE_RAM_ONLY_NO_ACTION, &ucValue);

                #ifdef SCALER_C341
                uPALIMGMGR_INFO uInfo = {.sConfig_NoSignalOutput.eWindow = eSOURCE_WINDOW_MAIN,
                                         .sConfig_NoSignalOutput.ucDisplayOutput = TRUE};
                palImgMgr_Config_NoSignalOutput(&uInfo);
                uInfo .sConfig_NoSignalOutput.eWindow = eSOURCE_WINDOW_SUB;
                palImgMgr_Config_NoSignalOutput(&uInfo);
                #endif
            }
        }
    }

    return eEXEC_CODE_PASS;
}

