void palDataMgr_SecurityTimer_Poll(void)// HICC2_Bruce_0016
{
	if( ++m_sAppDataMgrInfo.sSystemValues.ucSecurityPollCount >= 60 )
	{
        if((m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPINProtect == ets_ON) &&
            (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin > 0))
        {
            LOG_MSG(db_APP_ILLUMINATION, "%s()[%d]\n", __func__, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin);
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin -= 1;
            palDataMgr_Data_Access(edcSECURITY_TIMER, edaWRITE_THROUGH_WITH_ACTION, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ulSecurity_TotalRemainMin);
        }
		m_sAppDataMgrInfo.sSystemValues.ucSecurityPollCount = 0;
	}
}
