eEXEC_CODE palDataMgr_Access_Real_DateTime(eDATA_ACCESS_MODE eAccessMode, void *pValue) //G100_Coda_0038
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        UINT16 uwYear;
        UINT8 ucMonth;
        UINT8 ucDay;
        UINT8 ucHour;
        UINT8 ucMinute;

        char aucVerString[64];
        time_t sTime;
        struct tm *sTemp;

        time(&sTime);
        sTemp = localtime(&sTime);

        uwYear = (1900 + sTemp->tm_year);  //start at 1900 year
        ucMonth = (1 + sTemp->tm_mon);     //start at 0-11 month
        ucDay = sTemp->tm_mday;            //start at 01-31 day
        ucHour = sTemp->tm_hour;
        ucMinute = sTemp->tm_min;

        sprintf(aucVerString, "%04d / %02d / %02d    %02d : %02d",
                uwYear, ucMonth, ucDay,
                ucHour,
                ucMinute);
        memcpy((UINT8 *)pValue, aucVerString, strlen(aucVerString)+1);
    }
    else  //Write Function
    {
        palLANProcSendToLAN(edcSCHEDULE_VIEW_TODAY);
    }

    return eEXEC_CODE_PASS;
}


