eEXEC_CODE palDataMgr_Access_TestPattern(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucFactoryTestPattern;  //A70LV_Doulas_0024
    }
    else  //Write Function
    {
        UINT8 NewVal = *((UINT8*)pValue);                                                   //HICC2_Doulas_0093
        eTEST_PATTERN_ID eTP_ID = CommonAPI_TestPatternIDGet(edcFACTORY_TEST_PATTERN, NewVal);   //HICC2_Doulas_0093
        eEXE_TP_RESULT eRet = palDataMgr_TestPatternHandle(eTP_ID);                         //HICC2_Doulas_0093

        if(eRet != eEXE_TP_PASS)    //HICC2_Doulas_0093
        {
            return eEXEC_CODE_FAIL;
        }


        //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucFactoryTestPattern = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        //    EE_PUTVAR(sUserSystemSetting.sCommonSetting.ucFactoryTestPattern, *((UINT8*)pValue)); //A70LV_Doulas_0035
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            //LOG_MSG(db_ALWAYS, "palDataMgr_Access_TestPattern = %d\r\n",*((UINT8*)pValue));//HICC2_Doulas_0093
#if defined(PLATFORM_A70LK) || defined(PLATFORM_H60_4K)     //HICC2_Doulas_0093
        	if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucFactoryTestPattern == eCM_FACTORY_TP_ACTUATOR) &&
               ((palDataPath_PanelConfigGet() == eWAPRING_AP_GROUP_4K3D) || (palDataPath_PanelConfigGet() == eWAPRING_AP_GROUP_4K3D_DUALPIPE))) //HICC2_Casper_0022
            {
                palFormatterMgr_TestPattern(eCM_FACTORY_TP_NONE); //HICC2_Casper_0022
                halScaler_PixelShiftCalPattern_Set(1);
                halScaler_PixSftModSet(0);
            }
            else
            {
                palFormatterMgr_TestPattern(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucFactoryTestPattern);
                eWAPRING_AP_GROUP ePanelId = palDataPath_PanelConfigGet();


    			if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucFactoryTestPattern == eCM_FACTORY_TP_NONE)	//A70LK_Doulas_0018 //HICC2_Casper_0022
    			{
                    halScaler_PixelShiftCalPattern_Set(0);

    				if(ePanelId != eWAPRING_AP_GROUP_2D)
    		        {
                        if(ePanelId == eWAPRING_AP_GROUP_4K3D)
                        {
                            halScaler_PixSftModSet(0);
                        }
                        else if(ePanelId == eWAPRING_AP_GROUP_4K3D_DUALPIPE)
                        {
                            halScaler_PixSftModSet(0);
                        }
                        else
                        {
                            if(ePanelId == eWAPRING_AP_GROUP_3D)
                            {
                                palFormatterMgr_XPR_Set(eXPR_OFF_4WAY_120);
                            }
                            else if(ePanelId == eWAPRING_AP_GROUP_HIGH_SPEED)
                            {
                                palFormatterMgr_XPR_Set(eXPR_OFF_4WAY_240);
                            }
                            else
                            {
                                palFormatterMgr_XPR_Set(eXPR_ON);
                            }

                            halScaler_PixSftModSet(1);
                        }
    		        }
    			}
                else
                {
                    if(ePanelId == eWAPRING_AP_GROUP_4K3D)
                    {
                    }
                    else if(ePanelId == eWAPRING_AP_GROUP_4K3D_DUALPIPE)
                    {
                    }
                    else
                    {
                        halScaler_PixSftModSet(1);
                    }
                }
            }
#else
            palFormatterMgr_TestPattern(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucFactoryTestPattern);
#endif
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_PowerOffset(eDATA_ACCESS_MODE eAccessMode, void *pValue) //T100_Casper_0003
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        if (m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPOWER_OFFSET > POWER_OFFSET_MAX) //ZU860_John_0001 add power offset protection
        {
            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPOWER_OFFSET = POWER_OFFSET_DEFAULT;
        }

        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPOWER_OFFSET;
    }
    else  //Write Function
    {
        //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPOWER_OFFSET = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_POWER_OFFSET, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucPowerNum = CONSTANT_POWER_NUMBER_MAX_VALUE;

        #if  defined(CUSTOM_BARCO)||defined(CUSTOM_OPTOMA) //A35G2_Coda_0043
            if(eCM_POWER_MODE_CONSTANT_POWER == m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucPowerMode)
            {
                ucPowerNum = CONSTANT_POWER_NUMBER_MAX_VALUE;
            }
            else
            {
                ucPowerNum = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain;
            }
        #else
            ucPowerNum = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain;
        #endif

            palDataMgr_LightSource_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucPowerMode,ucPowerNum);
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_DimmingModeCheck(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //HICC2_Doulas_0088//T100_Casper_0004
{
    eEXEC_CODE eExecResult = eEXEC_CODE_PASS;

    if (edaREAD == eAccessMode)  //Read Function
  	{
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sSystemValues.ucDimPower;
    }
    else  //Write Function
    {
    	//UINT8 ucDimMode = *((UINT8*)pValue);
	    UINT8 ucDimModePower = *((UINT8*)pValue);
		UINT8 ucPoowerMode = eCM_POWER_MODE_CUSTOM_MODE;
		UINT8 ucDynamicBlack = ets_OFF;
		UINT8 ucRealBlack = ets_OFF;

    #ifdef OE_JIG
        m_sAppDataMgrInfo.sSystemValues.ucDimPower = DIM_POWER_NUMBER_DEFAULT_VALUE;
    #else
        LOG_MSG(db_APP_MONITOR, "palDataMgr_Access_DimmingModeCheck = %d (%d %d)\r\n" , *((UINT8*)pValue), m_DimNum, m_sAppDataMgrInfo.sSystemValues.ucDimPowerFlag) ; //HICC2_Doulas_0090//HICC2_Doulas_0088

		if((ucDimModePower != DIM_POWER_NUMBER_DEFAULT_VALUE) &&
		   (ucDimModePower < m_DimNum)) //HICC2_Doulas_0090
		{
		    m_sAppDataMgrInfo.sSystemValues.ucDimPower = ucDimModePower ;
            halFormatter_DimPower_Set(TRUE, m_sAppDataMgrInfo.sSystemValues.ucDimPower, FALSE);
            m_DimNum = m_sAppDataMgrInfo.sSystemValues.ucDimPower;  //HICC2_Doulas_0088
            m_sAppDataMgrInfo.sSystemValues.ucDimPowerFlag = 1;
            LOG_MSG(db_APP_MONITOR, "DimPowerFlag On\r\n") ;
		}

		palDataMgr_Data_Access(edcDYNAMIC_BLACK, edaREAD, &ucDynamicBlack);
		palDataMgr_Data_Access(edcREAL_BLACK, edaREAD, &ucRealBlack);

		LOG_MSG(db_APP_MONITOR, "ucDimModePower = %d\r\n",  ucDimModePower) ;
		LOG_MSG(db_APP_MONITOR, "ucDynamicBlack = %d, ucRealBlack = %d\r\n", ucDynamicBlack, ucRealBlack) ;
		LOG_MSG(db_APP_MONITOR, "current power mode = %d\r\n",	 m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucPowerMode) ;

		if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucPowerMode != eCM_POWER_MODE_ECO2)
        {
            m_DimNum = ucDimModePower;
			LOG_MSG(db_APP_MONITOR, "m_DimNum = %d\r\n", m_DimNum) ;

			if(ucDynamicBlack == ets_ON)
            {
            	ucDynamicBlack = ets_OFF;
				palDataMgr_Access_Dynamic_Black(edaWRITE_RAM_ONLY_WITH_ACTION, &ucDynamicBlack);
            }

            if(ucRealBlack == ets_ON)
            {
            	ucRealBlack = ets_OFF;
				palDataMgr_Access_Real_Black(edaWRITE_RAM_ONLY_WITH_ACTION, &ucDynamicBlack);
            }

			palDataMgr_Access_PowerMode(edaWRITE_RAM_ONLY_WITH_ACTION, &ucPoowerMode);
			palDataMgr_Access_ConstantPower(edaWRITE_RAM_ONLY_WITH_ACTION, &m_DimNum);
        }
	#endif
    }

	return eExecResult;
}

eEXEC_CODE palDataMgr_Access_ColorOffset(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
		if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucCOLOR_OFFSET < CCT_MIN_VALUE ||
			m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucCOLOR_OFFSET > CCT_MAX_VALUE)
		{
			m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucCOLOR_OFFSET = CCT_DEFAULT_VALUE; // 避免超出設定值造成畫面顏色問題
		}
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucCOLOR_OFFSET;
    }
    else  //Write Function
    {
        //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucCOLOR_OFFSET = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_COLOR_OFFSET, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palFormatterMgr_ColorOffsetSet(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucCOLOR_OFFSET);
            palDataMgr_Formatter_Parameter_Set(FALSE);
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_ConstantPower(eDATA_ACCESS_MODE eAccessMode, void *pValue)     //A70LV_Doulas_0024
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        if((m_sAppDataMgrInfo.sSystemValues.ucDimPowerFlag) &&
           (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain >= m_DimNum)) //HICC2_Doulas_0088
        {
            *((UINT8 *)pValue) = m_DimNum;
        }
        else
        {
            *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain;
        }
    }
    else  //Write Function
    {
        if((*((UINT8*)pValue) < CONSTANT_POWER_NUMBER_MIN_VALUE) ||
           (*((UINT8*)pValue) > CONSTANT_POWER_NUMBER_MAX_VALUE))      //A70LV_Doulas_0141 check range
        {
            return eEXEC_CODE_FAIL;
        }

        //Update Ram
        if((m_sAppDataMgrInfo.sSystemValues.ucDimPowerFlag) && (*((UINT8*)pValue) >= m_DimNum))   //HICC2_Doulas_0088
        {
            //m_DimNum = 80;  //HICC2_Doulas_0088
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain = m_DimNum; //H2PF_Simon_0068
        }
        else
        {
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain = *((UINT8*)pValue);
        }

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //EE_PUTVAR(sUserSystemSetting.sLightSetting.ucWaveformGain, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_WAVEFORMGAIN, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            if((m_sAppDataMgrInfo.sSystemValues.ucDimPowerFlag) && (*((UINT8*)pValue) >= m_DimNum))   //HICC2_Doulas_0088
            {
                palDataMgr_LightSource_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucPowerMode,
                                           m_DimNum);
            }
            else
            {
                UINT8 ucPowerNum = CONSTANT_POWER_NUMBER_MAX_VALUE;

            #if defined(CUSTOM_BARCO) || defined(CUSTOM_OPTOMA)  //A35G2_Coda_0043
                if(eCM_POWER_MODE_CONSTANT_POWER == m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucPowerMode)
                {
                    ucPowerNum = CONSTANT_POWER_NUMBER_MAX_VALUE;
                }
                else
                {
                    ucPowerNum = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain;
                }
            #else
                ucPowerNum = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucWaveformGain;
            #endif

                palDataMgr_LightSource_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucPowerMode,ucPowerNum);
            }
			palLANProcSendToLAN(edcINFO_LIGHT_SOURCE_POWER); //A70LV_Larry_0262
			palLANProcSendToLAN(edcCONSTANT_BRIGHTNESS); //H30K_Wesley_0005
			palDataMgr_OPDSnapshot(eOPD_LIGHT_SOURCE_LOG); //A70Gen2_Julie_0047
		}
    }

    return eEXEC_CODE_PASS;
}


eEXEC_CODE palDataMgr_Access_Burnin_Enable(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable;
    }
    else  //Write Function  //A70LV_Larry_0261 modify
    {
		UINT8 ucEnable = *((UINT8*)pValue);
		if(ucEnable > 2)// HICC2_Bruce_0009 // 2: Always Lamp On
		{
            ucEnable = ets_ON;
		}

        //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable = ucEnable;

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_BURNINENABLE, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            //Add action function for burn in function
            if (m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable)
            {
                if(m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle != 0)
                {
                    //send burn in enable event to F-Mcu

                    UINT16 uiConstantPower = CONSTANT_POWER_NUMBER_MAX_VALUE;
                    UINT8  ucPowertMode = eCM_POWER_MODE_CONSTANT_POWER;
                    UINT8  ucValue = ets_OFF;
					UINT8  ucStandbyPowerMode = eCM_STANDBY_MODE_COMMUNICATION;

                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucKeypadLock) //H30K_Doulas_0014 keypad lock enable
                    {
                        palDataMgr_Access_KeypadLock(edaWRITE_RAM_ONLY_WITH_ACTION, &ucValue);
                        palLANProcSendToLAN(edcKEYPAD_LOCK);
                    }
                    //trigger burn in function(draw test pattern)
                    halMCU_Auto_Power_On_Tmer_Set(m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff);
    			#ifdef PLATFORM_H30_4K
    				halMCU_Auto_Burn_In_Parameter_Set();
    			#endif
                    palDataPath_BurnInStart();        //A70LV_Doulas_0023
                    palIllumination_BurnIn_Count_Start(
                    m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable,
                    m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn,
                    m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle);

                    palDataMgr_Access_ConstantPower(edaWRITE_THROUGH_NO_ACTION, &uiConstantPower); //A70LV_Larry_0084
                    palDataMgr_Access_PowerMode(edaWRITE_THROUGH_WITH_ACTION, &ucPowertMode); //A70LV_Larry_0084
                    palDataMgr_UI_EventSend(edcUI_EVENT_BURNIN_PATTERN_UPDATE, TRUE, NULL);

    			#if defined(CUSTOM_BARCO)
                    palIllumination_TEC_Gating_InfoClean();//G100_Steven_0084
    			#endif

                    if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag)
        			{
        				UINT8 ucVal = (UINT8)ets_OFF;
        				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag = ucVal;
        				//EE_PUTVAR(sSystemDefault.ucFirstStartupFlag, ucVal);

                        utilDataMgr_CommonSet_CM(eDF_FIRSTSTARTUPFLAG, &ucVal);
        			}

                    if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucUSTFirstStartup)
                    {
                        UINT8 ucVal = (UINT8)ets_OFF;
                        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucUSTFirstStartup = ucVal;
                        utilDataMgr_CommonSet_CM(eDF_USTFIRSTSTARTUP, &ucVal);
                    }
					palDataMgr_Access_Energy_Saving(edaWRITE_THROUGH_WITH_ACTION, &ucValue);
					palDataMgr_Access_StandbyMode(edaWRITE_THROUGH_WITH_ACTION, &ucStandbyPowerMode);

                }
            }
            else
            {
                halMCU_Auto_Power_On_Set(ucEnable) ;
                palIllumination_BurnIn_Count_Stop();
                palDataPath_Resync();
            }
        }

        palLANProcSendToLAN(edcBURN_IN_STATE);
    }

    return eEXEC_CODE_PASS;
}


