eEXEC_CODE palDataMgr_ModelNameGet_Depend_SN_Rule(char *ModelName, UINT32 ModelID)
{
    UINT8 ucSN[32] = {0};
    UINT8 ProjectorID[9] = {0};
    UINT32 Index = 0;
    palDataMgr_Data_Access(edcSERIAL_NUMBER, edaREAD, ucSN);
    palDataMgr_Data_Access(edcCUSTOMER_CODE, edaREAD, ProjectorID);
    Index = CommonData_ModelNameTable_IndexGet(ProjectorID);
    if(Index >= CommonData_ModelNameTable_SizeGet())
    {
        LOG_MSG(db_ALWAYS, "!!!ModelNameTableIndex error %d (%s)\n", Index, ProjectorID);
        return eEXEC_CODE_FAIL;
    }

    eCOUNTRY_ORIGIN ModelRegion = eCOUNTRY_ORIGIN_WW;

    #ifdef PLATFORM_A35G2
    {
        if(ModelID == MODULE_TYPE_ID0_PLATFORM)
        {
            if(ucSN[3] == 'F') //LC2Cyywwxxx : 4th word : C CHINA //A35G2_CDS_Coda_0017
            {
                ModelRegion = eCOUNTRY_ORIGIN_CHINA;
            }
            else if(ucSN[3] == 'B' || ucSN[3] == 'A') //LC2Tyywwxxx : 4th word : T TWN
            {
                ModelRegion = eCOUNTRY_ORIGIN_TWN;
            }
            else
            {
                ModelRegion = eCOUNTRY_ORIGIN_WW;
            }
        }
        else if(ModelID == MODULE_TYPE_ID1_PLATFORM)
        {
            if(ucSN[3] == 'D') //LC2Cyywwxxx : 4th word : C CHINA  //A35G2_CDS_Coda_0017
            {
                ModelRegion = eCOUNTRY_ORIGIN_CHINA;
            }
            else if(ucSN[3] == 'A') //LC2Tyywwxxx : 4th word : T TWN
            {
                ModelRegion = eCOUNTRY_ORIGIN_TWN;
            }
            else
            {
                ModelRegion = eCOUNTRY_ORIGIN_WW;
            }
        }
        else if(ModelID == MODULE_TYPE_ID2_PLATFORM)
        {
            if(ucSN[3] == 'D') //LV2Cyywwxxx : 4th word : C CHINA
            {
                ModelRegion = eCOUNTRY_ORIGIN_CHINA;
            }
            else if(ucSN[3] == 'A') //LV2Tyywwxxx : 4th word : T TWN
            {
                ModelRegion = eCOUNTRY_ORIGIN_TWN;
            }
            else
            {
                ModelRegion = eCOUNTRY_ORIGIN_WW;
            }
        }
        else
        {
            LOG_MSG(db_ALWAYS, "!!! (%s@%d)unknown ModelID %d\n", ModelID, __FUNCTION__, __LINE__);
        }
    }
    #elif defined (PLATFORM_A70G2)
    {
        if(ucSN[3] == 'A') //LC2Cyywwxxx : 4th word : C CHINA //A35G2_CDS_Coda_0017
        {
            ModelRegion = eCOUNTRY_ORIGIN_CHINA;
        }
        else if(ucSN[3] == 'N') //LC2Tyywwxxx : 4th word : T TWN
        {
            ModelRegion = eCOUNTRY_ORIGIN_TWN;
        }
        else
        {
            ModelRegion = eCOUNTRY_ORIGIN_WW;
        }
    }
    #elif defined (PLATFORM_H60_2K) || defined (PLATFORM_H60_4K) || defined (PLATFORM_A70LK)  || defined (PLATFORM_H30_4K)  //HICC2_Doulas_0022
    {
        if(ucSN[3] == 'C') //U24Cyywwxxx : 4th word : C CHINA
        {
            ModelRegion = eCOUNTRY_ORIGIN_CHINA;
        }
        else if(ucSN[3] == 'N') //U24Nyywwxxx : 4th word : N TAA
        {
            ModelRegion = eCOUNTRY_ORIGIN_TWN;
        }
        else
        {
            ModelRegion = eCOUNTRY_ORIGIN_WW;
        }
    }
    #else
    LOG_MSG(db_ALWAYS, "Undefined SN rule for Model Name\n");
    #endif

    switch(ModelRegion)
    {
        case eCOUNTRY_ORIGIN_WW:
        default:
            snprintf(ModelName, MODEL_NAME_MAX_STR_LEN, "%s", ModelNameString[Index][eMN_MODEL_NAME]);
            break;

        case eCOUNTRY_ORIGIN_CHINA:
            snprintf(ModelName, MODEL_NAME_MAX_STR_LEN, "%s", ModelNameString[Index][eMN_CHINA_REGION_NAME]);
            break;

        case eCOUNTRY_ORIGIN_TWN:
            snprintf(ModelName, MODEL_NAME_MAX_STR_LEN, "%s", ModelNameString[Index][eMN_TWN_REGION_NAME]);
            break;
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_ModelNameGet_Depend_Neutral(char *ModelName)
{
    eMODEL_SWITCH_INDEX SwitchModel = eMODEL_SWITCH_DEFAULT;
    palDataMgr_Access_Model_Switch_Adjust(edaREAD, &SwitchModel);

    UINT8 ProjectorID[9] = {0};
    UINT32 Index = 0;
    palDataMgr_Data_Access(edcCUSTOMER_CODE, edaREAD, ProjectorID);
    Index = CommonData_ModelNameTable_IndexGet(ProjectorID);
    if(Index >= CommonData_ModelNameTable_SizeGet())
    {
        LOG_MSG(db_ALWAYS, "!!! ModelNameTableIndex error %d\n", Index);
        return eEXEC_CODE_FAIL;
    }

    switch(SwitchModel)
    {
        case eMODEL_SWITCH_DEFAULT:
        default:
            snprintf(ModelName, MODEL_NAME_MAX_STR_LEN, "%s", ModelNameString[Index][eMN_MODEL_NAME]);
            break;

        case eMODEL_SWITCH_NEUTRAL:
            snprintf(ModelName, MODEL_NAME_MAX_STR_LEN, "%s", ModelNameString[Index][eMN_NEUTRAL_NAME]);
            break;
    }

    return eEXEC_CODE_PASS;
}

