//T100_Sander_0005
eEXEC_CODE palDataMgr_Access_MODEL_NAME(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
#ifdef DEMO_SNDS   //HICC2_Doulas_0021
        char aucString[16];
        sprintf(aucString, "Generic");
        memcpy((UINT8 *)pValue, aucString, strlen(aucString)+1);
#elif  defined(OE_JIG)  //HICC2_Doulas_0034
        char aucString[16];
        #if defined(PLATFORM_H60_4K)      //HICC2_Doulas_0096
        sprintf(aucString, "H60K(OE_JIG)");
        #elif defined(PLATFORM_H30_4K) //HICC2_AC_0001
        sprintf(aucString, "H30K(OE_JIG)");
        #elif defined(PLATFORM_R70K)                        //HICC2_Tim_0001, add
        sprintf(aucString, "R70K(OE_JIG)");               //HICC2_Tim_0001, add
        #else
        sprintf(aucString, "H60U(OE_JIG)");
        #endif
        memcpy((UINT8 *)pValue, aucString, strlen(aucString)+1);
#else
        UINT8 uclens = strlen(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucModelName)+1;

        memcpy((UINT8 *)pValue, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucModelName, uclens);
#endif
    }
    else  //Write Function
    {
        UINT8 cModel = *((UINT8*)pValue);
        char acString[32] = {'\0'};
        UINT8 cSwitchModel = eMODEL_SWITCH_DEFAULT;//A35G2_Coda_0063

        if((palSystem_ModelIDGet() - MODEL_ID_0) >= Syscfg_Value_Get_Typeint(eModelID_Max))
        {
            LOG_MSG(db_ALWAYS, "(func:%s,line:%d) Model ID %d is exceed eModelID_Max %d\n",__FUNCTION__, __LINE__, palSystem_ModelIDGet(), Syscfg_Value_Get_Typeint(eModelID_Max));
            //未知版本直接return, 不改model name, 避免opfu失敗導致不能更新
            return eEXEC_CODE_PASS;
        }

        if(cModel == MODULE_NA_PLATFORM)
        {
            //未知版本直接return, 不改model name, 避免opfu失敗導致不能更新
            return eEXEC_CODE_PASS;
        }
        else
        {
            if(Syscfg_Value_Get_Typeint(eModelName_AlwaysNeutral) == TRUE)
            {
                palDataMgr_ModelNameGet_Neutral(acString);
            }
            else if(Syscfg_Value_Get_Typeint(eModelName_DependSN) == TRUE)
            {
                palDataMgr_ModelNameGet_Depend_SN_Rule(acString, cModel);
            }
            else if(Syscfg_Value_Get_Typeint(eModelName_DependNeutral) == TRUE)
            {
                palDataMgr_ModelNameGet_Depend_Neutral(acString);
            }
            else
            {
                palDataMgr_ModelNameGet_Normal(acString);
            }
        }

        if(strlen(acString) < MODEL_NAME_MAX_STR_LEN)
        {
            if(strncmp(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucModelName, acString, strlen(acString)) != 0)
            {
                //Storage : EEPROM
                if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
                {
                    memset(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucModelName, '\0', MODEL_NAME_MAX_LENGTH);
                    memcpy((char*)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucModelName, acString, strlen(acString));
                    utilDataMgr_CommonSet_CM(eDF_MODELNAME, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucModelName);
                }

            }

            halFrontEndCtrl_Model_Name_Set(acString); //A35G2_CDS_Coda_0032
        }
    }

    return eEXEC_CODE_PASS;
}

