eEXEC_CODE palDataMgr_Access_Customer_Code(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        UINT8 uclens = strlen(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucCustomCode)+1;

        memcpy((UINT8 *)pValue, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucCustomCode, uclens);
    }
    else  //Write Function
    {
        UINT8 cModel = *((UINT8*)pValue);
        char acString[32] = {'\0'};

		#if 1 //Depends on X35Gen2 design
		Board_MCU_ModelID_Set(cModel);
		#endif

        //Platform ID
        PLATFORM_ID_INDEX PlatformID = palDataMgr_Platform_ID_Get();
        snprintf(&acString[0], 3, "%02X", PlatformID);

        //Customer ID
        CUSTOMER_ID_INDEX CustomerID = CFG_CUSTOMER_ID;
        snprintf(&acString[2], 3, "%02X", CustomerID);

        //Model ID
        MODEL_ID_INDEX ModelID = palSystem_ModelIDGet();
        snprintf(&acString[4], 3, "%02X", ModelID);

        snprintf(&acString[6], 3, "00");
        LOG_MSG(db_APP_SYSTEM, "\nProject ID %s %02X %02X %02X\n", acString, PlatformID, CustomerID, ModelID); //HICC2_Doulas_0083 Modify


        if((palSystem_ModelIDGet() - MODEL_ID_0) >= Syscfg_Value_Get_Typeint(eModelID_Max))
        {
            //未知版本直接return, 不改Customer code, 避免opfu失敗導致不能更新
            LOG_MSG(db_ALWAYS, "(func:%s,line:%d) Model ID %d is exceed eModelID_Max %d\n",__FUNCTION__, __LINE__, palSystem_ModelIDGet(), Syscfg_Value_Get_Typeint(eModelID_Max));
            return eEXEC_CODE_PASS;
        }


        if(strlen(acString) < MODEL_NAME_MAX_LENGTH)
        {
            if(strncmp(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucCustomCode, acString, strlen(acString)) != 0)
            {
                //Storage : EEPROM
                if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
                {
                    memset(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucCustomCode, '\0', MODEL_NAME_MAX_LENGTH);
                    memcpy((char*)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucCustomCode, acString, strlen(acString)+1);
                    utilDataMgr_CommonSet_CM(eDF_CUSTOM_CODE, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucCustomCode);
                }

            }
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_SMCU_VERSION(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{

    if (edaREAD == eAccessMode)  //Read Function
    {
        char aucVerString[VERSION_STRING_MAX_LENGTH];

        if(sGlobalCfg.sDataCode_CFG.SMCU_Version_Type == eDATACODE_SMCU_VERSION_IS_ISCALER_VERSION)
        {
            if(Board_Stage_Get() <= EVT_STAGE)
            {
                sprintf(aucVerString, "V%02d.%02d.beta", VER_MAJOR, VER_MINOR);
            }
            else
            {
                sprintf(aucVerString, "V%02d.%02d", VER_MAJOR, VER_MINOR);
            }
            memcpy((UINT8 *)pValue, aucVerString, strlen(aucVerString)+1);
        }
        else if(sGlobalCfg.sDataCode_CFG.SMCU_Version_Type == eDATACODE_SMCU_VERSION_IS_LD_CONVERT_VERSION)
        {
            memcpy((UINT8 *)pValue, m_sAppDataMgrInfo.sSystemValues.sVERSION.m_LD_ConvertVersion, 8);//A70LV_Larry_0031
        }
    }
    else  //Write Function
    {
        if(sGlobalCfg.sDataCode_CFG.SMCU_Version_Type == eDATACODE_SMCU_VERSION_IS_ISCALER_VERSION)
        {
            return eEXEC_CODE_FAIL;
        }
        else if(sGlobalCfg.sDataCode_CFG.SMCU_Version_Type == eDATACODE_SMCU_VERSION_IS_LD_CONVERT_VERSION)
        {
            if(edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode) //A70LV_Larry_0031
            {
               memcpy(m_sAppDataMgrInfo.sSystemValues.sVERSION.m_LD_ConvertVersion, (UINT8 *)pValue, 8);
            }
        }
        else
        {
            return eEXEC_CODE_FAIL;
        }

    }

    return eEXEC_CODE_PASS;
}

