eEXEC_CODE palDataMgr_Access_Thermal_Sensor_Info(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        sprintf(((char *)pValue), "%d C" , m_sAppDataMgrInfo.sSystemValues.sTHERMAL_SENSOR_INFO.iThermalSensorTemperature[0]);
    }
    else  //Write Function
    {
        if(edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode)
        {
            UINT8 ThermalSensorNum = Syscfg_Value_Get_Typeint(eTS_INFO_Num_defined_in_MCU);
            UINT8 ucIndex = 0;

            for(ucIndex = 0 ; ucIndex < ThermalSensorNum ; ucIndex++)
            {
                memcpy(&m_sAppDataMgrInfo.sSystemValues.sTHERMAL_SENSOR_INFO.iThermalSensorTemperature[ucIndex], (UINT16 *)pValue+ucIndex, sizeof(UINT16));
            }
        }
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }

    return eEXEC_CODE_PASS;
}

//T100_Sander_0008 //A70LV_Larry_0033
void palDataMgr_Access_Get_Thermal_Sensor_Info(UINT8 ucIndex, void *pValue)
{
	char ucTemperatureString[127];

    if( Syscfg_Value_Get_Typeint(eDC_ThermalSensorWithFloat) == 1 )
    {
        sprintf(ucTemperatureString, "%d.%02d C",
                m_sAppDataMgrInfo.sSystemValues.sTHERMAL_SENSOR_INFO.iThermalSensorTemperature[ucIndex]/100,
                m_sAppDataMgrInfo.sSystemValues.sTHERMAL_SENSOR_INFO.iThermalSensorTemperature[ucIndex]%100);
        memcpy((UINT8 *)pValue, ucTemperatureString, strlen(ucTemperatureString)+1);
    }
    else
    {
    	sprintf(ucTemperatureString, "%d C",
    	        m_sAppDataMgrInfo.sSystemValues.sTHERMAL_SENSOR_INFO.iThermalSensorTemperature[ucIndex]);
    	memcpy((UINT8 *)pValue, ucTemperatureString, strlen(ucTemperatureString)+1);
    }

	return;
}

//A70LV_Larry_0033
void palDataMgr_Access_Set_Thermal_Sensor_Info(UINT8 ucIndex, void *pValue)
{
    UINT8 *pcData = (UINT8*)pValue;

    UINT16 uiTemperature = (UINT16)pcData[1]<<8 | (UINT16)pcData[0];

	m_sAppDataMgrInfo.sSystemValues.sTHERMAL_SENSOR_INFO.iThermalSensorTemperature[ucIndex] = (INT16)uiTemperature;
	return;
}

