eEXEC_CODE palDataMgr_Access_LD_Info(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        //read and reply
        //UINT8 ucIndex = 0 ;
        memcpy((UINT8 *)pValue,                                   m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Voltage,       (sizeof(UINT16)*MAX_LD_SW_PORT));
        memcpy((UINT8 *)pValue + (sizeof(UINT16)*MAX_LD_SW_PORT),    m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Current,    (sizeof(UINT16)*MAX_LD_SW_PORT));
        memcpy((UINT8 *)pValue + (sizeof(UINT16)*MAX_LD_SW_PORT*2),  m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLDTemperature, (sizeof(UINT16)*MAX_LD_SW_PORT));

    }
    else  //Write Function
    {
        if(edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode)
        {
            UINT8 ucIndex = 0 ;
            //LOG_MSG(db_ALWAYS, "palDataMgr_LD_Info_Num_Get() = %d\n",palDataMgr_LD_Info_Num_Get());
            //for(ucIndex = 0 ; ucIndex < palDataMgr_LD_Info_Num_Get() ; ucIndex++)
            {
                memcpy(m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Voltage,       (UINT8 *)pValue                                    , (sizeof(UINT16)*MAX_LD_SW_PORT));
                memcpy(m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Current,       (UINT8 *)pValue+(sizeof(UINT16)*MAX_LD_SW_PORT)    , (sizeof(UINT16)*MAX_LD_SW_PORT));
                memcpy(m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLDTemperature,    (UINT8 *)pValue+(sizeof(UINT16)*MAX_LD_SW_PORT*2)  , (sizeof(UINT16)*MAX_LD_SW_PORT));
            }
        }
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }

    return eEXEC_CODE_PASS;
}

//T100_Sander_0008
void palDataMgr_Access_Get_LD_Info(UINT8 ucIndex,  void *pValue) //A70LV_Larry_0030
{
	char 	ucLDString[127];
	UINT16 	uiTemp[2] ={ 0};
	//UINT8 	ucTempIndex = 0; //HICC2_Doulas_0042
	INT16 	iTemp = 0;

	if(Drivercfg_Value_Get(palSystem_ModelIDGet(),eLD_Exist,ucIndex) != DEVICE_IS_EXIST)//(ucIndex >=8 ) //HICC2_Doulas_0002 Modify
	{
		sprintf(ucLDString, "NA");
	}
	else
	{
		uiTemp[0] = m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Voltage[ucIndex];
		uiTemp[1] = m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Current[ucIndex];
		iTemp = m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLDTemperature[ucIndex]; //HICC2_Doulas_0042 Modify

		sprintf(ucLDString, "%02d.%02dV, %01d.%03dA, %02d.%02dT" ,
				uiTemp[0]/100,
				uiTemp[0]%100,
				uiTemp[1]/1000,
				uiTemp[1]%1000,
				iTemp/100,
				iTemp%100);
	} //G100_Steven_0049 end
	memcpy((UINT8 *)pValue, ucLDString, strlen(ucLDString)+1);
    return;
}

void palDataMgr_Access_Set_LD_Info(UINT8 ucIndex,  void *pValue) //A70LV_Larry_0030
{
    UINT8 *pcData = (UINT8*)pValue;
	UINT16 	uiVoltage;
	UINT16 	uiCurrent;
	UINT16 	uiTemperature;


    uiVoltage =     (UINT16)pcData[1]<<8 | (UINT16)pcData[0];
    uiCurrent =     (UINT16)pcData[3]<<8 | (UINT16)pcData[2];
    uiTemperature = (UINT16)pcData[5]<<8 | (UINT16)pcData[4];

	m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Voltage[ucIndex] = uiVoltage;
	m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLD_Current[ucIndex] = uiCurrent;
	m_sAppDataMgrInfo.sSystemValues.sLD_INFO.uiLDTemperature[ucIndex] = (INT16)uiTemperature;

    return;
}

