eEXEC_CODE palDataMgr_Access_DigitalHorzZoom(eDATA_ACCESS_MODE eAccessMode, void *pValue)   //A70LV_Doulas_0130 modify
{
    UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
    UINT8  ucAspectRatio = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucAspectRatio;   //A70LV_Doulas_0021
    UINT8  ucProportional = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucDigitalZoomProp;    //G100_Owen_0028

    if (edaREAD == eAccessMode)  //Read Function
    {
        if(ucAspectRatio == eCM_SCALING_MODE_CUSTOM)
            *((UINT16*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom;
        else
            *((UINT16*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom;
    }
    else  //Write Function
    {
        UINT16 uiOldVAlue;
        //Update RAM
        if(ucAspectRatio == eCM_SCALING_MODE_CUSTOM)    //A70LV_Doulas_0117 modify
        {
            uiOldVAlue = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom;
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom = *((UINT16*)pValue);
        }
        else
        {
            uiOldVAlue = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom;
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom = *((UINT16*)pValue);
        }

        if(ucProportional == ets_ON)    //G100_Owen_0028
        {
            INT32 iMax = 0, iMin = 0;
            INT16 iDiff = 0;
            UINT16 uiValue;

            if(ucAspectRatio == eCM_SCALING_MODE_CUSTOM)    //A70LV_Doulas_0117 modify
            {
                iDiff = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom - uiOldVAlue;
            }
            else
            {
                iDiff = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom - uiOldVAlue;
            }

            palDataMgr_Data_Access(edcDIGITAL_VERT_ZOOM, edaREAD, &uiValue);
            if((eEXEC_CODE_PASS == palDataMgr_Data_Range_Get(edcDIGITAL_VERT_ZOOM, edrMAX, &iMax)) &&
               (eEXEC_CODE_PASS == palDataMgr_Data_Range_Get(edcDIGITAL_VERT_ZOOM, edrMIN, &iMin)))
            {
                if((iMax >= (uiValue + iDiff)) && ((uiValue + iDiff) >= iMin))
                {
                    uiValue += iDiff;
                    palDataMgr_DigitalZoomProportional_Execute(edcDIGITAL_VERT_ZOOM, eAccessMode, &uiValue);
                }
                else
                {
                    if(ucAspectRatio == eCM_SCALING_MODE_CUSTOM)    //A70LV_Doulas_0117 modify
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom = uiOldVAlue;
                    }
                    else
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom = uiOldVAlue;
                    }

                    return eEXEC_CODE_FAIL;
                }
            }
            else
            {
                if(ucAspectRatio == eCM_SCALING_MODE_CUSTOM)    //A70LV_Doulas_0117 modify
                {
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom = uiOldVAlue;
                }
                else
                {
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom = uiOldVAlue;
                }

                return eEXEC_CODE_FAIL;
            }
        }

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //if(uiOldVAlue != *((UINT16*)pValue) )    //A70LV_Doulas_0117 vaule change //A35G2_BRC_Casper_0081
            {
                //UINT8 ucGuiSrc = (UINT8)CM2GUI(edcMAIN_INPUT, ucInputSource);
                if(ucAspectRatio == eCM_SCALING_MODE_CUSTOM)
                {
                    utilDataMgr_SourceColorSet_CM(eDFS_CUSTOMDIGITALHORZZOOM, ucInputSource, 0, (UINT8*)pValue);
                }
                else
                {
                    utilDataMgr_SourceColorSet_CM(eDFS_DIGITALHORZZOOM, ucInputSource, 0, (UINT8*)pValue);
                }
            }
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            if(ucAspectRatio == eCM_SCALING_MODE_CUSTOM)
                palDataPath_Digital_Horz_Zoom_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom);   //A70LV_Doulas_0030
            else
                palDataPath_Digital_Horz_Zoom_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom);
        }

        palLANProcSendToLAN(edcHORZ_POSITION);  //G100_Simon_0020
        palLANProcSendToLAN(edcVERT_POSITION);
        palLANProcSendToLAN(edcDIGITAL_HORZ_ZOOM);
        palLANProcSendToLAN(edcDIGITAL_VERT_ZOOM);
        palLANProcSendToLAN(edcDIGITAL_HORZ_SHIFT);
        palLANProcSendToLAN(edcDIGITAL_VERT_SHIFT);
        palLANProcSendToLAN(edcMAIN_ASPECT_RATIO);
    }

    return eEXEC_CODE_PASS;
}

