eEXEC_CODE palDataMgr_Access_DigitalZoomReset(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //G100_Owen_0011
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = ets_OFF;
    }
    else  //Write Function
    {
        UINT8 ucValue;
        INT32 iValue;

        ucValue = ets_OFF;
        palDataMgr_Access_DigitalZoom_Proportional(edaWRITE_THROUGH_WITH_ACTION, &ucValue);

        iValue = DIGITAL_HORZ_ZOOM_DEFAULT;
        palDataMgr_Access_DigitalHorzZoom(edaWRITE_THROUGH_WITH_ACTION, &iValue);

        iValue = DIGITAL_VERT_ZOOM_DEFAULT;
        palDataMgr_Access_DigitalVertZoom(edaWRITE_THROUGH_WITH_ACTION, &iValue);

        ucValue = DIGITAL_HORZ_SHIFT_DEFAULT;
        palDataMgr_Access_DigitalHorzShift(edaWRITE_THROUGH_WITH_ACTION, &ucValue);

        ucValue = DIGITAL_VERT_SHIFT_DEFAULT;
        palDataMgr_Access_DigitalVertShift(edaWRITE_THROUGH_WITH_ACTION, &ucValue);

        palDataMgr_Data_Range_Get(edcDIGITAL_ZOOM_PROPORTIONAL, edrDEFAULT, &iValue);
        palDataMgr_Access_DigitalZoom_Proportional(edaWRITE_THROUGH_WITH_ACTION, &iValue);

        palLANProcSendToLAN(edcDIGITAL_HORZ_ZOOM);
        palLANProcSendToLAN(edcDIGITAL_VERT_ZOOM);
        palLANProcSendToLAN(edcDIGITAL_HORZ_SHIFT);
        palLANProcSendToLAN(edcDIGITAL_VERT_SHIFT);
        palLANProcSendToLAN(edcDIGITAL_ZOOM_PROPORTIONAL); //G100_Simon_0021
        palLANProcSendToLAN(edcMAIN_ASPECT_RATIO);

    }
    return eEXEC_CODE_PASS; //HICC2_Doulas_0068
}

