eEXEC_CODE palDataMgr_Access_HorzPincushion(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzPincushion;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzPincushion = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_WARPHORZPINCUSHION, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucValue = (UINT8)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzPincushion; //A70LV_Larry_0053

            palGeo_H_PINBARREL_Set(ucValue);

#ifdef CUSTOM_CHRISTIE
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting != 0)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting = 0; //Warp memory set to "Off"
                utilDataMgr_CommonSet_CM(eDF_WARPINGAPPLYSETTING, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting);
                palLANProcSendToLAN(edcWARP_MEMORY_APPLY);
            }

            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpControl != WARP_CTRL__BASIC)
            {
                UINT8 ucData = (UINT8)WARP_CTRL__BASIC;
                palDataMgr_AccessADV_WarpControl(edaWRITE_THROUGH_NO_ACTION, &ucData);
                palLANProcSendToLAN(edcADV_WARP_CONTROL);
            }
#endif
        }
    }

    return eEXEC_CODE_PASS;
}

