eEXEC_CODE palDataMgr_Access_ForcePictureSettings(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
    UINT8  ucSignalType = palDataMgr_SignalType_Get();      //A70LV_Doulas_0119

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode;
    }
    else  //Write Function
    {
        UINT8 ucOldPictureMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode;   //A70LV_Doulas_0119
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode = *((UINT8*)pValue);

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucSourceKeyOption = eSOURCE_KEY_CHANGE_SOURCE;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucSourceLock = ets_ON;

        LOG_MSG(db_HAL_WARPING, "Force Picture Setting %d\n", *((UINT8*)pValue));

        if(ucOldPictureMode == eCM_PICTURE_SETTINGS_3D ||
           ucOldPictureMode == eCM_PICTURE_SETTINGS_3D_PASSIVE ||
           ucOldPictureMode == eCM_PICTURE_SETTINGS_2DHIGHSPEED ||
          (ucOldPictureMode == eCM_PICTURE_SETTINGS_USER &&
           (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode == eCM_PICTURE_SETTINGS_2DHIGHSPEED ||
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode == eCM_PICTURE_SETTINGS_3D ||
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode == eCM_PICTURE_SETTINGS_3D_PASSIVE))) //HICC2_Doulas_0065
        {
            //暫時解，twist link時，keep high speed mode
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode = ucOldPictureMode;
        }

        //#ifdef CUSTOM_CHRISTIE//HICC2_Julie_0011
        #if 0// R70K_Bruce_0065
        if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode != ucOldPictureMode) &&
           (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode != eCM_PICTURE_SETTINGS_USER))
        {
            UINT8 ucPresetMode = *((UINT8*)pValue);

            memcpy(&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sColorSetting[ucInputSource][ucPresetMode][ucSignalType],
                   &m_sDefSysSettings.sUserSystemSetting.sColorSetting[ucInputSource][ucPresetMode][ucSignalType], sizeof(sCOLOR_SETTING));

            memcpy(&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode],
                   &m_sDefSysSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode], sizeof(sHSG_SETTING));

            #if 0
            if(palImgMgr_PIP_PBP_Enable_Get())
            {
                palDataMgr_SubColorSetting_Set(eDFS_COLOR_BRIGHTNESS, m_sDefSysSettings.sUserSystemSetting.sColorSetting[m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub][ucPresetMode][ucSignalType].ucBrightness);
                palDataMgr_SubColorSetting_Set(eDFS_COLOR_CONTRAST, m_sDefSysSettings.sUserSystemSetting.sColorSetting[m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub][ucPresetMode][ucSignalType].ucContrast);
                palDataMgr_SubColorSetting_Set(eDFS_COLOR_CS, m_sDefSysSettings.sUserSystemSetting.sColorSetting[m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub][ucPresetMode][ucSignalType].ucCS);

                if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
                {
                    palDataMgr_SubColorSetting_toEEPROM(eDFS_COLOR_BRIGHTNESS, palDataMgr_SubColorSetting_Get(eDFS_COLOR_BRIGHTNESS));
                    palDataMgr_SubColorSetting_toEEPROM(eDFS_COLOR_CONTRAST, palDataMgr_SubColorSetting_Get(eDFS_COLOR_CONTRAST));
                    palDataMgr_SubColorSetting_toEEPROM(eDFS_COLOR_CS, palDataMgr_SubColorSetting_Get(eDFS_COLOR_CS));
                }

                if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
                {
                    palImgMgr_Brightness_Set(eSOURCE_WINDOW_SUB, palDataMgr_SubColorSetting_Get(eDFS_COLOR_BRIGHTNESS));
                    palImgMgr_Contrast_Set(eSOURCE_WINDOW_SUB, palDataMgr_SubColorSetting_Get(eDFS_COLOR_CONTRAST));
                    palImgMgr_ColorSpace_Set(eSOURCE_WINDOW_SUB, palDataMgr_SubColorSetting_Get(eDFS_COLOR_CS));
                }
            }
            #endif

            palDataMgr_Scaler_EEPROM_Iint();
        }
        #endif

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            UINT8 ucPresetMode = *((UINT8*)pValue);

            utilDataMgr_SourceColorSet_CM(eDFS_PRESETMODE, ucInputSource, 0, &ucPresetMode);

            utilDataMgr_CommonSet_CM(eDF_SOURCEKEYOPTION, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucSourceKeyOption);
            utilDataMgr_CommonSet_CM(eDF_SOURCELOCK, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucSourceLock);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucValue = 0;

            palImgMgr_PictureSettings_Set(eSOURCE_WINDOW_MAIN,m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode);

        #ifdef ENABLE_GO_BACK_TO_LAST_MODE                  //H30K_Tim_0006, add, ***
            palDataMgr_Last_Display_Mode_Set(ucInputSource, ucOldPictureMode);
        #endif //ENABLE_GO_BACK_TO_LAST_MODE                //H30K_Tim_0006, add, &&&

            palDataMgr_Formatter_Parameter_Set(TRUE);

            UINT8 ucPictureSetting = *((UINT8*)pValue);
            UINT8 ucUserModePicSetting = eCM_PICTURE_SETTINGS_BRIGHT;
            UINT8 ucPowerMode = 0 ;
            palDataMgr_Access_Apply_User_Mode(edaREAD, &ucUserModePicSetting);
            palDataMgr_Access_PowerMode(edaREAD, &ucPowerMode);
			palLDMgr_Fan_Mode_Set(ucPowerMode, ucPictureSetting, ucUserModePicSetting);	//G100_Clare_0011, add   //H2 wait review

            #ifndef CUSTOM_CHRISTIE
			if((ucOldPictureMode != *((UINT8*)pValue)) &&
		        (eCM_PICTURE_SETTINGS_USER == *((UINT8*)pValue)))		//G100_Doulas_0066 Modify
        	{
        	//	m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode = ucOldPictureMode;
            #ifdef ENABLE_SINGLE_USER_MODE                  //H30K_Tim_0005, add, ***
                ucOldPictureMode = eCM_PICTURE_SETTINGS_USER;
            #endif //ENABLE_SINGLE_USER_MODE                //H30K_Tim_0005, add, &&&
				palDataMgr_Access_Apply_User_Mode(edaWRITE_THROUGH_WITH_ACTION,&ucOldPictureMode);
        	}
        	#endif

            if((palDataPath_GetDataPathState() >= eDATA_PATH_STATE_ATTEMPT_LOCK)
                &&(palDataPath_GetDataPathState() <= eDATA_PATH_STATE_MONITOR_SOURCE))
            {
                palDataPath_Reconfig_Image();
                palDataPath_Reconfig_ImageSub();    //A70LV_Doulas_0213 CH2 set
            }
            else
            {
                palDataMgr_Format_Normal_Set();  //A35G2_CDS_Simon_0016
            }

            //palDataMgr_Access_HDRAutoEnable(edaREAD, &ucValue);							//G100_Doulas_0046 remove
            //LOG_MSG(db_ALWAYS, "HDR On %d \r\n", ucValue);
            //palDataMgr_Access_HDRAutoEnable(edaWRITE_RAM_ONLY_WITH_ACTION, &ucValue);		//G100_Doulas_0046 remove

            palLANProcSendToLAN(edcPICTURE_SETTINGS);  //H2PF_Simon_0028
			palLANProcSendToLAN(edcTINT);
			palLANProcSendToLAN(edcCOLOR);
            palLANProcSendToLAN(edcDETAIL);
			palLANProcSendToLAN(edcSKIN_COLOR);
			palLANProcSendToLAN(edcBRIGHTNESS);
			palLANProcSendToLAN(edcCONTRAST);
			palLANProcSendToLAN(edcRED_GAIN);
			palLANProcSendToLAN(edcGREEN_GAIN);
			palLANProcSendToLAN(edcBLUE_GAIN);
			palLANProcSendToLAN(edcRED_OFFSET);
			palLANProcSendToLAN(edcGREEN_OFFSET);
			palLANProcSendToLAN(edcBLUE_OFFSET);
			palLANProcSendToLAN(edcCOLOR_ENHANCEMENT);
			palLANProcSendToLAN(edcWHITE_PEAKING);
			palLANProcSendToLAN(edcGAMMA);
			palLANProcSendToLAN(edcCOLOR_TEMPERATURE);
			palLANProcSendToLAN(edcHSG_RED_HUE);
			palLANProcSendToLAN(edcHSG_RED_SATURATION);
			palLANProcSendToLAN(edcHSG_RED_GAIN);
			palLANProcSendToLAN(edcHSG_GREEN_HUE);
			palLANProcSendToLAN(edcHSG_GREEN_SATURATION);
			palLANProcSendToLAN(edcHSG_GREEN_GAIN);
			palLANProcSendToLAN(edcHSG_BLUE_HUE);
			palLANProcSendToLAN(edcHSG_BLUE_SATURATION);
			palLANProcSendToLAN(edcHSG_BLUE_GAIN);
			palLANProcSendToLAN(edcHSG_CYAN_HUE);
			palLANProcSendToLAN(edcHSG_CYAN_SATURATION);
			palLANProcSendToLAN(edcHSG_CYAN_GAIN);
			palLANProcSendToLAN(edcHSG_MAGENTA_HUE);
			palLANProcSendToLAN(edcHSG_MAGENTA_SATURATION);
			palLANProcSendToLAN(edcHSG_MAGENTA_GAIN);
			palLANProcSendToLAN(edcHSG_YELLOW_HUE);
			palLANProcSendToLAN(edcHSG_YELLOW_SATURATION);
			palLANProcSendToLAN(edcHSG_YELLOW_GAIN);
			palLANProcSendToLAN(edcHSG_WHITE_GAIN_RED);
			palLANProcSendToLAN(edcHSG_WHITE_GAIN_GREEN);
			palLANProcSendToLAN(edcHSG_WHITE_GAIN_BLUE);
			palLANProcSendToLAN(edcUSER_COLOR_MODE); //G100_Steven_0030
			palLANProcSendToLAN(edcCOLOR_SPACE);	//G100_Doulas_0086
            palLANProcSendToLAN(edcCOLOR_SPACE_AUTO); //HICC2_Simon_0002
            palLANProcSendToLAN(edcCOLOR_SPACE_RGB);
            palLANProcSendToLAN(edcCOLOR_SPACE_YUV);
			palLANProcSendToLAN(edcWALL_COLOR);		//G100_Doulas_0086
            palLANProcSendToLAN(edcINPUT_KEY);
            palLANProcSendToLAN(edcSOURCE_LOCK);
            palLANProcSendToLAN(edcSAVE_TO_USER);
        }
    }

    return eEXEC_CODE_PASS;
}


eEXEC_CODE palDataMgr_Access_SaveToUser(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
    UINT8  ucValue = 0;
    UINT16 iVal = 0; //G100_Steven_0020

    if (edaREAD == eAccessMode)  //Read Function
    {
        ucValue = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucSavePreset;
        *((UINT8*)pValue) = ucValue & 0x01;
    }
    else  //Write Function
    {
        //Update RAM
        ucValue = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucSavePreset;
        ucValue = (ucValue & 0xFE) + 1;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucSavePreset = ucValue;
//G100_Steven_0038
        if(eCM_PICTURE_SETTINGS_USER != m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode)
        {
        	palDataMgr_CopyUserColorSetting();
        	//LOG_MSG(db_ALWAYS, "\n SaveToUser 555 \n");
        }
        else
        {
        	//LOG_MSG(db_ALWAYS, "\n SaveToUser 111 \n");
        }

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //EE_PUTVAR(sUserSystemSetting.sSourceDependSetting[ucInputSource].ucSavePreset, ucValue);
        	UINT8 ucColorMode = eCM_PICTURE_SETTINGS_USER; //G100_Steven_0030
            //UINT8 ucGuiSrc = (UINT8)CM2GUI(edcMAIN_INPUT, ucInputSource);

            utilDataMgr_SourceColorSet_CM(eDFS_SAVEPRESET, ucInputSource, 0, (UINT8*)pValue);
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode = ucColorMode; //G100_Steven_0030
            //ucColorMode = CM2GUI(edcPICTURE_SETTINGS, ucColorMode); //G100_Steven_0030
            utilDataMgr_SourceColorSet_CM(eDFS_PRESETMODE, ucInputSource, 0, &ucColorMode); //G100_Steven_0030

            palDataMgr_SaveUserColorSettingToEEPROM();
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palDataMgr_Scaler_EEPROM_Iint();
            palLANProcSendToLAN(edcUSER_COLOR_MODE); //G100_Steven_0030
            palLANProcSendToLAN(edcPICTURE_SETTINGS);	//G100_Doulas_0087
        }
    }

    return eEXEC_CODE_PASS;
}

