eEXEC_CODE palDataMgr_Access_ContrastEnhancement(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement = *((UINT8*)pValue);

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_CONTRASTENHANCEMENT, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palImgMgr_ContrastEnhancement_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement);
            palDataPath_Format_ContrastEnhancementSet(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement,
                                                      m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucLightsOutSignalLevel);    //A70LV_Doulas_0046

            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement == eCONTRAST_ENHANCE_REAL_BLACK) //A70LV_Larry_0236
            {
                halFormatter_LightsOutTimerSet(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucLightsOutTimer);
                halFormatter_DISP_BlackLevelThresholdSet(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucLightsOnThreshold);	//A70LK_Simon_0014
            }
        }
        palLANProcSendToLAN(edcDYNAMIC_BLACK);  //HICC2_Doulas_0028
        palLANProcSendToLAN(edcREAL_BLACK);     //HICC2_Doulas_0028
    }

    return eEXEC_CODE_PASS;
}

