eEXEC_CODE palDataMgr_Access_HDR_Gamma(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //H2PF_Simon_0193
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma;
    }
    else  //Write Function
    {
        UINT8 ucOldVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma;

        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma = *((UINT8*)pValue);

        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_HDR_GAMMA, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

#ifdef SCALER_FPGA_F34

            UINT8 ucHDRDetect = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDREnable;
            UINT8 ucHDRMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode;
            UINT16 uiHDRNit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final;
            UINT16 uiHDRNitDisplay[1] = {0};
            UINT16 uiHDRMaxLimit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit;

            if(CFG_CUSTOMER_ID == CUSTOMER_ID_FUJIFILM) //HICC2_AC_0103
            {
                if((palDataPath_IsSourceLock()) && (palImgMgr_Input_3D_Format_Get() == ets_OFF) &&
                    (palImgMgr_HDR_Get(eSOURCE_WINDOW_MAIN) == eHDR_SETTING_HDR))
                {
                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_SDR_CUSTOM)
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_HDR;
                    }

                    if(ucHDRMode == eCM_HDR_AUTO)
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Display;
                        UINT16 uiHDRNit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final;

                        palDataPath_New_HDR10_Set(ucHDRDetect, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma, ucHDRMode, uiHDRNit, uiHDRMaxLimit);
                    }
                    else
                    {
                        UINT16 uiHDRNit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final;

                        palDataPath_New_HDR10_Set(ucHDRDetect, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma, ucHDRMode, uiHDRNit, uiHDRMaxLimit);
                    }
                }
                else if((palDataPath_IsSourceLock()) && (palImgMgr_Input_3D_Format_Get() == ets_OFF) &&
                    (palImgMgr_HDR_Get(eSOURCE_WINDOW_MAIN) == eHDR_SETTING_SDR))
                {
                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma != eCM_SDR_CUSTOM)
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_SDR_CUSTOM;
                    }

                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_SDR_CUSTOM)
                    {
                        switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Dynamic_Contrast)
                        {
                            case ets_OFF:
                            {
                                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit = 1000;
                            }
                            break;

                            case ets_ON:
                            {
                                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit = 10000;
                            }
                            break;

                            default:
                                break;
                        }

                        palDataPath_New_HDR10_Set(ucHDRDetect, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode, 1000, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit);
                    }
                }
            }
            else
            {
                if((palDataPath_IsSourceLock()) && (palSystem_PanelID_Get() == PANEL_2D_OUTPUT) && (palImgMgr_Input_3D_Format_Get() == ets_OFF) &&
                    (palImgMgr_HDR_Get(eSOURCE_WINDOW_MAIN) == eHDR_SETTING_HDR))
                {
                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_SDR_CUSTOM)
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_HDR;
                    }

                    if(ucHDRMode == eCM_HDR_AUTO)
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Display;
                        UINT16 uiHDRNit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final;

                        palDataPath_New_HDR10_Set(ucHDRDetect, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma, ucHDRMode, uiHDRNit, uiHDRMaxLimit);
                    }
                    else
                    {
                        UINT16 uiHDRNit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final;

                        palDataPath_New_HDR10_Set(ucHDRDetect, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma, ucHDRMode, uiHDRNit, uiHDRMaxLimit);
                    }
                }
                else if((palDataPath_IsSourceLock()) && (palSystem_PanelID_Get() == PANEL_2D_OUTPUT) && (palImgMgr_Input_3D_Format_Get() == ets_OFF) &&
                    (palImgMgr_HDR_Get(eSOURCE_WINDOW_MAIN) == eHDR_SETTING_SDR))
                {
                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma != eCM_SDR_CUSTOM)
                    {
                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_SDR_CUSTOM;
                    }

                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma == eCM_SDR_CUSTOM)
                    {
                        switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Dynamic_Contrast)
                        {
                            case ets_OFF:
                            {
                                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit = 1000;
                            }
                            break;

                            case ets_ON:
                            {
                                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit = 10000;
                            }
                            break;

                            default:
                                break;
                        }

                        palDataPath_New_HDR10_Set(ucHDRDetect, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode, 1000, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit);
                    }
                }
            }

#endif /* SCALER_FPGA_F34 */

        }
        palLANProcSendToLAN(edcHDR_DYNAMIC_CONTRAST);
        palLANProcSendToLAN(edcHDR_MODE);
        palLANProcSendToLAN(edcHDR_MANUAL_LEVEL_NIT);
        palLANProcSendToLAN(edcHDR_MANUAL_CUSTOM_NIT);
    }
    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HDR_Dynamic_Contrast(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //H2PF_Simon_0193
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Dynamic_Contrast;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Dynamic_Contrast = *((UINT8*)pValue);

        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_HDR10_DYNAMIC_CONTRAST, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

#ifdef SCALER_FPGA_F34

            UINT8 ucHDRDetect = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDREnable;
            UINT8 ucHDRGamma = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma;
            UINT8 ucHDRMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode;
            UINT16 uiHDRNit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final;

            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Dynamic_Contrast == ets_OFF && ucHDRGamma == eCM_SDR_CUSTOM)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit = 1000;
            }
            else if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Dynamic_Contrast == ets_ON && ucHDRGamma == eCM_SDR_CUSTOM)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit = 10000;
            }

            if((palDataPath_IsSourceLock()) && (palSystem_PanelID_Get() == PANEL_2D_OUTPUT) && (palImgMgr_Input_3D_Format_Get() == ets_OFF))
            {
                palDataPath_New_HDR10_Set(ucHDRDetect, ucHDRGamma, ucHDRMode, uiHDRNit, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit);
            }
#elif defined(SCALER_C341) /* SCALER_FPGA_F34 */
            {
                if(palDataPath_HDR_Info_Get() == eHDR_SETTING_SDR)
                {
                    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Dynamic_Contrast)  //SDR Enhance
                    {
                        halScaler_SDREnhance_Process();
                    }
                    else
                    {
                        halScaler_HDR_Disable();
                    }
                }

            }
#endif
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HDR_Mode(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //H2PF_Simon_0193
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode = *((UINT8*)pValue);

        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_HDR10_MODE, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

            UINT8 ucHDRDetect = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDREnable;
            UINT8 ucHDRGamma = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma;
            UINT16 uiHDRMaxLimit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit;

            if((palDataPath_IsSourceLock()) && (palSystem_PanelID_Get() == PANEL_2D_OUTPUT) && (palImgMgr_Input_3D_Format_Get() == ets_OFF))

            {
                UINT16 uiHDRNitDisplay[1] = {0};

                if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode == eCM_HDR_AUTO)
                {
                    palImgMgr_HdrMaxMasteringLuminanceGet(uiHDRNitDisplay);
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Display = uiHDRNitDisplay[0];
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = uiHDRNitDisplay[0];
                    palImg_HDR_Set(ucHDRDetect, ucHDRGamma, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode, uiHDRNitDisplay[0], uiHDRMaxLimit);
                }
                else
                {
                    switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level)
                    {
                        case eCM_HDR_500_NIT:
                        {
                            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 500;
                        }
                        break;
                        case eCM_HDR_1000_NIT:
                        {
                            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 1000;
                        }
                        break;
                        case eCM_HDR_2000_NIT:
                        {
                            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 2000;
                        }
                        break;
                        case eCM_HDR_4000_NIT:
                        {
                            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 4000;
                        }
                        break;
                        case eCM_HDR_CUSTOM_NIT:
                        {
                            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Custom_Nit;
                        }
                        break;

                        default:
                        break;
                    }
                    UINT16 uiHDRNit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final;
                    utilDataMgr_CommonSet_CM(eDF_HDR10_FINAL_NIT, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final);

                    palImg_HDR_Set(ucHDRDetect, ucHDRGamma, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode, uiHDRNit, uiHDRMaxLimit);
                }
            }

        }
        palLANProcSendToLAN(edcHDR_MANUAL_LEVEL_NIT);
        palLANProcSendToLAN(edcHDR_MANUAL_CUSTOM_NIT);

    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HDR_Manual_Level(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //H2PF_Simon_0193
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level = *((UINT8*)pValue);

        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_HDR10_MANUAL_LEVEL, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

#ifdef SCALER_FPGA_F34

            UINT8 ucHDRDetect = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDREnable;
            UINT8 ucHDRGamma = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Gamma;
            UINT8 ucHDRMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Mode;
            UINT16 uiHDRMaxLimit = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_MaxLimit;

            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level == eCM_HDR_500_NIT && ucHDRMode != eCM_HDR_AUTO)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 500;
            }
            else if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level == eCM_HDR_1000_NIT && ucHDRMode != eCM_HDR_AUTO)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 1000;
            }
            else if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level == eCM_HDR_2000_NIT && ucHDRMode != eCM_HDR_AUTO)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 2000;
            }
            else if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level == eCM_HDR_4000_NIT && ucHDRMode != eCM_HDR_AUTO)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = 4000;
            }
            else if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDR_Manual_Level == eCM_HDR_CUSTOM_NIT && ucHDRMode != eCM_HDR_AUTO)
            {
                 m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Custom_Nit;
            }

            utilDataMgr_CommonSet_CM(eDF_HDR10_FINAL_NIT, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final);

            if((palDataPath_IsSourceLock()) && (palSystem_PanelID_Get() == PANEL_2D_OUTPUT) && (palImgMgr_Input_3D_Format_Get() == ets_OFF))
            {
                palDataPath_New_HDR10_Set(ucHDRDetect, ucHDRGamma, ucHDRMode, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.uiHDR_Nit_Final, uiHDRMaxLimit);
            }
#endif /* SCALER_FPGA_F34 */
        }

        palLANProcSendToLAN(edcHDR_MANUAL_CUSTOM_NIT);
    }

    return eEXEC_CODE_PASS;
}

