eEXEC_CODE palDataMgr_Access_ImageFreeze(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucImageFreeze;
    }
    else  //Write Function
    {
        //Update RAM
        UINT8 ucOldValue = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucImageFreeze;   //A70LV_Doulas_0227

        if( utilWarp_GetOsdPatternType() != PAT_TYPE__OFF )
        {
            return eEXEC_CODE_FAIL;
        }

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucImageFreeze = *((UINT8*)pValue);
        //GuiCb.fpGui_Send_OSD_ExitCb();     //A70LV_Doulas_0164 remove//A70LV_Doulas_0139 close menu

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        //    EE_PUTVAR(sUserSystemSetting.sImageSetting.ucImageFreeze, *((UINT8*)pValue));
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palImgMgr_ImageFreeze_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucImageFreeze);
            if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucImageFreeze == ets_OFF) &&
               (ucOldValue == ets_ON))//A70LV_Doulas_0227 modify//A70LV_Doulas_0167 Add
            {
                UINT8 uc3D_Enable = eCM_3D_FORMAT_OFF;
                palDataMgr_Access_3DEnable(edaREAD, &uc3D_Enable);          //A70LV_Doulas_0277

                if((palImgMgr_Input_3D_Format_Config_Get() != eINPUT_3D_TYPE_OFF) ||
                    ((eCM_3D_FORMAT_OFF != uc3D_Enable) && (eCM_3D_FORMAT_AUTO != uc3D_Enable)))
                {
                    palDataMgr_Formatter_3D_Set();
                }

                palLANProcSendToLAN(edcIMAGE_FREEZE); //HICC2_Doulas_0053
                palDataMgr_UI_EventSend(edcUI_EVENT_OPEN_FREEZE_MENU_MSG, TRUE, NULL); //A70LV_Larry_0151

                MS_SLEEP(100);     //A70LV_Doulas_0227
            }
			else if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucImageFreeze == ets_ON) &&
                    (ucOldValue == ets_OFF))	//G100_Doulas_0092
			{
                UINT8 uc3D_Enable = eCM_3D_FORMAT_OFF;
                UINT8 ucFreeze_Message = eSOURCE_MESSAGE_FREEZE; //HICC2_Doulas_0053
                palDataMgr_Access_3DEnable(edaREAD, &uc3D_Enable);          //A70LV_Doulas_0277

                if((palImgMgr_Input_3D_Format_Config_Get() != eINPUT_3D_TYPE_OFF) ||
                    ((eCM_3D_FORMAT_OFF != uc3D_Enable) && (eCM_3D_FORMAT_AUTO != uc3D_Enable)))
                {
                    #ifdef SCALER_FPGA_F34 //HICC2_Doulas_0116
                    halFormatter_3D_3DModeSet(FALSE);
                    #else
                    palDataPath_Set3D_FirstFrameMode(); //HICC2_Doulas_0114
                    #endif
                }

                palDataMgr_Access_SUPPORT_MESSAGE(edaWRITE_THROUGH_WITH_ACTION,&ucFreeze_Message); //HICC2_Doulas_0053
                palLANProcSendToLAN(edcSUPPORT_MESSAGE); //HICC2_Doulas_0053

				palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);
			}
        }
    }

    return eEXEC_CODE_PASS;
}

