        *((UINT8 *)pValue+1) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPassWord[1];
        *((UINT8 *)pValue+2) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPassWord[2];
        *((UINT8 *)pValue+3) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucPassWord[3];
