        //m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sNetworkSetting.ucDHCP = *((UINT8*)pValue);

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sNetworkSetting.ucShowNetworkMessages = 1;

        //Storage : EEPROM
