eEXEC_CODE palDataMgr_Access_HSGAutoTestPatternWhite(eDATA_ACCESS_MODE eAccessMode, void *pValue) //G100_Coda_00109
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern_2;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern_2 = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //EE_PUTVAR(sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_HSGADJUSTMENTAUTOTESTPATTERN_2, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
        //    palImgMgr_HSGAutoTestPattern_Set(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern);
        }

#if 0 //###
		if(GuiCb.fpGui_IsCustom_White_NextMenu_L3Cb() == TRUE) //Move to appgui.c
        {
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern_2 == ets_ON)
            {
                GuiCb.fpGui_IsHSG_TestPattern_ON_Custom_White_NextMenu_L3Cb(); //Move to appgui.c
            }
            else
            {
                GuiCb.fpGui_IsHSG_TestPattern_OFF_Custom_White_NextMenu_L3Cb(); //Move to appgui.c
            }
        }
#endif
    }

    return eEXEC_CODE_PASS;
}


