                ucVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode].HSG_G_SAT;
                break;

        	case eDFS_HSG_G_GAIN:
                ucVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode].HSG_G_GAIN;
                break;

        	case eDFS_HSG_B_HUE:
        		ucVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode].HSG_B_HUE;
                break;

        	case eDFS_HSG_B_SAT:
                ucVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode].HSG_B_SAT;
                break;

        	case eDFS_HSG_B_GAIN:
                ucVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode].HSG_B_GAIN;
                break;

        	case eDFS_HSG_C_HUE:
        		ucVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode].HSG_C_HUE;
                break;

        	case eDFS_HSG_C_SAT:
