eEXEC_CODE palDataMgr_Access_HSGSelected(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected;
    }
    else  //Write Function
    {
        UINT8 OldVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected; //HICC2_Doulas_0139
        UINT8 NewVal = *((UINT8*)pValue); //HICC2_Casper_0026
        eTEST_PATTERN_ID eTP_ID = eTID_HSG_RED + NewVal; //HICC2_Casper_0026
        eEXE_TP_RESULT eRet = eEXE_TP_INVALID; //HICC2_Casper_0026
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_HSGSELECTED, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            //if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern == ets_ON) //HICC2_Doulas_0051        //T100_Doulas_0024
            //{
            //palDataMgr_UI_EventSend(edcUI_EVENT_HSG_TP_ON_CHECK, TRUE, NULL);
            //}
            palLANProcSendToLAN(edcHSG_SELECTED_VALUE0);
            palLANProcSendToLAN(edcHSG_SELECTED_VALUE1);
            palLANProcSendToLAN(edcHSG_SELECTED_VALUE2);
            palLANProcSendToLAN(edcHSG_SELECTED_WEB); //HICC2_Doulas_0129

            //palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL); //HICC2_Casper_0026
            //palDataMgr_UI_EventSend(edcUI_EVENT_HSG_TEST_PATTERN, eTP_ID, NULL); //HICC2_Doulas_0051 //HICC2_Casper_0026
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern == ets_ON) //HICC2_Doulas_0128 Modify//HICC2_Casper_0038
            {
                eRet = palDataMgr_TestPatternHandle(eTP_ID); //HICC2_Casper_0026
            }
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HSGSelected_Web(eDATA_ACCESS_MODE eAccessMode, void *pValue) //HICC2_Doulas_0128
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected;
    }
    else  //Write Function
    {
        UINT8 NewVal = *((UINT8*)pValue); //HICC2_Casper_0026
        eTEST_PATTERN_ID eTP_ID = eTID_HSG_RED + NewVal; //HICC2_Casper_0026
        eEXE_TP_RESULT eRet = eEXE_TP_INVALID; //HICC2_Casper_0026
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_HSGSELECTED, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            //if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern == ets_ON) //HICC2_Doulas_0051        //T100_Doulas_0024
            //{
            //palDataMgr_UI_EventSend(edcUI_EVENT_HSG_TP_ON_CHECK, TRUE, NULL);
            //}
            palLANProcSendToLAN(edcHSG_SELECTED_VALUE0);
            palLANProcSendToLAN(edcHSG_SELECTED_VALUE1);
            palLANProcSendToLAN(edcHSG_SELECTED_VALUE2);
            palLANProcSendToLAN(edcHSG_SELECTED); //HICC2_Doulas_0129

            //palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL); //HICC2_Casper_0026
            //palDataMgr_UI_EventSend(edcUI_EVENT_HSG_TEST_PATTERN, eTP_ID, NULL); //HICC2_Doulas_0051 //HICC2_Casper_0026
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGTestPatternCtrl != eCM_TEST_PATTERN_OFF)
            {
                eRet = palDataMgr_TestPatternHandle(eTP_ID);
            }
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HSGSelectedValue0(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT16  ucNode = eDFS_HSG_R_HUE + 3 * (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected);
    if((ucNode < eDFS_HSG_R_HUE) || (ucNode > eDFS_HSG_W_B_GAIN))
    {
        return eEXEC_CODE_FAIL;
    }

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = palDataMgr_HSG_Selected_Get(ucNode);
    }
    else  //Write Function
    {
        palDataMgr_HSG_Selected_Set(ucNode, eAccessMode, *((UINT8*)pValue));
    }
    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HSGSelectedValue1(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT16  ucNode = eDFS_HSG_R_SAT + 3 * (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected);
    if((ucNode < eDFS_HSG_R_HUE) || (ucNode > eDFS_HSG_W_B_GAIN))
    {
        return eEXEC_CODE_FAIL;
    }

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = palDataMgr_HSG_Selected_Get(ucNode);
    }
    else  //Write Function
    {
        palDataMgr_HSG_Selected_Set(ucNode, eAccessMode, *((UINT8*)pValue));
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HSGSelectedValue2(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT16  ucNode = eDFS_HSG_R_GAIN + 3 * (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected);
    if((ucNode < eDFS_HSG_R_HUE) || (ucNode > eDFS_HSG_W_B_GAIN))
    {
        return eEXEC_CODE_FAIL;
    }

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = palDataMgr_HSG_Selected_Get(ucNode);
    }
    else  //Write Function
    {
        palDataMgr_HSG_Selected_Set(ucNode, eAccessMode, *((UINT8*)pValue));
    }

    return eEXEC_CODE_PASS;
}

INT8 palDataMgr_HSGSelectedValue_Default_Get(eDATA_CODE eDataCode, tDATA_CODE *pValue)
{
    UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
    UINT8  ucPresetMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode;
    UINT16  ucNode = (eDataCode - edcHSG_SELECTED_VALUE0) + 3 * (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected);

    if(eCM_PICTURE_SETTINGS_USER == ucPresetMode)
    {
        ucPresetMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode;
    }

    if(palSystem_ModelIDGet() == MODEL_ID_0) //A35G2_BRC_Casper_0023
    {
        memcpy((UINT8*)pValue, (UINT8*)&sHSG_TABLE_SETTING_MODEL0[ucPresetMode] + ucNode, sizeof(UINT8));//A35G2_Coda_0106
    }
    else if(palSystem_ModelIDGet() == MODEL_ID_1) //A35G2_Coda_0106
    {
        memcpy((UINT8*)pValue, (UINT8*)&sHSG_TABLE_SETTING_MODEL1[ucPresetMode] + ucNode, sizeof(UINT8));
    }
    else
    {
        memcpy((UINT8*)pValue, (UINT8*)&sHSG_TABLE_SETTING_MODEL2[ucPresetMode] + ucNode, sizeof(UINT8));//A35G2_Coda_0106
    }
    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HSG_RGBCMY_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue) //G100_Coda_00110
{
   if (edaREAD == eAccessMode)  //Read Function
    {
    //    *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode].HSG_W_B_GAIN;
        *((UINT8 *)pValue) = ets_OFF;
    }
    else  //Write Function //A35G2_BRC_Casper_0065
    {
        UINT8 ucCount = 0;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern = (UINT8)ets_ON;
        utilDataMgr_CommonSet_CM(eDF_HSGADJUSTMENTAUTOTESTPATTERN, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGAdjustmentAutoTestPattern);
        palLANProcSendToLAN(edcHSG_AUTO_TEST_PATTERN);
        for(ucCount = 0; ucCount <= 5; ucCount++)
        {
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected = ucCount;
            switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected)
            {
                case 0:
                     palDataMgr_Access_HSG_Red_ResetDefault((eDATA_ACCESS_MODE) eAccessMode, (void *)pValue);
                break;

                case 1:
                     palDataMgr_Access_HSG_Green_ResetDefault((eDATA_ACCESS_MODE) eAccessMode, (void *)pValue);
                break;

                case 2:
                     palDataMgr_Access_HSG_Blue_ResetDefault((eDATA_ACCESS_MODE) eAccessMode, (void *)pValue);
                break;

                case 3:
                     palDataMgr_Access_HSG_Cyan_ResetDefault((eDATA_ACCESS_MODE) eAccessMode, (void *)pValue);
                break;

                case 4:
                     palDataMgr_Access_HSG_Magenta_ResetDefault((eDATA_ACCESS_MODE) eAccessMode, (void *)pValue);
                break;

                case 5:
                     palDataMgr_Access_HSG_Yellow_ResetDefault((eDATA_ACCESS_MODE) eAccessMode, (void *)pValue);
                break;

                case 6:
                      palDataMgr_Access_HSG_WhiteGain_ResetDefault((eDATA_ACCESS_MODE) eAccessMode, (void *)pValue);
                break;

                default:
                    break;
            }
        }

        //#ifdef CUSTOM_BARCO
	    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected = 0; // Red
        utilDataMgr_CommonSet_CM(eDF_HSGSELECTED, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHSGSelected);
        palLANProcSendToLAN(edcHSG_SELECTED);
        palLANProcSendToLAN(edcHSG_SELECTED_WEB); //HICC2_Doulas_0129
        //#endif


    }

    return eEXEC_CODE_PASS;
}

