eEXEC_CODE palDataMgr_Access_SerialNumber(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
	if (edaREAD == eAccessMode)  //Read Function
	{
		if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucSerialNumber[0] == 0)
		{
			snprintf((char *)pValue, SN_LENGTH, "-");
		}
		else
		{
			snprintf((char *)pValue, SN_LENGTH, "%s", (char *)m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucSerialNumber);
		}
		//GEC_UserInfo_Set(eGEC_GetSerialNumber, pValue); //A70LV_John_0045 import projector information to GEC
	}
	else  //Write Function
	{
		if(palDataMgr_ServiceModeGet() == ets_OFF)		//T100_Doulas_0029
		{
			LOG_MSG(db_APP_DATA_MGR, "palDataMgr_Access_SerialNumber fail \r\n");
			return eEXEC_CODE_FAIL;
		}
		//Update RAM

		snprintf((char *)m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucSerialNumber, SN_LENGTH, "%s" , (char *)pValue);
		//palDataMgr_ImageSetting_EDID_Type_Set((UINT8)eCM_SOURCE_RESERVED, (UINT8)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucCompatible_4K); //HICC2_Doulas_0070 remove//G100_John_0003 fix EDID version change issue

        utilOPD_RegulatoryInfo_Set(edcSERIAL_NUMBER, (char *)pValue, 0); //A65_OPTOMA_Julie_0080

		//Storage : EEPROM
		if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
		{
			utilDataMgr_CommonSet_CM(eDF_SERIALNUMBER, (UINT8*)pValue);
		}

		//Execute Action function
		if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
		{
			UINT8 ucValue = 0;	//G100_Doulas_0082
			UINT8 ucSwitch = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucModelSwitchAdjust;
            eCM_NATIVE_TIMING NativeTiming ;

            palFrontEndMgr_Model_Switch_Enable_Set(ucSwitch); //A65_OPTOMA_Julie_0065 //A35G2_Coda_0063

			ucValue = ((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDMI_EDID_1 & EDID_TYPE_MASK)<<HDMI1_EDID_TYPE2P0_SHIFT) +
		              ((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDMI_EDID_2 & EDID_TYPE_MASK)<<HDMI2_EDID_TYPE2P0_SHIFT) +
		              ((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDBaseT_EDID & EDID_TYPE_MASK)<<HDBASET_EDID_TYPE2P0_SHIFT);	//HICC2_Doulas_0068//G100_Doulas_0082

            palDataMgr_Access_Proj_Native_Timing(edaREAD, &NativeTiming);
			palFrontEndMgr_EDID_SN_Set(eCM_SOURCE_RESERVED, ucValue, NativeTiming, m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucSerialNumber);	//G100_Doulas_0082 Modify Add HDMI1/HDMI2/HDBaseT type

		}
	}

	return eEXEC_CODE_PASS;
}


