eEXEC_CODE palDataMgr_Access_LightSensorCalibration(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LV_Larry_0142 modify
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        //Sensor Calibration "YES"/"NO"
        if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucABP_CalibrateFlag != 1) //calibration pass
        {
            *((UINT8 *)pValue) = 0;
        }
        else
        {
            *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucABP_CalibrateFlag;
        }
    }
    else  //Write Function
    {
        //ToDo...  Sensor Calibration start
        UINT8 ucCalibrateFlag = *((UINT8 *)pValue);
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucABP_CalibrateFlag = ucCalibrateFlag;

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_ABP_CALIBRATEFLAG, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucData = 0; 		//G100_Doulas_0077 Modify
            ucCalibrateFlag = 0;

#if defined (CUSTOM_OPTOMA)
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sLightSetting.ucConstantBrightness = ets_OFF; //A35G2_Owen_0003
#endif
            palIllumination_ABP_StatusSet(eABP_STATUS_FACTORY_CAL); //T100_Larry_0018

            utilDataMgr_CommonSet_CM(eDF_ABP_CALIBRATEFLAG, &ucCalibrateFlag);

            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucABP_CalibrateFlag = 0;
            m_sAppDataMgrInfo.sSystemValues.ucLightSensorCalibrationProcess = 0;

            //memcpy(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorFull_BLD, aucData, 96);	//G100_Doulas_0077 remove
            for(;ucData < eLD_SEQ_NUMBER;ucData++)			//G100_Doulas_0077 Modify
			{
            	m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorFull_BLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorEco_BLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightFull_PWM_BLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightEco_PWM_BLD[ucData] = 0;

				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorFull_RLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorEco_RLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightFull_PWM_RLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightEco_PWM_RLD[ucData] = 0;

				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorFull_Dynamic_RLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorEco_Dynamic_RLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightFull_PWM_Dynamic_RLD[ucData] = 0;
				m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightEco_PWM_Dynamic_RLD[ucData] = 0;
			}
            EE_PUTVAR_SIZE(sSystemDefault.uiLightSensorFull_BLD, 96, m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiLightSensorFull_BLD);

        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_BurninType(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        //*((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable;
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucOsdBurnInIndex;//A35G2_Coda_0091
    }
    else  //Write Function
    {
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucOsdBurnInIndex = *((UINT8 *)pValue); //A35G2_Coda_0091
        //Update Ram
        switch(*((UINT8*)pValue))
        {
            default:
            case eBURNIN_TYPE_OFF:
                *((UINT8*)pValue) = 0;
                break;

            case eBURNIN_TYPE_60_10_2:
                *((UINT8*)pValue) = 1;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn = 60;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff = 10;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle = 2;
                break;

            case eBURNIN_TYPE_60_10_4:
                *((UINT8*)pValue) = 1;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn = 60;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff = 10;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle = 4;
                break;

            case eBURNIN_TYPE_60_10_6:
                *((UINT8*)pValue) = 1;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn = 60;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff = 10;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle = 6;
                break;

            case eBURNIN_TYPE_120_15_5:// HICC2_Bruce_0009
                *((UINT8*)pValue) = 1;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn = 120;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff = 15;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle = 5;
                break;

            case eBURNIN_TYPE_60_15_18:// HICC2_Bruce_0009
                *((UINT8*)pValue) = 1;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn = 60;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff = 15;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle = 18;
                break;

            case eBURNIN_TYPE_ALWAYS_ON:// HICC2_Bruce_0009
                *((UINT8*)pValue) = 2;// 2: Always Lamp On
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn = FW_BURNIN_TIME_ON_DEFAULT_VALUE;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff = FW_BURNIN_TIME_OFF_DEFAULT_VALUE;
                m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle = FW_BURNIN_CYCLE_DEFAULT_VALUE;
                break;
        }

        m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_BURNINENABLE, (UINT8*)pValue);
            utilDataMgr_CommonSet_CM(eDF_LAMPON,       &m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn);
            utilDataMgr_CommonSet_CM(eDF_LAMPOFF,      &m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff);
            utilDataMgr_CommonSet_CM(eDF_BURNINCYCLE,  (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            //Add action function for burn in function
            if (m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable)
            {
                //send burn in enable event to F-Mcu

                //trigger burn in function(draw test pattern)
                palDataPath_BurnInStart();

                palIllumination_BurnIn_Count_Start(
                    m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucBurnInEnable,
                    m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOn,
                    m_sAppDataMgrInfo.sEepSettings.sBurin_Information.uiBurnInCycle);
            }
            else
            {
                palIllumination_BurnIn_Count_Stop();
                palDataPath_Resync();
            }
            halMCU_Auto_Power_On_Tmer_Set(m_sAppDataMgrInfo.sEepSettings.sBurin_Information.ucLampOff);
            halMCU_Auto_Power_On_Set(*((UINT8*)pValue)) ;
#ifdef PLATFORM_H30_4K
            halMCU_Auto_Burn_In_Parameter_Set();
#endif
        }

        palLANProcSendToLAN(edcBURNIN_ENABLE);
        palLANProcSendToLAN(edcBURNIN_ON);
        palLANProcSendToLAN(edcBURNIN_OFF);
        palLANProcSendToLAN(edcBURNIN_CYCLE);
    }

    return eEXEC_CODE_PASS;
}



