eEXEC_CODE palDataMgr_Access_MainInput(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
    }
    else  //Write Function
    {
        palDataPath_Test_SetTimeStart();

        UINT8 ucOldMainSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;     //A70LV_Doulas_0117
        if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucPIPEnable != ets_OFF)  //A70LV_Doulas_0097
        {
            if(*((UINT8*)pValue) == m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub)
            {
                return eEXEC_CODE_FAIL;
            }
        }

        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain = *((UINT8*)pValue);
        #if defined(PLATFORM_H30_4K)
        palDataMgr_SubSourceChecking();
        if((halScaler_PIP_PBP_Enable_Get() == eCM_SCREEN_MODE_OFF)
            &&(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain != ucOldMainSource))
        {
            halFrontEndCtrl_SubInput_Set(&ucOldMainSource);    //set sub input source
            palDataPath_UserSetSourceInputSub((eCM_SOURCE_ID)ucOldMainSource);
        }
        #endif

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_INPUTSOURCEMAIN, (UINT8*)pValue); //HICC2_Doulas_0144 Modify
            /*if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucSourceKeyOption != eSOURCE_KEY_CHANGE_SOURCE_AUTO)     //HICC2_Doulas_0144//A70LV_Doulas_0117 not always save EEPROM
            {
                utilDataMgr_CommonSet_CM(eDF_INPUTSOURCEMAIN, (UINT8*)pValue);
            }
            else
            {
                ePOWER_STATE m_ePowerState = palSystem_PowerStateGet();     //A70LV_Doulas_0233
                if((m_ePowerState == ePOWER_STATE_COOLING) || (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucPIPEnable != ets_OFF))
                {
                    utilDataMgr_CommonSet_CM(eDF_INPUTSOURCEMAIN, (UINT8*)pValue);
                }
            }*/
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucInputKeyFunction = 0;
            palDataMgr_Access_InputKey(edaREAD, &ucInputKeyFunction) ;
            if((ucInputKeyFunction == eSOURCE_KEY_CHANGE_SOURCE_AUTO) && (m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[0] != eSOURCE_STATE_SEARCHING))
            {
                m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[0] = eSOURCE_STATE_SEARCHING;
                palLANProcSendToLAN(edcSHOW_MAINSOURCE_MESSAGES);
            }
            else if((ucInputKeyFunction != eSOURCE_KEY_CHANGE_SOURCE_AUTO) && (m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[0] != eSOURCE_STATE_CHECKING_FOR_SIGNAL))
            {
                m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[0] = eSOURCE_STATE_CHECKING_FOR_SIGNAL;
                palLANProcSendToLAN(edcSHOW_MAINSOURCE_MESSAGES);
            }

            if(palDataPath_IsSourceLock())      //A70LV_Doulas_0294
            {
                UINT8 ucShowLogo = 0;

				palImgMgr_SourceOutputOff(eSOURCE_WINDOW_MAIN);  //A35G2_CDS_Simon_0001
                if((palSystem_PanelID_Get() == PANEL_3D_OUTPUT) ||
                   (palSystem_PanelID_Get() == PANEL_2D_HIGHSPEED))
				{
				    palImgMgr_SourceOutputOff(eSOURCE_WINDOW_SUB);  //A35G2_CDS_Simon_0017
				    palDataPath_ShowLogo();
                    ucShowLogo = 1;
				}

				//palDataPath_ShowLogo();
                if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain != ucOldMainSource)
                {
                    if(ucShowLogo == 0)
                    {
                        if(!palDataMgr_IsOsdOpen())
                        {
                            palDataMgr_UI_EventSend(edcUI_EVENT_SOURCE_MENU_OPEN_SET, TRUE, NULL);
                        }

                        //palDataPath_ShowLogo();
                    }
                    palEnvironment_LightSourceBlankingOn_Set(TRUE,2); //HICC2_Doulas_0023
                }
                else
                {
                    palEnvironment_LightSourceBlankingOn_Set(TRUE,2); //HICC2_Doulas_0023
                }
            }
            palEnvironment_AutoSourceSearchTimerClear();    //A70LV_Doulas_0082
            palDataPath_UserSetSourceInput((eCM_SOURCE_ID)*((UINT8*)pValue)); //A70LV_Doulas_0112 //A70LV_Doulas_0029 modify
            //halFormatter_InputSourceSet(*((UINT8*)pValue));     //A70LV_Doulas_0037
            //palDataMgr_Formatter_Parameter_Set();       //A70LV_Doulas_0187 remove //A70LV_Doulas_0054 modify
            palLANProcSendToLAN(edcWALL_COLOR);		//G100_Doulas_0088 update Share memory
            palLANProcSendToLAN(edcBACKUPINPUT_CURRENT_SOURCE); //HICC2_Steven_0013
        }

#if 0
        if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain != ucOldMainSource)   //A70LV_Doulas_0117
        {
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain].ucAspectRatio != eCM_SCALING_MODE_CUSTOM)     //A70LV_Doulas_0130 mdoify
                palDataMgr_ResetDigitalZoomShiftRam();
        }
#endif /* 0 */
        palDataMgr_3DModeConditionUpdate();
    }

    return eEXEC_CODE_PASS;
}

