eEXEC_CODE palDataMgr_Access_SubInput(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub;
    }
    else  //Write Function
    {
        if(*((UINT8*)pValue) == m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain)  //A70LV_Doulas_0097
        {
            return eEXEC_CODE_FAIL;
        }

        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //UINT8 ucGuiSrcID = (UINT8)CM2GUI(edcSUB_INPUT, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_INPUTSOURCESUB, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucInputKeyFunction = 0;
            palDataMgr_Access_InputKey(edaREAD, &ucInputKeyFunction) ;
            if(ucInputKeyFunction == eSOURCE_KEY_CHANGE_SOURCE_AUTO && m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[1] != eSOURCE_STATE_SEARCHING)
            {
                m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[1] = eSOURCE_STATE_SEARCHING;
                palLANProcSendToLAN(edcSHOW_SUBSOURCE_MESSAGES);
            }
            else if(m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[1] != eSOURCE_STATE_CHECKING_FOR_SIGNAL)
            {
                m_sAppDataMgrInfo.sSystemValues.sSOURCE_INFO.ucSourceState[1] = eSOURCE_STATE_CHECKING_FOR_SIGNAL;
                palLANProcSendToLAN(edcSHOW_SUBSOURCE_MESSAGES);
            }

            if(palDataPath_IsSourceLockSub())      //A70LV_Doulas_0294
            {
				palImgMgr_SourceOutputOff(eSOURCE_WINDOW_SUB);   //A35G2_CDS_Simon_0001
                palEnvironment_LightSourceBlankingOn_Set(TRUE,2); //HICC2_Doulas_0023
            }

            palDataPath_UserSetSourceInputSub((eCM_SOURCE_ID)*((UINT8*)pValue)); //A70LV_Doulas_0112 //A70LV_Doulas_0029 modify

			if(palImgMgr_WB_OutputEnableGet() == FALSE)   //G100_Doulas_0058
			{
//				MS_SLEEP(1000);
				palImgMgr_WB_OutputEnableSet(1);
			}
        }
    }

    return eEXEC_CODE_PASS;
}

