eEXEC_CODE palDataMgr_Access_MainAspectRatioGet(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
    if (edaREAD == eAccessMode)  //Read Function
    {
        //A70LV_Doulas_0109 modify //A70LV_Doulas_0056 modify
        //char aucString[VERSION_STRING_MAX_LENGTH] = {0};
        //palDataPath_InputAspectRatio_Get((UINT8*)aucString);
        //memcpy((UINT8 *)pValue, aucString, strlen(aucString)+1);
        if(palDataPath_IsSourceLock())
        {
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucPIPEnable)
            {
                if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucMainLayout > eCM_MAIN_LAYOUT_PBP_MAIN_BOTTOM) //HICC2_Doulas_0065 Modify
                {   //PIP
                    *((UINT8*)pValue) = eCM_SCALING_MODE_AUTO;
                }
                else //PBP
                {
                    *((UINT8*)pValue) = eCM_SCALING_MODE_FULL_SIZE;
                }
            }
            else if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode == eCM_PICTURE_SETTINGS_2DHIGHSPEED ||
                   (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode == eCM_PICTURE_SETTINGS_USER &&
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode == eCM_PICTURE_SETTINGS_2DHIGHSPEED)) //HICC2_Doulas_0065
            {
                *((UINT8*)pValue) = eCM_SCALING_MODE_FULL_SIZE;
            }
            else
            {
                UINT8  ucIS_3D_Enable = palDataMgr_IS_3D_Enable();  //A70LV_Doulas_0162
                if(ucIS_3D_Enable == ets_ON)     //A70LV_Doulas_0162 modify aspect ratio 3D
                    *((UINT8*)pValue) = eCM_SCALING_MODE_3D;
                else
                {
                    *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucAspectRatio;
                }
            }
        }
        else
        {
            //sprintf((char *)aucString, "-");
            //memcpy((INT8 *)pValue, aucString, strlen((char *)aucString)+1);

            *((UINT8*)pValue) = eCM_SCALING_MODE_NUMBER;
        }
    }
    else  //Write Function
    {

    }

    return eEXEC_CODE_PASS;
}

