eEXEC_CODE palDataMgr_Access_LAN_Primary_DNS(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //T100_Simon_0015
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        char DNS_Info_String[16] = {0};
        sprintf(DNS_Info_String, "%d.%d.%d.%d" , m_sLAN_info.ucLAN_Primary_DNS_Show[0], m_sLAN_info.ucLAN_Primary_DNS_Show[1], m_sLAN_info.ucLAN_Primary_DNS_Show[2], m_sLAN_info.ucLAN_Primary_DNS_Show[3]);
        memcpy((UINT8 *)pValue, DNS_Info_String, strlen(DNS_Info_String)+1);
    }
    else  //Write Function
    {
        //Update RAM

        //pValue : 192.168.0.100
        //printf("\r\npalDataMgr_Access_LAN_Primary_DNS(%s)\r\n" , (char *)pValue);
        INT32 iValue = 0;           //G100_Owen_0057
        UINT8 aucPrimDNS[4] = {0};  //G100_Owen_0057
        UINT8 aucDataString[32] = {0};  //下面使用 strtok , 會把 . 取代為 NULL , 所以先複製一份來處理
        memcpy(aucDataString, pValue, strlen((char *)pValue));

        UINT8 ucIndex = 0 ;
        char *pch ;
        pch = strtok((char *)aucDataString, ".") ;   // 以 . 這個字元來分割字串

        while(pch != NULL && ucIndex < 4)
        {
            iValue = atoi(pch); //G100_Owen_0057
            if((iValue < 0) || (iValue > 255))  //G100_Owen_0047
            {
                return eEXEC_CODE_FAIL;
            }
            aucPrimDNS[ucIndex] = (UINT8)iValue;
            ucIndex++ ;
            pch = strtok(NULL, ".") ;
        }

        for(ucIndex = 0; ucIndex < 4; ucIndex++)    //G100_Owen_0057
        {
            m_sLAN_info.ucLAN_Primary_DNS_Show[ucIndex] = aucPrimDNS[ucIndex];
        }
        //palDataMgr_LanArgCopy2(); //A70LV_Larry_0278

        palLANProcSendToLAN(edcLAN_PRIMARY_DNS_1);
        palLANProcSendToLAN(edcLAN_PRIMARY_DNS_2);
        palLANProcSendToLAN(edcLAN_PRIMARY_DNS_3);
        palLANProcSendToLAN(edcLAN_PRIMARY_DNS_4);
    }

    return eEXEC_CODE_PASS;
}

