eEXEC_CODE palDataMgr_Access_PJLinkIPAddress(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
	#if(NETWORK_IPV6_ENABLE)
        snprintf(pValue, 64, "%s", m_sLAN_info.ucPJLink_IPv6);
	#else
        char AddressString[16] = {0};
        sprintf(AddressString, "%d.%d.%d.%d" , m_sLAN_info.ucPJLink_IP_Show[0], m_sLAN_info.ucPJLink_IP_Show[1], m_sLAN_info.ucPJLink_IP_Show[2], m_sLAN_info.ucPJLink_IP_Show[3] );
        memcpy((UINT8 *)pValue, AddressString, strlen(AddressString)+1);
	#endif
    }
    else  //Write Function
    {
        //Update RAM
	#if(NETWORK_IPV6_ENABLE)
        snprintf(m_sLAN_info.ucPJLink_IPv6, 64, "%s", (char *)pValue);  // HICC2_Keven_0025
        return eEXEC_CODE_PASS;
	#else
        //pValue : 192.168.0.100
        //printf("\r\nWrite palDataMgr_Access_LanIPAddress(%s)\r\n" , (char *)pValue);
        INT32 iValue = 0;
        UINT8 aucDataString[32] = {0};  //下面使用 strtok , 會把 . 取代為 NULL , 所以先複製一份來處理
        memcpy(aucDataString, pValue, strlen((char *)pValue));

        UINT8 ucIndex = 0 ;
        char *pch ;
        pch = strtok((char *)aucDataString, ".") ;   // 以 . 這個字元來分割字串
        if((iValue < 0) || (iValue > 255))  //G100_Owen_0047
        {
            return eEXEC_CODE_FAIL;
        }

        while(pch != NULL && ucIndex < 4)
        {
            m_sLAN_info.ucPJLink_IP_Show[ucIndex] = atoi(pch) ;
            ucIndex++ ;
            pch = strtok(NULL, ".") ;
        }

        //palDataMgr_LanArgCopy2(); //A70LV_Larry_0278

        #if 0
        UINT8 aucString[4] = {0} ;
        strncpy((char *)aucString, (char *)pValue + 0,  3);
        ucLAN_IP_Show[0] = (UINT8)atoi((char *)aucString) ;
        strncpy((char *)aucString, (char *)pValue + 4,  3);
        ucLAN_IP_Show[1] = (UINT8)atoi((char *)aucString) ;
        strncpy((char *)aucString, (char *)pValue + 8,  3);
        ucLAN_IP_Show[2] = (UINT8)atoi((char *)aucString) ;
        strncpy((char *)aucString, (char *)pValue + 12, 3);
        ucLAN_IP_Show[3] = (UINT8)atoi((char *)aucString) ;
        #endif

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        //    EE_PUTVAR(sUserSystemSetting.sNetworkSetting.ucDHCP, *((UINT8*)pValue));
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            //strncpy(TempStr[0] , (char *)&InputStr[0] , 3) ;
        }
	#endif
    }

    return eEXEC_CODE_PASS;
}

