eEXEC_CODE palDataMgr_Access_FirstStartupFlag(eDATA_ACCESS_MODE eAccessMode, void *pValue)     //T100_Doulas_0009
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag;
    }
    else  //Write Function
    {
        UINT8 ucTemp = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag;

        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag = *((UINT8*)pValue) ;

        //Execute Action function
        if ((edaWRITE_THROUGH_NO_ACTION == eAccessMode) || (edaWRITE_THROUGH_WITH_ACTION == eAccessMode))
        {
            utilDataMgr_CommonSet_CM(eDF_FIRSTSTARTUPFLAG, (UINT8*)pValue);
        }

        if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucFirstStartupFlag == FALSE && ucTemp)
        {
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucSourceKeyOption == eSOURCE_KEY_CHANGE_SOURCE_AUTO &&
               m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucPIPEnable == FALSE)
            {
                tDATA_CODE iDefauleSetting = 0;
                UINT8   ucInputSourceMain = 0;

                palDataMgr_Data_Range_Get(edcMAIN_INPUT, edrDEFAULT, &iDefauleSetting);
                ucInputSourceMain = (UINT8)iDefauleSetting;

                palDataMgr_Access_MainInput(edaWRITE_RAM_ONLY_WITH_ACTION, &ucInputSourceMain);
                palLANProcSendToLAN(edcMAIN_INPUT);
            }
        }
    }
    return eEXEC_CODE_PASS;
}

