eEXEC_CODE palDataMgr_Access_ColorWheel_2x_Index(eDATA_ACCESS_MODE eAccessMode, void *pValue)   //A70LV_Doulas_0138 modify
{
    UINT8  ucInputSource = 0;//m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;      //A70LV_Doulas_0263 modify
    UINT8  ucPresetMode = 0;//m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode;       //A70LV_Doulas_0263 modify
    UINT8  ucSignalType = 0;//palDataMgr_SignalType_Get();    //A70LV_Doulas_0263 modify//A70LV_Doulas_0013
    UINT8  ucWheelSpeed = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucCW_Speed;

    if (edaREAD == eAccessMode)  //Read Function
    {
        UINT16 iWheelIndex[2] = {0};

        iWheelIndex[0] = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiPWIndex[eCM_COLOR_WHEEL_SPEED_2X];    //2x
        iWheelIndex[1] = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiFWIndex[eCM_COLOR_WHEEL_SPEED_2X];    //2x
        LOG_MSG(db_APP_DATA_MGR, "Wheel2X get(%d,%d)\n",iWheelIndex[0],iWheelIndex[1]);
        memcpy((UINT8*)pValue, (UINT8*)iWheelIndex, sizeof(iWheelIndex));
    }
    else  //Write Function
    {
        UINT16 iWheelIndex[2] = {0};

        iWheelIndex[0] = ((UINT16*)pValue)[0];
        iWheelIndex[1] = ((UINT16*)pValue)[1];
        //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiPWIndex[eCM_COLOR_WHEEL_SPEED_2X] = iWheelIndex[0];
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiFWIndex[eCM_COLOR_WHEEL_SPEED_2X] = iWheelIndex[1];
        LOG_MSG(db_APP_DATA_MGR, "Wheel2X set(%d,%d)\n",iWheelIndex[0],iWheelIndex[1]);
        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_PWINDEX_0, (UINT8*)&iWheelIndex[0]);
            utilDataMgr_CommonSet_CM(eDF_FWINDEX_0, (UINT8*)&iWheelIndex[1]);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            if(ucWheelSpeed == eCM_COLOR_WHEEL_SPEED_2X)
            {
                halFormatter_PW_Index_Set(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiPWIndex[ucWheelSpeed]);
                halFormatter_FW_Index_Set(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.uiFWIndex[ucWheelSpeed]);
            }
        }
    }

    return eEXEC_CODE_PASS;
}

