eEXEC_CODE palDataMgr_Access_SyncThreshold(eDATA_ACCESS_MODE eAccessMode, void *pValue)          //A70LV_Doulas_0060
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucSyncThreshold *SYNC_THRESHOLD_STEP_VALUE;     //A70LV_Doulas_0110 modify
    }
    else  //Write Function
    {
        //Update RAM
        UINT8  ucValue = *((UINT8*)pValue)/SYNC_THRESHOLD_STEP_VALUE;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucSyncThreshold = ucValue;  //A70LV_Doulas_0110 modify

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_SYNCTHRESHOLD, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palImgMgr_SyncThreshold_Set(ucValue);   //A70LV_Doulas_0114
            halFrontEndCtrl_VGA_Sync_Threshold_Set(&ucValue);   //A70LV_Doulas_0112
        }
    }

    return eEXEC_CODE_PASS;
}

