eEXEC_CODE palDataMgr_Access_Warping_AP_Save(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LV_Larry_0318
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingSaveSetting;
    }
    else  //Write Function
    {
        //Update Ram
        UINT8 ucIndex = *((UINT8*)pValue);
        LOG_MSG(db_HAL_WARPING, "Warping_AP_Save %d\n", *((UINT8*)pValue));

        if(ucIndex == eCM_GEO_MEMORY_SAVE_NA)
        {
            return eEXEC_CODE_FAIL;
        }

        if(ucIndex < eCM_GEO_MEMORY_SAVE_NUMBER && ucIndex != eCM_GEO_MEMORY_SAVE_NA)
        {
            //UINT16 uiSize = sizeof(sWARP_MEMORY) - WARPING_MEMORY_RESERVED;
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingSaveSetting = ucIndex;
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting = ucIndex;
            #ifdef CUSTOM_CHRISTIE
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sWarpMemory[ucIndex].ucWarpingApply = WARPING_TYPE_AP_MYSTIQUE;
            #else
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sWarpMemory[ucIndex].ucWarpingApply = WARPING_TYPE_AP;
            #endif
            palDataMgr_WarpingMemorySaveConditionUpdate();  //G100_Simon_0048
            palGeo_CurrentWarpTypeSet(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sWarpMemory[ucIndex].ucWarpingApply);   //A35G2_Simon_0115

            //Blending
            //memcpy(&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sWarpMemory[ucIndex].ucBlendingTopEnable,
                   //&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingTopEnable,
                   //20);

            //warping H/V Interpolation
            //halWarp_MemoryInterpolationGet(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sWarpMemory[ucIndex].ucHLUT);

            //Storage : EEPROM
            if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
            {
                utilDataMgr_CommonSet_CM(eDF_WARPINGAPPLY_0 + (4*(ucIndex-1)), (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sWarpMemory[ucIndex].ucWarpingApply);
                utilDataMgr_CommonSet_CM(eDF_WARPINGSAVESETTING, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingSaveSetting);
                utilDataMgr_CommonSet_CM(eDF_WARPINGAPPLYSETTING, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting);

                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingLastSaved = *((UINT8*)pValue); //A35G2_CDS_Simon_0008 , record last apply for enable/disable hotkey
                utilDataMgr_CommonSet_CM(eDF_WARPINGLASTSAVED, (UINT8*)pValue);
            }

            //Execute Action function
            if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
            {
                //if(m_sAppDataMgrInfo.sSystemValues.ucTwistLink == 0)
                //{
                    //halWarping_MemorySave(ucIndex);
                //}
            }

            palLANProcSendToLAN(edcWARP_MEMORY_APPLY);
            palLANProcSendToLAN(edcWARP_MEMORY_SAVE);
            palLANProcSendToLAN(edcWARP_MEMORY_NAME_1);
            palLANProcSendToLAN(edcWARP_MEMORY_NAME_2);
            palLANProcSendToLAN(edcWARP_MEMORY_NAME_3);
            palLANProcSendToLAN(edcWARP_MEMORY_NAME_4);
            palLANProcSendToLAN(edcWARP_MEMORY_NAME_5);
        }
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }

    return eEXEC_CODE_PASS;
}

