eEXEC_CODE palDataMgr_Access_4CornerReset(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LV_Larry_0072
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = ets_OFF;
        return eEXEC_CODE_FAIL;
    }
    else  //Write Function
    {
        UINT16 uiSize = sizeof(UINT16) * 8;

        //Update RAM
        memset((UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopLeftHorz, 0, uiSize);

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            EE_PUTVAR_SIZE(sUserSystemSetting.sWarpSetting.ui4CornerTopLeftHorz, uiSize, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopLeftHorz);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT16 uiCount = 0;

            palGeo_4corner_Reset();

			#ifdef CUSTOM_CHRISTIE   //HICC2_Steven_0057 //ISS-0026042
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting != 0)
            {
            	m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting = 0; //Warp memory set to "Off"
            	utilDataMgr_CommonSet_CM(eDF_WARPINGAPPLYSETTING, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting);  //A35G2_CDS_Simon_0008
            	palLANProcSendToLAN(edcWARP_MEMORY_APPLY);
            }
			#endif

            for(uiCount = edc4CORNER_TOP_LEFT_HORZ; uiCount <= edc4CORNER_BOTTOM_RIGHT_VERT; uiCount++)
            {
                palLANProcSendToLAN(uiCount);
            }

        }
    }

    return eEXEC_CODE_PASS;
}

