eEXEC_CODE palDataMgr_Access_System_Update_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //ZU860_Julie_0003 //ZU860_Doulas_0036
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucSystemUpdateStatus;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucSystemUpdateStatus = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //EE_PUTVAR(sUserSystemSetting.sCommonSetting.ucSystemUpdateStatus, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_SYSTEM_UPDATE_STATUS, (UINT8*)pValue);	//A65_OPTOMA_Doulas_0025 Modify
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucStatus = *((UINT8*)pValue);

            LOG_MSG(db_APP_ETHERNET, "FOTA status %d\r\n", ucStatus);

            if(ucStatus == eFOTA_SYSTEM_UPDATE_STATUS_QUERY_FW || ucStatus == eFOTA_SYSTEM_UPDATE_STATUS_POWER_ON_QUERY) //A35G2_OTM_Owen_0001 //ZU860_Owen_0017
            {
                m_bSysUpdataOpFlg = TRUE;
            }
            else if(m_bSysUpdataOpFlg == TRUE)    //ZU860_Owen_0017
            {
                switch(ucStatus)    //ZU860_Owen_0013
                {
                    case eFOTA_SYSTEM_UPDATE_STATUS_NEW_FW_EXIST:// 1
                    case eFOTA_SYSTEM_UPDATE_STATUS_NO_NEW_FW:// 2
                    case eFOTA_SYSTEM_UPDATE_STATUS_ERROR_NETWORK_FAIL:// 4
                    case eFOTA_SYSTEM_UPDATE_STATUS_DOWNLOADING:// 5
                    case eFOTA_SYSTEM_UPDATE_STATUS_UPGRADE_READY:// 6
                    case eFOTA_SYSTEM_UPDATE_STATUS_DOWNLOAD_FAIL:// 7
                    case eFOTA_SYSTEM_UPDATE_STATUS_SERVER_NOT_CONNECTED:// 8
                    case eFOTA_SYSTEM_UPDATE_STATUS_ISO_PARSING_FAIL:// 9
                    case eFOTA_SYSTEM_UPDATE_STATUS_HTTP_DISABLE_FAIL:// 11
                        palDataMgr_UI_EventSend(edcUI_EVENT_SYSTEM_UPDATE, ucStatus, NULL);// HICC2_Bruce_0010
                        palInput_FOTA_StatusSet(ucStatus);
                        break;

                    default:
                        break;
                }
            }
        }
    }

    return eEXEC_CODE_PASS;
}

