eEXEC_CODE palDataMgr_Access_Silent_FOTA_Execute(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A65_OPTOMA_Julie_0092
{
	static UINT8 SilentFOTAExe = 0;

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = SilentFOTAExe;
    }
    else  //Write Function
    {
        //Update RAM

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucValue = *(UINT8*)pValue;

            if(ucValue == eFOTA_EXECUTE_PARSING_FW && m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucSystemUpdateStatus == eFOTA_SYSTEM_UPDATE_STATUS_NEW_FW_EXIST)
        	{
				SilentFOTAExe = ucValue;
				//palLANProcSendToLAN(edcSILENTFOTA_EXECUTE);   //A35G2_OTM_Owen_0001
        	}
            if(ucValue == eFOTA_EXECUTE_UPGRADE_FW && m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucSystemUpdateStatus == eFOTA_SYSTEM_UPDATE_STATUS_UPGRADE_READY)
            {
            	SilentFOTAExe = ucValue;
				palLANProcSendToLAN(edcSILENTFOTA_EXECUTE);
            }
			else
			{
            	SilentFOTAExe = 0;
			}
        }
    }
    return eEXEC_CODE_PASS;
}

