eEXEC_CODE palDataMgr_Access_ServiceModeFlag(eDATA_ACCESS_MODE eAccessMode, void *pValue)   //A70LV_Doulas_0138
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        char aucString[16];
        if(palDataMgr_ServiceModeGet())
            sprintf(aucString, "1");
        else
            sprintf(aucString, "0");
        memcpy((UINT8 *)pValue, aucString, strlen(aucString)+1);
    }
    else  //Write Function
    {
        char aucString[32] = "service,service";
        char aucCapital_String[32] = "SERVICE,SERVICE";
        UINT16 uiLens1;
        UINT16 uiLens2;

        uiLens1 = strlen((char*)pValue);
        uiLens2 = strlen(aucString);
        //LOG_MSG(db_ALWAYS, "(func:%s, line:%d) %d,%d \r\n", __FUNCTION__, __LINE__,uiLens1,uiLens2);
        if(((memcmp(aucString,(UINT8*)pValue,uiLens2) == 0)||(memcmp(aucCapital_String,(UINT8*)pValue,uiLens2) == 0)) &&
           (uiLens1 == uiLens2))
        {
            palDataMgr_ServiceModeSet(ets_ON);
            //LOG_MSG(db_APP_DATA_MGR, "(func:%s, line:%d) %s \r\n", __FUNCTION__, __LINE__,(UINT8*)pValue);
        }
        else
        {
            LOG_MSG(db_APP_DATA_MGR, "(func:%s, line:%d) %s(%d,%d) \r\n", __FUNCTION__, __LINE__,(UINT8*)pValue,uiLens1,uiLens2);
            return eEXEC_CODE_FAIL;
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode)
        {
        }
    }

    return eEXEC_CODE_PASS;
}

