eEXEC_CODE palDataMgr_Access_DirectPictureMute(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //T100_Simon_0005
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sSystemValues.sSYSTEM_VARIABLE.ucPictureMute ;
    }
    else  //Write Function //G100_Larry_0007
    {
        UINT8 ucValue = (*((UINT8 *)pValue) != 0) ? 1:0;
        if( palDataMgr_Get_Camera_Working_Status() == eCAMERA_STATUS_WORKING )
        {
            return eEXEC_CODE_FAIL;
        }

        if(palEnvironment_Fake_Power_Down_Get() == FALSE)	//G100_Clare_0055
        {
            //m_sAppDataMgrInfo.sSystemValues.sSYSTEM_VARIABLE.ucPictureMute = *((UINT8 *)pValue) ;

            if(edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode) //G100_Owen_0032 //G100_Larry_0008
            {
                m_sAppDataMgrInfo.sSystemValues.sSYSTEM_VARIABLE.ucPictureMute = ucValue;
            }

            if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
            {
                if(ucValue != m_sAppDataMgrInfo.sSystemValues.sSYSTEM_VARIABLE.ucPictureMute)
                {
                    if(ucValue)  //blank screen
                    {
                        ucValue = palIllumination_DirectShutter(1);

                        if(ucValue == 1)
                        {
	                        palIllumination_OPDSnapshot_Recode(eOPD_SHUTTER_ON_LOG);//A70LK_Julie_0002
                        }
                    }
                    else
                    {
                        ucValue = palIllumination_DirectShutter(0);

                        if(ucValue == 0)
                        {
	                        palIllumination_OPDSnapshot_Recode(eOPD_SHUTTER_OFF_LOG);//A70LK_Julie_0002
                        }
                    }

                    m_sAppDataMgrInfo.sSystemValues.sSYSTEM_VARIABLE.ucPictureMute = ucValue;
                }
                else
                {
                    return eEXEC_CODE_FAIL;
                }
            }
        }

        palLANProcSendToLAN(edcPICTURE_MUTE);
    }

    return eEXEC_CODE_PASS;
}


