eEXEC_CODE palDataMgr_Access_BackupIputSwitch(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupIputSwitch;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupIputSwitch = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //EE_PUTVAR(sUserSystemSetting.sCommonSetting.ucSourceMode, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_BACKUP_INPUT_SWITCH, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
#ifdef SCALER_FPGA_F34
            palImgMgr_BackupSwitchSet(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupIputSwitch);

            palDataPath_BackupPrimaryInput((eCM_SOURCE_ID)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput);
            palDataPath_BackupSecondaryInput((eCM_SOURCE_ID)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput);
            if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucPIPEnable == ets_OFF) && (palImgMgr_Input_3D_Format_Config_Get() == eINPUT_3D_TYPE_OFF))
            {
                UINT8 ucSetting = 0;

                ucSetting = eCM_LOW_LATENCY_MODE_OFF;
                palDataMgr_Access_LowLatencyMode(edaWRITE_THROUGH_WITH_ACTION, &ucSetting);

                palDataMgr_Access_MainInput(edaREAD, &ucSetting);
                if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput == ucSetting) ||
                    (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput == ucSetting))
                {
                    //MainInput
                    palDataMgr_Access_MainInput(edaWRITE_RAM_ONLY_WITH_ACTION, &ucSetting);
                }
            }

#else
        	halFrontEndCtrl_Backup_AutoSW_Set((UINT8*)pValue);
//G100_Steven_0028

        	//if(ets_ON == *(UINT8*)pValue /*&& appGui_IsBackup_Input_NextMenu_L3() == TRUE*/) //Move to appgui.c
        	{
        	    #if 0  //A35G2_CDS_Simon_0036 remove
        		//G100_Steven_0055 start, Enable auto switch 就會設置當下 first input 為 main input
            	UINT8 ucBK_PriInput = palDataMgr_BKInput_Trans2_CMInput(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput);
            	//if(ucBK_PriInput != m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain)
            	{
            		palDataMgr_Access_MainInput(eAccessMode, (void *)&ucBK_PriInput);
            		palLANProcSendToLAN(edcMAIN_INPUT);
            	}
            	#endif
            	//G100_Steven_0055 end
        		halFrontEndCtrl_Backup_First_Set((UINT8 *)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput);
        		halFrontEndCtrl_Backup_Second_Set((UINT8 *)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput);
        	}

            palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
#if 0
            palImgMgr_SclDatapathSet(*((UINT8*)pValue));
            if(*((UINT8*)pValue) == eSOURCE_MODE_BACKUP)
            {
                palDataPath_BackupInput(eSOURCE_WINDOW_MAIN, (eCM_SOURCE_ID)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput);
            }
            else
            {
                palDataPath_BackupInput(eSOURCE_WINDOW_MAIN, eCM_SOURCE_NUMBER);
            }
#endif
#endif /* SCALER_FPGA_F34 */
        }
    }
    return eEXEC_CODE_PASS;
}
