//G100_Steven_0016
eEXEC_CODE palDataMgr_Access_BackupPrimaryInput(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput;
    }
    else  //Write Function
    {
    	//G100_Steven_0031
        if(*((UINT8*)pValue) == m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput)
        {
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput;
        }

        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //EE_PUTVAR(sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_BACKUP_PRIMARY_INPUT,   (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput);
            utilDataMgr_CommonSet_CM(eDF_BACKUP_SECONDARY_INPUT, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
#ifdef SCALER_FPGA_F34
            palDataPath_BackupPrimaryInput((eCM_SOURCE_ID)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput);
            palDataPath_BackupSecondaryInput((eCM_SOURCE_ID)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput); //A70LK_Jacky_0012
            if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucPIPEnable == ets_OFF) && (halScaler_Input_3D_Format_Config_Get() == eINPUT_3D_TYPE_OFF))
            {
                UINT8 ucSetting = 0;
                palDataMgr_Access_MainInput(edaREAD, &ucSetting);
                if((m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput == ucSetting) ||
                    (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput == ucSetting))
                {
                    //MainInput
                    palDataMgr_Access_MainInput(edaWRITE_RAM_ONLY_WITH_ACTION, &ucSetting);
                }
            }
#else
            //G100_Steven_0055 start, PrimaryInput 連動當下 main input
        	UINT8 ucBK_PriInput = palDataMgr_BKInput_Trans2_CMInput(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput);

        	//palDataMgr_BKInput_SetCurMainInput();
            halFrontEndCtrl_Backup_First_Set ((UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupPrimaryInput);
            halFrontEndCtrl_Backup_Second_Set((UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackupSecondaryInput);
            //palDataPath_BackupInput(eSOURCE_WINDOW_MAIN, *((UINT8*)pValue));

            #if 0  //A35G2_CDS_Simon_0036 remove
        	if(!palDataMgr_GetBackupRestoreExecution()) //G100_Steven_0064
        	{
        		if(ucBK_PriInput != m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain)
        		{
        			palDataMgr_Access_MainInput(eAccessMode, (void *)&ucBK_PriInput);
        			palLANProcSendToLAN(edcMAIN_INPUT);
        		} //G100_Steven_0055 end
        	}
        	#endif
#endif /* SCALER_FPGA_F34 */
        }

        palLANProcSendToLAN(edcBACKUPINPUT_PRIMARY_RESOLUTION);
        palLANProcSendToLAN(edcBACKUPINPUT_PRIMARY_HORZRATE);
        palLANProcSendToLAN(edcBACKUPINPUT_PRIMARY_COLORSPACE);
        palLANProcSendToLAN(edcFIRST_INPUT_HDR_INFO);

        palLANProcSendToLAN(edcBACKUPINPUT_SECONDARY_RESOLUTION);
        palLANProcSendToLAN(edcBACKUPINPUT_SECONDARY_HORZRATE);
        palLANProcSendToLAN(edcBACKUPINPUT_SECONDARY_COLORSPACE);
        palLANProcSendToLAN(edcSECOND_INPUT_HDR_INFO);

        palLANProcSendToLAN(edcBACKUPINPUT_SECONDARY_INPUT);   //A35G2_CDS_Simon_0025
    }

    return eEXEC_CODE_PASS;
}

