eEXEC_CODE palDataMgr_CustomerSplah(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LV_Larry_0235
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        #if defined(CUSTOM_OPTOMA) //A35G2_Coda_0063
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucDefaultLogo;
        #else
        *((UINT8*)pValue) = palSystem_CustomerSplashGet();
        #endif
    }
    else  //Write Function
    {
    #if defined(CUSTOM_OPTOMA) //A35G2_Coda_0063
         //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucDefaultLogo = *((UINT8 *)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_CUSTOM_DEFAULT_LOGO, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucDefaultLogo);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
        //    palSystem_CustomerSplah(ucCustomerSplash);
        //    palSystem_PowerDown();
            palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
        }

    #else
        //Update RAM
        UINT8 ucCustomerSplash = *((UINT8*)pValue);
        palSystem_CustomerSplashSet(ucCustomerSplash);


        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            UINT8 ucCount = 0;
            //UINT8 ucGuiPresetMode = 0;
			UINT8 ucPresetMode = 0;

            if(ucCustomerSplash == CUSTOM_LOGO_SCREENX)
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement = eCONTRAST_ENHANCE_REAL_BLACK;
                utilDataMgr_CommonSet_CM(eDF_CONTRASTENHANCEMENT, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement);

                //ucGuiPresetMode = (UINT8)CM2GUI(edcPICTURE_SETTINGS, eCM_PICTURE_SETTINGS_BLENDING);
                ucPresetMode = eCM_PICTURE_SETTINGS_BLENDING;

                for(ucCount = 0; ucCount < INPUT_SOURCE_MAX; ucCount++)
                {
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucCount].ucPresetMode = eCM_PICTURE_SETTINGS_BLENDING;
                    utilDataMgr_SourceColorSet_CM(eDFS_PRESETMODE, ucCount, 0, &ucPresetMode);
                }
            }
            else
            {
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement = eCONTRAST_ENHANCE_OFF;
                utilDataMgr_CommonSet_CM(eDF_CONTRASTENHANCEMENT, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement);

                //ucGuiPresetMode = (UINT8)CM2GUI(edcPICTURE_SETTINGS, eCM_PICTURE_SETTINGS_BRIGHT);
                ucPresetMode = eCM_PICTURE_SETTINGS_BRIGHT;

                for(ucCount = 0; ucCount < INPUT_SOURCE_MAX; ucCount++)
                {
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucCount].ucPresetMode = eCM_PICTURE_SETTINGS_BRIGHT;
                    utilDataMgr_SourceColorSet_CM(eDFS_PRESETMODE, ucCount, 0, &ucPresetMode);
                }
            }

            palDataMgr_sSourceDependSetting_Init_Default();
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palSystem_CustomerSplah(ucCustomerSplash);
            palSystem_PowerDown();
        }
    #endif
    }

    return eEXEC_CODE_PASS;
}

