eEXEC_CODE palDataMgr_NetworkWaitMessage(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LV_Larry_0278
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sSystemValues.ucNetworkWaitMessage;
    }
    else  //Write Function
    {
        UINT8 ucState = *((UINT8 *)pValue);

        LOG_MSG(db_APP_LAN, "palDataMgr_NetworkWaitMessage %d \n", ucState);

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            if(ucState == 3) //A70LV_Larry_0411
            {
                m_sAppDataMgrInfo.sSystemValues.ucNetworkWaitMessage = ucState;
                //palDataMgr_UI_EventSend(edcUI_EVENT_MENUOPEN_WAIT_MSG, TRUE, NULL);
                palEnvironment_NetworkWaitMessage(60);
                //halBoard_LAN_Reset_Set(10);
            }

            //Todo
            if((ucState == 0)) //G100 code move to appgui
            {
                palEnvironment_NetworkWaitMessage(0);
                MS_SLEEP(100);
                m_sAppDataMgrInfo.sSystemValues.ucNetworkResetFlag = 0;
            }

            if(m_sAppDataMgrInfo.sSystemValues.ucNetworkWaitMessage <= eCM_NETWORK_STATUS_MESSAGE_SUCCESS)
            {
                m_sAppDataMgrInfo.sSystemValues.ucNetworkWaitMessage = ucState;
            }
            palLANProcSendToLAN(edcNETWORK_MESSAGE);
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_NetworkStatusMessage(eDATA_ACCESS_MODE eAccessMode, void *pValue)//A70Gen2_Julie_0042
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sSystemValues.ucNetworkStatusMessage;
    }
    else  //Write Function
    {
        UINT8 ucState = *((UINT8 *)pValue);

        m_sAppDataMgrInfo.sSystemValues.ucNetworkStatusMessage = ucState;

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
        #ifdef NETWORK_IP_DHCP //HICC2_Julie_0064
            if(ucState == eCM_NETWORK_STATUS_MESSAGE_PROCESSING)
            {
                palEnvironment_NetworkStatusMessage(60);
            }

            if(ucState == eCM_NETWORK_STATUS_MESSAGE_IDLE)
            {
                palEnvironment_NetworkStatusMessage(0);
                MS_SLEEP(100);
                m_sAppDataMgrInfo.sSystemValues.ucNetworkResetFlag = 0;

                if(m_sAppDataMgrInfo.sSystemValues.ucNetworkWaitMessage == TRUE)
                {
                    m_sAppDataMgrInfo.sSystemValues.ucNetworkWaitMessage = 0;
                }
            }

            palLANProcSendToLAN(edcNETWORK_STATUS_MESSAGE);
            palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
        #endif
        }
    }

    return eEXEC_CODE_PASS;
}

