eEXEC_CODE palDataMgr_FanFilter(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LV_Larry_0287
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        char aucString[16] = {0}; //A70LV_Larry_0293

        //eFILTER_TYPE_FOG        = 0x00,
        //eFILTER_TYPE_NOFILTER1  = 0x01,
        //eFILTER_TYPE_NOFILTER2  = 0x02,
        //eFILTER_TYPE_NOFILTER   = 0x03,
        //m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucFanFilter = eFILTER_TYPE_NOFILTER;	//HICC2_Doulas_0009 remove

        if(m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucFanFilter == eFILTER_TYPE_FOG)
        {
            sprintf((char *)aucString, "Fog Filter");
        }
        else if(m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucFanFilter == eFILTER_TYPE_NOFILTER_R)
        {
            sprintf((char *)aucString, "Unknown Filter");//Unknow Type R"); //HICC2_Doulas_0060
        }
        else if(m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucFanFilter == eFILTER_TYPE_NOFILTER_L)
        {
            sprintf((char *)aucString, "Unknown Filter");//"Unknow Type L"); //HICC2_Doulas_0060
        }
        else
        {
            sprintf((char *)aucString, "No Filter");
        }

        memcpy((INT8 *)pValue, aucString, strlen((char *)aucString)+1);
    }
    else  //Write Function
    {
        m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucFanFilter = *((UINT8 *)pValue);

        if(m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucHighAltitudeEnable == 0xFF)
        {
            m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucHighAltitudeEnable = m_sAppDataMgrInfo.sSystemValues.sFAN_INFO.ucFanFilter;

            palLANProcSendToLAN(edcHIGH_ALTITUDE);//HICC2_Julie_0020
        }
    }

    return eEXEC_CODE_PASS;
}


