eEXEC_CODE palDataMgr_Service_LightSourceHours(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
		*((UINT32*)pValue) = (UINT32)m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinute[eTIMER_RECORD_BLD] / 60;
    }
    else  //Write Function
    {
        //Update RAM
        UINT32 ulHours = *((UINT32*)pValue);

        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinute[eTIMER_RECORD_BLD]  = ulHours*60;

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_LIGHTSOURCEMINUTE_B, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinute[eTIMER_RECORD_BLD]);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palIllumination_Init_LDHoursSet(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinute[eTIMER_RECORD_BLD]);
			palLANProcSendToLAN(edcLIGHT_SOURCE_HOURS); //A70LV_Larry_0310
            palLANProcSendToLAN(edcSERVICE_LIGHT_SOURCE_HOUR);
            palLANProcSendToLAN(edcLD_HOURS_INFO); //HICC2_Doulas_0061
        }
    }

    return eEXEC_CODE_PASS;
}

