    				    MS_SLEEP(100);
                        palDataMgr_UI_EventSend(edcUI_EVENT_WAIT_PROCESS_MESSAGE_EXIT, 2, NULL);
					//LOG_MSG(db_ALWAYS,"Restore fail\r\n");
