// HICC20_Keven_0002, for four modes of projection
eEXEC_CODE palDataMgr_Access_ProjectionMode(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8  ucValue = 0;
    UINT8  ucValue_Rear;
    INT32  iDataCeiling = 0;
    INT32  iDataRear = 0;

    if (edaREAD == eAccessMode)  //Read Function
    {

        iDataCeiling = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucCeilingMount;
        iDataRear =  m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucRearProject;
        if(iDataCeiling==0 && iDataRear==0)
        *((UINT8 *)pValue) = ePROJECTION_MODE_FRONT;
        else if(iDataCeiling==1 && iDataRear==0)
        *((UINT8 *)pValue) = ePROJECTION_MODE_FRONT_CEILING;
        else if(iDataCeiling==0 && iDataRear==1)
        *((UINT8 *)pValue) = ePROJECTION_MODE_REAR;
        else if(iDataCeiling==1 && iDataRear==1)
        *((UINT8 *)pValue) = ePROJECTION_MODE_REAR_CEILING;

    }

    else  //Write Function
    {

        UINT8 ucCeiling = eCM_CEILING_MOUNT_OFF;
        UINT8 ucRear = eCM_CEILING_MOUNT_AUTO;
        ucValue = *((UINT8 *)pValue);

        switch(ucValue)
        {
            case ePROJECTION_MODE_FRONT:
                 ucCeiling = CLI_CEILING_MOUNT_OFF;
                 ucRear = CLI_REAR_PROJECTION_FRONT;
                 break;

            case ePROJECTION_MODE_REAR:
                 ucCeiling = CLI_CEILING_MOUNT_OFF;
                 ucRear = CLI_REAR_PROJECTION_REAR;
                 break;

            case ePROJECTION_MODE_REAR_CEILING:
                 ucCeiling = CLI_CEILING_MOUNT_ON;
                 ucRear = CLI_REAR_PROJECTION_REAR;
                 break;

            case ePROJECTION_MODE_FRONT_CEILING:
                 ucCeiling = CLI_CEILING_MOUNT_ON;
                 ucRear = CLI_REAR_PROJECTION_FRONT;
                 break;
        }

        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucRearProject = ucRear;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucCeilingMount = ucCeiling;


        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_REARPROJECT, &ucRear);
            utilDataMgr_CommonSet_CM(eDF_CEILINGMOUNT, &ucCeiling);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

            palFormatterMgr_CeilingMount_RearProjectSet(palMotorEvent_CeilingGet(),
                             (BOOL)m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucRearProject);    //A70LV_Doulas_0062 modify
            palLANProcSendToLAN(edcORIENTATION_STATE);

            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucCeilingMount)
            {
                palMotorEvent_CeilingSet(TRUE);
            }
            else
            {
                palMotorEvent_CeilingSet(FALSE);
            }

            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucRearProject)
            {
                palMotorEvent_RearSet(TRUE);
            }
            else
            {
                palMotorEvent_RearSet(FALSE);
            }

            #if (ENABLE_COLOR_UNIFORMITY == TRUE)				//G100_Tim_0020, add, start  //A65_OPTOMA_CL_0005 //A35G2_Coda_0075
            if( palGeo_Color_Uniformity_Init_Status_Get() == WARPING_ACU_INIT_DONE )
            {
                palDataPath_Color_Uniformity_Recheck();
            }
		    #endif //ENABLE_COLOR_UNIFORMITY					//G100_Tim_0020, add, end
        }

    }

    return eEXEC_CODE_PASS;

}

