eEXEC_CODE palDataMgr_Access_BackGround_Color(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //ZU860_Doulas_0006 modify
{
	if(edaREAD == eAccessMode)   //Read Function
	{
#ifdef CURSOR_FIXTURE
		*((UINT8*)pValue) = eCM_BACKGROUND_COLOR_BLUE;
#else
		*((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackgroundColor;
#endif
	}
	else  //Write Function
	{
		//Update RAM
		m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackgroundColor = *((UINT8*)pValue);

		//Storage : EEPROM
		if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
		{
            //UINT8 ucGuiValue = (UINT8)CM2GUI(edcBACKGROUND_COLOR, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_BACKGROUND_COLOR, (UINT8*)pValue);
		}

    #ifdef CUSTOM_OPTOMA //A35G2_Coda_0067
        //Execute Action function
		if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
		{
            UINT8 ucValue = 0;

            palDataMgr_Access_LogoChange(edaREAD, &ucValue);	//A65_OPTOMA_Doulas_0127
			if(ucValue != eCM_CHANGE_LOGO_DEFAULT)					//A65_OPTOMA_Doulas_0127 Modify
			{
				ucValue = eCM_CHANGE_LOGO_DEFAULT;
				palDataMgr_Access_LogoChange(eAccessMode, &ucValue);
			}

            eLOGO_OSD_DRIVER eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;

            switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackgroundColor)
            {
                case eCM_BACKGROUND_COLOR_BLUE:
                    eCurrentSplash = eLOGO_OSD_DRIVER_BLUE;
                    break;

                case eCM_BACKGROUND_COLOR_BLACK:
                    eCurrentSplash = eLOGO_OSD_DRIVER_BLACK;
                    break;

                case eCM_BACKGROUND_COLOR_WHITE: //EK816U_626U_Energy_0020
                    eCurrentSplash = eLOGO_OSD_DRIVER_WHITE;
                    break;

                case eCM_BACKGROUND_COLOR_RED:
                    eCurrentSplash = eLOGO_OSD_DRIVER_RED;
                    break;

                case eCM_BACKGROUND_COLOR_GREEN:
                    eCurrentSplash = eLOGO_OSD_DRIVER_GREEN;
                    break;

                case eCM_BACKGROUND_COLOR_GRAY:
                    eCurrentSplash = eLOGO_OSD_DRIVER_GRAY;
                    break;

                default:
                    eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;
                    break;
            }

            palDataMgr_UI_EventSend(edcUI_EVENT_CURRENT_SPLASH, eCurrentSplash, NULL);
            palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);	//A65_OPTOMA_Doulas_0127
		}
    #else
		//Execute Action function
		if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
		{
			if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucSplashStartupEnable == eCM_LOGO_PATTERN_FACTORY_LOGO)
			{
                UINT8 ucValue = 0;
                switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackgroundColor)  //G100_Owen_0048
                {
                    case eCM_BACKGROUND_COLOR_BLUE:
                    case eCM_BACKGROUND_COLOR_BLACK:
                    case eCM_BACKGROUND_COLOR_WHITE:
                        palDataMgr_Access_LogoChange(edaREAD, &ucValue);
                        if(ucValue == eCM_CHANGE_LOGO_CAPTURED)
                        {
                            ucValue = eCM_CHANGE_LOGO_DEFAULT;
                            palDataMgr_Access_LogoChange(eAccessMode, &ucValue);
                        }
                        break;
                }

                eLOGO_OSD_DRIVER eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;

                switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackgroundColor)
                {
                    case eCM_BACKGROUND_COLOR_BLUE:
                        eCurrentSplash = eLOGO_OSD_DRIVER_BLUE;
                        break;

                    case eCM_BACKGROUND_COLOR_BLACK:
                        eCurrentSplash = eLOGO_OSD_DRIVER_BLACK;
                        break;

                    case eCM_BACKGROUND_COLOR_WHITE: //EK816U_626U_Energy_0020
                        eCurrentSplash = eLOGO_OSD_DRIVER_WHITE;
                        break;

                    default:
                        eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;
                        break;
                }

                palDataMgr_UI_EventSend(edcUI_EVENT_CURRENT_SPLASH, eCurrentSplash, NULL);
			}

		}
    #endif
	}
	return eEXEC_CODE_PASS;
}

