eEXEC_CODE palDataMgr_Access_Dynamic_Black(eDATA_ACCESS_MODE eAccessMode, void *pValue) //ZU860_Doulas_0006 modify
{
    if(edaREAD == eAccessMode)   //Read Function
    {
        switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement)
        {
            case eCONTRAST_ENHANCE_DYNAMIC_BLACK:
            //case eCONTRAST_ENHANCE_DYNAMIC_BLACK_REAL_BLACK:
                *((UINT8*)pValue) = ets_ON;
                break;

            default:
                *((UINT8*)pValue) = ets_OFF;
                break;
        }
    }
    else  //Write Function
    {
        UINT8 ucSetting = eCONTRAST_ENHANCE_OFF;

        if(*((UINT8*)pValue) == ets_ON)
        {
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement == eCONTRAST_ENHANCE_OFF)
            {
                ucSetting = eCONTRAST_ENHANCE_DYNAMIC_BLACK;
                palDataMgr_Access_ContrastEnhancement(eAccessMode, (void*)&ucSetting);
            }
        }
        else if(*((UINT8*)pValue) == ets_OFF)
        {
            if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucContrastEnhancement == eCONTRAST_ENHANCE_DYNAMIC_BLACK)
            {
                ucSetting = eCONTRAST_ENHANCE_OFF;
                palDataMgr_Access_ContrastEnhancement(eAccessMode, (void*)&ucSetting);
            }
        }

        palLANProcSendToLAN(edcCONTRAST_ENHANCEMENT);
        palLANProcSendToLAN(edcDYNAMIC_BLACK);
        palLANProcSendToLAN(edcDB_SPEED);
        palLANProcSendToLAN(edcDB_STRENGTH);
        palLANProcSendToLAN(edcDB_LIGHT_LEVEL);
        palLANProcSendToLAN(edcREAL_BLACK);
        palLANProcSendToLAN(edcLIGHTS_OUT_TIMER_X05);
        palLANProcSendToLAN(edcLIGHTS_OUT_SIGNAL_LEVEL);
        palLANProcSendToLAN(edcLIGHTS_ON_THRESHOLD);
    }
    return eEXEC_CODE_PASS;
}

