eEXEC_CODE palDataMgr_Access_Backup_Restore_Web_Save(eDATA_ACCESS_MODE eAccessMode, void *pValue) //G100_Doulas_0004
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = ucWeb_Backup;
    }
    else  //Write Function
    {
        UINT8 ucIndex = *((UINT8*)pValue);
		UINT8 ucResult = eEXEC_CODE_FAIL;

        if(ucIndex < eBACKUP_RESTORE_MAX_NUMBER)
        {
            //Update Ram
            ucWeb_Backup = ucIndex;

            //Storage : EEPROM
            if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
            {
                //utilDataMgr_CommonSet_CM(eDF_BACKUPRESTORESAVE, (UINT8*)pValue);
            }

            //Execute Action function
            if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
            {
                eDATA_CODE eDataCode = edcBACKUP_RESTORE_WEB_SAVE_RESULT;
                ucWeb_Backup_Result = eBACKUP_RESTORE_RESULT_PROCESSING;
                palDataMgr_ImportDataToDatabase(eDataCode);
                utilIpc_SendData(eIPC_SEND_DATA_UPDATE_DATACODE_ITEM, 0, &eDataCode, eEXEC_CODE_PASS, sizeof(UINT16)*1);//HICC2_Julie_0053

                if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucImageFreeze) //G100_Larry_0039
                {
                    ucWeb_Backup_Result = eBACKUP_RESTORE_RESULT_FAIL;
					palLANProcSendToLAN((UINT16)edcBACKUP_RESTORE_WEB_SAVE_RESULT);
                    return eEXEC_CODE_FAIL;
                }

                palDataMgr_ResetCountSet(__FUNCTION__, 60);
                ucResult = utilDataMgr_WebBackupSave_CM(ucIndex);	//HICC2_Doulas_0003
				//LOG_MSG(db_ALWAYS,"palDataMgr_Access_Backup_Restore_Web_Save %d\r\n",ucResult);		//G100_Doulas_0030
                palDataMgr_ResetCountSet(__FUNCTION__, 0);
				if(ucResult == eEXEC_CODE_FAIL)
				{
					ucWeb_Backup_Result = eBACKUP_RESTORE_RESULT_FAIL;		//G100_Doulas_0031
					palLANProcSendToLAN((UINT16)edcBACKUP_RESTORE_WEB_SAVE_RESULT);		//G100_Doulas_0070
					return eEXEC_CODE_FAIL;
				}
				else
				{
					ucWeb_Backup_Result = eBACKUP_RESTORE_RESULT_PASS;		//G100_Doulas_0031
				}
            }
        }
        else
        {
        	ucWeb_Backup_Result = eBACKUP_RESTORE_RESULT_INDEX_FAIL;		//G100_Doulas_0031
        	palLANProcSendToLAN((UINT16)edcBACKUP_RESTORE_WEB_SAVE_RESULT);		//G100_Doulas_0070
            return eEXEC_CODE_FAIL;
        }
		palLANProcSendToLAN((UINT16)edcBACKUP_RESTORE_WEB_SAVE_RESULT);		//G100_Doulas_0034
    }

    return eEXEC_CODE_PASS;
}

