eEXEC_CODE palDataMgr_Access_Blending_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue) //G100_Owen_0009
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = ets_OFF;
    }
    else  //Write Function
    {
        UINT16 uiCount = 0;

        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingGamma = eCM_BLENDING_GAMMA_2_2; //A70LV_Larry_0308

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendApplySetting = BLEND_APPLY_DEFAULT_VALUE;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendSaveSetting = BLEND_SAVE_DEFAULT_VALUE;

        //Blending
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingTopEnable = 0;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingBottomEnable = 0;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingLeftEnable = 0;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingRightEnable = 0;

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingTopStartPixel = BLENDING_TOP_START_PIXEL_DEF_VALUE;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingBottomStartPixel = BLENDING_BOTTOM_START_PIXEL_DEF_VALUE;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingLeftStartPixel = BLENDING_LEFT_START_PIXEL_DEF_VALUE;
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingRightStartPixel = BLENDING_RIGHT_START_PIXEL_DEF_VALUE;

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingTopPixelWidth = BLENDING_TOP_PIXEL_WIDTH_DEF_VALUE; //A70LV_Larry_0224
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingBottomPixelWidth = BLENDING_BOTTOM_PIXEL_WIDTH_DEF_VALUE; //A70LV_Larry_0224
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingLeftPixelWidth = BLENDING_LEFT_PIXEL_WIDTH_DEF_VALUE; //A70LV_Larry_0224
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingRightPixelWidth = BLENDING_RIGHT_PIXEL_WIDTH_DEF_VALUE; //A70LV_Larry_0224

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //Memory
            utilDataMgr_CommonSet_CM(eDF_BLENDAPPLYSETTING,   &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendApplySetting);
            utilDataMgr_CommonSet_CM(eDF_BLENDSAVESETTING,    &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendSaveSetting);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGGAMMA,       &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingGamma);

            //Blending

            utilDataMgr_CommonSet_CM(eDF_BLENDINGTOPENABLE,    &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingTopEnable);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGBOTTOMENABLE, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingBottomEnable);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGLEFTENABLE,   &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingLeftEnable);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGRIGHTENABLE,  &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingRightEnable);

            utilDataMgr_CommonSet_CM(eDF_BLENDINGTOPSTARTPIXEL,    (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingTopStartPixel);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGBOTTOMSTARTPIXEL, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingBottomStartPixel);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGLEFTSTARTPIXEL,   (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingLeftStartPixel);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGRIGHTSTARTPIXEL,  (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingRightStartPixel);

            utilDataMgr_CommonSet_CM(eDF_BLENDINGTOPPIXELWIDTH,    (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingTopPixelWidth);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGBOTTOMPIXELWIDTH, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingBottomPixelWidth);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGLEFTPIXELWIDTH,   (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingLeftPixelWidth);
            utilDataMgr_CommonSet_CM(eDF_BLENDINGRIGHTPIXELWIDTH,  (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.uiBlendingRightPixelWidth);

        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palGeo_Egb_Off();
            palDataMgr_MenuOffsetUpdateForEdgeBlending();
        }

        for(uiCount = edcBLENDING_TOP_ENABLE; uiCount <= edcBLENDING_RIGHT_PIXEL_WIDTH; uiCount++)
        {
            palLANProcSendToLAN(uiCount);
        }
        palLANProcSendToLAN(edcBLENDING_GAMMA);
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_DynamicContrast_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //G100_Owen_0010
{
    if(edaREAD == eAccessMode)   //Read Function
    {
        *((UINT8 *)pValue) = ets_OFF;
    }
    else  //Write Function
    {
        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            INT32 lSetting = 0;

            palDataMgr_Data_Range_Get(edcCONTRAST_ENHANCEMENT, edrDEFAULT, &lSetting);
            palDataMgr_Access_ContrastEnhancement(eAccessMode, (void*)&lSetting);

            //Dynamic Black
            palDataMgr_Data_Range_Get(edcDYNAMIC_BLACK, edrDEFAULT, &lSetting);
            palDataMgr_Access_Dynamic_Black(eAccessMode, (void*)&lSetting);

            palDataMgr_Data_Range_Get(edcDB_SPEED, edrDEFAULT, &lSetting);
            palDataMgr_Access_DB_Speed(eAccessMode, (void*)&lSetting);

            palDataMgr_Data_Range_Get(edcDB_STRENGTH, edrDEFAULT, &lSetting);
            palDataMgr_Access_DB_Strength(eAccessMode, (void*)&lSetting);

            palDataMgr_Data_Range_Get(edcDB_LIGHT_LEVEL, edrDEFAULT, &lSetting);
            palDataMgr_Access_DB_Light_Level(eAccessMode, (void*)&lSetting);

            //Real Black
            palDataMgr_Data_Range_Get(edcREAL_BLACK, edrDEFAULT, &lSetting);
            palDataMgr_Access_Real_Black(eAccessMode, (void*)&lSetting);

            palDataMgr_Data_Range_Get(edcLIGHTS_OUT_TIMER_X05, edrDEFAULT, &lSetting);
            palDataMgr_LightsOutTimer05x(eAccessMode, (void*)&lSetting);

			palDataMgr_Data_Range_Get(edcLIGHTS_ON_THRESHOLD, edrDEFAULT, &lSetting);	//A70Gen2_Doulas_0044
            palDataMgr_LightsOnThreshold(eAccessMode, (void*)&lSetting);				//A70Gen2_Doulas_0044

            palDataMgr_Data_Range_Get(edcLIGHTS_OUT_SIGNAL_LEVEL, edrDEFAULT, &lSetting);
            palDataMgr_LightsOutSignalLevel(eAccessMode, (void*)&lSetting);

            palLANProcSendToLAN(edcCONTRAST_ENHANCEMENT);
            palLANProcSendToLAN(edcDYNAMIC_BLACK);
            palLANProcSendToLAN(edcDB_SPEED);
            palLANProcSendToLAN(edcDB_STRENGTH);
            palLANProcSendToLAN(edcDB_LIGHT_LEVEL);
            palLANProcSendToLAN(edcREAL_BLACK);
            palLANProcSendToLAN(edcLIGHTS_OUT_TIMER_X05);
            palLANProcSendToLAN(edcLIGHTS_OUT_SIGNAL_LEVEL);    //G100_Simon_0021
            palLANProcSendToLAN(edcLIGHTS_ON_THRESHOLD);
        }
    }

    return eEXEC_CODE_PASS;
}

