eEXEC_CODE palDataMgr_AccessADV_BlackLevelBrightnessSetting(eDATA_ACCESS_MODE eAccessMode, void *pValue)		//A65_OPTOMA_Doulas_0020
{
	UINT8 ucBlackLevelArea = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelArea;
    if (edaREAD == eAccessMode)  //Read Function
    {
    	m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBrightness = BLACKLEVEL_VALUE_R; //value not change
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBrightness;
    }
    else  //Write Function
    {
    	UINT8 ucVal = *((UINT8*)pValue);
		UINT8 ucRed = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea];
		UINT8 ucGreen = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea];
		UINT8 ucBlue = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea];
		BOOL  bValueChanged = FALSE;

		//LOG_MSG(db_ALWAYS,"Brightness = %d\r\n",ucVal);

        //Update RAM
    	if(ucVal != BLACKLEVEL_VALUE_R)		//Value changed
    	{
			if(ucVal > BLACKLEVEL_VALUE_R)
			{
				if(((INT16)ucRed + (INT16)ucVal - BLACKLEVEL_VALUE_R) >= BLACKLEVEL_VALUE_MAX)
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea] = BLACKLEVEL_VALUE_MAX;
				}
				else
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea] += (ucVal - BLACKLEVEL_VALUE_R);
				}

				if(((INT16)ucGreen + (INT16)ucVal - BLACKLEVEL_VALUE_R) >= BLACKLEVEL_VALUE_MAX)
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea] = BLACKLEVEL_VALUE_MAX;
				}
				else
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea] += (ucVal - BLACKLEVEL_VALUE_R);
				}

				if(((INT16)ucBlue + (INT16)ucVal - BLACKLEVEL_VALUE_R) >= BLACKLEVEL_VALUE_MAX)
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea] = BLACKLEVEL_VALUE_MAX;
				}
				else
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea] += (ucVal - BLACKLEVEL_VALUE_R);
				}

			}
			else
			{
				if(((INT16)ucRed + (INT16)ucVal - BLACKLEVEL_VALUE_R) <= BLACKLEVEL_VALUE_MIN)
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea] = BLACKLEVEL_VALUE_MIN;
				}
				else
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea] -= (BLACKLEVEL_VALUE_R - ucVal);
				}

				if(((INT16)ucGreen + (INT16)ucVal - BLACKLEVEL_VALUE_R) <= BLACKLEVEL_VALUE_MIN)
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea] = BLACKLEVEL_VALUE_MIN;
				}
				else
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea] -= (BLACKLEVEL_VALUE_R - ucVal);
				}

				if(((INT16)ucBlue + (INT16)ucVal - BLACKLEVEL_VALUE_R) <= BLACKLEVEL_VALUE_MIN)
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea] = BLACKLEVEL_VALUE_MIN;
				}
				else
				{
					m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea] -= (BLACKLEVEL_VALUE_R - ucVal);
				}
			}

    		if( (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea]   != ucRed) ||
				(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea] != ucGreen) ||
				(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea] != ucBlue) )
			{
				bValueChanged = TRUE;
			}

        	//Storage : EEPROM
        	if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        	{
        		if(bValueChanged)
				{
					if(ucBlackLevelArea == BLACKLEVEL_AREA__BOTTOM)
	           		{
	            		utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_RED_BOTTOM, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea]);
						utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_GREEN_BOTTOM, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea]);
						utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_BLUE_BOTTOM, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea]);
	           		}
					else
					{
						utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_RED_TOP, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea]);
						utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_GREEN_TOP, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea]);
						utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_BLUE_TOP, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea]);
					}
				}
        	}

        	//Execute Action function
        	if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        	{
        		if(bValueChanged)
				{
					palGeo_AdvBlackLevel_SetRed(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[ucBlackLevelArea]);  //H2PF_Simon_0106
					palGeo_AdvBlackLevel_SetGreen(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[ucBlackLevelArea]);
					palGeo_AdvBlackLevel_SetBlue(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[ucBlackLevelArea]);
				}
        	}

			if(bValueChanged)
			{
				palLANProcSendToLAN(edcADV_BLACK_LEVEL_RED);
				palLANProcSendToLAN(edcADV_BLACK_LEVEL_GREEN);
				palLANProcSendToLAN(edcADV_BLACK_LEVEL_BLUE);
			}
        }
    }

    return eEXEC_CODE_PASS;
}

