eEXEC_CODE palDataMgr_AccessADV_BlackLevelReset(eDATA_ACCESS_MODE eAccessMode, void *pValue)		//A65_OPTOMA_Doulas_0029 Modify//A65_OPTOMA_Doulas_0020
{
	UINT8 ucBlackLevelArea = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelArea;
	if (edaREAD == eAccessMode)  //Read Function
	{
		*((UINT8*)pValue) = ets_ON;
	}
	else  //Write Function
	{
		UINT8 ucVal = *((UINT8*)pValue);
		//LOG_MSG(db_ALWAYS,"palDataMgr_AccessADV_BlackLevelReset %d\r\n",ucVal);	//A65_OPTOMA_Doulas_0037 remove
		//Update RAM
        if(ucVal ==	eBLACK_LEVEL_RESET_ALL)
		{
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelArea = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelArea;
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__BOTTOM];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__TOP];

			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__BOTTOM];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__BOTTOM];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__BOTTOM];

			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__TOP];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__TOP];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__TOP];
		}
		else if(ucVal == eBLACK_LEVEL_RESET_BOTTOM)
		{
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__BOTTOM];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__BOTTOM];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__BOTTOM];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__BOTTOM] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__BOTTOM];
		}
		else if(ucVal == eBLACK_LEVEL_RESET_TOP)
		{
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__TOP];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__TOP];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__TOP];
			m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__TOP] = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__TOP];
		}
		m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBoundary = m_sDefSysSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBoundary;		//A35G2_Owen_0002 //A65_OPTOMA_Doulas_0239

		//Storage : EEPROM
		if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
		{
			if(ucVal ==	eBLACK_LEVEL_RESET_ALL)
			{
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_AREA,          &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelArea);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_ENABLE_BOTTOM, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__BOTTOM]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_ENABLE_TOP,    &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__TOP]);

				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_RED_BOTTOM,  &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__BOTTOM]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_GREEN_BOTTOM,&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__BOTTOM]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_BLUE_BOTTOM, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__BOTTOM]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_RED_TOP,     &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__TOP]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_GREEN_TOP,   &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__TOP]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_BLUE_TOP,    &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__TOP]);
			}
			else if(ucVal == eBLACK_LEVEL_RESET_BOTTOM)
			{
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_ENABLE_BOTTOM, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__BOTTOM]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_RED_BOTTOM,  &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__BOTTOM]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_GREEN_BOTTOM,&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__BOTTOM]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_BLUE_BOTTOM, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__BOTTOM]);
			}
			else if(ucVal == eBLACK_LEVEL_RESET_TOP)
			{
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_ENABLE_TOP,    &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__TOP]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_RED_TOP,     &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__TOP]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_GREEN_TOP,   &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__TOP]);
				utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_BLUE_TOP,    &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__TOP]);
			}
#if defined(CUSTOM_OPTOMA)
			utilDataMgr_CommonSet_CM(eDF_ADV_BLACK_LEVEL_BOUNDARY,    &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBoundary);	//A35G2_Owen_0002 //A65_OPTOMA_Doulas_0239
#endif
		}

		//Execute Action function
		if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
		{
			m_ucResetCount = 45;	//A65_OPTOMA_Doulas_0037
			palGeo_AdvBlackLevel_Reset(ucVal);  //H2PF_Simon_0106
			m_ucResetCount = 0;		//A65_OPTOMA_Doulas_0037
		}

		palLANProcSendToLAN(edcADV_BLACK_LEVEL_AREA);
		palLANProcSendToLAN(edcADV_BLACK_LEVEL_ENABLE);
		palLANProcSendToLAN(edcADV_BLACK_LEVEL_RED);
		palLANProcSendToLAN(edcADV_BLACK_LEVEL_GREEN);
		palLANProcSendToLAN(edcADV_BLACK_LEVEL_BLUE);
		palLANProcSendToLAN(edcADV_BLACK_LEVEL_BOUNDARY);	//A35G2_Owen_0002 //A65_OPTOMA_Doulas_0239
	}

	return eEXEC_CODE_PASS;
}


