eEXEC_CODE palDataMgr_Access_AW_WarpPoint_Position(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    sDST_AW_WARP_POINT_POSITION CurVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sAwWarpPointPosition;
    sDST_AW_WARP_POINT_POSITION NewVal = *((sDST_AW_WARP_POINT_POSITION *)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
        palGeo_AdvWarpGP_GetColPosition(&CurVal.PosX);
        palGeo_AdvWarpGP_GetRowPosition(&CurVal.PosY);
        memcpy(pValue, &CurVal, sizeof(CurVal));
    }
    else  //Write Function
    {
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sAwWarpPointPosition = NewVal;

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            if(palGeo_AdvWarpGP_SetPosition(NewVal.PosX, NewVal.PosY) != ePAL_GEO_EXEC_CODE_PASS)
            {
                return eEXEC_CODE_FAIL;
            }
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_AW_WarpPoint_All_Position(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *(UINT32 *)pValue = 0;
    }
    else  //Write Function
    {
        sDST_AW_WARP_POINT_ALL_POSITION sData;
        memset(&sData, 0, sizeof(sDST_AW_WARP_POINT_ALL_POSITION));
        if(utilMisc_GetFileData(WEB_PAGE_WARP_TMP_FILENAME, (UINT8 *)&sData, sizeof(sDST_AW_WARP_POINT_ALL_POSITION)) != UTILMISC_EXEC_PASS)
        {
            LOG_MSG(db_HAL_WARPING, "%s file read fail\r\n", WEB_PAGE_WARP_TMP_FILENAME);
            return eEXEC_CODE_FAIL;
        }

        LOG_MSG(db_HAL_WARPING, "ALL_POSITION Data\r\n");
        LOG_MSG(db_HAL_WARPING, " - [0][0]:[%f %f] [1][0]:[%f %f]\r\n", sData.ControlPoint[0][0].x, sData.ControlPoint[0][0].y, sData.ControlPoint[1][0].x, sData.ControlPoint[1][0].y);
        LOG_MSG(db_HAL_WARPING, " - GridNum        %d\r\n", sData.GridNum);
        LOG_MSG(db_HAL_WARPING, " - InnerEn        %d\r\n", sData.InnerEn);
        LOG_MSG(db_HAL_WARPING, " - Sharpness      %d\r\n", sData.Sharpness);
        LOG_MSG(db_HAL_WARPING, " - GridColor      %d\r\n", sData.GridColor);
        LOG_MSG(db_HAL_WARPING, " - GridBackground %d\r\n", sData.GridBackground);
        LOG_MSG(db_HAL_WARPING, " - HeaderStr      %s\r\n", sData.HeaderStr);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            // Grid Color
            //palDataMgr_AccessADV_WarpGridColor(eAccessMode, &sData.GridColor);
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpGridColor = (UINT8)sData.GridColor;
            utilDataMgr_CommonSet_CM(eDF_ADV_WARP_GRIDCOLOR, (UINT8*)&sData.GridColor);
            palGeo_AdvWarpGridColor(sData.GridColor, FALSE);   //no redraw pattern

            // BG Color
            palDataMgr_AccessADV_WarpBackground(eAccessMode, &sData.GridBackground);
            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpBackgroundColor = (UINT8)sData.GridBackground;
            utilDataMgr_CommonSet_CM(eDF_ADV_WARP_GRIDBACKGROUND, (UINT8*)&sData.GridBackground);
            palGeo_AdvWarpBackgroundColor(sData.GridBackground, FALSE);  //no redraw pattern

            // Inner
            palDataMgr_AccessADV_WarpInnerGridPoints(edaWRITE_THROUGH_NO_ACTION, &sData.InnerEn);  //no redraw pattern

            // Grid Points
            palDataMgr_AccessADV_WarpGridPoints(eAccessMode, &sData.GridNum);  //redraw pattern here

            // Sharpness
            palDataMgr_AccessADV_WarpSharpness(eAccessMode, &sData.Sharpness);

            // All Position
            Point2f ControlPoint[AW_WARP_H_POINT_NUM][AW_WARP_V_POINT_NUM];
            memcpy(ControlPoint, sData.ControlPoint, sizeof(Point2f));
            palGeo_AdvWarpGP_SetAllPosition(ControlPoint);

        }

        palLANProcSendToLAN(edcADV_WARP_GRID_POINTS);
        palLANProcSendToLAN(edcADV_WARP_INNER);
        palLANProcSendToLAN(edcADV_WARP_SHARPNESS);
        palLANProcSendToLAN(edcADV_WARP_GRID_COLOR);
        palLANProcSendToLAN(edcADV_WARP_GRID_BACKGROUND);
        palLANProcSendToLAN(edcAW_SEL_WARP_POINT_COL);
        palLANProcSendToLAN(edcAW_SEL_WARP_POINT_ROW);

    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_AW_WarpTable_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAwWarpTableReset;
    UINT8 NewVal = *((UINT8*)pValue);

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = CurVal;
    }
    else  //Write Function
    {
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAwWarpTableReset = NewVal;

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            if(palGeo_AdvWarp_SettingReset() == ePAL_GEO_EXEC_CODE_PASS)
            {
                palDataMgr_AdvReset_Execution(0);
            }
        }

        palLANProcSendToLAN(edcADV_WARP_GRID_POINTS);
        palLANProcSendToLAN(edcADV_WARP_INNER);
        palLANProcSendToLAN(edcADV_WARP_SHARPNESS);
        palLANProcSendToLAN(edcADV_WARP_GRID_COLOR);
        palLANProcSendToLAN(edcADV_WARP_GRID_BACKGROUND);
        palLANProcSendToLAN(edcAW_SEL_WARP_POINT_COL);
        palLANProcSendToLAN(edcAW_SEL_WARP_POINT_ROW);
    }

    return eEXEC_CODE_PASS;
}

