// Mem1 ~ Mem5
// save  mem datacode CMdatacode 1 ~ 5
// apply mem datacode CMdatacode 1 ~ 5
eEXEC_CODE palDataMgr_Access_Warping_Apply(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LV_Larry_0070 //A70LV_Larry_0318 modify
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting;
    }
    else  //Write Function
    {
        UINT8 ucValue = *((UINT8*)pValue);
        UINT8 MemIndex = ucValue;
        MemIndex = *((UINT8*)pValue);

        UINT8 WarpControl = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpControl;

        if(MemIndex < eCM_GEO_MEMORY_APPLY_NUMBER && MemIndex != eCM_GEO_MEMORY_APPLY_OFF)
        {
            if(palDataMgr_ApplyWarpMemoryItemAvailable(MemIndex) == 0)  //unsaved
            {
                return eEXEC_CODE_FAIL;
            }
        }

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting = *((UINT8*)pValue);

        LOG_MSG(db_HAL_WARPING, "Warp apply %d (Current Warp Control %d)\n", *((UINT8*)pValue), WarpControl);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_WARPINGAPPLYSETTING, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
			ePAL_GEO_EXEC_CODE eResult = ePAL_GEO_EXEC_CODE_FAIL;
			UINT8 ucMemoryIndex = 0 ;
			UINT8 ucApplyType = 0;

            if(*((UINT8*)pValue) == eCM_GEO_MEMORY_APPLY_OFF)  //set to Off , reset to default
            {
                palDataMgr_Access_ResetWarpingOnly();
                palLANProcSendToLAN(edcADV_WARP_GRID_POINTS);
                palLANProcSendToLAN(edcADV_WARP_INNER);
                palLANProcSendToLAN(edcADV_WARP_SHARPNESS);
                palLANProcSendToLAN(edcADV_WARP_GRID_COLOR);
                palLANProcSendToLAN(edcADV_WARP_GRID_BACKGROUND);
                palLANProcSendToLAN(edcAW_SEL_WARP_POINT_COL);
                palLANProcSendToLAN(edcAW_SEL_WARP_POINT_ROW);
                return eEXEC_CODE_PASS;
            }

            ucMemoryIndex = *((UINT8*)pValue);

            ucApplyType = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.sWarpMemory[ucMemoryIndex].ucWarpingApply;

            if(Syscfg_Value_Get_Typeint(eGeo_BehaviorType) == eGEO_SUPPORT_TWIST_MYSTIQUE)
            {
                if(palGeo_ApLinkFlag_Get() == TRUE)   //only save value, avoid show twice apply processing (apply table and apply memory)  //A35G2_Simon_0083  //A35G2_Simon_0086
                {
                    return eEXEC_CODE_PASS;
                }
            }

            if(ucMemoryIndex > WARPING_SAVE_MAX_VALUE)
            {
                return eEXEC_CODE_FAIL;
            }

            LOG_MSG(db_HAL_WARPING, "\nWarping Apply %d (Type %d)\n", ucMemoryIndex, ucApplyType );

            palGeo_CurrentWarpTypeSet(ucApplyType);   //A35G2_Simon_0115

            palLANProcSendToLAN(edcWARP_MEMORY_SAVE);  //HICC2_Simon_0019

            if(//ucApplyType == WARPING_TYPE_OSD_MYSTIQUE ||
               ucApplyType == WARPING_TYPE_AP_MYSTIQUE)
            {
                if(palGeo_AdvWarpShowOsdPattern_ParaGet() == PAT_TYPE__WARP_SEL_CTRL_POINT)
                {
                    palGeo_AdvWarpShowOsdPattern(PAT_TYPE__OFF);
                    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAwWarpPattern_Show = 0;
    			    palLANProcSendToLAN(edcAW_WARP_PATTERN_SHOW);
                }
            }

            //palDataMgr_ResetCountSet(__FUNCTION__, 45);  //HICC2_Simon_0009
		    switch(ucApplyType)
		    {
		        case WARPING_TYPE_ADVANCED:
		        case WARPING_TYPE_BASIC:
		            {
		                if(ucApplyType == WARPING_TYPE_BASIC)
		                {
		                    if(CFG_CUSTOMER_ID == CUSTOMER_ID_OPTOMA || CFG_CUSTOMER_ID == CUSTOMER_ID_BARCO)
                            {
		                        if(WarpControl == WARP_CTRL__ADVANCED)
                                {
                                    if(palGeo_AdvWarpShowOsdPattern_ParaGet() != PAT_TYPE__OFF)
                                    {
                                        //Disable warp grid pattern
                                        palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);
                                        if(palDataPath_IsSourceLock())
                                        {
                                            palDataMgr_UI_EventSend(edcUI_EVENT_SPLASH, 0, NULL);
                                        }
                                        else
                                        {
                                            palDataMgr_UI_EventSend(edcUI_EVENT_SPLASH, 1, NULL);
                                        }

                                        palGeo_AdvWarpShowOsdPattern(PAT_TYPE__OFF);
                                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAwWarpPattern_Show = 0;
                        			    palLANProcSendToLAN(edcAW_WARP_PATTERN_SHOW);
                                    }
                                }
                            }

                            eResult = palGeo_Apply_BasicWarpMemory(ucMemoryIndex); //HICC2_Doulas_0025
		                }
		                else
		                {
                            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpControl = WARP_CTRL__ADVANCED;

                            if(CFG_CUSTOMER_ID == CUSTOMER_ID_OPTOMA || CFG_CUSTOMER_ID == CUSTOMER_ID_BARCO)
                            {
                                if(WarpControl == WARPING_TYPE_BASIC)
                                {
                                    if(palGeo_AdvWarpShowOsdPattern_ParaGet() != PAT_TYPE__OFF)
                                    {
                                        //Disable warp grid pattern
                                        palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);
                                        if(palDataPath_IsSourceLock())
                                        {
                                            palDataMgr_UI_EventSend(edcUI_EVENT_SPLASH, 0, NULL);
                                        }
                                        else
                                        {
                                            palDataMgr_UI_EventSend(edcUI_EVENT_SPLASH, 1, NULL);
                                        }

                                        palGeo_AdvWarpShowOsdPattern(PAT_TYPE__OFF);
                                        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAwWarpPattern_Show = 0;
                        			    palLANProcSendToLAN(edcAW_WARP_PATTERN_SHOW);
                                    }
                                }
                            }
                            eResult = palGeo_Apply_AdvMemory(ucMemoryIndex); //HICC2_Doulas_0025
		                }

    				    if(eResult == ePAL_GEO_EXEC_CODE_PASS)
    					{
    						UINT8 ucWarpmode = 0;//utilWarp_GetWarpCtrl();
    						sWARP_BASIC stWarpingBasic;
    						sBLENDING_BASIC stBlendingBasic;
    						UINT16 uiKeystoneH = 1;
    						UINT16 uiKeystoneV = 1;
    						UINT16 uiPinwidH = 1;
    						UINT16 uiPinwidV = 1;
    						OSD_WARP stADVWarp;

                            if(ucApplyType == WARPING_TYPE_BASIC)
    		                {
                                ucWarpmode = WARP_CTRL__BASIC;
    		                }
    		                else if(ucApplyType == WARPING_TYPE_ADVANCED)
    		                {
                                ucWarpmode = WARP_CTRL__ADVANCED;
    		                }

    						palDataMgr_AccessADV_WarpControl(edaWRITE_THROUGH_NO_ACTION,&ucWarpmode);
    						if(ucApplyType == WARPING_TYPE_BASIC)
    						{
    							//Warping doing
    							halBasicWarpSettingGet();
    							//halBasicBlendSettingGet();
    							palGeo_Warp_GeometrySet();

                                if(Syscfg_Value_Get_Typeint(eGeo_BehaviorType) != eGEO_SUPPORT_TWIST_MYSTIQUE)
                                {
        							palGeo_Warp_BlendingSet();
                                }

    							palGeo_Func_Set(eGFN_CLI_BKLV_RESET, NULL);
    						}
    						else if(ucApplyType == WARPING_TYPE_ADVANCED)
    						{
    						}

    						palGeo_DBD_BlendingEnable(FALSE);  //H2PF_Simon_0104

    					//Update Basic Parameter
    						//Warping parameter update
                            palGeo_WarpingParameterAllGet((UINT8*)&stWarpingBasic);
                            palGeo_BlendParameterAllGet((UINT8*)&stBlendingBasic);
    						uiKeystoneH = (UINT16)((stWarpingBasic.PM_WPKEYANG_H/2) + KEYSTONE_BASED);
    						uiKeystoneV = (UINT16)(stWarpingBasic.PM_WPKEYANG_V + KEYSTONE_BASED);
    						uiPinwidH	= (UINT16)((stWarpingBasic.PM_WPPINWID_H/2) + PINBARREL_BASED);
    						uiPinwidV	= (UINT16)((stWarpingBasic.PM_WPPINWID_V/2) + PINBARREL_BASED);
    						palDataMgr_Access_HorizontalKeystone(edaWRITE_THROUGH_NO_ACTION,&uiKeystoneH);
    						palDataMgr_Access_VerticalKeystone(edaWRITE_THROUGH_NO_ACTION,&uiKeystoneV);
    						palDataMgr_Access_HorzPincushion(edaWRITE_THROUGH_NO_ACTION,&uiPinwidH);
    						palDataMgr_Access_VertPincushion(edaWRITE_THROUGH_NO_ACTION,&uiPinwidV);
    						palDataMgr_Access_4CornerTopLeftHorz(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_TLX);
    						palDataMgr_Access_4CornerTopLeftVert(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_TLY);
    						palDataMgr_Access_4CornerTopRightHorz(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_TRX);
    						palDataMgr_Access_4CornerTopRightVert(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_TRY);
    						palDataMgr_Access_4CornerBottomLeftHorz(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_BLX);
    						palDataMgr_Access_4CornerBottomLeftVert(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_BLY);
    						palDataMgr_Access_4CornerBottomRightHorz(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_BRX);
    						palDataMgr_Access_4CornerBottomRightVert(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.PM_WPKEY4C_BRY);
    						palDataMgr_Access_AutoWarpFilter(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.m_cWarpAutoFilter);
    						palDataMgr_Access_ManualWarpHorzFilter(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.m_cWarpFilterSelect_H);
    						palDataMgr_Access_ManualWarpVertFilter(edaWRITE_THROUGH_NO_ACTION,&stWarpingBasic.m_cWarpFilterSelect_V);

    						//Blending parameter update
    						palDataMgr_Access_BlendingTopEnable(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.ucBlending_T_Enable);
    						palDataMgr_Access_BlendingBottomEnable(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.ucBlending_B_Enable);
    						palDataMgr_Access_BlendingLeftEnable(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.ucBlending_L_Enable);
    						palDataMgr_Access_BlendingRightEnable(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.ucBlending_R_Enable);
    						palDataMgr_Access_BlendingTopStartPixel(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_T_St);
    						palDataMgr_Access_BlendingBottomStartPixel(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_B_St);
    						palDataMgr_Access_BlendingLeftStartPixel(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_L_St);
    						palDataMgr_Access_BlendingRightStartPixel(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_R_St);
    						palDataMgr_Access_BlendingTopPixelWidth(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_T_Width);
    						palDataMgr_Access_BlendingBottomPixelWidth(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_B_Width);
    						palDataMgr_Access_BlendingLeftPixelWidth(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_L_Width);
    						palDataMgr_Access_BlendingRightPixelWidth(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.uiBlending_R_Width);
    						palDataMgr_Access_BlendingGamma(edaWRITE_THROUGH_NO_ACTION,&stBlendingBasic.ucBlendingGamma);

    					//Update ADV Parameter
    						halADVWarpSettingGet(&stADVWarp);
    						palDataMgr_AccessADV_WarpGridPoints(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.eWarpPoint);	//17x17
    						palDataMgr_AccessADV_WarpInnerGridPoints(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.bWarpInnerOn);
    						palDataMgr_AccessADV_WarpSharpness(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.nWarpSharpness);
    						palDataMgr_AccessADV_WarpGridColor(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.eGridColor);
    						palDataMgr_AccessADV_WarpBackground(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.eBkgColor);
    						palDataMgr_AccessADV_BlendingOverlapGridNumber(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.nOverlapGridNum);
    						palDataMgr_AccessADV_BlendingGamma(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.nBlendGamma);

    						palDataMgr_ADV_Blend_LfRtTpBm_Update();

    						//apply black level
                            if(Syscfg_Value_Get_Typeint(eGeo_BlackLevelType) == eGEO_BLACKLEVEL_CLI_ONLY)
    						{
        						palGeo_Func_Set(eGFN_CLI_BKLV_RESET, NULL);

        						uPALGEOAPI_INFO uInfo = {.sGFN_CLI_BKLV_LOAD_DATA_INFO.Index = ucMemoryIndex-1};
        						palGeo_Func_Set(eGFN_CLI_BKLV_LOAD_DATA, &uInfo);
        				    }
    						else if(Syscfg_Value_Get_Typeint(eGeo_BlackLevelType) == eGEO_BLACKLEVEL_OSD)
    						{
    						    if(ucWarpmode == WARP_CTRL__ADVANCED)
    						    {
    						        UINT8 ucArea = BLACKLEVEL_AREA__TOP;
        							palDataMgr_AccessADV_BlackLevelSelectArea(edaWRITE_THROUGH_NO_ACTION,&ucArea);
        							palDataMgr_AccessADV_BlackLevelEnable(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.bEnable[BLACKLEVEL_AREA__TOP]);
        							palDataMgr_AccessADV_BlackLevelRedSetting(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__TOP+1][BLACKLEVEL_BT_RED]);
        							palDataMgr_AccessADV_BlackLevelGreenSetting(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__TOP+1][BLACKLEVEL_BT_GREEN]);
        							palDataMgr_AccessADV_BlackLevelBlueSetting(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__TOP+1][BLACKLEVEL_BT_BLUE]);

        							ucArea = BLACKLEVEL_AREA__BOTTOM;
        							palDataMgr_AccessADV_BlackLevelSelectArea(edaWRITE_THROUGH_NO_ACTION,&ucArea);
        							palDataMgr_AccessADV_BlackLevelEnable(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.bEnable[BLACKLEVEL_AREA__BOTTOM]);
        							palDataMgr_AccessADV_BlackLevelRedSetting(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__BOTTOM+1][BLACKLEVEL_BT_RED]);
        							palDataMgr_AccessADV_BlackLevelGreenSetting(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__BOTTOM+1][BLACKLEVEL_BT_GREEN]);
        							palDataMgr_AccessADV_BlackLevelBlueSetting(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__BOTTOM+1][BLACKLEVEL_BT_BLUE]);

        							palDataMgr_AccessADV_BlackLevelSelectArea(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.ucArea);
        							palDataMgr_AccessADV_BlackLevelBoundarySetting(edaWRITE_THROUGH_NO_ACTION,&stADVWarp.stBlackLevel.ucBoundary);	//A35G2_Owen_0002 //A65_OPTOMA_Doulas_0239
    							}
    							else
    							{
                                    palGeo_BlackLevel_Enable(FALSE);
    							}
							}
							else
							{
							    palGeo_BlackLevel_Enable(FALSE);  //H2PF_Simon_0104
							}


                            if(utilWarp_GetOsdPatternType() == PAT_TYPE__WARP_SEL_CTRL_POINT)
                            {
                                palGeo_AdvWarpShowOsdPattern(PAT_TYPE__WARP_SEL_CTRL_POINT);
                            }
                            else if(utilWarp_GetOsdPatternType() == PAT_TYPE__WARP_MOV_CTRL_POINT)
                            {
                                palGeo_AdvWarpShowOsdPattern(PAT_TYPE__WARP_MOV_CTRL_POINT);
                            }

    						//G100_Doulas_0073 Add
    						palLANProcSendToLAN(edcADV_WARP_CONTROL);
    						palLANProcSendToLAN(edcVERTICAL_KEYSTONE);
    						palLANProcSendToLAN(edcHORIZONTAL_KEYSTONE);
    						palLANProcSendToLAN(edcHORZ_PINCUSHION);
    						palLANProcSendToLAN(edcVERT_PINCUSHION);
    						palLANProcSendToLAN(edc4CORNER_TOP_LEFT_HORZ);
    						palLANProcSendToLAN(edc4CORNER_TOP_LEFT_VERT);
    						palLANProcSendToLAN(edc4CORNER_TOP_RIGHT_HORZ);
    						palLANProcSendToLAN(edc4CORNER_TOP_RIGHT_VERT);
    						palLANProcSendToLAN(edc4CORNER_BOTTOM_LEFT_HORZ);
    						palLANProcSendToLAN(edc4CORNER_BOTTOM_LEFT_VERT);
    						palLANProcSendToLAN(edc4CORNER_BOTTOM_RIGHT_HORZ);
    						palLANProcSendToLAN(edc4CORNER_BOTTOM_RIGHT_VERT);
    						palLANProcSendToLAN(edcAUTO_WARP_FILTER);       //HICC2_Doulas_0025
    						palLANProcSendToLAN(edcMANUAL_WARP_HORZ_FILTER);//HICC2_Doulas_0025
    						palLANProcSendToLAN(edcMANUAL_WARP_VERT_FILTER);//HICC2_Doulas_0025
    						palLANProcSendToLAN(edcADV_WARP_GRID_POINTS);
    						palLANProcSendToLAN(edcADV_WARP_INNER);
    						palLANProcSendToLAN(edcADV_WARP_SHARPNESS);
    						palLANProcSendToLAN(edcADV_WARP_GRID_COLOR);
    						palLANProcSendToLAN(edcADV_WARP_GRID_BACKGROUND);
    						palLANProcSendToLAN(edcADV_BLEND_OVERLAP_GRID_NUMBER);
    						palLANProcSendToLAN(edcADV_BLEND_GAMMA);
    						palLANProcSendToLAN(edcADV_BLEND_LEFT);
    						palLANProcSendToLAN(edcADV_BLEND_RIGHT);
    						palLANProcSendToLAN(edcADV_BLEND_TOP);
    						palLANProcSendToLAN(edcADV_BLEND_BOTTOM);

							palLANProcSendToLAN(edcADV_BLACK_LEVEL_AREA);	//A65_OPTOMA_Doulas_0020
							palLANProcSendToLAN(edcADV_BLACK_LEVEL_ENABLE);
							palLANProcSendToLAN(edcADV_BLACK_LEVEL_RED);
							palLANProcSendToLAN(edcADV_BLACK_LEVEL_GREEN);
							palLANProcSendToLAN(edcADV_BLACK_LEVEL_BLUE);
							palLANProcSendToLAN(edcADV_BLACK_LEVEL_BOUNDARY);	//A35G2_Owen_0002 //A65_OPTOMA_Doulas_0239
			            }
			        }
		            break;

		        case WARPING_TYPE_AP:
		            {
		                UINT8 ucData = (UINT8)WARP_CTRL__AP;
		                palDataMgr_AccessADV_WarpControl(edaWRITE_THROUGH_NO_ACTION, &ucData);

		                uPALGEOAPI_INFO uInfo;
		                uInfo.sGFN_AP_WARP_MEM_APPLY_INFO.ApplyIndex = ucMemoryIndex;
		                uInfo.sGFN_AP_DBDBLEND_MEM_APPLY_INFO.ApplyIndex = ucMemoryIndex;
		                uInfo.sGFN_AP_BKLV_MEM_APPLY_INFO.ApplyIndex = ucMemoryIndex;

		                palGeo_Func_Set(eGFN_AP_WARP_MEM_APPLY,         &uInfo);
		                palGeo_Func_Set(eGFN_AP_DBDBLEND_MEM_APPLY,     &uInfo);
		                palGeo_Func_Set(eGFN_AP_BKLV_MEM_APPLY,         &uInfo);
		            }
		            break;

		        case WARPING_TYPE_AP_MYSTIQUE:
		            {
		                UINT8 ucData = (UINT8)WARP_CTRL__AP;
		                palDataMgr_AccessADV_WarpControl(edaWRITE_THROUGH_NO_ACTION, &ucData);

		                uPALGEOAPI_INFO uInfo;
		                uInfo.sGFN_AP_WARP_MEM_APPLY_INFO.ApplyIndex = ucMemoryIndex;
		                palGeo_Func_Set(eGFN_AP_WARP_MEM_APPLY, &uInfo);
		            }
		            break;

		        default:
		            {
		                LOG_MSG(db_HAL_WARPING, "\nunknown Warping Apply Type %d\n\n" , ucApplyType);
		            }
		            break;
		    }

            //palDataMgr_ResetCountSet(__FUNCTION__, 0);  //HICC2_Simon_0009


        }

        palLANProcSendToLAN(edcADV_WARP_CONTROL);  //HICC2_Simon_0019
        palLANProcSendToLAN(edcWARP_MEMORY_SAVE);
        palLANProcSendToLAN(edcADV_WARP_GRID_POINTS);
        palLANProcSendToLAN(edcADV_WARP_INNER);
        palLANProcSendToLAN(edcADV_WARP_SHARPNESS);
        palLANProcSendToLAN(edcADV_WARP_GRID_COLOR);
        palLANProcSendToLAN(edcADV_WARP_GRID_BACKGROUND);
        palLANProcSendToLAN(edcAW_SEL_WARP_POINT_COL);
        palLANProcSendToLAN(edcAW_SEL_WARP_POINT_ROW);

    }

    return eEXEC_CODE_PASS;
}


eEXEC_CODE palDataMgr_Access_LogoChange(eDATA_ACCESS_MODE eAccessMode, void *pValue)   //G100_Owen_0048
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLogoChange;
    }
    else  //Write Function
    {
        //Update RAM
        UINT8 ucOld_Value = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLogoChange; //H30K_Doulas_0060
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLogoChange = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_LOGOCHANGE, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            eLOGO_OSD_DRIVER eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;

        #if (LOGO_REPLACE == 1) && defined(CUSTOM_OPTOMA) //A35G2_Coda_0061
            if (*((UINT8 *)pValue) == eCM_CHANGE_LOGO_DEFAULT)
            {
			#if (LOGO_REPLACE == 1) // R70G2_Bruce#0019 //ZU860_Clare_0124
                //palEnvironment_LightSourceBlankingOn_Set(TRUE, 1);   //ZU860_Doulas_0083 Add
                //halGui_HWInit();
			#endif
			    if(ucOld_Value == eCM_CHANGE_LOGO_USER) //H30K_Doulas_0061
			    {
                    palDataMgr_UI_EventSend(edcUI_EVENT_CURRENT_SPLASH, eLOGO_OSD_DRIVER_BLACK, NULL);
                    palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
                    MS_SLEEP(1000);
                }
				if(!palDataPath_IsSourceLock())	//A65_OPTOMA_Doulas_0130
				{
					palImgMgr_CaptureImage_Show(FALSE);		//A65_OPTOMA_Doulas_0129
				}

				switch(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucBackgroundColor)
				{
					case eCM_BACKGROUND_COLOR_BLUE:
						eCurrentSplash = eLOGO_OSD_DRIVER_BLUE;
						break;

					case eCM_BACKGROUND_COLOR_BLACK:
						eCurrentSplash = eLOGO_OSD_DRIVER_BLACK;
						break;

					case eCM_BACKGROUND_COLOR_WHITE:
						eCurrentSplash = eLOGO_OSD_DRIVER_WHITE;
						break;

					case eCM_BACKGROUND_COLOR_RED:
						eCurrentSplash = eLOGO_OSD_DRIVER_RED;
						break;

					case eCM_BACKGROUND_COLOR_GREEN:
						eCurrentSplash = eLOGO_OSD_DRIVER_GREEN;
						break;

					case eCM_BACKGROUND_COLOR_GRAY:
						eCurrentSplash = eLOGO_OSD_DRIVER_GRAY;
						break;

					default:
						eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;
						break;
				}
            }
            else if (*((UINT8 *)pValue) == eCM_CHANGE_LOGO_NEUTRAL)
            {
				eCurrentSplash = eLOGO_OSD_DRIVER_BLUE;
				LOG_MSG(db_ASSERT, "%s(eCM_CHANGE_LOGO_NEUTRAL)\r\n", __FUNCTION__);
            }
            else if (*((UINT8 *)pValue) == eCM_CHANGE_LOGO_USER)
            {
			#if (LOGO_REPLACE == 1) // R70G2_Bruce#0019 //ZU860_Clare_0124
                //palEnvironment_LightSourceBlankingOn_Set(TRUE, 1);  //ZU860_Doulas_0083 Add
                UINT8 ucValue = ets_OFF; //ZU860_Clare_0133
                if(ucOld_Value == eCM_CHANGE_LOGO_DEFAULT) //H30K_Doulas_0061
                {
                    palDataMgr_UI_EventSend(edcUI_EVENT_CURRENT_SPLASH, eLOGO_OSD_DRIVER_BLACK, NULL);
                    palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
                    MS_SLEEP(500);
                }

                if(!palDataPath_IsSourceLock())	//A65_OPTOMA_Doulas_0130
                {
                	palImgMgr_CaptureImage_Show(FALSE);		//A65_OPTOMA_Doulas_0129
                }
                palDataMgr_Access_2nd_Logo_Replaced(edaREAD, &ucValue);    //ZU860_Clare_0133
                if (ucValue == ets_ON)    //ZU860_Clare_0129
                {
                    //halGui_SecondLogoHWInit();
				    eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;
                    LOG_MSG(db_ASSERT, "%s(eLOGO_OSD_DRIVER_CUSTOM_LOGO)\r\n", __FUNCTION__);
                }
                else
                {
				    eCurrentSplash = eLOGO_OSD_DRIVER_NONE;
                    LOG_MSG(db_ASSERT, "%s(eLOGO_OSD_DRIVER_NONE)\r\n", __FUNCTION__);
                }
			#else
				eCurrentSplash = eLOGO_OSD_DRIVER_FACTORY_LOGO;
			#endif
            }
			else //eCM_CHANGE_LOGO_CAPTURED
			{
				if(!palDataPath_IsSourceLock()) //G100_Owen_0056
				{
					if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLogoChange == eCM_CHANGE_LOGO_CAPTURED)
					{
						palImgMgr_CaptureImage_Show(TRUE);
					}
					else
					{
						palImgMgr_CaptureImage_Show(FALSE);
					}
				}
			}

            palDataMgr_UI_EventSend(edcUI_EVENT_CURRENT_SPLASH, eCurrentSplash, NULL);
            palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);

		#else
            if((palDataPath_IsSourceLock() == FALSE) && (palDataPath_IsSourceLockSub() == FALSE)) //G100_Owen_0056 //G100_Owen_0099 //A35G2_BRC_Casper_0036
            {
                if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLogoChange == eCM_CHANGE_LOGO_CAPTURED)
                {
                    palImgMgr_CaptureImage_Show(TRUE);
                }
                else
                {
                    palImgMgr_CaptureImage_Show(FALSE);
                }
            }
        #endif

        }
    }

    return eEXEC_CODE_PASS;
}

