eEXEC_CODE palDataMgr_Access_WAP_Enable(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A70LK_Casper_0007 //G50_Casper_0006
{
    UINT16 uiWAP_PWM100[eCM_PICTURE_SETTINGS_NUMBER][eLD_SEG_NUMBERS]={0};
    UINT16 uiWAP_PWM50[eCM_PICTURE_SETTINGS_NUMBER][eLD_SEG_NUMBERS]={0};
    UINT16 uiWAP_PWM30[eCM_PICTURE_SETTINGS_NUMBER][eLD_SEG_NUMBERS]={0};
    UINT16 uiWAP_PWM10[eCM_PICTURE_SETTINGS_NUMBER][eLD_SEG_NUMBERS]={0};
    UINT16 uiCount = 0;
    uCCT_TABLE uCCTTable = {0};
    UINT8  ucWAP_Init = 0;

    utilDataMgr_CCT_StorageGet(&uCCTTable); //HICC2_Casper_0014

    if(edaREAD == eAccessMode)  //Read Function
    {
        if(uCCTTable.sDataStruct.ulCCT_Tag == CCT_NEW_CALIBRATION_TAG)
        {
            m_ucWAP_Enable = ets_ON;
        }
        else
        {
            m_ucWAP_Enable = ets_OFF;
        }
        *((UINT8 *)pValue) = m_ucWAP_Enable;
    }
    else  //Write Function
    {
        m_ucWAP_Enable = *((UINT8 *)pValue);

        if(m_ucWAP_Enable)
        {
            if(GEC_WAP_Flag_Get() == CCT_NEW_CALIBRATION_TAG)
            {
                uCCTTable.sDataStruct.ulCCT_Tag = CCT_NEW_CALIBRATION_TAG;
                palFormatterMgr_WAP_AllSet(eWAP_POWERLEVEL_100,&uCCTTable.sDataStruct.uiPWM100Data[0][0]);
                palFormatterMgr_WAP_AllSet(eWAP_POWERLEVEL_50,&uCCTTable.sDataStruct.uiPWM50Data[0][0]);
                palFormatterMgr_WAP_AllSet(eWAP_POWERLEVEL_30,&uCCTTable.sDataStruct.uiPWM30Data[0][0]);
                palFormatterMgr_WAP_AllSet(eWAP_POWERLEVEL_10,&uCCTTable.sDataStruct.uiPWM10Data[0][0]);
            }
        }
        else
        {
            uCCTTable.sDataStruct.ulCCT_Tag = 0;
            ucWAP_Init = 0xFF;
            palFormatterMgr_APCCT_Set((UINT8 *)&ucWAP_Init);
        }

        palDataMgr_CCT_Set(&uCCTTable); //HICC2_Casper_0014 //HICC2_Casper_0025
    }

    return eEXEC_CODE_PASS;
}

