eEXEC_CODE palDataMgr_Access_LensCenterSetting(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    eEXEC_CODE eExecResult = eEXEC_CODE_PASS;

    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sSystemValues.ucLensCenterSetting;
    }
    else  //Write Function
    {
        UINT8 cData = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode)
        {
            m_sAppDataMgrInfo.sSystemValues.ucLensCenterSetting = cData;
        }

        //Execute Action function
        if (edaWRITE_THROUGH_NO_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            eRESULT eResult = palMotor_LensCenterSettingSet(&cData);

            if(eResult == rcSUCCESS)
            {
                sLENSMEMORY sLensMem = {0};

                palMotorLensPositionGet(&sLensMem);

                m_sAppDataMgrInfo.sSystemValues.ucLensCenterSetting = cData;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.wLensHPosition = sLensMem.wLensHPosition;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.wLensVPosition = sLensMem.wLensVPosition;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.wZoomPosition = sLensMem.wZoomPosition;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.wFocusPosition = sLensMem.wFocusPosition;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.cDirH = sLensMem.cDirH;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.cDirV = sLensMem.cDirV;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.cDirZoom  = sLensMem.cDirZoom;
                m_sAppDataMgrInfo.sSystemValues.sLensInfo.cDirFocus = sLensMem.cDirFocus;

                palDataMgr_OPD_LensOpticaCenter();
            }
        }
    }

	return eExecResult;
}

