//A35G2_CDS_Simon_0008   //for hotkey enable/disable warp/blend
eEXEC_CODE palDataMgr_Access_WarpToggle(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
#ifdef SCALER_FPGA_F34
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucGeometryEnable;
    }
    else  //Write Function
    {
        UINT8 ucGeometryEnable = *((UINT8*)pValue);

        //if AP link, do warp toggle by AP
        if((palGeo_ApLinkFlag_Get() == TRUE) && (ucGeometryEnable == FALSE))  //A35G2_Simon_0086
        {
            return eEXEC_CODE_PASS;
        }

        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucGeometryEnable = ucGeometryEnable;

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_GEOMETRYENABLE, (UINT8*)&ucGeometryEnable);
            palGeo_Draw_FrameBufferGeometryEnable(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucGeometryEnable);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            if(ucGeometryEnable && (halWarping_EnableGet() == FALSE))
            {
                palImgMgr_DisableRGB(eHAL_SCALER_RGB_ITEM_GEOMETRY); //A70LK_Casper_0008
                MS_SLEEP(50);
                palGeo_EnableSet(TRUE);
                palImgMgr_RGBEnableItemSet(eHAL_SCALER_RGB_ITEM_GEOMETRY); //A70LK_Casper_0008
                utilCounter_Reg_TimerEvent(eTIMER_EVENT_BLACKING_DISABLE_COUNT, 3000, 0, 0, palImgMgr_EnableRGB, NULL); //A70LK_Coda_0015

                //halWarping_WarpDownScalingIssueWorkAround();
            }
            else if((!ucGeometryEnable) && (halWarping_EnableGet() == TRUE))
            {
                palImgMgr_DisableRGB(eHAL_SCALER_RGB_ITEM_GEOMETRY); //A70LK_Casper_0008
                MS_SLEEP(50);
                palGeo_EnableSet(FALSE);
                palImgMgr_RGBEnableItemSet(eHAL_SCALER_RGB_ITEM_GEOMETRY); //A70LK_Casper_0008
                utilCounter_Reg_TimerEvent(eTIMER_EVENT_BLACKING_DISABLE_COUNT, 3000, 0, 0, palImgMgr_EnableRGB, NULL);//A70LK_Coda_0015

                //appGui_SentGeometryMenuCheck();
            }

            //appDataMgr_MenuOffsetUpdateForEdgeBlending();
            palDataMgr_3DModeConditionUpdate();
        }
    }

#else
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucGeometryEnable;   //HICC2_Simon_0011
    }
    else  //Write Function
    {
    	LOG_MSG(db_HAL_WARPING, "Warp hotkey Toggle\n");
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucGeometryEnable = *((UINT8*)pValue);   //HICC2_Simon_0011

        //if AP link, do warp toggle by AP
        if(palGeo_ApLinkFlag_Get() == TRUE)  //A35G2_Simon_0086
        {
            return eEXEC_CODE_PASS;
        }

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {

        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucToggleToEnable = FALSE;   //If true, need to apply last saved memory. If off, apply memory to off

            if(palGeo_ApLinkFlag_Get() == FALSE)  //A35G2_Simon_0086
            {
                //if warp/blend both are off, and all setting are default, then apply last setting.
                if(//apply memory all off
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingApplySetting == eCM_GEO_MEMORY_APPLY_OFF &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendApplySetting   == eCM_GEO_MEMORY_APPLY_OFF &&
                   //keystone
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzKeystone == KEYSTONE_DEFAULT_VALUE &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpVertKeystone == KEYSTONE_DEFAULT_VALUE &&
                   //pincushion
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzPincushion == HORZ_PINCUSHIN_DEFAULT_VALUE &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpVertPincushion == HORZ_PINCUSHIN_DEFAULT_VALUE &&
                   //4-corner
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopLeftHorz     == 0 &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopLeftVert     == 0 &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopRightHorz    == 0 &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopRightVert    == 0 &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerBottomLeftHorz  == 0 &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerBottomLeftVert  == 0 &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerBottomRightHorz == 0 &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerBottomRightVert == 0 &&
                   //edge blending
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingLeftEnable   == FALSE &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingTopEnable    == FALSE &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingRightEnable  == FALSE &&
                   m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingBottomEnable == FALSE
                )
                {
                    ucToggleToEnable = TRUE ;
                }
            }

            if(ucToggleToEnable)  //apply warp/blend to last saved seeting
            {
                UINT8 ucLastSavedWarping  = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpingLastSaved;
                UINT8 ucLastSavedBlending = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendLastSaved;
                LOG_MSG(db_HAL_WARPING, "last saved (%d)(%d)\n", ucLastSavedWarping, ucLastSavedBlending);

                if(ucLastSavedWarping <= WARPING_SAVE_MAX_VALUE )
                {
                    palDataMgr_Access_Warping_Apply(edaWRITE_THROUGH_WITH_ACTION, &ucLastSavedWarping);  //HICC2_Simon_0005
                    LOG_MSG(db_HAL_WARPING, "hotkey to apply warp (%d)\n", ucLastSavedWarping);
                }

                if(ucLastSavedBlending <= BLEND_SAVE_MAX_VALUE)
                {
                    palDataMgr_Access_Blend_Apply(edaWRITE_THROUGH_WITH_ACTION, &ucLastSavedBlending);   //HICC2_Simon_0005
                    LOG_MSG(db_HAL_WARPING, "hotkey to apply blend (%d)\n", ucLastSavedBlending);
                }

            }
            else  //apply to warp/blend off
            {
                UINT8 ucData = 0;  //off
                palDataMgr_Access_Warping_Apply(edaWRITE_THROUGH_WITH_ACTION, &ucData);
                palDataMgr_Access_Blend_Apply(edaWRITE_THROUGH_WITH_ACTION, &ucData);
            	LOG_MSG(db_HAL_WARPING, "hotkey to apply all off\n");
            }

            palLANProcSendToLAN(edcWARP_MEMORY_APPLY);   //HICC2_Simon_0005
            palLANProcSendToLAN(edcBLEND_MEMORY_APPLY);  //HICC2_Simon_0005

        }
    }
#endif /* SCALER_FPGA_F34 */

    return eEXEC_CODE_PASS;
}

