//A65_OPTOMA_Jerry_0004 start
eEXEC_CODE palDataMgr_Access_ProService_Pair_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
#ifdef PROSERVICE_ALPHA_ENABLE
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucProServicePairStatus;
        LOG_MSG(db_APP_SCHEDULE, "Read Pair status %d\r\n", *((UINT8*)pValue));
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucProServicePairStatus = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_PROSERVICE_PAIRED_STATUS, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucStatus = *((UINT8*)pValue);

            LOG_MSG(db_APP_SCHEDULE, "Write Pair status %d, PairFlag: %d, BindingFlag: %d\r\n", ucStatus, m_bProServicePairFlag, m_bProServiceBindingFlag); //Optoma_Tim_0070, mod

            if(ucStatus == ePROSERVICE_PAIR_STATUS_PAIR_REQUEST_TO_SERVER)
            {   LOG_MSG(db_APP_SCHEDULE, "PROSERVICE_PAIR_STATUS_PAIR_REQUEST_TO_SERVER\r\n");
                m_bProServicePairFlag = TRUE;
            }

            if(m_bProServicePairFlag == TRUE)
            {
                switch(ucStatus)
                {
                    case ePROSERVICE_PAIR_STATUS_IDLE:
                    {
                        m_bProServicePairFlag = 0;
                    } break;

                    case ePROSERVICE_PAIR_STATUS_PAIR_CODE_READY_FROM_SERVER:// 2
                    {
                        UINT8 ConfirmStatus = ets_ON; // the confirm pair page option default value is confirm(On)
                        palDataMgr_Access_Confirmation(edaWRITE_THROUGH_WITH_ACTION, &ConfirmStatus);

                        palEnvironment_ProServicePowerDownTimerSet(300);
                        palEnvironment_ProServicePowerDownMessageCountSet(300);
                        palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_PAIR, ucStatus, NULL);// HICC2_Bruce_0010
                    } break;

                    case ePROSERVICE_PAIR_STATUS_PAIR_CODE_SUCCESS_FROM_SERVER:// 4
                	{
						palEnvironment_ProServicePowerDownMessageCountSet(0);
						palEnvironment_ProServicePowerDownTimerSet(0);
                        palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_PAIR, ucStatus, NULL);// HICC2_Bruce_0010
                    } break;

                    //ZU860_Tim_0091, add, start
                    // user abort, stop the process, and waiting for setting to IDLE by ProService AP.
                    case ePROSERVICE_PAIR_STATUS_PAIR_CODE_USER_ABORTED:
                    {
                        palEnvironment_ProServicePowerDownMessageCountSet(0);
                        palEnvironment_ProServicePowerDownTimerSet(0);
                    } break;
                    //ZU860_Tim_0091, add, end

                    case ePROSERVICE_PAIR_STATUS_PAIR_CODE_CONFIRM_TO_SERVER:
                        break;

                    case ePROSERVICE_PAIR_STATUS_PAIR_CODE_ERROR:// 10
                	{
                        palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_PAIR, ucStatus, NULL);// HICC2_Bruce_0010
                        m_bProServicePairFlag = 0;
                        m_bProServiceBindingFlag = 0;
                    } break;

                    default:
                        break;
                }
            }
            //palLANProcSendToLAN(edcPROSERVICE_PAIR_STATUS);
        }
    }

    return eEXEC_CODE_PASS;
#else
    if(edaREAD == eAccessMode)
    {
        *((UINT8*)pValue) = 0;
    }

    return eEXEC_CODE_FAIL;
#endif
}

