eEXEC_CODE palDataMgr_Access_ProService_Binding_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
#ifdef PROSERVICE_ALPHA_ENABLE
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucProServiceBindStatus;
          LOG_MSG(db_APP_SCHEDULE, "Read Binding status.. %d\r\n", *((UINT8*)pValue));
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucProServiceBindStatus = *((UINT8*)pValue);
        LOG_MSG(db_APP_SCHEDULE, "Write Binding status %d\r\n", *((UINT8*)pValue));
        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_PROSERVICE_BINDED_STATUS, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 ucStatus = *((UINT8*)pValue);

            if(ucStatus == ePROSERVICE_STATUS_QUERY)
            {
                m_bProServiceBindingFlag = TRUE;
                LOG_MSG(db_APP_SCHEDULE, "ProService Binding Query flag %d, %d\r\n", ucStatus, m_bProServiceBindingFlag); //Optoma_Tim_0070, mod
            }
            else if(m_bProServiceBindingFlag == TRUE)
            {
                LOG_MSG(db_APP_SCHEDULE, "Get ProService Binding status %d\r\n", ucStatus);

                switch(ucStatus)
                {
                    case ePROSERVICE_STATUS_NO_BINDING:// 1
                        {
                            UINT8 ConfirmStatus = ets_OFF;
                            palDataMgr_Access_Confirmation(edaWRITE_THROUGH_WITH_ACTION, &ConfirmStatus);
                            palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_BIND, ucStatus, NULL);// HICC2_Bruce_0010
                        }
                        break;

                    case ePROSERVICE_STATUS_BINDING:// 2
                        palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_BIND, ucStatus, NULL);// HICC2_Bruce_0010
                        break;

                    case ePROSERVICE_STATUS_ERROR_REGISTER_LOST:// 10
                        palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_BIND, ucStatus, NULL);// HICC2_Bruce_0010
                        break;

                    //Optoma_Tim_0070, add, start
                    case ePROSERVICE_STATUS_ERROR_NETWORK_TIMEOUT:// 11
                        palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_BIND, ucStatus, NULL);// HICC2_Bruce_0010
                        break;
                    //Optoma_Tim_0070, add, end

                    case ePROSERVICE_STATUS_IDLE:// 0
                    default:
                        palDataMgr_UI_EventSend(edcUI_EVENT_PROSERVICE_BIND, ucStatus, NULL);// HICC2_Bruce_0010
                        break;
                }
                m_bProServiceBindingFlag = FALSE;
                LOG_MSG(db_APP_SCHEDULE, "Clear Binding Query flag %d, %d\r\n", ucStatus, m_bProServiceBindingFlag);
            }
            //palLANProcSendToLAN(edcPROSERVICE_BINDING_STATUS);
        }
    }

    return eEXEC_CODE_PASS;
#else
    if(edaREAD == eAccessMode)
    {
        *((UINT8*)pValue) = 0;
    }

    return eEXEC_CODE_FAIL;
#endif
}

