eEXEC_CODE palDataMgr_Access_ResetLightSourceHours(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A65_OPTOMA_Doulas_0027//A35G2_Coda_0061
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = ets_OFF;
    }
    else  //Write Function
    {
        //Update Ram
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinuteNormal = 0;
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinuteEco = 0;
		m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinuteCustom = 0;
		m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinute[eTIMER_RECORD_BLD] = 0;

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        	utilDataMgr_CommonSet_CM(eDF_LIGHTSOURCEMINUTENORMAL, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinuteNormal);
            utilDataMgr_CommonSet_CM(eDF_LIGHTSOURCEMINUTEECO, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinuteEco);
			utilDataMgr_CommonSet_CM(eDF_LIGHTSOURCEMINUTECUSTOM, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinuteCustom);
			utilDataMgr_CommonSet_CM(eDF_LIGHTSOURCEMINUTE_B, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinute[eTIMER_RECORD_BLD]);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            palIllumination_Init_LDHoursSet(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ulLightSourceMinute[eTIMER_RECORD_BLD]);
        }

		palLANProcSendToLAN(edcLIGHT_SOURCE_HOURS_NORAML_INFO);
        palLANProcSendToLAN(edcLIGHT_SOURCE_HOURS_ECO_INFO);
		palLANProcSendToLAN(edcLIGHT_SOURCE_HOURS_CUSTOM_INFO);
		palLANProcSendToLAN(edcLIGHT_SOURCE_HOURS);
		palLANProcSendToLAN(edcLIGHT_SOURCE_HOURS_INFO);
		palLANProcSendToLAN(edcLD_HOURS_INFO);

    }

    return eEXEC_CODE_PASS;
}

