eEXEC_CODE palDataMgr_Access_Display_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //A65_OPTOMA_Doulas_0032 Modify//A65_OPTOMA_Doulas_0028
{
    if(edaREAD == eAccessMode)   //Read Function
    {
        *((UINT8 *)pValue) = ets_OFF;
    }
    else  //Write Function
    {
        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
        #if defined(CUSTOM_CHRISTIE)// R70K_Bruce_0065//HICC2_Julie_0011
            {
                UINT8 ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
                //UINT8 ucGuiSrc = (UINT8)CM2GUI(edcMAIN_INPUT, ucInputSource);
                tDATA_CODE Value = 0;

                palDataMgr_ResetCountSet(__FUNCTION__, 45);

                palDataMgr_Data_ReadDefaultWrite(edcSIZE_PRESETS);// x35G2_Bruce_0001
                #if 1
                // for VGA
                palDataMgr_Data_ReadDefaultWrite(edcPIXEL_PHASE);
                palDataMgr_Data_ReadDefaultWrite(edcHORZ_POSITION);
                palDataMgr_Data_ReadDefaultWrite(edcVERT_POSITION);
                #endif
                palDataMgr_Data_Range_Get(edcDIGITAL_HORZ_ZOOM, edrDEFAULT, &Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzZoom = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_CUSTOMDIGITALHORZZOOM, ucInputSource, 0, (UINT8 *)&Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzZoom = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_DIGITALHORZZOOM, ucInputSource, 0, (UINT8 *)&Value);
                palDataMgr_Access_DigitalHorzZoom(edaWRITE_THROUGH_WITH_ACTION, &Value);
                palLANProcSendToLAN(edcDIGITAL_HORZ_ZOOM);

                palDataMgr_Data_Range_Get(edcDIGITAL_VERT_ZOOM, edrDEFAULT, &Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalVertZoom = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_CUSTOMDIGITALVERTZOOM, ucInputSource, 0, (UINT8 *)&Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalVertZoom = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_DIGITALVERTZOOM, ucInputSource, 0, (UINT8 *)&Value);
                palDataMgr_Access_DigitalVertZoom(edaWRITE_THROUGH_WITH_ACTION, &Value);
                palLANProcSendToLAN(edcDIGITAL_VERT_ZOOM);

                palDataMgr_Data_Range_Get(edcDIGITAL_HORZ_SHIFT, edrDEFAULT, &Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalHorzShift = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_CUSTOMDIGITALHORZSHIFT, ucInputSource, 0, (UINT8 *)&Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalHorzShift = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_DIGITALHORZSHIFT, ucInputSource, 0, (UINT8 *)&Value);
                palDataMgr_Access_DigitalHorzShift(edaWRITE_THROUGH_WITH_ACTION, &Value);
                palLANProcSendToLAN(edcDIGITAL_HORZ_SHIFT);

                palDataMgr_Data_Range_Get(edcDIGITAL_VERT_SHIFT, edrDEFAULT, &Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiCustomDigitalVertShift = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_CUSTOMDIGITALVERTSHIFT, ucInputSource, 0, (UINT8 *)&Value);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].uiDigitalVertShift = Value;
                utilDataMgr_SourceColorSet_CM(eDFS_DIGITALVERTSHIFT, ucInputSource, 0, (UINT8 *)&Value);
                palDataMgr_Access_DigitalVertShift(edaWRITE_THROUGH_WITH_ACTION, &Value);
                palLANProcSendToLAN(edcDIGITAL_VERT_SHIFT);

                // Geometry Correction
                //appDataMgr_Access_WarpingMemory_Clear(eAccessMode, pValue);
                palDataMgr_Access_WarpReset(eAccessMode, pValue);

                palDataMgr_ResetCountSet(__FUNCTION__, 0);
            }
        #else
            UINT8 ucSetting = ets_ON;
            INT32 iValue = 0;
            m_ucResetCount = 45;    //G100_Owen_0065


            //reset warping
            //palDataMgr_Access_WarpReset(eAccessMode, pValue); //H30K_Doulas_0027

			#ifdef CUSTOM_OPTOMA  //H30K_David_0001
			//Light source settings
            palDataMgr_Data_Range_Get(edcPOWER_MODE, edrDEFAULT, &iValue);
            palDataMgr_Access_PowerMode(eAccessMode, &iValue);
            palDataMgr_Data_Range_Get(edcCONSTANT_POWER_NUMBER, edrDEFAULT, &iValue);
            palDataMgr_Access_ConstantPower(eAccessMode, &iValue);
            palDataMgr_Data_Range_Get(edcCONSTANT_INTENSITY_PWM, edrDEFAULT, &iValue);
            palDataMgr_Access_LightSensorIntensity_Default(eAccessMode, &iValue);
			palDataMgr_Data_Range_Get(edcCONSTANT_BRIGHTNESS, edrDEFAULT, &iValue);
            palDataMgr_Access_Constant_Brightness(eAccessMode, &iValue);
			palDataMgr_Data_Range_Get(edcLOW_LATENCY_MODE, edrDEFAULT, &iValue);//H30K_David_0004
			palDataMgr_Access_LowLatencyMode(eAccessMode, &iValue);//H30K_David_0004
			#endif

			//A65_OPTOMA_Doulas_0006 Modify , display mode reset
			//Aspect ratio
			palDataMgr_Data_Range_Get(edcSIZE_PRESETS, edrDEFAULT, &iValue);
            palDataMgr_Access_SizePresets(eAccessMode, &iValue);
			//digital zoom
            palDataMgr_Data_Range_Get(edcDIGITAL_ZOOM_RESET, edrDEFAULT, &iValue);
            palDataMgr_Access_DigitalZoomReset(eAccessMode, &iValue);

			//H-position	//A65_OPTOMA_Doulas_0062 Add
			palDataMgr_Data_Range_Get(edcHORZ_POSITION, edrDEFAULT, &iValue);
			palDataMgr_Access_HorzPosition(eAccessMode, &iValue);
			//V-position	//A65_OPTOMA_Doulas_0062 Add
			palDataMgr_Data_Range_Get(edcVERT_POSITION, edrDEFAULT, &iValue);
			palDataMgr_Access_VertPosition(eAccessMode, &iValue);

			//edge mask
			palDataMgr_Data_Range_Get(edcEDGE_MASK, edrDEFAULT, &iValue);
            palDataMgr_Access_EdgeMask(eAccessMode, &iValue);
			//Freeze
			iValue = m_sDefSysSettings.sUserSystemSetting.sImageSetting.ucImageFreeze;
    		palDataMgr_Access_ImageFreeze(edaWRITE_RAM_ONLY_WITH_ACTION, &iValue);

			//PIP
			palDataMgr_Data_Range_Get(edcPIP_PBP_ENABLE, edrDEFAULT, &iValue);
	        palDataMgr_Access_PIP_PBP_Enable(eAccessMode, &iValue);

	        palDataMgr_Data_Range_Get(edcMAIN_INPUT, edrDEFAULT, &iValue);
	        palDataMgr_Access_MainInput(eAccessMode, &iValue);
	        palDataMgr_Data_Range_Get(edcSUB_INPUT, edrDEFAULT, &iValue);
	        palDataMgr_Access_SubInput(edaWRITE_THROUGH_NO_ACTION, &iValue);

	        palDataMgr_Data_Range_Get(edcSIZE, edrDEFAULT, &iValue);
	        palDataMgr_Access_PIP_PBP_Size(eAccessMode, &iValue);

            #if defined(CUSTOM_OPTOMA) //A35G2_Coda_0139
            iValue = eCM_MAIN_LAYOUT_PIP_BOTTOM_RIGHT;
			#else
        	palDataMgr_Data_Range_Get(edcMAIN_LAYOUT, edrDEFAULT, &iValue);
        	#endif
            palDataMgr_Access_PIP_PBP_Layout(eAccessMode, &iValue);



	        palDataMgr_Data_Range_Get(edcMAIN_LAYOUT, edrDEFAULT, &iValue);
	        palDataMgr_Access_PIP_PBP_Layout(eAccessMode, &iValue);

			//Test pattern
			palDataMgr_Data_Range_Get(edcOSDTEST_PATTERN, edrDEFAULT, &iValue);
            palDataMgr_Access_OSDTestPattern(eAccessMode, &iValue);

			palDataMgr_Scaler_EEPROM_Iint();
            palImgMgr_IintChannelSetting(eSOURCE_WINDOW_MAIN);
            palImgMgr_IintChannelSetting(eSOURCE_WINDOW_SUB);

			//warping
			//palDataMgr_Access_WarpReset(eAccessMode, (void*)&ucSetting);		//A65_OPTOMA_Doulas_0089 remove

			palDataPath_Resync();
            palDataPath_ResyncSub();


			palLANProcSendToLAN(edcSIZE_PRESETS);
			palLANProcSendToLAN(edcHORZ_POSITION);	//A65_OPTOMA_Doulas_0062
			palLANProcSendToLAN(edcVERT_POSITION);	//A65_OPTOMA_Doulas_0062
			palLANProcSendToLAN(edcEDGE_MASK);
			palLANProcSendToLAN(edcIMAGE_FREEZE);
			palLANProcSendToLAN(edcPIP_PBP_ENABLE);
            palLANProcSendToLAN(edcSIZE);
            palLANProcSendToLAN(edcMAIN_LAYOUT);
			palLANProcSendToLAN(edcMAIN_INPUT);
			palLANProcSendToLAN(edcOSDTEST_PATTERN);

			//H30K_David_0001 start
			#ifdef CUSTOM_OPTOMA
            palLANProcSendToLAN(edcPOWER_MODE);
            palLANProcSendToLAN(edcCONSTANT_POWER_NUMBER);
            palLANProcSendToLAN(edcCONSTANT_INTENSITY_PWM);
            palLANProcSendToLAN(edcCONSTANT_BRIGHTNESS);
			palLANProcSendToLAN(edcLOW_LATENCY_MODE);//H30K_David_0004
			#endif
			//H30K_David_0001 end
            m_ucResetCount = 0; //G100_Owen_0065
        #endif
        }
    }

    return eEXEC_CODE_PASS;
}

