eEXEC_CODE palDataMgr_Access_Setup_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //A65_OPTOMA_Doulas_0032 Modify//A65_OPTOMA_Doulas_0028 //A35G2_Coda_0057
{
    if(edaREAD == eAccessMode)   //Read Function
    {
        *((UINT8 *)pValue) = ets_OFF;
    }
    else  //Write Function
    {
        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            INT32 iValue = 0;

        #if defined(CUSTOM_CHRISTIE)// R70K_Bruce_0065//HICC2_Julie_0011
            {
                palDataMgr_ResetCountSet(__FUNCTION__, 45);

                /*Resets Configuration to default, except for following: Language, PIN Protect, Network Settings, and Date and Time.*/
                //Lens Settings
                palDataMgr_Data_ReadDefaultWrite(edcLOCK_ALL_LENS_MOTORS);
                //palDataMgr_Data_ReadDefaultWrite(edcLensMemoryReset); //HICC2_Steven_0038 ISS-0023690, 執行Reset configuration會把Lens memory清除.

                //ceiliing mount
                palDataMgr_Data_ReadDefaultWrite(edcCEILING_MOUNT);

                //rear projection
                palDataMgr_Data_ReadDefaultWrite(edcREAR_PROJECTION);

                //Menu Preferences
                palDataMgr_Data_ReadDefaultWrite(edcMEMU_HORZ_OFFSET);
                palDataMgr_Data_ReadDefaultWrite(edcMEMU_VERT_OFFSET);
                palDataMgr_Data_ReadDefaultWrite(edcSHOW_MESSAGES);
                palDataMgr_Data_ReadDefaultWrite(edcMENU_TRANSPARENCY);
                palDataMgr_Data_ReadDefaultWrite(edcSPLASH_STARTUP);
                palDataMgr_Data_ReadDefaultWrite(edcMENU_TIME_OUT);

                //Shutter Settings
                palDataMgr_Data_ReadDefaultWrite(edcFADE_IN);// x35G2_Bruce_0001
                palDataMgr_Data_ReadDefaultWrite(edcFADE_OUT);
                palDataMgr_Data_ReadDefaultWrite(edcSTARTUP_SHUTTER);

                //Power Management
                palDataMgr_Data_ReadDefaultWrite(edcSTANDBY_MODE);
                palDataMgr_Data_ReadDefaultWrite(edcAC_POWER_ON);
                palDataMgr_Data_ReadDefaultWrite(edcAUTO_SHUTDOWN);
                palDataMgr_Data_ReadDefaultWrite(edcSLEEP_TIMER);

                //High Altitude
                //palDataMgr_Data_ReadDefaultWrite(edcHIGH_ALTITUDE);
                palDataMgr_Data_Range_Get(edcHIGH_ALTITUDE, edrDEFAULT, &iValue);
                if(eFUNC_CONTROL_ENABLE == palDataMgr_Control_HighAltitude())//HICC2_Julie_0020
                {
                    palDataMgr_Access_HighAltitude(eAccessMode, &iValue);
                }
                else
                {
                    palDataMgr_Access_HighAltitude(edaWRITE_THROUGH_NO_ACTION, &iValue);
                }
                palLANProcSendToLAN(edcHIGH_ALTITUDE);//HICC2_Julie_0034

                //IR Control
                palDataMgr_Data_ReadDefaultWrite(edcTOP_IR);
                palDataMgr_Data_ReadDefaultWrite(edcFRONT_IR);
                palDataMgr_Data_ReadDefaultWrite(edcREAR_IR);
                palDataMgr_Data_ReadDefaultWrite(edcHDBASET_IR);

                //12V Trigger
                palDataMgr_Data_ReadDefaultWrite(edc12V_TRIGGER);

                //Communications
                palDataMgr_Data_ReadDefaultWrite(edcSERIAL_PORT_BAUD_RATE);
                palDataMgr_Data_ReadDefaultWrite(edcSERIAL_PORT_ECHO);
                palDataMgr_Data_ReadDefaultWrite(edcPROJECTOR_ADDRESS);

                //Backlight Preferences
                palDataMgr_Data_ReadDefaultWrite(edcKEYPAD_BACKLIGHT);
                palDataMgr_Data_ReadDefaultWrite(edcSTATUS_LED);

                //Hot-Key Settings
                palDataMgr_Data_ReadDefaultWrite(edcHOT_KEY_SETTINGS);

                //schedule
                palDataMgr_Access_Schedule_Reset_Schedule_All(eAccessMode, pValue);

                palDataMgr_ResetCountSet(__FUNCTION__, 0);

                palDataMgr_Access_SplashLogoEnable(edaREAD, &iValue);
                palDataMgr_UI_EventSend(edcUI_EVENT_CURRENT_SPLASH, iValue, NULL);
                palLANProcSendToLAN(edcPROJECTOR_GROUP_RESET);
            }
        #else
			UINT8    ucPWord[5] = {0};
            m_ucResetCount = 45;    //G100_Owen_0065

			//Language
			palDataMgr_Data_Range_Get(edcLANGUAGE, edrDEFAULT, &iValue);
			palDataMgr_Access_Language(eAccessMode,&iValue);

			//ceiliing mount
            palDataMgr_Data_Range_Get(edcCEILING_MOUNT, edrDEFAULT, &iValue);			//A65_OPTOMA_Doulas_0006
            palDataMgr_Access_CeilingMount(eAccessMode, &iValue);
			//rear projection
            palDataMgr_Data_Range_Get(edcREAR_PROJECTION, edrDEFAULT, &iValue);			//A65_OPTOMA_Doulas_0006
            palDataMgr_Access_RearProjection(eAccessMode, &iValue);

			//Lock all lens motors
			palDataMgr_Data_Range_Get(edcLOCK_ALL_LENS_MOTORS, edrDEFAULT, &iValue); 	//A65_OPTOMA_Doulas_0006
            palDataMgr_Access_LensLockAllMotors(eAccessMode, &iValue);
			//Len Memory clear
			palDataMgr_Data_Range_Get(edcLensMemoryReset, edrDEFAULT, &iValue);
			palDataMgr_Access_LensMemory_Clear(eAccessMode, &iValue);

			//Active image setup
				//TODO:

			//schedule ?
            iValue = ets_ON;
            palDataMgr_Access_Schedule_Reset_Schedule_All(eAccessMode, &iValue); //G100_Coda_0044

			//Date and time :  //G100_Coda_00110 cpc factory set , don't reset
				//TODO:
            //palDataMgr_Access_DateTimeReset(edaWRITE_THROUGH_WITH_ACTION, &iValue);

			//Power settings reset
            palDataMgr_Access_PowerSettings_Reset(edaWRITE_THROUGH_WITH_ACTION, &iValue);

			//H30K_David_0001 start
			#ifndef CUSTOM_OPTOMA
			//Light source settings
            palDataMgr_Data_Range_Get(edcPOWER_MODE, edrDEFAULT, &iValue);
            palDataMgr_Access_PowerMode(eAccessMode, &iValue);
            palDataMgr_Data_Range_Get(edcCONSTANT_POWER_NUMBER, edrDEFAULT, &iValue);
            palDataMgr_Access_ConstantPower(eAccessMode, &iValue);
            palDataMgr_Data_Range_Get(edcCONSTANT_INTENSITY_PWM, edrDEFAULT, &iValue);
            palDataMgr_Access_LightSensorIntensity_Default(eAccessMode, &iValue);
			palDataMgr_Data_Range_Get(edcCONSTANT_BRIGHTNESS, edrDEFAULT, &iValue);
            palDataMgr_Access_Constant_Brightness(eAccessMode, &iValue);
			#endif
			//H30K_David_0001 end

			//Shutter
            palDataMgr_Data_Range_Get(edcFADE_IN, edrDEFAULT, &iValue);
            palDataMgr_Access_FadeIn_Time(eAccessMode, &iValue);
            palDataMgr_Data_Range_Get(edcFADE_OUT, edrDEFAULT, &iValue);
            palDataMgr_Access_FadeOut_Time(eAccessMode, &iValue);
            palDataMgr_Data_Range_Get(edcSTARTUP_SHUTTER, edrDEFAULT, &iValue);
            palDataMgr_Access_Startup_Shutter(eAccessMode, &iValue);

			//Security
			palDataMgr_Data_Range_Get(edcPIN_PROTECT, edrDEFAULT, &iValue);
            palDataMgr_Access_PINProtect(eAccessMode, &iValue);

			ucPWord[0] = m_sDefSysSettings.sSystemDefault.ucPassWord[0];
        	ucPWord[1] = m_sDefSysSettings.sSystemDefault.ucPassWord[1];
        	ucPWord[2] = m_sDefSysSettings.sSystemDefault.ucPassWord[2];
        	ucPWord[3] = m_sDefSysSettings.sSystemDefault.ucPassWord[3];
        	ucPWord[4] = m_sDefSysSettings.sSystemDefault.ucPassWord[4];
			palDataMgr_Access_ChangePIN(edaWRITE_THROUGH_NO_ACTION, ucPWord);

			palDataMgr_Data_Range_Get(edcSECURITY_TIMER, edrDEFAULT, &iValue);
            palDataMgr_Access_SecurityTimer_TotalRemainMin(edaWRITE_THROUGH_NO_ACTION, &iValue);
			palDataMgr_Data_Range_Get(edcSECURITY_TIMER_MONTH, edrDEFAULT, &iValue);
            palDataMgr_Access_SecurityMonth(edaWRITE_THROUGH_NO_ACTION, &iValue);
			palDataMgr_Data_Range_Get(edcSECURITY_TIMER_DAY, edrDEFAULT, &iValue);
            palDataMgr_Access_SecurityDay(edaWRITE_THROUGH_NO_ACTION, &iValue);
			palDataMgr_Data_Range_Get(edcSECURITY_TIMER_HOUR, edrDEFAULT, &iValue);
            palDataMgr_Access_SecurityHour(edaWRITE_THROUGH_NO_ACTION, &iValue);

			//Keypad Lock
			palDataMgr_Data_Range_Get(edcKEYPAD_LOCK, edrDEFAULT, &iValue);
			palDataMgr_Access_KeypadLock(edaWRITE_THROUGH_WITH_ACTION, &iValue);

            //On screen display
            palDataMgr_Access_OnScreenDisplay_Reset(edaWRITE_THROUGH_WITH_ACTION, &iValue);

            //Change logo
            palDataMgr_Access_LogoDelete(edaWRITE_THROUGH_WITH_ACTION, &iValue);    //G100_Owen_0058
            palDataMgr_Data_Range_Get(edcLOGO_CHANGE, edrDEFAULT, &iValue);         //G100_Owen_0050
            palDataMgr_Access_LogoChange(edaWRITE_THROUGH_WITH_ACTION, &iValue);    //G100_Owen_0050

			//delete logo capture //A35G2_Coda_0099
			palImgMgr_CaptureImage_Del(palDataPath_IsSourceLock());


            //Backlight
            palDataMgr_Data_Range_Get(edcKEYPAD_BACKLIGHT, edrDEFAULT, &iValue);
            palDataMgr_Access_KeypadBacklight(eAccessMode, &iValue);
            palDataMgr_Data_Range_Get(edcPWRKEY_BACKLIGHT, edrDEFAULT, &iValue);
            palDataMgr_Access_PwrKeyBacklight(eAccessMode, &iValue);

            //High altitude
            palDataMgr_Data_Range_Get(edcHIGH_ALTITUDE, edrDEFAULT, &iValue);
            palDataMgr_Access_HighAltitude(eAccessMode, &iValue);

			//User Data
			palDataMgr_Data_Range_Get(edcBACKUP_RESTORE_SAVE, edrDEFAULT, &iValue);
            palDataMgr_Access_Backup_Restore_Save(edaWRITE_THROUGH_NO_ACTION, &iValue);
			palDataMgr_Data_Range_Get(edcBACKUP_RESTORE_RESTORE, edrDEFAULT, &iValue);
            palDataMgr_Access_Backup_Restore_Restore(edaWRITE_THROUGH_NO_ACTION, &iValue);
			utilDataMgr_UserDataReset_CM();		//G100_Doulas_0075

			//system update
			palDataMgr_Data_Range_Get(edcNOTIFICATIONSYSTEMUPDATE, edrDEFAULT, &iValue);
            palDataMgr_Access_Notification_System_Update(eAccessMode, &iValue);

			//silent system update
			palDataMgr_Data_Range_Get(edcSILENTFOTA_SYSTEMUPDATE, edrDEFAULT, &iValue); //A35G2_OTM_Owen_0001
            palDataMgr_Access_SilentFOTA_System_Update(eAccessMode, &iValue);           //A35G2_OTM_Owen_0001

			palLANProcSendToLAN(edcLANGUAGE);
            palLANProcSendToLAN(edcCEILING_MOUNT);					//A65_OPTOMA_Doulas_0006
            palLANProcSendToLAN(edcREAR_PROJECTION);				//A65_OPTOMA_Doulas_0006
            palLANProcSendToLAN(edcLOCK_ALL_LENS_MOTORS);         	//A65_OPTOMA_Doulas_0006
            palLANProcSendToLAN(edcLENS_APPLY_POSITION);
            palLANProcSendToLAN(edcLENS_SAVE_CURRENT_POSITION);

			//Active image setup

			//schedule

			//Date and time :
				//TODO
            //H30K_David_0001 start
			#ifndef CUSTOM_OPTOMA
            palLANProcSendToLAN(edcPOWER_MODE);
            palLANProcSendToLAN(edcCONSTANT_POWER_NUMBER);
            palLANProcSendToLAN(edcCONSTANT_INTENSITY_PWM);
            palLANProcSendToLAN(edcCONSTANT_BRIGHTNESS);
			#endif
			//H30K_David_0001 end
			palLANProcSendToLAN(edcFADE_IN);
            palLANProcSendToLAN(edcFADE_OUT);
            palLANProcSendToLAN(edcSTARTUP_SHUTTER);

			palLANProcSendToLAN(edcPIN_PROTECT);
			palLANProcSendToLAN(edcCHANGE_PIN);
			palLANProcSendToLAN(edcSECURITY_TIMER);
			palLANProcSendToLAN(edcSECURITY_TIMER_MONTH);
			palLANProcSendToLAN(edcSECURITY_TIMER_DAY);
			palLANProcSendToLAN(edcSECURITY_TIMER_HOUR);

			palLANProcSendToLAN(edcKEYPAD_LOCK);
			palLANProcSendToLAN(edcLOGO_CHANGE);    //G100_Simon_0034
            palLANProcSendToLAN(edcKEYPAD_BACKLIGHT);
            palLANProcSendToLAN(edcPWRKEY_BACKLIGHT);
            palLANProcSendToLAN(edcHIGH_ALTITUDE);

			palLANProcSendToLAN(edcBACKUP_RESTORE_SAVE);
			palLANProcSendToLAN(edcBACKUP_RESTORE_RESTORE);

			palLANProcSendToLAN(edcNOTIFICATIONSYSTEMUPDATE);
            palLANProcSendToLAN(edcSILENTFOTA_SYSTEMUPDATE);    //A35G2_OTM_Owen_0001


            m_ucResetCount = 0; //G100_Owen_0065
        #endif
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_ACCESS_Lens_Speed_pps(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{

	if(edaREAD == eAccessMode)   //Read Function
	{

		*((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLensSpeed;
	}
	else  //Write Function
	{
	    UINT8 ucData = *((UINT8*)pValue);
		//Update RAM
		m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLensSpeed = *((UINT8*)pValue);

		//Storage : EEPROM
		if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
		{
            utilDataMgr_CommonSet_CM(eDF_UST_LENS_SPEED, (UINT8*)pValue);
		}

		//Execute Action function
		if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
		{
    		UINT8 ucData = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucLensSpeed;

            if(ucData == eLENS_SPEED_AUTO)
            {
                if(m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucLensType == eLENS_ID_AUST)
                {
                    ucData = eLENS_SPEED_UST;

                }
            }
            palMotor_Lens_Speed_Set(&ucData);
		}
        palLANProcSendToLAN(edcLENS_SPEED);
	}

	return eEXEC_CODE_PASS;
}

