eEXEC_CODE palDataMgr_Access_Model_Switch_Adjust(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A65_OPTOMA_Julie_0064//A35G2_Coda_0063
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucModelSwitchAdjust;
    }
    else  //Write Function
    {

		m_ModelSwitchTemp = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucModelSwitchAdjust; //A65_OPTOMA_Julie_0082
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucModelSwitchAdjust = *((UINT8*)pValue);
		//LOG_MSG(db_APP_SYSTEM, "(%s,%d) ucModelSwitchAdjust[%d](0=Default, 1=Neutral).\r\n", __FUNCTION__, __LINE__, m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucModelSwitchAdjust);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //EE_PUTVAR(sUserSystemSetting.sCommonSetting.ucSystemUpdateStatus, *((UINT8*)pValue));
            utilDataMgr_CommonSet_CM(eDF_MODEL_SWITCH_ADJUST, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
        	UINT8 ucData = 0xFF;
			UINT8 ucSwitch = *((UINT8*)pValue);
			char cStrTemp[64] = {'\0'}, cStrTemp2[16] = {'\0'};
			const char *m_sModelReplaceString[eMODEL_SWITCH_UNKNOW] = {"DEFAULT","NEUTRAL"};

			sprintf(cStrTemp, "edcMODEL_SWITCH_NEUTRAL");
			sprintf(cStrTemp2, "%s", m_sModelReplaceString[ucSwitch]);

			//ilDataMgr_Write_ModelChangeLog(cStrTemp, cStrTemp2); //A65_OPTOMA_Julie_0065
			utilOPD_Write_ModelChangeLog(cStrTemp, cStrTemp2); //A65_OPTOMA_Julie_0066

			//ucData = eCM_BACKGROUND_COLOR_LOGO;
			//palDataMgr_Access_BackGround_Color(edaWRITE_THROUGH_WITH_ACTION, &ucData);

			if(m_ModelSwitchTemp != m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucModelSwitchAdjust) //A65_OPTOMA_Julie_0082
			{
				UINT8 ucValue = ets_ON;
				m_ModelSwitchTemp = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucModelSwitchAdjust;
				LOG_MSG(db_APP_SYSTEM, "(%s,%d) Model Switch Change : m_ModelSwitchTemp[%d](0=DEFAULT, 1=NEUTRAL).\r\n", __FUNCTION__, __LINE__, m_ModelSwitchTemp);

				if(ucSwitch == eMODEL_SWITCH_NEUTRAL)
				{
					ucData = eCUSTOM_SPLASH_LOGO_BLUE;
					palDataMgr_CustomerSplah(edaWRITE_THROUGH_WITH_ACTION, &ucData);
				}
				else
				{
					ucData = eCUSTOM_SPLASH_LOGO_DEFAULT;
					palDataMgr_CustomerSplah(edaWRITE_THROUGH_WITH_ACTION, &ucData);
				}

				palFrontEndMgr_Model_Switch_Enable_Set(ucSwitch);
				#if defined(CUSTOM_OPTOMA)
				//appGui_PowerOff_PowerRestart_Event(); //A65_OPTOMA_Julie_0061
				//palDataMgr_Data_Access(edcFACTORY_RESET, edaWRITE_THROUGH_WITH_ACTION, &ucValue );//H30K_David_0006
				palDataMgr_Access_Factory_Reset(edaWRITE_THROUGH_WITH_ACTION, NULL);//H30K_David_0006
				palEnvironment_ReplaceModel_TimerSet();//H30K_David_0006
				#endif
			}
        }
    }

    return eEXEC_CODE_PASS;
}



