eEXEC_CODE palDataMgr_Access_DMD_199(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A35G2_Coda_0090
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        #ifdef PLATFORM_A35G2
        {
            if(palDataMgr_DMD_Type_Get() == eDMD_TYPE_S600)
            {
                *( ( UINT8 * ) pValue ) = ets_ON; //s600 support 199
            }
            else
            {
                *( ( UINT8 * ) pValue ) = ets_OFF;
            }
        }
        #else
        {

            //HEP no 1/99
            *( ( UINT8 * ) pValue ) = ets_OFF;      //HICC2_Simon_0020

        }
        #endif

        LOG_MSG(db_APP_SCHEDULE, "199 support %d\r\n", *( ( UINT8 * ) pValue ));
    }
    else if(edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode) //Write Function
    {
        // read only
        return eEXEC_CODE_FAIL;
    }

    return eEXEC_CODE_PASS;
}
