eEXEC_CODE palDataMgr_Access_WebPin_Protect_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A65_OPTOMA_Julie_0085 //A65_OPTOMA_Julie_0083 //A35G2_Coda_0125
{
    if (edaREAD == eAccessMode)  //Read Function
    {
		UINT8 ucValue = palDataMgr_PIN_Protect_Checking(); //osd(PIN_PROTECT_Status): 0=Pin protect, 99=no protect.
		if(ucValue == ePASSWORD_PROTECT_LOCKED)
		{
			*((UINT8 *)pValue) = ets_ON; //web read: 1=open pin protect.
		}
		else
		{
			*((UINT8 *)pValue) = ets_OFF; //web read: 0=no protect.
		}
    }
    else  //Write Function
    {
		palLANProcSendToLAN(edcWEB_PIN_PROTECT_STATE);
    }

    return eEXEC_CODE_PASS;
}

