//A65_OPTOMA_CL_0008  //A65_OPTOMA_CL_0011
eEXEC_CODE palDataMgr_Access_Focus_Move(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 ucLensMotorLock = 0;
    UINT8 ucValue = 0;
    UINT16 uiPeriod = 0;
    UINT32 ulValue = 0;

    if(edaREAD == eAccessMode)  //Read Function
    {
        //*((UINT32 *)pValue) = (UINT32)halMotorFocusDurationGet();
    }
    else
    {
        ulValue = *((UINT32 *)pValue);
        uiPeriod = ulValue >>16 & 0xffff;
        ucValue = ((ulValue & 0xff)== 1) ? 1:0;

        palDataMgr_Access_LensLockAllMotors(edaREAD, &ucLensMotorLock);  //get lens motor's lock status
        if (ucLensMotorLock == eLENS_LOCK_ALL_ALLOW)
        {
            //motor can move
            switch(ucValue)
            {
                case 0:
                    halMotorFocusSetWithDuration(eZOOMLENS_CMD_FOCUS_NEAR_STEP_DURATION, uiPeriod);
                    break;
                case 1:
                    halMotorFocusSetWithDuration(eZOOMLENS_CMD_FOCUS_FAR_STEP_DURATION, uiPeriod);
                    break;
            }
        }
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }
    return eEXEC_CODE_PASS;
}


