eEXEC_CODE palDataMgr_Access_TelnetCLI(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        UINT8 TelnetReplyString[256] = {0};
        palLANProcTelnetReplyStringGet(TelnetReplyString);
        memcpy((UINT8 *)pValue, TelnetReplyString, strlen(TelnetReplyString)+1);
    }
    else
    {
        sPAYLOAD sInPayload;
        sInPayload.uModule.sBIT.ucModuleID = eCMD_MODULE_LAN;
        sInPayload.uModule.sBIT.cRW = CMD_WRITE;
        sInPayload.ucSubCmd = eLAN_MSG_TELNET_CMD;

        UINT8 *TelnetCLIString = pValue;
        if(strlen(TelnetCLIString) >= MAX_IPC_PKT)
        {
            LOG_MSG(db_ASSERT, "(func:%s, line:%d)telnet command too long (%d)\n", __FUNCTION__, __LINE__, strlen(TelnetCLIString));
            return eEXEC_CODE_OVER_RANGE;
        }

        sLAN_DATA_FORMAT sLanFormatData;
        snprintf(sLanFormatData.uData.acBuffer, sizeof(sLanFormatData.uData.acBuffer), "%s", TelnetCLIString);
        memcpy(&sInPayload.aucData, &sLanFormatData, sizeof(sLAN_DATA_FORMAT));

        utilHost_PayloadSend((UINT8*)&sInPayload);

    }

    return eEXEC_CODE_PASS;
}

