eEXEC_CODE palDataMgr_Access_AutoShutdownTimer_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = 0;
    UINT8 NewVal = *((UINT8*)pValue);

    if(edaREAD == eAccessMode)
    {
        *((UINT8*)pValue) = CurVal;
    }
    else
    {
        UINT8 ucTimer = 0;
        palDataMgr_Access_AutoShutdown(edaREAD, &ucTimer);

        UINT32 CountTimer = 0;

#if(defined(CUSTOM_BARCO) || defined(CUSTOM_OPTOMA)) //A65_Owen_0006
        if(ucTimer > AUTO_SHUTDOWN_TIMER_MAX_VALUE)
            ucTimer = AUTO_SHUTDOWN_TIMER_MAX_VALUE;

        CountTimer = 60 * ucTimer;

        palEnvironment_AutoShutDownDefaultSet(CountTimer);// HICC2_Bruce_0006
        palEnvironment_AutoShutDownTimerSet(CountTimer, TRUE);

    #if 0 //###
        if(GuiCb.fpGui_IsAutoPowerDown_MenuCb() == TRUE)    //A35G2_BRC_Coda_0015
        {
    #if 1 //defined(CUSTOM_OPTOMA)
                if((palEnvironment_SleepTimerGet() > 60 || palEnvironment_SleepTimerGet() == 0)
                    && (palEnvironment_SecurityPowerDownTimerGet() > 10 || palEnvironment_SecurityPowerDownTimerGet() == 0))    //A35G2_Coda_0072 //A35G2_Coda_0075
                {
				    palDataMgr_UI_EventSend(edcUI_EVENT_AUTO_POWER_OFF_EXIT, TRUE, NULL); //GuiCb.fpGui_SendAutoPowerOffMenuExitCb();   //A35G2_Coda_0044
                }
    #else
                GuiCb.fpGui_Send_OSD_ExitCb();
    #endif
        }
    #endif
#else
        switch(ucTimer)
        {
            case eAUTO_OFF_TIME_5MIN:
                CountTimer = 60 * 5; //Sec
                break;

            case eAUTO_OFF_TIME_10MIN:
                CountTimer = 60 * 10; //Sec
                break;

            case eAUTO_OFF_TIME_15MIN:
                CountTimer = 60 * 15; //Sec
                break;

            case eAUTO_OFF_TIME_20MIN:
                CountTimer = 60 * 20; //Sec
                break;

            case eAUTO_OFF_TIME_25MIN:
                CountTimer = 60 * 25; //Sec
                break;

            case eAUTO_OFF_TIME_30MIN:
                CountTimer = 60 * 30; //Sec
                break;

            case eAUTO_OFF_TIME_NEVER:
            default:
                CountTimer = 0;
                break;
        }

        palEnvironment_AutoShutDownDefaultSet(CountTimer);
        palEnvironment_AutoShutDownTimerSet(CountTimer, TRUE);

    #if 0 //###
        if(GuiCb.fpGui_IsAutoPowerDown_MenuCb() == TRUE)    //A35G2_CDS_Coda_0035
        {
            palDataMgr_UI_EventSend(edcUI_EVENT_AUTO_POWER_OFF_EXIT, TRUE, NULL); //GuiCb.fpGui_SendAutoPowerOffMenuExitCb();
        }
    #endif
#endif

    }

    return eEXEC_CODE_PASS;
}

