eEXEC_CODE palDataMgr_Access_UI_Event_AF_Cal_Fail(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT32 CurVal = m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail;
    UINT32 NewVal = *((UINT32*)pValue);

    if(edaREAD == eAccessMode)
    {
        *((UINT32*)pValue) = CurVal;
    }
    else
    {
        //m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = NewVal;

        switch (NewVal)//error index //Messge info, please check language table
		{
		   	case eAF_HID_CONNECT_ERR: //  2
			case eAF_GET_FOCUS_VALUE_ERR: //  5
			case eAF_GET_WRGB_ERR: //  14
			    m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 0; //please connect the camera
			    break;

		   	case eAF_GET_COLOR_WHEEL_SPD_ERR: //  9
			   	m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 1; //Camera dose not support this color wheel speed
			   	break;

		   	case eAF_TAKE_PIC_BEFORE_ERR: //  12
			case eAF_CAMERA_GENERAL_ERR: //  19
			case eAF_GET_CLEAR_POSITION_ERR: //  22
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 2; //Image recognition error
				break;

		   	case eAF_OVER_EXPOSURE_ERR: //  15
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 3; //The image is overexposed
			   	break;

		   	case eAF_WRGB_ERR: //  16
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 4; //The image is underxposed
			   	break;

		   	case eAF_SET_AUTO_GAIN_ERR: //  17
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 5; //Image capture error
			   	break;

		   	case eAF_CAMERA_BUSY_ERR: //  18
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 6; //Camera is busy
			   	break;

			case eAF_LENSLOCK_ERR: // 21:
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 7; //Operation des not support lens lock
			   	break;

		   	default:
			   	m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AF_Cal_Fail = 8; //Calibration fail
			   	break;
		}
    }

    return eEXEC_CODE_PASS;
}


