eEXEC_CODE palDataMgr_Access_UI_Event_AC_Cal_Fail(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT32 CurVal = m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail;
    UINT32 NewVal = *((UINT32*)pValue);

    if(edaREAD == eAccessMode)
    {
        *((UINT32*)pValue) = CurVal;
    }
    else
    {
        //m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = NewVal;

        switch (NewVal)
		{
		   	case eAWC_GET_COLOR_WHEEL_SPD_ERR: // 5
			   m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 0; //Camera dose not support this color wheel speed
			   break;

		   	case eAWC_AWB_ERR: // 6
			   m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 1; //please connect the camera
			   break;

		   	case eAWC_SEARCH_ROI_ERR: // 7
			case eAWC_GET_WRGB_ERR: // 8
			case eAWC_TUNE_EXPOSURE_ERR: // 15
			case eAWC_TUNE_WHITEBALANCE_ERR: // 16
			case eAWC_LOCK3A_ERR: // 19
			case eAWC_TAKEPICTURE_ERR: // 20
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 2; //Image recognition error
				break;

		   	case eAWC_SET_GAIN_ERR: //  9
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 3; //Image capture error
			   	break;

		   	case eAWC_CAMERA_BUSY_ERR: // 1
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 4; //Camera is busy
			   	break;

			case eAWC_INPUTSOURCE_ERR: // 12
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 5; //Please disable auto source before calibration
				break;

			case eAWC_NOTEVER_ERR: // 13
			case eAWC_COMMAND_PARA_ERR: // 14
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 6; //Operation is not supported
				break;

		   	case eAWC_AUTOTUNE_OVEREXPOSURE: // 17
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 7; //The image is overexposed
			   	break;

		   	case eAWC_AUTOTUNE_UNDEREXPOSURE: // 18
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 8; //The image is underxposed
			   	break;

		   	default:
			   	m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_AC_Cal_Fail = 9; //Calibration fail
			   	break;
		}
    }

    return eEXEC_CODE_PASS;
}



