eEXEC_CODE palDataMgr_Access_UI_Event_ACU_Cal_Fail(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT32 CurVal = m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail;
    UINT32 NewVal = *((UINT32*)pValue);

    if(edaREAD == eAccessMode)
    {
        *((UINT32*)pValue) = CurVal;
    }
    else
    {
        //m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = NewVal;

        switch (NewVal)
		{
			case eACU_STATUS_TARGET_POSITION_ERR: // 2
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 0; //Operation is not supported
				break;

		   	case eACU_STATUS_HID_CONNECT_ERR: //
			case eACU_STATUS_TAKE_PICTURE_ERR: //  12
			   	m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 1; //please connect the camera
			   	break;

			case eACU_STATUS_SYSTEM_ERR: //  4
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 2; //System communication error
				break;

			case eACU_STATUS_CAMERA_ROI_ERR: //  8
			//case eACU_STATUS_CAMERA_ROUGH_AUTO_TUNE_ERR: // 9 //HICC2_Doulas_0022 deprecated
			case eACU_STATUS_CAMERA_AUTO_TUNE_ERR: //  10
			case eACU_STATUS_FIND_POINTS_ERR: //  11
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 3; //Image recognition error
				break;

		   	case eACU_STATUS_GET_RGB_ERR: //  13
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 4; //Image capture error
			   	break;

			case eACU_STATUS_CALCULATE_UNIFORMITY_ERR: //  14
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 5; //Out of calibration range
				break;

		   	case eACU_STATUS_BUSY_ERR: //  15
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 6; //Camera is busy
			   	break;

		   	case eACU_STATUS_COLOR_WHEEL_SPEED_NOT_SUPPORT_ERR: //  16
			   	m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 7; //Camera dose not support this color wheel speed
			   	break;

			case eACU_STATUS_GAMMA_NOT_SUPPORT_ERR: //  17
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 8; //Operation does not support this gamma
				break;

		   	case eACU_STATUS_OVER_EXPOSURE_ERR: //  18
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 9; //The image is overexposed
			   	break;

		   	case eACU_STATUS_UNDER_EXPOSURE_ERR: //  19
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 10; //The image is underxposed
			   	break;

			case eACU_STATUS_FUNCTION_NOT_ENABLE_ERR: //  20
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 11; //Please enable the function before calibration
			   	break;

			case eACU_STATUS_FIND_TARGET_ERR: //  21  //HICC2_Simon_0003
				m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 12; //Target recognition error
			   	break;

		   	default:
			   	m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_ACU_Cal_Fail = 13; //Calibration fail
			   	break;
		}
    }

    return eEXEC_CODE_PASS;
}

