//using sDST_LENS_INFO structure
eEXEC_CODE palDataMgr_Access_CurLensInfo(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)
    {
        memcpy(pValue, &m_sAppDataMgrInfo.sSystemValues.sLensInfo, sizeof(sDST_LENS_INFO));
    }
    else
    {
    #if defined(PLATFORM_R70K) || defined(PLATFORM_H30_4K) //HICC2_AC_0010
        palMotor_LSM_Factory_Menu();
        palMotor_LSM_Lens_ID_Get();
    #else
        //get data from driver

        sLENS_INFO sLensInfo;
        sLENSMEMORY sLensMem;
        sMOTOR_LIMIT sFocus;
        sMOTOR_LIMIT sZoom;
        sMOTOR_LIMIT sLensBacklash = {0};
        UINT32 ulLensIDAdc;
        UINT8 ucLensSetting = 0;
        UINT32 ulStep[2] = {0};
        sLENS_LIMIT sFullLimit, sActiveLimit;
        UINT8 aucVersion[2] = {0};

        palMotor_ZoomLimit_Get(&sZoom);
        palMotor_FocusLimit_Get(&sFocus);
        palMotorLensPositionGet(&sLensMem);
        palMotor_Lens_Backlash_Get(&sLensBacklash);
        palMotor_LensIdADC_Get(&ulLensIDAdc);
        palMotor_LensCenterSettingGet(&ucLensSetting);
        palMotor_LensCenterGet((BYTE*)&ulStep);
        //palMotor_LensPositionFullGet((UINT8*)&sFullLimit);
        palMotor_LensPositionActiveGet((UINT8*)&sActiveLimit);
        palEnvironment_LENS_EEPROM_Version_Get(aucVersion); //HICC2_Julie_0055

        sLensInfo.wLensHPosition = sLensMem.wLensHPosition;
        sLensInfo.wLensVPosition = sLensMem.wLensVPosition;
        sLensInfo.wZoomPosition = sLensMem.wZoomPosition;
        sLensInfo.wFocusPosition = sLensMem.wFocusPosition;
        sLensInfo.cDirH = sLensMem.cDirH;  //OSD (Left : 0,Down : 1), Motor Driver (Near Sensor : 1,Far Sensor : 0)
        sLensInfo.cDirV = sLensMem.cDirV; //OSD (Up : 1,Down : 0), Motor Driver (Near Sensor : 1,Far Sensor : 0)
        sLensInfo.cDirZoom  = sLensMem.cDirZoom;
        sLensInfo.cDirFocus = sLensMem.cDirFocus;
        sLensInfo.wZoomMaximumValue = sZoom.wMaximumValue;
        sLensInfo.wZoomMinimumValue = sZoom.wMinimumValue;
        sLensInfo.wFocusMaximumValue = sFocus.wMaximumValue;
        sLensInfo.wFocusMinimumValue = sFocus.wMinimumValue;
        sLensInfo.wBacklashH = sLensBacklash.wMaximumValue;
        sLensInfo.wBacklashV = sLensBacklash.wMinimumValue;
        sLensInfo.ulLensIDAdcValue = ulLensIDAdc;
        sLensInfo.ulLensCenterH = ulStep[0];
        sLensInfo.ulLensCenterV = ulStep[1];
        sLensInfo.wLensEepromVersion = (aucVersion[0] << 8) | aucVersion[1]; //HICC2_Julie_0055

        //sLensInfo.ulFullMaxValueH = sFullLimit.dwMaxValueH; //HICC2_Casper_0035
        //sLensInfo.ulFullMinValueH = sFullLimit.dwMinValueH; //HICC2_Casper_0035
        //sLensInfo.ulFullMaxValueV = sFullLimit.dwMaxValueV; //HICC2_Casper_0035
        //sLensInfo.ulFullMinValueV = sFullLimit.dwMinValueV; //HICC2_Casper_0035
        sLensInfo.ulActiveMaxValueH = sActiveLimit.dwMaxValueH;
        sLensInfo.ulActiveMinValueH = sActiveLimit.dwMinValueH;
        sLensInfo.ulActiveMaxValueV = sActiveLimit.dwMaxValueV;
        sLensInfo.ulActiveMinValueV = sActiveLimit.dwMinValueV;

        LOG_MSG(db_HAL_LENS, "Lens Pos H %d, V %d, dir H %d, V %d, Backlash H %d, V %d\n", sLensInfo.wLensHPosition, sLensInfo.wLensVPosition, sLensInfo.cDirH, sLensInfo.cDirV, sLensBacklash.wMaximumValue, sLensBacklash.wMinimumValue);
        LOG_MSG(db_HAL_LENS, "Pos Zoom  %d, Focus %d, Zoom dir %d, Focus dir %d\n", sLensInfo.wZoomPosition, sLensInfo.wFocusPosition, sLensInfo.cDirZoom, sLensInfo.cDirFocus);
        LOG_MSG(db_HAL_LENS, "Lens Zoom Max %d, Zoom Min %d, Focus Max %d, Focus Min %d\n", sZoom.wMaximumValue, sZoom.wMinimumValue, sFocus.wMaximumValue, sFocus.wMinimumValue);

        m_sAppDataMgrInfo.sSystemValues.ucLensCenterSetting = ucLensSetting;
        memcpy(&m_sAppDataMgrInfo.sSystemValues.sLensInfo, &sLensInfo, sizeof(sLensInfo));
    #endif
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_LensHeaderInfo(eDATA_ACCESS_MODE eAccessMode, void *pValue)//HICC2_Julie_0060//HICC2_Julie_0061
{
    if(edaREAD == eAccessMode)
    {
        memcpy(pValue, &m_sAppDataMgrInfo.sSystemValues.sLensHeaderInfo, sizeof(sDST_LENS_HEADER_INFO));
    }
    else
    {
        sLENS_HEADER sLensHeaderInfo = {0};
        UINT8 cString[32] = {0};
        UINT8 cSize = 0, cIndex = 0;

        //get data from driver
        for(cIndex = 0; cIndex < eLENS_SYS_PARAM_NUMBERS; cIndex++)
        {
            halMotor_Lens_Header_Index_Set(cIndex);

            memset(cString, 0, sizeof(cString));
            MS_SLEEP(50);

            cSize = halMotor_Lens_Header_Param_Size(cIndex);
            halMotor_Lens_Header_Get(cSize, (UINT8*)&cString);

            switch (cIndex)
            {
                case eLENS_HEADER_VENDOR_SN:
                    memcpy(sLensHeaderInfo.acVerdorSN, &cString, MOTOR_SN_NUMBER);
                    break;

                case eLENS_HEADER_NVRAM_ID:
                    sLensHeaderInfo.lLensNvramId = cString[0];
                    break;

                default:
                    break;
            }
        }
        memcpy(&m_sAppDataMgrInfo.sSystemValues.sLensHeaderInfo, &sLensHeaderInfo, sizeof(sLensHeaderInfo));
    }
    return eEXEC_CODE_PASS;
}

