eEXEC_CODE palDataMgr_Access_Schedule_Packet(eDATA_ACCESS_MODE eAccessMode, void *pValue) //HICC2_Doulas_0035
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        sLAN_SCHEDULE_StructPayload sStructPayload;
        sLAN_SCHEDULE_PACKET sSendSchedule;

        memset((UINT8 *)&sStructPayload, 0, sizeof(_sStructPayload));
        memset((UINT8*)&sSendSchedule, 0, sizeof(sLAN_SCHEDULE_PACKET));

        palDataMgr_Schedule_Build_LanPacket(&sSendSchedule);

        memcpy((UINT8*)&sStructPayload.Data, (UINT8*)&sSendSchedule, sizeof(sLAN_SCHEDULE_PACKET));
        memcpy((UINT8 *)pValue, (UINT8*)&sStructPayload, sizeof(sLAN_SCHEDULE_StructPayload));

        LOG_MSG(db_APP_SCHEDULE, "(%s,%d) Schedule Struct %d\n", __FUNCTION__, __LINE__, sizeof(sLAN_SCHEDULE_StructPayload));
    }
    else  //Write Function
    {
        //Update RAM
        sLAN_SCHEDULE_StructPayload sStructPayload;
        sLAN_SCHEDULE_PACKET sLanScheduleData;
        UINT8 ucTimer = 0;

        memset((UINT8 *)&sStructPayload, 0, sizeof(_sStructPayload));
        memset((UINT8*)&sLanScheduleData, 0, sizeof(sLAN_SCHEDULE_PACKET));
        LOG_MSG(db_APP_SCHEDULE, "(%s,%d) utilCLI_LAN_ScheduleCmd_Set Ready\r\n", __FUNCTION__, __LINE__);

        //ToDo
        memcpy((UINT8*)&sStructPayload, ((UINT8*)pValue), sizeof(sLAN_SCHEDULE_StructPayload));
        memcpy((UINT8*)&sLanScheduleData, (UINT8*)&sStructPayload.Data, sizeof(sLAN_SCHEDULE_PACKET));

        palDataMgr_Schedule_Unpack_LanPacket(&sLanScheduleData);
        //palEnvironment_AutoShutDownClear(); //A35G2_BRC_Coda_0015

        palDataMgr_Access_AutoShutdown(edaREAD, (void*)&ucTimer);
        palDataMgr_Access_AutoShutdown(edaWRITE_RAM_ONLY_WITH_ACTION, (void*)&ucTimer);

        palLANProcScheduleSend_Update();//HICC2_Julie_0029
        palLANProcScheduleSend();

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
        }
    }
    return eEXEC_CODE_PASS;
}


