eEXEC_CODE palDataMgr_Geo_convertTPtoDTDT(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_CONVERT_TP2DTDT));
    }
    else
    {
        sTP_DATA *TpData = (sTP_DATA *)pValue;
        UINT16 uiSize = TpData->Width * TpData->Height ;
        size_t ret;

        //memset(&TpData, psInData->aucData ,*pwByteCount);
        //float *tpx = (float *)malloc(TpData->width * TpData->height * sizeof(float));
        //float *tpy = (float *)malloc(TpData->width * TpData->height * sizeof(float));
        //memset(tpx, TpData->tpx , (TpData->width * TpData->height * sizeof(float)) );
        //memset(tpy, TpData->tpy , (TpData->width * TpData->height * sizeof(float)) );
        //halWarping_convertTPtoDTDT(TpData->tpx, TpData->tpy, TpData->Width, TpData->Height);
        //free(tpx);
        //free(tpy);

        FILE *pFile_TPx = NULL;
        FILE *pFile_TPy = NULL;
        pFile_TPx = fopen(TpData->FileName_TPx, "rb");
        pFile_TPy = fopen(TpData->FileName_TPy, "rb");
        LOG_MSG(db_HAL_WARPING, "\nTp filename %s %s %d %d \n", TpData->FileName_TPx
                                                              , TpData->FileName_TPy
                                                              , TpData->Width
                                                              , TpData->Height);
        if(pFile_TPx == NULL || pFile_TPy == NULL)
        {
        	if(pFile_TPx != NULL)
        		fclose(pFile_TPx);

        	if(pFile_TPy != NULL)
        		fclose(pFile_TPy);

            LOG_MSG(db_HAL_WARPING, "\nCan not open file (%s)(%s)\n", TpData->FileName_TPx , TpData->FileName_TPy);
            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }

        FLOAT *pucData_TPx = (FLOAT *)malloc(uiSize * sizeof(FLOAT));
        FLOAT *pucData_TPy = (FLOAT *)malloc(uiSize * sizeof(FLOAT));
        if(pucData_TPx == NULL || pucData_TPy == NULL)
        {
    		if(pucData_TPx != NULL)
    			free(pucData_TPx);

    		if(pucData_TPy != NULL)
    			free(pucData_TPy);

            if(pFile_TPx != NULL)
                fclose(pFile_TPx);

            if(pFile_TPy != NULL)
                fclose(pFile_TPy);

            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }
        memset(pucData_TPx, 0xFF, (uiSize * sizeof(FLOAT)));
        memset(pucData_TPy, 0xFF, (uiSize * sizeof(FLOAT)));
        ret = fread(pucData_TPx, sizeof(FLOAT), uiSize, pFile_TPx);
        if(ret != uiSize)
        {
            LOG_MSG(db_HAL_WARPING, "TPx file read error, ret=%zu, expected=%u\n", ret, uiSize);
            free(pucData_TPx);
            free(pucData_TPy);
            fclose(pFile_TPx);
            fclose(pFile_TPy);
            ASSERT_ALWAYS();
            return eEXEC_CODE_FAIL;
        }

        ret = fread(pucData_TPy, sizeof(FLOAT), uiSize, pFile_TPy);
        if(ret != uiSize)
        {
            LOG_MSG(db_HAL_WARPING, "TPy file read error, ret=%zu, expected=%u\n", ret, uiSize);
            free(pucData_TPx);
            free(pucData_TPy);
            fclose(pFile_TPx);
            fclose(pFile_TPy);
            ASSERT_ALWAYS();
            return eEXEC_CODE_FAIL;
        }

        //printf("\npucData_TPx[0]=%d , pucData_TPx[1]=%d , pucData_TPx[2]=%d\n", pucData_TPx[0], pucData_TPx[1], pucData_TPx[2] ) ;
        //printf("pucData_TPy[0]=%d , pucData_TPy[1]=%d , pucData_TPy[2]=%d\n", pucData_TPy[0], pucData_TPy[1], pucData_TPy[2] ) ;

        palGeo_convertTPtoDTDT(pucData_TPx, pucData_TPy, TpData->Width, TpData->Height);

        free(pucData_TPx);
        free(pucData_TPy);
        fclose(pFile_TPx);
        fclose(pFile_TPy);
    }

    return eEXEC_CODE_PASS;
}

