//Blending API
eEXEC_CODE palDataMgr_Geo_SetBlendingTable(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        //*(UINT8 *)pValue = 0;
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_SET_DBD_BLENDING_TABLE));
    }
    else
    {
        eHAL_WARPING_EXEC_CODE eResult = eHAL_WARPING_EXEC_CODE_PASS;
        sBLENDING_TABLE_INFO *sDotByDotInfo = (sBLENDING_TABLE_INFO *)pValue;

        UINT8 nDataMode = 0;
        FILE *pFile = NULL;

        if(sDotByDotInfo->FileName == NULL)
        {
            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }

        pFile = fopen(sDotByDotInfo->FileName, "rb");
        LOG_MSG(db_HAL_WARPING, "\nDBD filename %s\n", sDotByDotInfo->FileName);

        if(pFile == NULL)
        {
            LOG_MSG(db_HAL_WARPING, "\nCan not open DBD file\n");
            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }

        UINT32 ulSize = sDotByDotInfo->Width * sDotByDotInfo->Height ;
        UINT8 *pucDBD_Data = (UINT8 *)malloc(ulSize);
        if(pucDBD_Data == NULL)
        {
            fclose(pFile);
            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }
        memset(pucDBD_Data, 0xFF, ulSize);
        if(fread(pucDBD_Data, 1, ulSize, pFile) != ulSize)
        {
            LOG_MSG(db_HAL_WARPING, "(func:%s, line:%d) fread fail\n", __FUNCTION__, __LINE__);
        }

        LOG_MSG(db_HAL_WARPING, "\nWidth=%d , Height=%d\n", sDotByDotInfo->Width , sDotByDotInfo->Height) ;

        palGeo_DBD_BlendingTable_Set(sDotByDotInfo->Width, sDotByDotInfo->Height, pucDBD_Data);

        free(pucDBD_Data);
        fclose(pFile);

        LOG_MSG(db_HAL_WARPING , "%s End" , __FUNCTION__);

    }

    return eEXEC_CODE_PASS;

}

