// ==============================================================================
// DESCRIPTION: Get the ACU data and send to the iChip, and save the data if it is valid.
// Params: psInData : ACU data
// Params: psOutData :
// Params: pwByteCount :
// Returns: rcSUCCESS: success
// Returns: rcERROR: fail
//
// Modification History
// --------------------
// 2021/06/17, Tim Chen modify
// --------------------
// ==============================================================================
eEXEC_CODE palDataMgr_Geo_ColorUniformityInterface(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_COLOR_UNIFORMITY_INTERFACE));
    }
    else
    {
        sCOLOR_UNIFORMITY_INFO *sColorUniformityInfo = (sCOLOR_UNIFORMITY_INFO *)pValue;

        if(sColorUniformityInfo->FileName == NULL)
        {
            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }

        FILE *pFile = NULL;
        pFile = fopen(sColorUniformityInfo->FileName, "rb");
        LOG_MSG(db_HAL_WARPING, "\nColor Uniformity filename %s\n", sColorUniformityInfo->FileName);
        LOG_MSG(db_HAL_WARPING, "Color Uniformity WriteEnable %d\n", sColorUniformityInfo->ucWriteEnable);
        if(pFile == NULL)
        {
            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }

        UINT8 *pucData = (UINT8 *)malloc(WARPING_COLOR_UNIFORMITY_SIZE);
        if(pucData == NULL)
        {
            fclose(pFile);
            ASSERT_ALWAYS();

            return eEXEC_CODE_FAIL;
        }
        memset(pucData, 0xFF, WARPING_COLOR_UNIFORMITY_SIZE);
        if(fread(pucData, 1, WARPING_COLOR_UNIFORMITY_SIZE, pFile) != WARPING_COLOR_UNIFORMITY_SIZE)
        {
            LOG_MSG(db_HAL_WARPING, "(func:%s, line:%d) fread fail\n", __FUNCTION__, __LINE__);
        }

        if( sColorUniformityInfo->ucWriteEnable == eACU_SET_ICHIP_ONLY )
        {
            palGeo_Color_Uniformity_File_Apply(sColorUniformityInfo->FileName);

            if(palDataMgr_CU_Data_Enable_Get() &&
               palDataMgr_CU_Data_Status_Get() &&
               palSystem_PanelID_Get() == PANEL_2D_OUTPUT
            )
            {

            }
            else
            {
                palGeo_Color_Uniformity_Enable_Set(0);
            }
        }
        else
        {
            palGeo_Color_Uniformity_Data_Save(sColorUniformityInfo->ucWriteEnable, pucData);

            UINT8 FileValid = 0;
            palDataMgr_Access_ACU_Save(edaREAD, &FileValid);
            FileValid |= (UINT8)( 1 << ( (eACU_FILE_LIST)sColorUniformityInfo->ucWriteEnable - 1 ) );
            palDataMgr_Access_ACU_Save(edaWRITE_THROUGH_WITH_ACTION, &FileValid);
        }

        free(pucData);
        fclose(pFile);
    }

    return eEXEC_CODE_PASS;
}


