eEXEC_CODE palDataMgr_Geo_ClearOSD(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //H2PF_Simon_0038
{
    UINT8 CurVal = m_sAppDataMgrInfo.sSystemValues.sGEO_INFO.ucGeoClear;
    UINT8 NewVal = *(UINT8 *)pValue;

    if(edaREAD == eAccessMode)  //Read Function
    {
        *(UINT8 *)pValue = CurVal;
    }
    else
    {
        m_sAppDataMgrInfo.sSystemValues.sGEO_INFO.ucGeoClear = NewVal;
        LOG_MSG(db_HAL_WARPING, "ClearOSD Cmd %d\n", NewVal);

        #ifdef SAME_RAM_FOR_BEFORE_WARP_OSD_AND_SCALER_OSD
        {
            uPALGEOAPI_INFO uInfo = {.sGFN_CLEAR_OSD_INFO.eLocation = (eWARPOSD_INSERT_LOCATION)NewVal};
            palGeo_DrawOSDQueueSet(eGFN_CLEAR_OSD, uInfo);
        }
        #else
        {
            palGeo_ClearOSD(NewVal);
        }
        #endif
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Geo_DrawRect(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_DRAW_RECT));
    }
    else
    {
        sWARPOSD_RECT_DRAW_INFO *sDrawRectInfo = (sWARPOSD_RECT_DRAW_INFO *)pValue;

        #ifdef SAME_RAM_FOR_BEFORE_WARP_OSD_AND_SCALER_OSD  //H2PF_Simon_0038
        {
            uPALGEOAPI_INFO uInfo = {.sGFN_DRAW_RECT_INFO.eInsertLocation   = sDrawRectInfo->ucLayerMode,
                                     .sGFN_DRAW_RECT_INFO.PosX              = sDrawRectInfo->iX,
                                     .sGFN_DRAW_RECT_INFO.PosY              = sDrawRectInfo->iY,
                                     .sGFN_DRAW_RECT_INFO.Width             = sDrawRectInfo->iWidth,
                                     .sGFN_DRAW_RECT_INFO.Height            = sDrawRectInfo->iHeight,
                                     .sGFN_DRAW_RECT_INFO.ColorIdx          = sDrawRectInfo->iColorIndex
                                    };

            palGeo_DrawOSDQueueSet(eGFN_DRAW_RECT, uInfo);
        }
        #else
        {
            palGeo_DrawRect(sDrawRectInfo->ucLayerMode,
                            sDrawRectInfo->iX,
                            sDrawRectInfo->iY,
                            sDrawRectInfo->iWidth,
                            sDrawRectInfo->iHeight,
                            sDrawRectInfo->iColorIndex );
        };
        #endif
    }

    return eEXEC_CODE_PASS;
}


eEXEC_CODE palDataMgr_Geo_DrawRects(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_DRAW_RECTS));
    }
    else
    {
        sWARPOSD_RECTS_DRAW_INFO *sRectsInfo = (sWARPOSD_RECTS_DRAW_INFO *)pValue;

        if(sRectsInfo->sRect.ucLayerMode == eWDT_AFTER_WARP)  //on OSD  //A65_OPTOMA_CL_0007
        {
            palGeoAdvWarpShowOsdPattern_Unblocked_TwistLink(PAT_TYPE__DRAW_RECTS);   //HICC2_Simon_0008
        }
        for(UINT16 uiIndex = 0 ; uiIndex < sRectsInfo->ucTotalNumber ; uiIndex++ )
        {
            sWARPOSD_RECTS_DRAW_INFO *sSingleRectAddr = sRectsInfo + uiIndex;  //A65_OPTOMA_CL_0007
            sWARPOSD_RECT_DRAW_INFO *sRectInfo = &sSingleRectAddr->sRect ;

            if( sRectInfo->ucLayerMode >= eWDT_INVALID ||
                sRectInfo->iX < 0 ||
                sRectInfo->iY < 0 ||
                sRectInfo->iX >= halWarping_HResGet() ||
                sRectInfo->iY >= halWarping_VResGet() ||
                sRectInfo->iWidth  > halWarping_HResGet() ||
                sRectInfo->iHeight > halWarping_VResGet()
               )
            {
                LOG_MSG(db_HAL_WARPING, "Error RECT Data = %d %d %d %d %d %d\n", sRectInfo->ucLayerMode,
                                                                                 sRectInfo->iX,
                                                                                 sRectInfo->iY,
                                                                                 sRectInfo->iWidth,
                                                                                 sRectInfo->iHeight,
                                                                                 sRectInfo->iColorIndex );

                continue;
            }
            LOG_MSG(db_HAL_WARPING, "Rect Info = %d %d %d %d %d %d\n", sRectInfo->ucLayerMode,
                                                                       sRectInfo->iX,
                                                                       sRectInfo->iY,
                                                                       sRectInfo->iWidth,
                                                                       sRectInfo->iHeight,
                                                                       sRectInfo->iColorIndex );

            #ifdef SAME_RAM_FOR_BEFORE_WARP_OSD_AND_SCALER_OSD
            {
                uPALGEOAPI_INFO uInfo = {.sGFN_DRAW_RECT_INFO.eInsertLocation   = sRectInfo->ucLayerMode,
                                         .sGFN_DRAW_RECT_INFO.PosX              = sRectInfo->iX,
                                         .sGFN_DRAW_RECT_INFO.PosY              = sRectInfo->iY,
                                         .sGFN_DRAW_RECT_INFO.Width             = sRectInfo->iWidth,
                                         .sGFN_DRAW_RECT_INFO.Height            = sRectInfo->iHeight,
                                         .sGFN_DRAW_RECT_INFO.ColorIdx          = sRectInfo->iColorIndex
                                        };

                palGeo_DrawOSDQueueSet(eGFN_DRAW_RECT, uInfo);
            }
            #else
            {
                palGeo_DrawRect(sRectInfo->ucLayerMode,
                                sRectInfo->iX,
                                sRectInfo->iY,
                                sRectInfo->iWidth,
                                sRectInfo->iHeight,
                                sRectInfo->iColorIndex);
            }
            #endif

        }
    }

    return eEXEC_CODE_PASS;

}
