eEXEC_CODE palDataMgr_Geo_DrawLines(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_DRAW_LINES));
    }
    else
    {
        sWARPOSD_LINES_DRAW_INFO *psLinesInfo = (sWARPOSD_LINES_DRAW_INFO *)pValue;

        UINT16 uiTotalLine = psLinesInfo->ucTotalNumber;

        LOG_MSG(db_HAL_WARPING, "%s Total %d\n", __FUNCTION__, uiTotalLine);

        for(UINT16 uiIndex = 0 ; uiIndex < uiTotalLine ; uiIndex++ )
        {
            sWARPOSD_LINES_DRAW_INFO *sSingleLineAddr = psLinesInfo + uiIndex;
            sWARPOSD_LINE_DRAW_INFO *sLineInfo = &sSingleLineAddr->sLine ;

            LOG_MSG(db_HAL_WARPING, "Line Number = %d - %d\n", sSingleLineAddr->ucTotalNumber , uiIndex);

            if( sLineInfo->ucLayerMode >= eWDT_INVALID ||
                sLineInfo->iLeft   < 0 ||
                sLineInfo->iTop    < 0 ||
                sLineInfo->iRight  < 0 || sLineInfo->iRight  >= halWarping_HResGet() ||
                sLineInfo->iBottom < 0 || sLineInfo->iBottom >= halWarping_VResGet()
               )
            {
                LOG_MSG(db_HAL_WARPING, "Error Line Data = %d %d %d %d %d 0x%X\n", sLineInfo->ucLayerMode,
                                                                                 sLineInfo->iLeft,
                                                                                 sLineInfo->iTop,
                                                                                 sLineInfo->iRight,
                                                                                 sLineInfo->iBottom,
                                                                                 sLineInfo->lColorIndex );

                continue;
            }

            LOG_MSG(db_HAL_WARPING, "Line Info = %u %u %u %u %u 0x%X\n", sLineInfo->ucLayerMode,
                                                                       sLineInfo->iLeft,
                                                                       sLineInfo->iTop,
                                                                       sLineInfo->iRight,
                                                                       sLineInfo->iBottom,
                                                                       sLineInfo->lColorIndex );

            #if 0
            halWarping_AP_DrawRect(sLineInfo->ucLayerMode,
                                   sLineInfo->iLeft,
                                   sLineInfo->iTop,
                                   sLineInfo->iRight  - sLineInfo->iLeft + 1,
                                   sLineInfo->iBottom - sLineInfo->iTop  + 1,
                                   sLineInfo->iColorIndex
                                   );
            #endif

            #ifdef SAME_RAM_FOR_BEFORE_WARP_OSD_AND_SCALER_OSD  //H2PF_Simon_0038
            {
                uPALGEOAPI_INFO uInfo = {.sGFN_DRAW_LINE_INFO.eLocation   = sLineInfo->ucLayerMode,
                                         .sGFN_DRAW_LINE_INFO.Left        = sLineInfo->iLeft,
                                         .sGFN_DRAW_LINE_INFO.Top         = sLineInfo->iTop,
                                         .sGFN_DRAW_LINE_INFO.Right       = sLineInfo->iRight,
                                         .sGFN_DRAW_LINE_INFO.Bottom      = sLineInfo->iBottom,
                                         .sGFN_DRAW_LINE_INFO.ColorIndex  = sLineInfo->lColorIndex
                                        };

                palGeo_DrawOSDQueueSet(eGFN_DRAW_LINE, uInfo);
            }
            #else
            {
                //only draw on memory (before warp)
                palGeo_DrawLine(sLineInfo->ucLayerMode,
                                sLineInfo->iLeft,
                                sLineInfo->iTop,
                                sLineInfo->iRight,
                                sLineInfo->iBottom,
                                sLineInfo->lColorIndex
                                );
            }
            #endif

        }
    }

    return eEXEC_CODE_PASS;

}

