eEXEC_CODE palDataMgr_Geo_CopyOSDRect(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_DRAW_COPY_OSD_RECT));
    }
    else
    {
        sWARPOSD_COPY_OSD_RECT_INFO *sCopyOSDRectInfo = (sWARPOSD_COPY_OSD_RECT_INFO *)pValue;

        ePAL_GEO_EXEC_CODE eResult = ePAL_GEO_EXEC_CODE_PASS;

        #ifdef SAME_RAM_FOR_BEFORE_WARP_OSD_AND_SCALER_OSD  //H2PF_Simon_0038
        {
            uPALGEOAPI_INFO uInfo = {.sGFN_DRAW_COPY_OSD_RECT_INFO.eLocation    = sCopyOSDRectInfo->ucLayerMode,
                                     .sGFN_DRAW_COPY_OSD_RECT_INFO.SrcX         = sCopyOSDRectInfo->iSourceX,
                                     .sGFN_DRAW_COPY_OSD_RECT_INFO.SrcY         = sCopyOSDRectInfo->iSourceY,
                                     .sGFN_DRAW_COPY_OSD_RECT_INFO.SrcWidth     = sCopyOSDRectInfo->iSourceWidth,
                                     .sGFN_DRAW_COPY_OSD_RECT_INFO.SrcHeight    = sCopyOSDRectInfo->iSourceHeight,
                                     .sGFN_DRAW_COPY_OSD_RECT_INFO.DestX        = sCopyOSDRectInfo->iDestinationX,
                                     .sGFN_DRAW_COPY_OSD_RECT_INFO.DestY        = sCopyOSDRectInfo->iDestinationY
                                    };

            palGeo_DrawOSDQueueSet(eGFN_DRAW_COPY_OSD_RECT, uInfo);
        }
        #else
        {
            eResult = palGeo_CopyOSDRect(sCopyOSDRectInfo->ucLayerMode,   //G100_Simon_0079
                                         sCopyOSDRectInfo->iSourceX,
                                         sCopyOSDRectInfo->iSourceY,
                                         sCopyOSDRectInfo->iSourceWidth,
                                         sCopyOSDRectInfo->iSourceHeight,
                                         sCopyOSDRectInfo->iDestinationX,
                                         sCopyOSDRectInfo->iDestinationY);
        }
        #endif

        if(eResult == ePAL_GEO_EXEC_CODE_PASS)
        {
            return eEXEC_CODE_PASS;
        }
        else
        {
            ASSERT_ALWAYS();
            return eEXEC_CODE_FAIL;
        }
    }

    return eEXEC_CODE_PASS;
}

