eEXEC_CODE palDataMgr_Geo_DrawBoxes(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        memset(pValue, 0, palDataMgr_DataSizeGet(edcGEO_DRAW_BOXES));
    }
    else
    {
        sWARPOSD_BOXES_DRAW_INFO *psBoxesInfo = (sWARPOSD_BOXES_DRAW_INFO *)pValue;

        UINT16 uiTotalBox = psBoxesInfo->ucTotalNumber;

        LOG_MSG(db_HAL_WARPING, "%s Total %d\n", __FUNCTION__, uiTotalBox);

        for(UINT16 uiIndex = 0 ; uiIndex < uiTotalBox ; uiIndex++ )
        {
            sWARPOSD_BOXES_DRAW_INFO *sSingleBoxAddr = psBoxesInfo + uiIndex;
            sWARPOSD_BOX_DRAW_INFO *sBoxInfo = &sSingleBoxAddr->sBox ;

            LOG_MSG(db_HAL_WARPING, "Box Number = %d - %d\n", sSingleBoxAddr->ucTotalNumber , uiIndex);

            if( sBoxInfo->ucLayerMode >= eWDT_INVALID ||
                sBoxInfo->iX      < 0 ||
                sBoxInfo->iY      < 0 ||
                sBoxInfo->iWidth  < 0 || sBoxInfo->iWidth  > halWarping_HResGet() ||
                sBoxInfo->iHeight < 0 || sBoxInfo->iHeight > halWarping_VResGet() ||
                sBoxInfo->iR      < 0 || sBoxInfo->iR >= 256 ||
                sBoxInfo->iG      < 0 || sBoxInfo->iG >= 256 ||
                sBoxInfo->iB      < 0 || sBoxInfo->iB >= 256
               )
            {
                LOG_MSG(db_HAL_WARPING, "Error Box Data (index: %d)\n", uiIndex);

                continue;
            }

            LOG_MSG(db_HAL_WARPING, "Box Info = %d %d %d %d %d %d %d %d\n", sBoxInfo->ucLayerMode,
                                                                            sBoxInfo->iX,
                                                                            sBoxInfo->iY,
                                                                            sBoxInfo->iWidth,
                                                                            sBoxInfo->iHeight,
                                                                            sBoxInfo->iR,
                                                                            sBoxInfo->iG,
                                                                            sBoxInfo->iB);


            #ifdef SAME_RAM_FOR_BEFORE_WARP_OSD_AND_SCALER_OSD  //H2PF_Simon_0038
            {
                uPALGEOAPI_INFO uInfo = {.sGFN_DRAW_BOXES_INFO.eLocation    = sBoxInfo->ucLayerMode,
                                         .sGFN_DRAW_BOXES_INFO.PosX         = sBoxInfo->iX,
                                         .sGFN_DRAW_BOXES_INFO.PosY         = sBoxInfo->iY,
                                         .sGFN_DRAW_BOXES_INFO.Width        = sBoxInfo->iWidth,
                                         .sGFN_DRAW_BOXES_INFO.Height       = sBoxInfo->iHeight,
                                         .sGFN_DRAW_BOXES_INFO.Red          = sBoxInfo->iR,
                                         .sGFN_DRAW_BOXES_INFO.Green        = sBoxInfo->iG,
                                         .sGFN_DRAW_BOXES_INFO.Blue         = sBoxInfo->iB,
                                        };

                palGeo_DrawOSDQueueSet(eGFN_DRAW_BOXES, uInfo);
            }
            #else
            {
                //only draw on memory (before warp)
                palGeo_DrawBoxes(sBoxInfo->ucLayerMode,
                                 sBoxInfo->iX,
                                 sBoxInfo->iY,
                                 sBoxInfo->iWidth,
                                 sBoxInfo->iHeight,
                                 sBoxInfo->iR,
                                 sBoxInfo->iG,
                                 sBoxInfo->iB);
            }
            #endif
        }
    }

    return eEXEC_CODE_PASS;

}

