UINT8 *pauctmpFullColor = NULL;
void DrawPNG(void)
{
    LOG_MSG(db_HAL_WARPING, "%s Start\n", __FUNCTION__);

    INT16 iWidth, iHeight;
    if(pauctmpFullColor == NULL)
    {
        pauctmpFullColor = (UINT8 *)malloc(2160 * 3840 * 3 + 1024);
        if(pauctmpFullColor == NULL)
        {
            ASSERT_ALWAYS();
        }
    }

    memset(pauctmpFullColor, 0, (2160 * 3840 * 3 + 1024));

    //read PNG file
    read_png_file("./PIC.png", &iWidth, &iHeight);
    LOG_MSG(db_HAL_WARPING, "\nPNG Width=%d, Height=%d\n", iWidth, iHeight);

    //process file
    process_file(pauctmpFullColor, 3840, 2160);
    LOG_MSG(db_HAL_WARPING, "process_file done\n");

    //Start Draw
    halWarping_DrawPNG_OnOSD(100, 100, iWidth, iHeight, pauctmpFullColor);

    //free(pauctmpFullColor);

    LOG_MSG(db_HAL_WARPING, "%s End\n", __FUNCTION__);

}
#endif

