eEXEC_CODE palDataMgr_Access_writeEeprom(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        if(m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucWriteEEPROM_Flag)
        {
            *((UINT8 *)pValue) = 1;
        }
        else
        {
            *((UINT8 *)pValue) = 0;
        }
    }
    else  //Write Function
    {
        UINT32 ucXPR_ADC0 = 0;
        UINT32 ucXPR_ADC1 = 0;
        UINT32 ucOld_XPR_ADC0 = 0;
        UINT32 ucOld_XPR_ADC1 = 0;
        tDATA_CODE IsOSDOpen = 0;

        ucOld_XPR_ADC0 = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiEepromTargetADC_AWC0;
        ucOld_XPR_ADC1 = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiEepromTargetADC_AWC1;

        palFormatterMgr_XPR_Gain_Write_EEPROM();

        palFormatterMgr_XPR_EepromTargetAdcAxis0_Get(&ucXPR_ADC0);
        m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiEepromTargetADC_AWC0 = ucXPR_ADC0;

        palFormatterMgr_XPR_EepromTargetAdcAxis1_Get(&ucXPR_ADC1);
        m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiEepromTargetADC_AWC1 = ucXPR_ADC1;

        if((ucOld_XPR_ADC0 != m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiEepromTargetADC_AWC0) &&
            (ucOld_XPR_ADC1 != m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiEepromTargetADC_AWC1))
        {
            m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucWriteEEPROM_Flag = 1;
        }
        else
        {
            m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucWriteEEPROM_Flag = 0;
        }

        palLANProcSendToLAN(edcCH1_EEP_TARGET_ADC_READ);
        palLANProcSendToLAN(edcCH0_EEP_TARGET_ADC_READ);

        palDataMgr_Data_Access(edcUI_STATUS_IS_OSD_OPEN, edaREAD, &IsOSDOpen);
        if(IsOSDOpen == 1)
        {
            palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
        }
    }

    return eEXEC_CODE_PASS;
}

