eEXEC_CODE palDataMgr_Access_Actuator_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue)// R70K_Bruce_0057
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = 0;
    }
    else  //Write Function
    {
        //Update RAM
        palDataMgr_sActuator_Factory_Reset();

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_ACTUATOR_DAC_AWC0, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucDAC_AWC0);
            utilDataMgr_CommonSet_CM(eDF_ACTUATOR_SFDELAY_AWC0, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ulSubframeDelay_AWC0);
            utilDataMgr_CommonSet_CM(eDF_ACTUATOR_SEGMENTLEN_AWC0, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiSegmentLength_AWC0);
            utilDataMgr_CommonSet_CM(eDF_ACTUATOR_DAC_AWC1, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucDAC_AWC1);
            utilDataMgr_CommonSet_CM(eDF_ACTUATOR_SFDELAY_AWC1, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ulSubframeDelay_AWC1);
            utilDataMgr_CommonSet_CM(eDF_ACTUATOR_SEGMENTLEN_AWC1, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiSegmentLength_AWC1);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT32 ulDelay = 0;

            palFormatterMgr_Actuator_Gain_Set(0, m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucDAC_AWC0);
            palFormatterMgr_Actuator_Segment_Length_Set(0, m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiSegmentLength_AWC0);
            ulDelay = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ulSubframeDelay_AWC0 * 10; //HICC2_Doulas_0099
            palFormatterMgr_Actuator_SubFrameDelay_Set(0, ulDelay);

            palFormatterMgr_Actuator_Gain_Set(1, m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucDAC_AWC1);
            palFormatterMgr_Actuator_Segment_Length_Set(1, m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiSegmentLength_AWC1);
            ulDelay = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ulSubframeDelay_AWC1 * 10; //HICC2_Doulas_0099
            palFormatterMgr_Actuator_SubFrameDelay_Set(1, ulDelay);
            if(m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopEn_Axis0 == 0 )
            {
                m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopGain_Axis0 = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucDAC_AWC0;
                m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopSegmentLength_Axis0 = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiSegmentLength_AWC0;
            }
            if(m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopEn_Axis1 == 0 )
            {
                m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopGain_Axis1 = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucDAC_AWC1;
                m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopSegmentLength_Axis1 = m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.uiSegmentLength_AWC1;
            }
            m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopEn_Axis0 = 0;
            palFormatterMgr_XPR_Close_Loop_Enable_Axis0_Set(m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopEn_Axis0);
            m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopEn_Axis1 = 0;
            palFormatterMgr_XPR_Close_Loop_Enable_Axis1_Set(m_sAppDataMgrInfo.sEepSettings.sActuatorSetting.ucCloseLoopEn_Axis1);
        }

        palLANProcSendToLAN(edcCH0_DACGAIN);
        palLANProcSendToLAN(edcCH0_SFDELAY);
        palLANProcSendToLAN(edcCH0_SEGMENTLEN);
        palLANProcSendToLAN(edcCH1_DACGAIN);
        palLANProcSendToLAN(edcCH1_SFDELAY);
        palLANProcSendToLAN(edcCH1_SEGMENTLEN);
        palLANProcSendToLAN(edcCLOSE_LOOP_ENABLE_AXIS0);
        palLANProcSendToLAN(edcCLOSE_LOOP_ENABLE_AXIS1);
        palLANProcSendToLAN(edcCLOSE_LOOP_GAIN_AXIS0);
        palLANProcSendToLAN(edcCLOSE_LOOP_SEGMENT_LENGTH_AXIS0);
        palLANProcSendToLAN(edcCLOSE_LOOP_GAIN_AXIS1);
        palLANProcSendToLAN(edcCLOSE_LOOP_SEGMENT_LENGTH_AXIS1);

    }
}
