UINT32 palDataMgr_Schedule_Enable_Current_Week(UINT8 *bEnable) //A65_OPTOMA_Julie_0042
{
	UINT8 ucCurrentWeekdayValue = 0, ucCurrWeekEnable = 0;;
	UINT32 uiDataCode = edcSCHEDULE_MONDAY_ENABLE;

	palDataMgr_Access_Schedule_ViewWeekday(edaREAD, &ucCurrentWeekdayValue); //Index[0-6]=[Sunday,Monday,Tuesday,Wednesday,Thursday,Friday,Saturday]

	if(ucCurrentWeekdayValue == 0)
	{
		uiDataCode = edcSCHEDULE_SUNDAY_ENABLE; //datacode[697-703]=[MONDAY,TUESDAY,WEDNESDAY,THURSDAY,FRIDAY,SATURDAY,SUNDAY]
	}
	else if(ucCurrentWeekdayValue < 7)
	{
		uiDataCode = edcSCHEDULE_MONDAY_ENABLE + ucCurrentWeekdayValue - 1;
	}
	else
	{
		ASSERT_ALWAYS();
	}

	palDataMgr_Data_Access(uiDataCode, edaREAD, &ucCurrWeekEnable);
	*bEnable = ucCurrWeekEnable;

	//LOG_MSG(db_ALWAYS,"(%s,%d) ucCurrentWeekdayValue[%d] uiDataCode[%d] bEnable[%d]\r\n", __FUNCTION__, __LINE__, ucCurrentWeekdayValue, uiDataCode, *bEnable);

	return uiDataCode;
}

