eEXEC_CODE palDataMgr_Access_Schedule_Event_Time_Info(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 ucUserChoiceWeekDay = m_sAppDataMgrInfo.sSystemValues.ucCurrentWeekday;
    UINT8 ucUserChoiceEventIndex = m_sAppDataMgrInfo.sSystemValues.ucCurrentEventListNum;
    UINT8 ucViewEventType = m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].ucFunctionType;
    UINT8 ucViewEventIndex = m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].ucEventIndex;
    if (edaREAD == eAccessMode)  //Read Function
    {
        UINT16 TotalMinute = 0;
	    TotalMinute = m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].uwTimeMin;
        LOG_MSG(db_APP_SCHEDULE,"Get total time min = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].uwTimeMin);
        *((UINT16*)pValue) = TotalMinute;
    }
    else  //Write Function
    {
        m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].uwTimeMin = *((UINT16*)pValue);
        LOG_MSG(db_APP_SCHEDULE,"Set total time min = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].uwTimeMin);
        if( m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].ucFunctionType != ets_OFF)
        {
            LOG_MSG(db_APP_SCHEDULE,"Send Lan total time min = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventIndex].uwTimeMin);
            palLANProcScheduleSend();
        }
    }

    return eEXEC_CODE_PASS;
}

