//G100_Coda_0017
eEXEC_CODE palDataMgr_Access_Schedule_Event_Function_Type(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 ucUserChoiceWeekDay = m_sAppDataMgrInfo.sSystemValues.ucCurrentWeekday;
    UINT8 ucUserChoiceEventListNum = m_sAppDataMgrInfo.sSystemValues.ucCurrentEventListNum; //G100_Coda_0024

    if (edaREAD == eAccessMode)  //Read Function
    {
         if (m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventListNum].ucFunctionType >= eSCHEDULE_EVENT_FUNCTION_NUMBER) //avoid overflow
         {
            LOG_MSG(db_APP_SCHEDULE, "Read function Type %d overflow\r\n", *((UINT8*)pValue));
            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventListNum].ucFunctionType = 0;
         }
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventListNum].ucFunctionType;
        LOG_MSG(db_APP_SCHEDULE, "Read Event Type %d\r\n", *((UINT8*)pValue));
    }
    else  //Write Function
    {
        if (*((UINT8*)pValue) >= eSCHEDULE_EVENT_FUNCTION_NUMBER) //avoid overflow
        {
            LOG_MSG(db_APP_SCHEDULE, "set function Type %d overflow\r\n", *((UINT8*)pValue));
            *((UINT8*)pValue) = 0;
        }
        //Update RAM

        m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventListNum].ucFunctionType = *((UINT8*)pValue);

        if(*((UINT8*)pValue) != ets_OFF)	 //G100_Coda_0021
        {
            //set event exist flag
            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].ucIsEventExist = ets_ON;
            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventListNum].ucEventIndex = 1;
        }
        else //A35G2_CDS_CODA_0008
        {
            //set event exist flag
            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].ucIsEventExist = ets_OFF;
            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucUserChoiceEventListNum].ucEventIndex = 0;
        }

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //utilDataMgr_CommonSet_CM(eDF_KEYPADBACKLIGHT, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            LOG_MSG(db_APP_SCHEDULE, "set function Type %d\r\n", *((UINT8*)pValue));
            //palLANProcScheduleSend();//A35G2_CDS_CODA_0008
        }


        palLANProcSendToLAN(edcSCHEDULE_EVENT_TYPE_INDEX);
    }
    return eEXEC_CODE_PASS;
}
