int compare(const void *arg1, const void *arg2)  //G100_Coda_0029
{
    return  (*(int *)arg1 - *(int *)arg2);
}


void palDataMgr_Schedule_Sort_Event_List_By_ExecuteTime(void)  //G100_Coda_0029
{
    sWEEKDAY_EVENT TempCheckSortEvent[16] = {0};
    UINT8 ucUserChoiceWeekDay = m_sAppDataMgrInfo.sSystemValues.ucCurrentWeekday;
    UINT8 ucCount;
    int CheckSortNum[16] = {0};
    UINT8 ucSortedEventListNum = 0;
    int ucSortedEventTimeNum = 0;
    int ucShiftReferenceIndex = 0;

    memcpy((UINT8*)&TempCheckSortEvent[0], (UINT8*)&m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[0], sizeof(sWEEKDAY_EVENT) * 16);

    for(ucCount = 0; ucCount < 16; ucCount++)
    {
        if(m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucCount].ucFunctionType == ets_OFF)
        {
            CheckSortNum[ucCount] = 1440; //this event is Null,  sort time set 1440
        }
        else
        {
            CheckSortNum[ucCount] = TempCheckSortEvent[ucCount].uwTimeMin;
        }

        CheckSortNum[ucCount] = (CheckSortNum[ucCount] << 4) | ucCount; //embedded Eevnt list num to sort time data last 4 bit
    }

    qsort((void *)CheckSortNum, 16, sizeof(int), compare);

    for(ucCount = 0; ucCount < 16; ucCount++)
    {
        ucSortedEventTimeNum = CheckSortNum[ucCount] >> 4;   //get time data
        ucShiftReferenceIndex = CheckSortNum[ucCount] & 0xf; //get original event list num
        LOG_MSG(db_APP_SCHEDULE, "Sort count[%d]%d = %d, ucUserChoiceWeekDay = %d\r\n",ucCount, ucSortedEventTimeNum ,ucShiftReferenceIndex, ucUserChoiceWeekDay);

        //memcpy((UINT8*)&m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucShiftReferenceIndex], (UINT8*)&TempCheckSortEvent[ucCount], sizeof(sWEEKDAY_EVENT));
        m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucCount].uwTimeMin = TempCheckSortEvent[ucShiftReferenceIndex].uwTimeMin;
        m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucCount].ucFunctionType = TempCheckSortEvent[ucShiftReferenceIndex].ucFunctionType;
        m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[ucUserChoiceWeekDay].sWeekDayEvent[ucCount].ucEventIndex = TempCheckSortEvent[ucShiftReferenceIndex].ucEventIndex;

    }

}

eEXEC_CODE palDataMgr_Access_Schedule_Duplicate_Check(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT32 CurVal = m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_DuplicateCheck;

    if (edaREAD == eAccessMode)  //Read Function
    {
         *((UINT32*)pValue) = CurVal;
    }
    else  //Write Function
    {
        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //utilDataMgr_CommonSet_CM(eDF_KEYPADBACKLIGHT, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            UINT8 WeekDay = m_sAppDataMgrInfo.sSystemValues.ucCurrentWeekday;
            UINT8 EventIdx = m_sAppDataMgrInfo.sSystemValues.ucCurrentEventListNum;
            UINT8 i = 0, j = 0;
            UINT8 ucDuplicateCheck = 0;

            m_sAppDataMgrInfo.sSystemValues.uiDuplicate_TimeMin = 0;
            m_sAppDataMgrInfo.sSystemValues.ucDuplicate_FuncType = 0;
            m_sAppDataMgrInfo.sSystemValues.ucDuplicate_EventIdx = 0;

            for(i = 0; i < 16; i++)
            {
                if((m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[i].uwTimeMin == 1440)
                || (m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[i].ucFunctionType == 0))
                {
                    continue;
                }
                for(j = i + 1; j < 16; j++)
                {
                    if((m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[i].uwTimeMin
                    == m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].uwTimeMin)
                    && (m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[i].ucFunctionType
                    == m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].ucFunctionType)
                    && (m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[i].ucEventIndex
                    == m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].ucEventIndex))
                    {
                        m_sAppDataMgrInfo.sSystemValues.uiDuplicate_TimeMin = m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].uwTimeMin;
                        m_sAppDataMgrInfo.sSystemValues.ucDuplicate_FuncType = m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].ucFunctionType;
                        m_sAppDataMgrInfo.sSystemValues.ucDuplicate_EventIdx = m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].ucEventIndex;
                        if(EventIdx == i || EventIdx == j)
                        {
                            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[EventIdx].uwTimeMin = 1440;
                            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[EventIdx].ucFunctionType = 0;
                            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[EventIdx].ucEventIndex = 0;
                        }
                        else
                        {
                            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].uwTimeMin = 1440;
                            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].ucFunctionType = 0;
                            m_sAppDataMgrInfo.sSystemValues.sScheduleInfo.sWeekday_Info[WeekDay].sWeekDayEvent[j].ucEventIndex = 0;
                        }

                        palLANProcSendToLAN(edcUI_SCHEDULE_DUPLICATE_INFO);

                        ucDuplicateCheck = 1;
                        m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_DuplicateCheck = 1;

                        break;
                    }
                }
            }

            if(ucDuplicateCheck == 0)
            {
                m_sAppDataMgrInfo.sSystemValues.sUIEventInfo.UI_DuplicateCheck = 0;
            }
        }
    }

    return eEXEC_CODE_PASS;
}

