eEXEC_CODE palDataMgr_Access_Auto_Color_Match(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        *(UINT8*)pValue = m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch;
    }
    else  //Write Function
    {
        //Storage : EEPROM
        m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch = *(UINT8*)pValue;

        palDataMgr_AutoColorMatchExecute_Set(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch);

        if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch >= eAF_AC_EXECUTE && m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch <= eAF_AC_EXECUTE_NO_UIMSG)
        {
            _sGROUPING_CLIENT_RESULT sGroupingAutoColorMatchStatus  = {0};
            palDataMgr_Access_Group_Auto_Color_Match_Status(eAccessMode, &sGroupingAutoColorMatchStatus);

            palLANProcSendToLAN(edcGROUP_AUTO_COLOR_MATCH_STATUS);
        }
    }
    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_Group_Auto_Color_Match_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        memcpy(pValue, &m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus, sizeof(_sGROUPING_CLIENT_RESULT));
    }
    else  //Write Function
    {
        memcpy(&m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus, pValue, sizeof(_sGROUPING_CLIENT_RESULT));
#if 1 //TBD Larry
        //Update RAM

        if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet == eGCS_STATUS_PROCESSING)        //G100_Clare_0024, mod, start
        {
            palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);

            if( palDataMgr_Camera_OSD_Lock_Get() == eOSD_NOT_LOCKED)           //G100_Clare_0024, mod //A35G2_Coda_0056
            {
                palDataMgr_Camera_OSD_Lock_Set(eOSD_LOCKED);                  //G100_Clare_0024, mod
            }

            if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch == eAF_AC_NOT_EXECUTE)
            {
                UINT8 ucData = eAF_AC_EXECUTE_NO_UIMSG;  //from AP

                palDataMgr_Access_Auto_Color_Match(eAccessMode, &ucData);
            }
        }                                                                       //G100_Clare_0024, mod, end
        else if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet <= eGCS_STATUS_TIMEOUT )        //G100_Clare_0024, mod, release lock when receive status.
        {
            //UI Event for draw message or dialog
            if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch == eAF_AC_EXECUTE)
            {
                if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet == eGCS_STATUS_SUCCESS)   //pass
                {
                    //show dialog to view new or previous image
                    palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_COMPLETE, TRUE, NULL);
                }
                else   //fail
                {
                    if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet == eGCS_STATUS_FUNCTION_FAIL)
                    {
                        palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.functionRet, NULL);
                    }
                    else
                    {
                        palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet, NULL);
                    }
                }
            }
            else if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch == eAF_AC_EXECUTE_NO_CHECK)
            {
                if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet == eGCS_STATUS_SUCCESS)   //pass
                {
                    //using the same as auto focus complete message
                    palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_COMPLETE, TRUE, NULL);
                }
                else   //fail
                {
                    if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet == eGCS_STATUS_FUNCTION_FAIL)
                    {
                        palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.functionRet, NULL);
                    }
                    else
                    {
                        palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet, NULL);
                    }
                }
            }

            //AC Apply Set
            if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch == eAF_AC_EXECUTE ||    //execute from OSD
               m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorMatch == eAF_AC_EXECUTE_NO_CHECK)  // execute from CLI
            {
                if(eGCS_STATUS_SUCCESS == m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus.clientRet)
                {
                    m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorSelect = eAC_APPLY_CALIBRATED;
                    palLANProcSendToLAN(edcACM_SELECT);
                }
            }

            m_sAppDataMgrInfo.sSystemValues.cGroupingAutoColorSelect = eAC_APPLY_IDLE;
            palLANProcSendToLAN(edcACM_SELECT);


            UINT8 ucData = eAF_AC_NOT_EXECUTE;
            palDataMgr_Access_Auto_Color_Match(eAccessMode, &ucData);

            ucData = eOSD_NOT_LOCKED;
            palDataMgr_Access_OSD_Lock(eAccessMode, &ucData);
        }
#endif /* 0 */

    }
    return eEXEC_CODE_PASS;
}


eEXEC_CODE palDataMgr_Access_Group_Auto_Focus_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        memcpy(pValue, &m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus, sizeof(_sGROUPING_CLIENT_RESULT));
    }
    else  //Write Function
    {
        //_sGROUPING_CLIENT_RESULT *psGroupingStatus = (_sGROUPING_CLIENT_RESULT*)pValue;
        memcpy(&m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus, pValue, sizeof(_sGROUPING_CLIENT_RESULT));

        palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);

        //if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoFocus == eAF_STATUS_PROCESSING)
        if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.clientRet == eGCS_STATUS_PROCESSING )             //A65_OPTOMA_Doulas_0039 Modify//G100_Clare_0024, mod, start
        {
            if( palDataMgr_Camera_OSD_Lock_Get() == eOSD_NOT_LOCKED )           //G100_Clare_0024, mod
            {
                palDataMgr_Camera_OSD_Lock_Set( eOSD_LOCKED );                  //G100_Clare_0024, mod
            }

            if( utilWarp_GetOsdPatternType() != PAT_TYPE__OFF )    //G100_Simon_0007
            {
                //Disable warp grid pattern
                palGeo_AdvWarpShowOsdPattern(PAT_TYPE__OFF);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAwWarpPattern_Show = 0;
                palLANProcSendToLAN(edcAW_WARP_PATTERN_SHOW);
            }
        }                                                                       //G100_Clare_0024, mod, end
        else if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.clientRet <= eGCS_STATUS_TIMEOUT)             //A65_OPTOMA_Doulas_0039 Modify//G100_Clare_0024, mod, release lock when receive status.
        {
            palDataMgr_Camera_OSD_Lock_Set(eOSD_NOT_LOCKED);       //G100_Clare_0024, mod

            //UI Event for draw message or dialog
            if(palDataMgr_AutoFocusExecute_Get() == eAF_AC_EXECUTE ||
               palDataMgr_AutoFocusExecute_Get() == eAF_AC_EXECUTE_NO_CHECK ||
               m_sAppDataMgrInfo.sSystemValues.cGroupingAutoFocus == eAF_AC_EXECUTE ||
               m_sAppDataMgrInfo.sSystemValues.cGroupingAutoFocus == eAF_AC_EXECUTE_NO_CHECK)
            {
                if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.clientRet == eGCS_STATUS_SUCCESS)   //pass
                {
                    palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_COMPLETE, TRUE, NULL);
                }
                else if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.clientRet != eGCS_STATUS_PROCESSING)   //fail
                {
                    if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoFocus != eAF_AC_NOT_EXECUTE)
                    {

                        if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.clientRet == eGCS_STATUS_FUNCTION_FAIL) // sGroupingMenuSearch.ucCnt == 1, master only
                        {
                            if(m_sAppDataMgrInfo.sSystemValues.sGroupingMenuSelect.ucCnt <= 1)
                            {
                                palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.functionRet, NULL);
                            }
                            else
                            {
                                INT32 offset = 0;

                                memcpy(&m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus, &m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus, sizeof(_sGROUPING_CLIENT_RESULT));
                                palLANProcSendToLAN(edcGROUP_AUTO_COLOR_MATCH_STATUS);  //used ACM datacode

                                if(m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.functionRet < eACM_RESULT_IDLE)
                                {
                                    offset = eACM_AF_STATUS_PROCESSING;
                                }

                                palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, (offset + m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.functionRet), NULL);
                            }
                        }
                        else
                        {
                            memcpy(&m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus, &m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus, sizeof(_sGROUPING_CLIENT_RESULT));
                            palLANProcSendToLAN(edcGROUP_AUTO_COLOR_MATCH_STATUS);

                            palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.clientRet, NULL);
                        }
                    }
                    else
                    {
                        palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.sGroupingAutoFocusStatus.functionRet, NULL);
                    }
                }
            }

            palDataMgr_AutoFocusExecute_Set(eAF_AC_NOT_EXECUTE);
            m_sAppDataMgrInfo.sSystemValues.cGroupingAutoFocus = eAF_AC_NOT_EXECUTE;
        }
    }

    return eEXEC_CODE_PASS;
}

