eEXEC_CODE palDataMgr_Access_ActuatorPattern(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //H2PF_Simon_0057
{
    UINT8 CurVal = m_sAppDataMgrInfo.sSystemValues.ucActuatorPattern;
    UINT8 NewVal = *((UINT8*)pValue);

    if(edaREAD == eAccessMode)
    {
        *((UINT8*)pValue) = CurVal;
    }
    else
    {
        m_sAppDataMgrInfo.sSystemValues.ucActuatorPattern = NewVal;

        char TP_FileName[128] = {0};

        m_sAppDataMgrInfo.sSystemValues.ucSystem_Busy = ets_ON;
        palLANProcSendToLAN(edcSYSTEM_BUSY);
        //palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);
        //palDataMgr_UI_EventSend(edcUI_EVENT_MENUOPEN_WAIT_MSG, TRUE, NULL);
        //MS_SLEEP(300);

    	//if(palSystem_Suspend(__FUNCTION__) == rcSUCCESS)	//G100_Doulas_0030 Modify
    	{
            switch(NewVal)
            {
                case eCM_ACTUATOR_PATTERN_OFF:
                    palGeo_Draw_PNG_Pattern_Off();

                    if(palDataPath_IsSourceLock() == FALSE)  //H2PF_Simon_0061
                    {
                        UINT8 Source = 0 ;
                        palDataMgr_Access_MainInput(edaREAD, &Source);
                        palDataMgr_Access_MainInput(edaWRITE_RAM_ONLY_WITH_ACTION, &Source);
                    }
                    break;

                case eCM_ACTUATOR_PATTERN_0:
                    {
                        //turn off splash
                        palDataMgr_UI_EventSend(edcUI_EVENT_SPLASH, 0, NULL);

                        if((m_sAppDataMgrInfo.sSystemValues.ucActuatorPatternChange & 0x01) == 0)
                        {
                            palSystem_ActuatorPatternSet(0);
                            m_sAppDataMgrInfo.sSystemValues.ucActuatorPatternChange |= 0x01;
                        }
                        else
                        {
                            palGeo_Draw_PNG_PatternChange(0);
                        }
                    }
                    break;

                case eCM_ACTUATOR_PATTERN_1:
                    {
                        //turn off splash
                        palDataMgr_UI_EventSend(edcUI_EVENT_SPLASH, 0, NULL);

                        if((m_sAppDataMgrInfo.sSystemValues.ucActuatorPatternChange & 0x02) == 0)
                        {
                            palSystem_ActuatorPatternSet(1);
                            m_sAppDataMgrInfo.sSystemValues.ucActuatorPatternChange |= 0x02;
                        }
                        else
                        {
                            palGeo_Draw_PNG_PatternChange(1);
                        }
                    }
                    break;

                default:
                    LOG_MSG(db_ASSERT, "Actuator Pattern ID Error %d\r\n", NewVal);
                    break;
            }

			//palSystem_Resume(__FUNCTION__);
            //palDataMgr_ResetCountSet(__FUNCTION__, 0);
			//MS_SLEEP(100);

			if(NewVal != eCM_ACTUATOR_PATTERN_OFF)
			{
                palDataMgr_UI_EventSend(edcUI_EVENT_WAIT_PROCESS_MESSAGE_EXIT, 2, NULL);
            }
        }
    }

    m_sAppDataMgrInfo.sSystemValues.ucSystem_Busy = ets_OFF;
    palLANProcSendToLAN(edcSYSTEM_BUSY);

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Power_On_Counter(void)// HICC2_Bruce_0007
{
    eEXEC_CODE ret = eEXEC_CODE_PASS;

    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOnCounter > 9999)
    {
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOnCounter = 0;
        ret = eEXEC_CODE_FAIL;
    }
    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOnCounter < 9999)
    {
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOnCounter += 1;
        utilDataMgr_CommonSet_CM(eDF_POWER_ON_COUNTER, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOnCounter);
        palLANProcSendToLAN(edcPOWER_ON_OFF_COUNTER);
    }
    return ret;
}

eEXEC_CODE palDataMgr_Power_Off_Counter(void)// HICC2_Bruce_0007
{
    eEXEC_CODE ret = eEXEC_CODE_PASS;

    if (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOffCounter > 9999)
    {
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOffCounter = 0;
        ret = eEXEC_CODE_FAIL;
    }
    if (m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOffCounter < 9999)
    {
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOffCounter += 1;
        utilDataMgr_CommonSet_CM(eDF_POWER_OFF_COUNTER, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.uiPowerOffCounter);
        palLANProcSendToLAN(edcPOWER_ON_OFF_COUNTER);
    }
    return ret;
}

