eEXEC_CODE palDataMgr_Access_IPV6_LAN_Default_Gateway(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        char AddressString[64] = {0};

        snprintf(AddressString, 64, "%04x:%04x:%04x:%04x:%04x:%04x:%04x:%04x",
            m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[0], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[1], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[2], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[3],
            m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[4], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[5], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[6], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[7]);

        memcpy((UINT8 *)pValue, AddressString, strlen(AddressString)+1);
    }
    else  //Write Function
    {
        INT32 iValue = 0;
        UINT16 aucLanTmp[8] = {0};
        UINT8 aucDataString[64] = {0};
        UINT8 ucIndex = 0 ;
        char *pch ;
        char *endptr;

        memcpy(aucDataString, pValue, strlen((char *)pValue));
        pch = strtok((char *)aucDataString, ":");

        while(pch != NULL && ucIndex < 8)
        {
            iValue = strtol(pch, &endptr, 16);

            if((iValue < 0) || (iValue > 0xFFFF))
            {
                return eEXEC_CODE_FAIL;
            }
            aucLanTmp[ucIndex] = (UINT16)iValue;
            ucIndex++ ;
            pch = strtok(NULL, ":") ;
        }

        for(ucIndex = 0; ucIndex < 8; ucIndex++)
        {
            m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[ucIndex] = aucLanTmp[ucIndex];
        }

        LOG_MSG(db_APP_LAN, "IPV6 Default Gateway %04x:%04x:%04x:%04x:%04x:%04x:%04x:%04x",
            m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[0], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[1], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[2], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[3],
            m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[4], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[5], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[6], m_sLAN_info.ucLAN_IPV6_GATEWAY_Show[7]);

        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_1);
        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_2);
        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_3);
        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_4);
        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_5);
        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_6);
        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_7);
        palLANProcSendToLAN(edcIPV6_DEFAULT_GATEWAY_8);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {

        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

        }
    }

    return eEXEC_CODE_PASS;
}

