eEXEC_CODE palDataMgr_Access_Model_Switch_PassWord(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        BYTE ucServiceZK1320TPasswordData[5]  = "3812";
        BYTE ucServiceZK1120TSTPasswordData[5]  = "3611";

        if(palSystem_ModelIDGet() == MODEL_ID_0)
        {
            memcpy((UINT8 *)pValue, ucServiceZK1120TSTPasswordData, strlen((char*)ucServiceZK1120TSTPasswordData));
        }
        else
        {
			memcpy((UINT8 *)pValue, ucServiceZK1320TPasswordData, strlen((char*)ucServiceZK1320TPasswordData));
        }
    }
    else  //Write Function
    {
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_LVPS_Info(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)
    {
        memcpy(pValue, &m_sAppDataMgrInfo.sSystemValues.sLVPS_Info, sizeof(sDST_LVPS_INFO));
    }
    else
    {
        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            memcpy(&m_sAppDataMgrInfo.sSystemValues.sLVPS_Info, pValue , sizeof(sDST_LVPS_INFO));

            LOG_MSG(db_HAL_MCU, "\r LVPS Info:\r\n");
            LOG_MSG(db_HAL_MCU, "wInputVoltage       = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.lInputVoltage);
            LOG_MSG(db_HAL_MCU, "wPFC_OutputVoltage  = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.lPFC_OutputVoltage);
            LOG_MSG(db_HAL_MCU, "w5V_Voltage         = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l5V_Voltage);
            LOG_MSG(db_HAL_MCU, "w12V_Voltage        = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l12V_Voltage);
            LOG_MSG(db_HAL_MCU, "w52V_Voltage        = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l52V_Voltage);
            LOG_MSG(db_HAL_MCU, "w5V_Current         = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l5V_Current);
            LOG_MSG(db_HAL_MCU, "w12V_Current        = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l12V_Current);
            LOG_MSG(db_HAL_MCU, "w52V_Current        = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l52V_Current);

            LOG_MSG(db_HAL_MCU, "wPFC_MOS_Temperature       = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.lPFC_MOS_Temperature);
            LOG_MSG(db_HAL_MCU, "wBridge_Temperature        = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.lBridge_Temperature);
            LOG_MSG(db_HAL_MCU, "wLVPS_Ambient_Temperature  = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.lLVPS_Ambient_Temperature);
            LOG_MSG(db_HAL_MCU, "w12V_SR_MOSFET_Temperature = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l12V_SR_MOSFET_Temperature);
            LOG_MSG(db_HAL_MCU, "w52V_SR_MOSFET_Temperature = %d\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.l52V_SR_MOSFET_Temperature);

            LOG_MSG(db_HAL_MCU, "uiPRIMARY_PROTECTION_STATUS   = %x\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.uiPRIMARY_PROTECTION_STATUS);
            LOG_MSG(db_HAL_MCU, "uiSECONDARY_PROTECTION_STATUS = %x\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.uiSECONDARY_PROTECTION_STATUS);
            LOG_MSG(db_HAL_MCU, "uiIO_STATUS                   = %x\r\n", m_sAppDataMgrInfo.sSystemValues.sLVPS_Info.uiIO_STATUS);
        }
    }
    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_HDBaseT_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucHDBaseT_Status;
    }
    else
    {
        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {

            m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucHDBaseT_Status = *((UINT8*)pValue);
        }
    }
    return eEXEC_CODE_PASS;
}




