void palDataMgr_OPDSourceInfo(UINT8 ucCH) //G100_Julie_0016
{
    uOPD_DATA uOPDData = {0};
    UINT8  ucInputSource = 0, ucVideoFormat[eFE_MSG_VIDEO_FORMAT_MAIN_SZ] = {0}, ucData = 0;

    if(ucCH == 1) //sub source
    {
        ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub;
        snprintf(uOPDData.sSource.cInput, 7, "Sub");

		palDataMgr_Data_Access(edcSUB_PIXEL_CLOCK, edaREAD, &uOPDData.sSource.cPixelClock);
		palDataMgr_Access_SubColorSpaceGet(edaREAD, &uOPDData.sSource.cColorSpace);
    }
    else
    {
        ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
        snprintf(uOPDData.sSource.cInput, 7, "Main");

		palDataMgr_Data_Access(edcMAIN_PIXEL_CLOCK, edaREAD, &uOPDData.sSource.cPixelClock);
		palDataMgr_Access_MainColorSpaceGet(edaREAD, &uOPDData.sSource.cColorSpace);
    }

    uOPDData.sSource.wActiveH = palImgMgr_Input_H_Active_Get(ucCH);
    uOPDData.sSource.wActiveV = palImgMgr_Input_V_Active_Get(ucCH);

    palImgMgr_VGA_H_Total_Get(ucCH, &uOPDData.sSource.wTotalH);
    palImgMgr_VGA_V_Total_Get(ucCH, &uOPDData.sSource.wTotalV);

    palImgMgr_Horz_Start_Position_Get(ucCH, &uOPDData.sSource.wStartH);
    palImgMgr_Vert_Start_Position_Get(ucCH, &uOPDData.sSource.wStartV);

	halFrontEndCtrl_videoFormat_Get(ucVideoFormat);
    uOPDData.sSource.cDeepColor = ucVideoFormat[0];

    switch(ucInputSource)
    {
	    case eCM_SOURCE_VGA:
            snprintf(uOPDData.sSource.cSourceName, 23, "%s", m_sDefSysSettings.sUserSystemSetting.sSourceSetting.cSourceName[eCM_SOURCE_VGA]);
			break;

        case eCM_SOURCE_HDMI1:
            snprintf(uOPDData.sSource.cSourceName, 23, "%s", m_sDefSysSettings.sUserSystemSetting.sSourceSetting.cSourceName[eCM_SOURCE_HDMI1]);
            break;

        case eCM_SOURCE_HDMI2:
            snprintf(uOPDData.sSource.cSourceName, 23, "%s", m_sDefSysSettings.sUserSystemSetting.sSourceSetting.cSourceName[eCM_SOURCE_HDMI2]);
            break;

        case eCM_SOURCE_DVI:
            snprintf(uOPDData.sSource.cSourceName, 23, "%s", m_sDefSysSettings.sUserSystemSetting.sSourceSetting.cSourceName[eCM_SOURCE_DVI]);
            break;

        case eCM_SOURCE_DISPLAYPORT:
            snprintf(uOPDData.sSource.cSourceName, 23, "%s", m_sDefSysSettings.sUserSystemSetting.sSourceSetting.cSourceName[eCM_SOURCE_DISPLAYPORT]);
            break;

        case eCM_SOURCE_3GSDI:
            snprintf(uOPDData.sSource.cSourceName, 23, "%s", m_sDefSysSettings.sUserSystemSetting.sSourceSetting.cSourceName[eCM_SOURCE_3GSDI]);
            break;

        case eCM_SOURCE_HDBASET:
            snprintf(uOPDData.sSource.cSourceName, 23, "%s", m_sDefSysSettings.sUserSystemSetting.sSourceSetting.cSourceName[eCM_SOURCE_HDBASET]);
            break;

        default:
            break;
    }

    utilOPD_EventSet(eOPD_SOURCE_LOG, &uOPDData);

    //palImgMgr_RxPortAVI_Info(ucCH, ucInputSource, uOPDData.cData);

    //utilOPD_EventSet(eOPD_AVI_INFOFRAME_LOG, &uOPDData);

    //palImgMgr_RxPortVSI_Info(ucCH, ucInputSource, uOPDData.cData);

    //utilOPD_EventSet(eOPD_HDMI_VENDOR_LOG, &uOPDData);
}

