void palDataMgr_OPDInputPlugInState(UINT8 ucEvent)  //A35G2_Simon_0075
{
    uOPD_DATA uOPDData = {0};

    UINT16 uiInputDetect     = palDataPath_InputDetectGet();
    UINT16 uiLastInputDetect = palDataPath_LastInputDetectGet();

    const char *m_sSource_String[eCM_SOURCE_NUMBER] =
    {
        /* 00 */ "RESERVED",
        /* 01 */ "VGA",
        /* 02 */ "BNC",
        /* 03 */ "HDMI-1",
        /* 04 */ "HDMI-2",
        /* 05 */ "DVI-D",
        /* 06 */ "DP",
        /* 07 */ "3G-SDI",
        /* 08 */ "HDBaseT",
        /* 09 */ "COMPOSITE",
        /* 10 */ "PRESENTER",
        /* 11 */ "CARDREADER",
        /* 12 */ "MINIUSB",
        /* 13 */ "SLOT1",
        /* 14 */ "SLOT2",
    };

    UINT8 ucChanged = uiInputDetect ^ uiLastInputDetect;

    for(UINT8 ucIndex = 0 ; ucIndex < eCM_SOURCE_NUMBER ; ucIndex++)
    {
        UINT8 ucPlugChanged = (ucChanged >> ucIndex) & 0x01 ;

        if(ucPlugChanged)
        {
            if(ucIndex == eCM_SOURCE_3GSDI)
            {
                snprintf(uOPDData.cString, 31,  "%s,%s", m_sSource_String[ucIndex], (((uiInputDetect >> ucIndex) & 0x01) == 1) ? "LockOn" : "LockOff" );
            }
            else
            {
                snprintf(uOPDData.cString, 31,  "%s,%s", m_sSource_String[ucIndex], (((uiInputDetect >> ucIndex) & 0x01) == 1) ? "Detect5V" : "Lost5V" );
            }

            utilOPD_EventSet(ucEvent, &uOPDData);
        }
    }

}

