void palDataMgr_LanMacAddress_Strtol(char *cMAC) //A65_OPTOMA_Julie_0080
{
	char str[3], *endptr;
	UINT8 acMAC[6] = {0}, ucIndex = 0;
    UINT8 ucString[32] = {0};

	for(ucIndex = 0; ucIndex < 6; ucIndex++)
	{
		str[0] = *(cMAC + ucIndex * 3 + 0);
		str[1] = *(cMAC + ucIndex * 3 + 1);
		str[2] = '\0';
		acMAC[ucIndex] = (int) strtol((const char *)str, &endptr, 16) ;
	}
	sprintf(ucString, "%02X%02X%02X%02X%02X%02X", acMAC[0], acMAC[1], acMAC[2], acMAC[3], acMAC[4], acMAC[5]);
	utilOPD_RegulatoryInfo_Set(edcLAN_MAC_ADDRESS, ucString, 0);
}

void palDataMgr_OPDRegulatoryInfo(void) //A65_OPTOMA_Julie_0080
{
	char cMAC[20] = {'\0'};
    UINT8 ucString[32] = {0}, ucIndex = 0;
    #ifdef CUSTOM_OPTOMA
	palDataMgr_Data_Access(edcFOTA_MODEL_NAME, edaREAD, ucString);  //A35G2_Coda_0127
	utilOPD_RegulatoryInfo_Set(edcMODEL_NAME, ucString, 0);
	#else
    palDataMgr_Data_Access(edcMODEL_NAME, edaREAD, ucString);
	utilOPD_RegulatoryInfo_Set(edcMODEL_NAME, ucString, 0);
	#endif

	palDataMgr_Data_Access(edcSERIAL_NUMBER, edaREAD, ucString);
	utilOPD_RegulatoryInfo_Set(edcSERIAL_NUMBER, ucString, 0);

	palDataMgr_Data_Access(edcLAN_MAC_ADDRESS, edaREAD, cMAC); //G100_Julie_0044
	palDataMgr_LanMacAddress_Strtol((void*)&cMAC);

	palDataMgr_Data_Access(edcPICTURE_SETTINGS, edaREAD, &ucIndex);
	utilOPD_RegulatoryInfo_Set(edcPICTURE_SETTINGS, 0, ucIndex);
}

