int palDataMgr_IP_Conflict_Verify(void)   //G100_Julie_0035
{
	char str[1024] = {'\0'};

	char LAN_IP_Address[16] = {0};
	snprintf(LAN_IP_Address, 16, "%d.%d.%d.%d" , m_sLAN_info.ucLAN_IP_Show[0], m_sLAN_info.ucLAN_IP_Show[1], m_sLAN_info.ucLAN_IP_Show[2], m_sLAN_info.ucLAN_IP_Show[3]);

	char Crestron_IP_Address[16] = {0};
	snprintf(Crestron_IP_Address, 16, "%d.%d.%d.%d" , m_sLAN_info.ucCrestron_IP_Show[0], m_sLAN_info.ucCrestron_IP_Show[1], m_sLAN_info.ucCrestron_IP_Show[2], m_sLAN_info.ucCrestron_IP_Show[3]);

	if (strcmp(LAN_IP_Address, Crestron_IP_Address) == 0)
	{
	    //LOG_MSG(db_ALWAYS, "str1?tr2?詨?!\n");
		snprintf(str, 1023, "%s,%s:%s,%s:%s", "IP_Conflict", "LAN_IP_ADDRESS", LAN_IP_Address, "CRESTRON_IP_ADDRESS", Crestron_IP_Address);
		utilOPD_CLI_EventSet(eOPD_CLI_TELNET_LOG, (char*)str);
	    return 1;
	}
	else
	{
	    //LOG_MSG(db_ALWAYS, "str1?tr2銝??\n");
		return 0;
	}
}

UINT8 palDataMgr_Data_Type(eDATA_CODE eDataCode) //A70LV_Larry_0064
{
    if (eDataCode >= DATAMGR_ACCESS_TABLE_ENTRIES)
        return DATA_TYPE_NA;

    return m_sDataMgr_Access_LutTable[eDataCode].ucDataType;
}

eFUNC_CONTROL palDataMgr_MenuItem_Control(eDATA_CONTROL eDataControl)
{
    eFUNC_CONTROL eResult = eFUNC_CONTROL_DISABLE;

    if(eDataControl >= eacINVALID)
        return eFUNC_CONTROL_DISABLE;

    eResult = m_sDataControl_LutTable[eDataControl].Item_Access_Enable();

    return eResult;
}

eFUNC_CONTROL palDataMgr_DataCode_Control(eDATA_CODE eDataCode) //A70LV_Larry_0052 modify
{
    eFUNC_CONTROL eResult = eFUNC_CONTROL_DISABLE;

    if(eDataCode >= DATAMGR_ACCESS_TABLE_ENTRIES)
        return eFUNC_CONTROL_DISABLE;

    eResult = m_sDataControl_LutTable[m_sDataMgr_Access_LutTable[eDataCode].FuncPoint.uiDataControl].Item_Access_Enable();

    if((palEnvironment_Fake_Power_Down_Get()) &&
        (m_sDataControl_LutTable[m_sDataMgr_Access_LutTable[eDataCode].FuncPoint.uiDataControl].uiDataControl != eacNORAML) &&
        (m_sDataControl_LutTable[m_sDataMgr_Access_LutTable[eDataCode].FuncPoint.uiDataControl].uiDataControl != eacLAN_DHCP))
    {
        return eFUNC_CONTROL_DISABLE;
    }
    return eResult;
}

