eEXEC_CODE palDataMgr_Data_Range_Get(eDATA_CODE eDataCode, eDATA_RANGE_MODE eRange, tDATA_CODE *pValue)  //G100_Simon_0067//HICC2_Julie_0011
{
    if (eDataCode >= DATAMGR_ACCESS_TABLE_ENTRIES || eRange >= edrINVALID)
        return eEXEC_CODE_FAIL;

    switch (eRange)
    {
        case edrMAX: //A70LV_Larry_0186 modify
        {
            UINT32 uiData = 0;

            switch(eDataCode)
            {
                case edcBLENDING_TOP_START_PIXEL:  //A70LV_Larry_0258
                    m_sDataMgr_Access_LutTable[edcBLENDING_TOP_PIXEL_WIDTH].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
					if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_TOP_START_PIXEL].iData_Max)
					{
						uiData = m_sDataMgr_Access_LutTable[edcBLENDING_TOP_PIXEL_WIDTH].iData_Max - uiData;

						if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_TOP_START_PIXEL].iData_Max)
						{
							uiData = 0;
						}
						else
						{
							uiData =  m_sDataMgr_Access_LutTable[edcBLENDING_TOP_START_PIXEL].iData_Max - uiData;
						}
					}
					else
					{
						uiData = 0;
					}
                    break;

                case edcBLENDING_TOP_PIXEL_WIDTH:
                    m_sDataMgr_Access_LutTable[edcBLENDING_TOP_START_PIXEL].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
                    break;

                case edcBLENDING_BOTTOM_START_PIXEL:  //A70LV_Larry_0258
                    m_sDataMgr_Access_LutTable[edcBLENDING_BOTTOM_PIXEL_WIDTH].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
					if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_BOTTOM_START_PIXEL].iData_Max)
					{
						uiData = m_sDataMgr_Access_LutTable[edcBLENDING_BOTTOM_PIXEL_WIDTH].iData_Max - uiData;

						if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_BOTTOM_START_PIXEL].iData_Max)
						{
							uiData = 0;
						}
						else
						{
							uiData =  m_sDataMgr_Access_LutTable[edcBLENDING_BOTTOM_START_PIXEL].iData_Max - uiData;
						}
					}
					else
					{
						uiData = 0;
					}
                    break;

                case edcBLENDING_BOTTOM_PIXEL_WIDTH:
                    m_sDataMgr_Access_LutTable[edcBLENDING_BOTTOM_START_PIXEL].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
                    break;

                case edcBLENDING_LEFT_START_PIXEL:  //A70LV_Larry_0258
                    m_sDataMgr_Access_LutTable[edcBLENDING_LEFT_PIXEL_WIDTH].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
					if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_LEFT_START_PIXEL].iData_Max)
					{
						uiData = m_sDataMgr_Access_LutTable[edcBLENDING_LEFT_PIXEL_WIDTH].iData_Max - uiData;

						if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_LEFT_START_PIXEL].iData_Max)
						{
							uiData = 0;
						}
						else
						{
							uiData =  m_sDataMgr_Access_LutTable[edcBLENDING_LEFT_START_PIXEL].iData_Max - uiData;
						}
					}
					else
					{
						uiData = 0;
					}
                    break;

                case edcBLENDING_LEFT_PIXEL_WIDTH:
                    m_sDataMgr_Access_LutTable[edcBLENDING_LEFT_START_PIXEL].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
                    break;

                case edcBLENDING_RIGHT_START_PIXEL:  //A70LV_Larry_0258
                    m_sDataMgr_Access_LutTable[edcBLENDING_RIGHT_PIXEL_WIDTH].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
					if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_RIGHT_START_PIXEL].iData_Max)
					{
						uiData = m_sDataMgr_Access_LutTable[edcBLENDING_RIGHT_PIXEL_WIDTH].iData_Max - uiData;

						if(uiData > m_sDataMgr_Access_LutTable[edcBLENDING_RIGHT_START_PIXEL].iData_Max)
						{
							uiData = 0;
						}
						else
						{
							uiData =  m_sDataMgr_Access_LutTable[edcBLENDING_RIGHT_START_PIXEL].iData_Max - uiData;
						}
					}
					else
					{
						uiData = 0;
					}
                    break;

                case edcBLENDING_RIGHT_PIXEL_WIDTH:
                    m_sDataMgr_Access_LutTable[edcBLENDING_RIGHT_START_PIXEL].FuncPoint.DataMgr_Access(edaREAD, (void*)&uiData);
                    break;

                 #ifdef CUSTOM_CHRISTIE

                 case edcFRAME_DELAY:
                    if(m_sDataMgr_Access_LutTable[eDataCode].iData_Max > palImgMgr_FrameDelay_Max_Get())
                    {
                        uiData = m_sDataMgr_Access_LutTable[eDataCode].iData_Max - palImgMgr_FrameDelay_Max_Get();
                    }
                 break;

                 #endif

                 default:
                    uiData = 0;
                    break;
            }
            *((INT32*)pValue) = m_sDataMgr_Access_LutTable[eDataCode].iData_Max - (INT32)uiData;
        }
            break;

        case edrMIN:
            *((INT32*)pValue) = m_sDataMgr_Access_LutTable[eDataCode].iData_Min;    //A70LV_Doulas_0024
            break;

        case edrDEFAULT:
            switch(eDataCode)
            {

                case edcMANUAL_WARP_HORZ_FILTER: //A70LV_Larry_0220
                    {
                        UINT8 ucData = 0;
                        halWarp_GeometryParameterGet(eWARP_EVENT_DEFAULT_FILTER_H, &ucData);
                        *((INT32*)pValue) = ucData;
                    }
                    break;

                case edcMANUAL_WARP_VERT_FILTER: //A70LV_Larry_0220
                    {
                        UINT8 ucData = 0;
                        halWarp_GeometryParameterGet(eWARP_EVENT_DEFAULT_FILTER_V, &ucData);
                        *((INT32*)pValue) = ucData;
                    }
                    break;

                case edcPICTURE_SETTINGS: //A70LV_Larry_0235
                    {
                        if(palSystem_CustomerSplashGet() == CUSTOM_LOGO_SCREENX)
                        {
                            *((INT32*)pValue) = eCM_PICTURE_SETTINGS_BLENDING;
                        }
                        else
                        {
                            *((INT32*)pValue) = eCM_PICTURE_SETTINGS_BRIGHT;
                        }
                    }
                    break;

                case edcCONTRAST_ENHANCEMENT: //A70LV_Larry_0235
                    {
                        if(palSystem_CustomerSplashGet() == CUSTOM_LOGO_SCREENX)
                        {
                            *((INT32*)pValue) = eCONTRAST_ENHANCE_REAL_BLACK;
                        }
                        else
                        {
                            *((INT32*)pValue) = eCONTRAST_ENHANCE_OFF;
                        }
                    }
                    break;

                case edcSYNC_THRESHOLD:     //A70LV_Doulas_0246 modify
                    *((INT32*)pValue) = m_sDataMgr_Access_LutTable[eDataCode].iData_Default*SYNC_THRESHOLD_STEP_VALUE;
                    break;

                default:
                    *((INT32*)pValue) = m_sDataMgr_Access_LutTable[eDataCode].iData_Default;    //A70LV_Doulas_0024
                    break;
            }
            break;
    }

    return eEXEC_CODE_PASS;
}

INT32 palDataMgr_Data_DefaultValue_Get(eDATA_CODE eDataCode)
{
    if (eDataCode >= DATAMGR_ACCESS_TABLE_ENTRIES)
        return 0;

    return m_sDataMgr_Access_LutTable[eDataCode].iData_Default;
}

void palDataMgr_Data_DefaultValue_Set(eDATA_CODE eDataCode, INT32 iValue)
{
    if (eDataCode < DATAMGR_ACCESS_TABLE_ENTRIES)
    {
        m_sDataMgr_Access_LutTable[eDataCode].iData_Default = iValue;
    }
}

eEXEC_CODE palDataMgr_Data_ReadDefaultWrite(eDATA_CODE eDataCode)// R70K_Bruce_0065//HICC2_Julie_0011
{
    INT32 iValue = 0;
    eEXEC_CODE eResult = palDataMgr_Data_Range_Get(eDataCode, edrDEFAULT, &iValue);
    if(eResult != eEXEC_CODE_PASS)
    {
        LOG_MSG(db_APP_DATA_MGR, "%s()=%d, appDataMgr_Data_Range_Get(%d) Fail !!!\r\n", __func__, eResult, eDataCode);
        return(eResult);
    }

    eResult = m_sDataMgr_Access_LutTable[eDataCode].FuncPoint.DataMgr_Access(edaWRITE_THROUGH_WITH_ACTION, &iValue);
    if(eResult != eEXEC_CODE_PASS)
    {
        LOG_MSG(db_APP_DATA_MGR, "%s()=%d, m_sDataMgr_Access_LutTable[%d] Fail !!!\r\n", __func__, eResult, eDataCode);
        return(eResult);
    }

    palLANProcSendToLAN(eDataCode);
    return(eEXEC_CODE_PASS);
}

