psEEPROM_SETTINGS palDataMgr_GetDefaultSettingConfig(void)
{
    return &m_sDefSysSettings;
}

void palDataMgr_DefaultSettingConfig(void)      //A70LV_Doulas_0015 modify
{
    UINT16 uiTotalCount = 0, uiCount = 0, uiCount2 = 0;
    INT32  iValue = 0;
    char   cString[64] = {'\0'};

    uiTotalCount = InitOSDDafaultValueTotalCountGet();

    if(uiTotalCount != 0)
    {
        for(uiCount = 0; uiCount < uiTotalCount; uiCount++)
        {
            if(InitOSDDafaultValueGet(uiCount, cString, &iValue))
            {
                for(uiCount2 = 0; uiCount2 < edcINVALID; uiCount2++)
                {
                    if(strcmp(cString, palDataMgr_DataCodeStringGet(uiCount2)) == 0)
                    {
                        palDataMgr_Data_DefaultValue_Set(uiCount2, iValue);
                        break;
                    }
                }
            }
        }
    }

    palDataMgr_sLayoutVersion_Init_Default();
    palDataMgr_sADC_cal_values_Init_Default();
    palDataMgr_sWaveformstate_Init_Default();
    palDataMgr_sBurin_Information_Init_Default();
    palDataMgr_sSystemDefault_Init_Default();
    palDataMgr_sUserSystemSetting_Init_Default();
    palDataMgr_sTiming_Table_Init_Default();        //A70LV_Doulas_0194
}



