void palDataMgr_ImportAllDataToDatabase(void)
{
    UINT32 StartTime = TMO_GetSysRunTime();

    sDATABASE_ITEM_DATA_FORMAT sWriteData ;
    sDATACODE_INFO sWriteDatacodeInfo ;

    for(UINT16 Index = 0 ; Index < DATAMGR_ACCESS_TABLE_ENTRIES; Index++ )
    {
        memset(&sWriteData, 0, sizeof(sDATABASE_ITEM_DATA_FORMAT));

        sWriteData.ucType           = (UINT8)palDataMgr_Data_Type((eDATA_CODE)Index);
        sWriteData.ucGrayoutStatus  = (UINT8)palDataMgr_DataCode_Control((eDATA_CODE)Index);
        sWriteData.uiItemIndex      = (UINT16)Index;
        sWriteData.uiValueSize      = palDataMgr_DataSizeGet((eDATA_CODE)Index);

        //LOG_MSG(db_UTL_DATABASE, "%d " , sWriteData.uiItemIndex);

        switch(sWriteData.ucType)
        {
            case DATA_TYPE_STRING:
            case DATA_TYPE_STRUCT:
            case DATA_TYPE_VOID:
                {
                    palDataMgr_Data_Access((eDATA_CODE)Index, edaREAD, sWriteData.uValue.acString);
                    //LOG_MSG(db_UTL_DATABASE, "%s\n" , sWriteData.uValue.acString);
                }
                break;

            case DATA_TYPE_UI_DIGIT_8:
            case DATA_TYPE_UI_DIGIT_16:
            case DATA_TYPE_UI_DIGIT_32:
            case DATA_TYPE_I_DIGIT_8:
            case DATA_TYPE_I_DIGIT_16:
            case DATA_TYPE_I_DIGIT_32:
            case DATA_TYPE_FLOAT:
                {
                    palDataMgr_Data_Access((eDATA_CODE)Index, edaREAD, &sWriteData.uValue.lValue);
                    //LOG_MSG(db_UTL_DATABASE, "%d\n" , sWriteData.uValue.lValue);
                }
                break;

            case DATA_TYPE_NA:
                sWriteData.uValue.lValue = 0;
                break ;

            default:
                {
                    palDataMgr_Data_Access((eDATA_CODE)Index, edaREAD, &sWriteData.uValue.lValue);
                    //LOG_MSG(db_UTL_DATABASE, "%d\n" , sWriteData.uValue.lValue);
                }
                break;

        }


        utilDatabase_WriteData(eSB_DATABASE_ITEM, &sWriteData, Index);

        //write Datacode Info to shared memory
        memset(&sWriteDatacodeInfo, 0, sizeof(sDATACODE_INFO));
        sWriteDatacodeInfo.Max              = m_sDataMgr_Access_LutTable[Index].iData_Max;
        sWriteDatacodeInfo.Min              = m_sDataMgr_Access_LutTable[Index].iData_Min;
        sWriteDatacodeInfo.IsSupportAckdone = m_sDataMgr_Access_LutTable[Index].IsSupportAckdone;
        utilDatabase_WriteData(eSB_DATACODE_INFO, &sWriteDatacodeInfo, Index);

    }

    LOG_MSG(db_UTL_DATABASE, "%s Time: %d ms\n" , __FUNCTION__ , TMO_GetPeriod(StartTime));

}

