UINT8 palDataMgr_CopyUserColorSetting(void)
{
    UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
    UINT8  ucPresetMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode;
    UINT8  ucSignalType = palDataMgr_SignalType_Get();
    UINT8  ucSubSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceSub; //G100_Steven_0088

    //save pre-display mode
    m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode =
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode;

    memcpy(&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sUserColorSetting[ucInputSource][ucPresetMode][ucSignalType], //G100_Steven_0016
        &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sColorSetting[ucInputSource][ucPresetMode][ucSignalType], sizeof(sCOLOR_SETTING));

    memcpy(&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sUserHSG_setting[ucInputSource][ucPresetMode],   //G100_Steven_0020
        &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sHSG_setting[ucInputSource][ucPresetMode], sizeof(sHSG_SETTING));
    //G100_Steven_0088 start
    if(palDataPath_IsSourceLockSub() == TRUE && palImgMgr_PIP_PBP_Enable_Get()!=ets_OFF)
    {
    	m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sUserColorSetting[ucSubSource][ucPresetMode][ucSignalType].ucBrightness
		= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sColorSetting[ucSubSource][ucPresetMode][ucSignalType].ucBrightness;

    	m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sUserColorSetting[ucSubSource][ucPresetMode][ucSignalType].ucContrast
		= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sColorSetting[ucSubSource][ucPresetMode][ucSignalType].ucContrast;

    	m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sUserColorSetting[ucSubSource][ucPresetMode][ucSignalType].ucCS
		= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sColorSetting[ucSubSource][ucPresetMode][ucSignalType].ucCS;
    } //G100_Steven_0088 end
    return eEXEC_CODE_PASS;
}
