eFUNC_CONTROL palDataMgr_LanApplyAvalibleCheck(void)     //A70LV_Doulas_0025
{
    UINT8 i = 0;

    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sNetworkSetting.ucDHCP == ets_ON)
    {
        return eFUNC_CONTROL_DISABLE ;
    }

    for(i = 0 ; i < 4 ; i++)
    {
        if(m_sLAN_info.ucLAN_IP_Show[i] != m_sLAN_info.ucLAN_IP[i])
        {
            return eFUNC_CONTROL_DISABLE ;
        }

        if(m_sLAN_info.ucLAN_MASK_Show[i] != m_sLAN_info.ucLAN_MASK[i])
        {
            return eFUNC_CONTROL_DISABLE ;
        }

        if(m_sLAN_info.ucLAN_GATEWAY_Show[i] != m_sLAN_info.ucLAN_GATEWAY[i])
        {
            return eFUNC_CONTROL_DISABLE ;
        }
    }

    return eFUNC_CONTROL_ENABLE ;
}

//將實際的 LAN 資訊 , 寫回系統顯示的數值
