{
    UINT8 i;

    m_sLAN_info.ucLAN_DHCP_Show = m_sLAN_info.ucLAN_DHCP;

    for(i = 0 ; i < 4 ; i++)
    {
        m_sLAN_info.ucLAN_IP_Show[i]            = m_sLAN_info.ucLAN_IP[i] ;
        m_sLAN_info.ucLAN_MASK_Show[i]          = m_sLAN_info.ucLAN_MASK[i] ;
        m_sLAN_info.ucLAN_GATEWAY_Show[i]       = m_sLAN_info.ucLAN_GATEWAY[i] ;
        m_sLAN_info.ucLAN_Primary_DNS_Show[i]   = m_sLAN_info.ucLAN_Primary_DNS[i];
        m_sLAN_info.ucLAN_Secondary_DNS_Show[i] = m_sLAN_info.ucLAN_Secondary_DNS[i];
    }

    m_sLAN_info.ucLAN_Path_Show = m_sLAN_info.ucLAN_Path;   //G100_Owen_0027
}

