void palDataMgr_LanArg_Send_Mcu(UINT16 uiDataCode)//A35Gen2_Coda
{
    switch(uiDataCode)
    {
        case edcLAN_PATH_SWITCH:
            halMCU_LAN_Path_Set(m_sLAN_info.ucLAN_Path);
            break;

        case edcLAN_IP_ADDRESS:
            halMCU_LAN_IP_INFO_Set(m_sLAN_info.ucLAN_IP);
            break;
    }
}

