UINT8 palDataMgr_ResetDigitalZoomShiftRam(void)   //A70LV_Doulas_0117
{
    eEXEC_CODE eExecResult = eEXEC_CODE_PASS;
    UINT8  ucValue;
    UINT16 uiValue;
    UINT8  ucProportional;

    palDataMgr_Access_DigitalZoom_Proportional(edaREAD, &ucProportional);
    ucValue = ets_OFF;
    palDataMgr_Access_DigitalZoom_Proportional(edaWRITE_RAM_ONLY_NO_ACTION, &ucValue);

    palDataMgr_Access_DigitalHorzZoom(edaREAD, &uiValue);
    if(uiValue != DIGITAL_HORZ_ZOOM_DEFAULT)
    {
        uiValue = DIGITAL_HORZ_ZOOM_DEFAULT;
        palDataMgr_Access_DigitalHorzZoom(edaWRITE_THROUGH_NO_ACTION, &uiValue);
        palImgMgr_DigitalHorzZoom_Set(uiValue);
    }

    palDataMgr_Access_DigitalVertZoom(edaREAD, &uiValue);
    if(uiValue != DIGITAL_VERT_ZOOM_DEFAULT)
    {
        uiValue = DIGITAL_VERT_ZOOM_DEFAULT;
        palDataMgr_Access_DigitalVertZoom(edaWRITE_THROUGH_NO_ACTION, &uiValue);
        palImgMgr_DigitalVertZoom_Set(uiValue);
    }

    palDataMgr_Access_DigitalHorzShift(edaREAD, &ucValue);
    if(ucValue != DIGITAL_HORZ_SHIFT_DEFAULT)
    {
        ucValue = DIGITAL_HORZ_SHIFT_DEFAULT;
        palDataMgr_Access_DigitalHorzShift(edaWRITE_THROUGH_NO_ACTION, &ucValue);
        palImgMgr_DigitalHorzShift_Set(ucValue);
    }

    palDataMgr_Access_DigitalVertShift(edaREAD, &ucValue);
    if(ucValue != DIGITAL_VERT_SHIFT_DEFAULT)
    {
        ucValue = DIGITAL_VERT_SHIFT_DEFAULT;
        palDataMgr_Access_DigitalVertShift(edaWRITE_THROUGH_NO_ACTION, &ucValue);
        palImgMgr_DigitalVertShift_Set(ucValue);
    }

    palDataMgr_Access_DigitalZoom_Proportional(edaWRITE_RAM_ONLY_NO_ACTION, &ucProportional);
    return eExecResult;
}


void palDataMgr_ResetDigitalZoomShift(void)
{
    UINT8  ucValue;
    UINT16 uiValue;

    palDataMgr_Data_Access(edcDIGITAL_HORZ_ZOOM, edaREAD, (void*)&uiValue);
    if(uiValue != DIGITAL_HORZ_ZOOM_DEFAULT)
    {
        uiValue = DIGITAL_HORZ_ZOOM_DEFAULT;
        //palDataMgr_Data_Access(edcDIGITAL_HORZ_ZOOM, edaWRITE_THROUGH_NO_ACTION, &uiValue);
        palDataMgr_DigitalZoomProportional_Execute(edcDIGITAL_HORZ_ZOOM, edaWRITE_THROUGH_NO_ACTION, &uiValue); //H30K_Doulas_0042
        palImgMgr_DigitalHorzZoom_Set(uiValue);
    }

    palDataMgr_Data_Access(edcDIGITAL_VERT_ZOOM, edaREAD, (void*)&uiValue);
    if(uiValue != DIGITAL_VERT_ZOOM_DEFAULT)
    {
        uiValue = DIGITAL_VERT_ZOOM_DEFAULT;
        //palDataMgr_Data_Access(edcDIGITAL_VERT_ZOOM, edaWRITE_THROUGH_NO_ACTION, &uiValue);
        palDataMgr_DigitalZoomProportional_Execute(edcDIGITAL_VERT_ZOOM, edaWRITE_THROUGH_NO_ACTION, &uiValue); //H30K_Doulas_0042
        palImgMgr_DigitalVertZoom_Set(uiValue);
    }

    palDataMgr_Data_Access(edcDIGITAL_HORZ_SHIFT, edaREAD, (void*)&ucValue);
    if(ucValue != DIGITAL_HORZ_SHIFT_DEFAULT)
    {
        ucValue = DIGITAL_HORZ_SHIFT_DEFAULT;
        palDataMgr_Data_Access(edcDIGITAL_HORZ_SHIFT,edaWRITE_THROUGH_NO_ACTION, &ucValue);
        palImgMgr_DigitalHorzShift_Set(ucValue);
    }

    palDataMgr_Data_Access(edcDIGITAL_VERT_SHIFT, edaREAD, (void*)&ucValue);
    if(ucValue != DIGITAL_VERT_SHIFT_DEFAULT)
    {
        ucValue = DIGITAL_VERT_SHIFT_DEFAULT;
        palDataMgr_Data_Access(edcDIGITAL_VERT_SHIFT, edaWRITE_THROUGH_NO_ACTION, &ucValue);
        palImgMgr_DigitalVertShift_Set(ucValue);
    }
}


UINT8 palDataMgr_ResetAllHoursToDefault(void)      //A70LV_Doulas_0128
{
    eEXEC_CODE eExecResult = eEXEC_CODE_PASS;
    UINT32      ulLDHours = 0;

	palDataMgr_Access_LD_Hours_Factory(edaWRITE_THROUGH_NO_ACTION, &ulLDHours);// HICC2_Bruce_0012
	palDataMgr_Access_TotalProjectorHours_Factory(edaWRITE_THROUGH_NO_ACTION, &ulLDHours);

#if 1   //G100_Owen_0042
    palIllumination_Init_LDHoursSet(ulLDHours);
    palIllumination_Init_TotalProjectHoursSet(ulLDHours);

    palDataMgr_Data_Access(edcLD_HOURS, edaWRITE_THROUGH_NO_ACTION, &ulLDHours);
    palDataMgr_Data_Access(edcTOTAL_PROJECTOR_HOURS, edaWRITE_THROUGH_NO_ACTION, &ulLDHours);
    palDataMgr_Data_Access(edcLIGHT_SOURCE_HOURS_NORAML, edaWRITE_THROUGH_NO_ACTION, &ulLDHours);
    palDataMgr_Data_Access(edcLIGHT_SOURCE_HOURS_ECO, edaWRITE_THROUGH_NO_ACTION, &ulLDHours);
    palDataMgr_Data_Access(edcLIGHT_SOURCE_HOURS_QUIET, edaWRITE_THROUGH_NO_ACTION, &ulLDHours);
    palDataMgr_Data_Access(edcLIGHT_SOURCE_HOURS_CUSTOM, edaWRITE_THROUGH_NO_ACTION, &ulLDHours);

    palLANProcSendToLAN(edcTOTAL_PROJECTOR_HOURS_INFO); //HICC2_Doulas_0061
    palLANProcSendToLAN(edcLD_HOURS_INFO); //HICC2_Doulas_0061
    palLANProcSendToLAN(edcSERVICE_LIGHT_SOURCE_HOUR); //HICC2_Doulas_0061
#else
    UINT32      ulTotalProjectorHours = 0;

    eExecResult = palDataMgr_Data_Access(edcLD_HOURS, edaWRITE_THROUGH_NO_ACTION, &ulLDHours);
    if(eExecResult == eEXEC_CODE_PASS)
    {
        palIllumination_Init_LDHoursSet(ulLDHours, TRUE); //A70LV_Larry_0268

        eExecResult = palDataMgr_Data_Access(edcTOTAL_PROJECTOR_HOURS, edaWRITE_THROUGH_NO_ACTION, &ulTotalProjectorHours);

        if(eExecResult == eEXEC_CODE_PASS)
        {
            palIllumination_Init_TotalProjectHoursSet(ulLDHours, TRUE); //A70LV_Larry_0268
        }
    }
#endif
    return eExecResult;
}

