UINT8 palDataMgr_IS_3D_Enable(void)         //A70LV_Doulas_0153
{
    UINT8  ucValue = 0;
    UINT8  uc3D_Enable = ets_OFF;
    UINT8  uc3D_Mode = ets_OFF;
    UINT8  ucPIP_Mode = ets_OFF;    //ZU860_Doulas_0104
    //LOG_MSG(db_ALWAYS, "palDataMgr_DigitalZoomShiftSet \r\n");

    palDataMgr_Access_3DEnable(edaREAD, &ucValue);
    palDataMgr_Access_3DMode(edaREAD, &uc3D_Mode);      //ZU860_Doulas_0049
    palDataMgr_Access_PIP_PBP_Enable(edaREAD, &ucPIP_Mode);      //ZU860_Doulas_0104
    if(uc3D_Mode == eCM_3D_MODE_OFF)                  //H30K_Doulas_0001//ZU860_Doulas_0049
    {
        ucValue = eCM_3D_FORMAT_OFF;
    }
    else if(ucPIP_Mode)   //ZU860_Doulas_0104 Add
    {
        ucValue = eCM_3D_FORMAT_OFF;
    }

    switch(ucValue)
    {
        case eCM_3D_FORMAT_AUTO:
            //get frontend 3D infomation to check 3D on/off
            switch(palImgMgr_Input_3D_Format_Get())    //A70LV_Doulas_0154
            {
                case eINPUT_3D_TYPE_FRAMEPACKING:
                case eINPUT_3D_TYPE_SIDEBYSIDE:
                case eINPUT_3D_TYPE_TOPANDBOTTOM:
                //case eINPUT_3D_TYPE_FRAME_SEQUENTIAL:   //ZU860_Doulas_0049 remove
                    uc3D_Enable = ets_ON;
                    break;

                default:
                    uc3D_Enable = ets_OFF;
                    break;
            }
            break;

        case eCM_3D_FORMAT_FRAME_PACKING:
        case eCM_3D_FORMAT_SIDE_BY_SIDE:
        case eCM_3D_FORMAT_TOP_AND_BOTTOM:
        case eCM_3D_FORMAT_FRAME_SEQUENTIAL:
        case eCM_3D_FORMAT_DUALPIPE:
        case eCM_3D_FORMAT_DUALPIPE_3D:
        case eCM_3D_FORMAT_4K3D:
        case eCM_3D_FORMAT_4K3D_DUALPIPE:
            uc3D_Enable = ets_ON;
            break;

        case eCM_3D_FORMAT_OFF:
            uc3D_Enable = ets_OFF;
            break;

        default:
            break;
    }

    return uc3D_Enable;
}

void palDataMgr_SourceName_Get(UINT8 ucSource, char *cDynamicString)
{
    switch(ucSource)
    {
        case eCM_SOURCE_VGA:
            palDataMgr_Data_Access(edcSOURCE1_NAME, edaREAD, cDynamicString);
            break;
        case eCM_SOURCE_HDMI1:
            palDataMgr_Data_Access(edcSOURCE3_NAME, edaREAD, cDynamicString);
            break;
        case eCM_SOURCE_HDMI2:
            palDataMgr_Data_Access(edcSOURCE4_NAME, edaREAD, cDynamicString);
            break;
        case eCM_SOURCE_DVI:
            palDataMgr_Data_Access(edcSOURCE5_NAME, edaREAD, cDynamicString);
            break;
        case eCM_SOURCE_DISPLAYPORT:
            palDataMgr_Data_Access(edcSOURCE6_NAME, edaREAD, cDynamicString);   //G100_Wilsonj_0005
            break;
        case eCM_SOURCE_3GSDI:
            palDataMgr_Data_Access(edcSOURCE7_NAME, edaREAD, cDynamicString);
            break;
        case eCM_SOURCE_HDBASET:
            palDataMgr_Data_Access(edcSOURCE8_NAME, edaREAD, cDynamicString);
            break;

        default:
            sprintf((char *)cDynamicString, "-");
            break;
    }
}

