sBACKUP_RESTORE palDataMgr_ConfigurationRead(void)    //A70LV_Doulas_0280//A70LV_Doulas_0279
{
    sBACKUP_RESTORE sBR;
    UINT16 uiWord = 0;
    UINT8 ucDataType;
    eEXEC_CODE eResult = eEXEC_CODE_FAIL;
    UINT16 udBR_DataCodeTable[] = {
        edcCOLOR_WHEEL_SPEED,
        edcSIZE_PRESETS,
        edcPICTURE_SETTINGS,
        edcPRE_USER_MODE,           //A70LV_Doulas_0282
        edcDIGITAL_HORZ_ZOOM,
        edcDIGITAL_VERT_ZOOM,
        edcDIGITAL_HORZ_SHIFT,
        edcDIGITAL_VERT_SHIFT,

        edcBRIGHTNESS,
        edcCONTRAST,
        edcDETAIL,

        edcGAMMA,
        edcWHITE_PEAKING,
        edcCOLOR_TEMPERATURE,

        edcRED_GAIN,
        edcGREEN_GAIN,
        edcBLUE_GAIN,
        edcRED_OFFSET,
        edcGREEN_OFFSET,
        edcBLUE_OFFSET,
        edcTINT,
        edcCOLOR,
        edcSKIN_COLOR,

        edcCOLOR_ENHANCEMENT,
        edcHSG_ENABLE,

        edcHSG_RED_HUE,
        edcHSG_RED_SATURATION,
        edcHSG_RED_GAIN,
        edcHSG_GREEN_HUE,
        edcHSG_GREEN_SATURATION,
        edcHSG_GREEN_GAIN,
        edcHSG_BLUE_HUE,
        edcHSG_BLUE_SATURATION,
        edcHSG_BLUE_GAIN,
        edcHSG_CYAN_HUE,
        edcHSG_CYAN_SATURATION,
        edcHSG_CYAN_GAIN,
        edcHSG_MAGENTA_HUE,
        edcHSG_MAGENTA_SATURATION,
        edcHSG_MAGENTA_GAIN,
        edcHSG_YELLOW_HUE,
        edcHSG_YELLOW_SATURATION,
        edcHSG_YELLOW_GAIN,
        edcHSG_WHITE_GAIN_RED,
        edcHSG_WHITE_GAIN_GREEN,
        edcHSG_WHITE_GAIN_BLUE,
        edcWALL_COLOR,

        edcNON,
    };

    for( uiWord = 0; uiWord < BACK_RESTORE_ITEM_MAX; uiWord++)
    {
        sBR.sRestoreItem[uiWord].udDataCode = 0;
        sBR.sRestoreItem[uiWord].ucSize = 0;
        sBR.sRestoreItem[uiWord].DataValue.DWord = 0;
    }

    for( uiWord = 0; uiWord < BACK_RESTORE_RETENTION; uiWord++)
    {
        sBR.Retention[uiWord] = 0;
    }

    sBR.sRestoreVersion.uiMODEL_INDEX = 'A';
    sBR.sRestoreVersion.udBACKUP_RESTORE_CHECKING = BACK_RESTORE_CHECKING_NUM;
    palDataMgr_Data_Access(edcSMCU_VERSION, edaREAD, sBR.sRestoreVersion.ucSCALER_VERSION);
    palDataMgr_Data_Access(edcLAN_VERSION, edaREAD, sBR.sRestoreVersion.ucLAN_VERSION);
    palDataMgr_Data_Access(edcFORMATER_VERSION, edaREAD, sBR.sRestoreVersion.ucFORMATER_VERSION);
    palDataMgr_Data_Access(edcFRONTEND_VERSION, edaREAD, sBR.sRestoreVersion.ucFRONTEND_VERSION);

    for( uiWord = 0; udBR_DataCodeTable[uiWord] != edcNON ; uiWord++)
    {
        sBR.sRestoreItem[uiWord].udDataCode = udBR_DataCodeTable[uiWord];
        ucDataType = palDataMgr_Data_Type((eDATA_CODE)udBR_DataCodeTable[uiWord]);
        switch(ucDataType)
        {
            case DATA_TYPE_UI_DIGIT_8:
            {
                UINT8 ucValue;
                eResult = palDataMgr_Data_Access((eDATA_CODE)udBR_DataCodeTable[uiWord], edaREAD, &ucValue);
                if(eResult == eEXEC_CODE_PASS)
                {
                    sBR.sRestoreItem[uiWord].ucSize = 1;
                    sBR.sRestoreItem[uiWord].DataValue.Bytes[0] = ucValue;
                }

                LOG_MSG(db_APP_DATA_MGR, "DataCode(%d) %d\r\n", udBR_DataCodeTable[uiWord], ucValue);
            }
            break;

            case DATA_TYPE_UI_DIGIT_16:
            {
                UINT16 uiValue;
                eResult = palDataMgr_Data_Access((eDATA_CODE)udBR_DataCodeTable[uiWord], edaREAD, &uiValue);
                if(eResult == eEXEC_CODE_PASS)
                {
                    sBR.sRestoreItem[uiWord].ucSize = 2;
                    sBR.sRestoreItem[uiWord].DataValue.Words[0] = uiValue;
                }

                LOG_MSG(db_APP_DATA_MGR, "DataCode(%d) %d\r\n", udBR_DataCodeTable[uiWord], uiValue);
            }
            break;

            case DATA_TYPE_UI_DIGIT_32:
            {
                UINT32 udValue;
                eResult = palDataMgr_Data_Access((eDATA_CODE)udBR_DataCodeTable[uiWord], edaREAD, &udValue);
                if(eResult == eEXEC_CODE_PASS)
                {
                    sBR.sRestoreItem[uiWord].ucSize = 4;
                    sBR.sRestoreItem[uiWord].DataValue.DWord = udValue;
                }

                LOG_MSG(db_APP_DATA_MGR, "DataCode(%d) 0x%x\r\n", udBR_DataCodeTable[uiWord], udValue);
            }
            break;

            case DATA_TYPE_UI_DIGIT_64:
            {

            }
            break;

            case DATA_TYPE_I_DIGIT_8:
            {
                INT8 cValue;
                eResult = palDataMgr_Data_Access((eDATA_CODE)udBR_DataCodeTable[uiWord], edaREAD, &cValue);
                if(eResult == eEXEC_CODE_PASS)
                {
                    sBR.sRestoreItem[uiWord].ucSize = 1;
                    sBR.sRestoreItem[uiWord].DataValue.Bytes[0] = cValue;
                }

                LOG_MSG(db_APP_DATA_MGR, "DataCode(%d) %d\r\n", udBR_DataCodeTable[uiWord], cValue);
            }
            break;

            case DATA_TYPE_I_DIGIT_16:
            {
                INT16 iValue;
                eResult = palDataMgr_Data_Access((eDATA_CODE)udBR_DataCodeTable[uiWord], edaREAD, &iValue);
                if(eResult == eEXEC_CODE_PASS)
                {
                    sBR.sRestoreItem[uiWord].ucSize = 2;
                    sBR.sRestoreItem[uiWord].DataValue.Words[0] = iValue;
                }

                LOG_MSG(db_APP_DATA_MGR, "DataCode(%d) %d\r\n", udBR_DataCodeTable[uiWord], iValue);
            }
            break;

            case DATA_TYPE_I_DIGIT_32:
            {
                INT32 idValue;
                eResult = palDataMgr_Data_Access((eDATA_CODE)udBR_DataCodeTable[uiWord], edaREAD, &idValue);
                if(eResult == eEXEC_CODE_PASS)
                {
                    sBR.sRestoreItem[uiWord].ucSize = 4;
                    sBR.sRestoreItem[uiWord].DataValue.DWord = idValue;
                }

                LOG_MSG(db_APP_DATA_MGR, "DataCode(%d) 0x%x\r\n", udBR_DataCodeTable[uiWord], idValue);
            }
            break;

            case DATA_TYPE_I_DIGIT_64:
            {

            }
            break;


            case DATA_TYPE_NA:
            case DATA_TYPE_STRING:
            case DATA_TYPE_FLOAT:
            default:
            break;
        }
    }
    //sBackRestore = sBR;
    //palIapProc_BackupRestoreSet(ucIndex,(UINT8*)&sBR);
    return sBR;
}

