eEXEC_CODE palDataMgr_Access_HDMI_OUT(eDATA_ACCESS_MODE eAccessMode, void *pValue)	//G100_Doulas_0057 Add save EEPROM
{

    if (edaREAD == eAccessMode)  //Read Function
    {
		*((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDMI_OUT;
    }
    else  //Write Function
    {
        //Update RAM
		m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDMI_OUT = *((UINT8*)pValue);

        //Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            //UINT8 lGuiValue = (UINT8)CM2GUI(edcHDMI_OUT, *((UINT8*)pValue));
			utilDataMgr_CommonSet_CM(eDF_HDMI_OUT, (UINT8*)pValue);
        }

        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
        	halFrontEndCtrl_HDMI_OUT_Set((UINT8*)pValue);
        }
    }

    return eEXEC_CODE_PASS;
}
