void palDataMgr_DateTime_Unpack_LanPacket(_sDateTime * sLanDateTimePacket) //G100_Coda_0038
{
    UINT8 ucCount = 0;
    //LOG_MSG(db_APP_SCHEDULE,"parse time mode = %s\r\n", sLanDateTimePacket->Mode);
    if(strcmp(sLanDateTimePacket->Mode, "Manual") == 0)
    {
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucClockMode = 1;
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.uwYear   = (UINT16)atol(sLanDateTimePacket->Year); //HICC2_Doulas_0035
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMonth  = (UINT8)atol(sLanDateTimePacket->Month);
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDay    = (UINT8)atol(sLanDateTimePacket->Day);
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucHour   = (UINT8)atol(sLanDateTimePacket->Hour);
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMinute = (UINT8)atol(sLanDateTimePacket->Minute);
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucSecond = (UINT8)atol(sLanDateTimePacket->Second);
    }
    else
    {
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucClockMode = 0;
    }

    for(ucCount = 0; ucCount < 4; ucCount++)
    {
        if(strcmp(sLanDateTimePacket->NTP, pcNtpServer_Str[ucCount]) == 0)
        {
            m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucNtpServer = ucCount;
            break;
        }
    }

    for(ucCount = 0; ucCount < (DATE_TIME_ZONE_MAX_VAULE + 1); ucCount++)  //G100_Coda_0079
    {
        if(strcmp(sLanDateTimePacket->Timezone, sTimeZoneInfoLUT[ucCount].ucAreaStr) == 0)
        {
            m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone = ucCount;
            break;
        }
    }

    if(strcmp(sLanDateTimePacket->DST, "1") == 0)
    {
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDaylightSavingTime = 1;
    }
    else
    {
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDaylightSavingTime = 0;
    }

    if(strcmp(sLanDateTimePacket->Interval, "Hourly") == 0)
    {
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucUpdateInterval = 0;
    }
    else
    {
        m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucUpdateInterval = 1;
    }


    tDATA_CODE IsOSDOpen = 0;
    palDataMgr_Data_Access(edcUI_STATUS_IS_OSD_OPEN, edaREAD, &IsOSDOpen);
    if(IsOSDOpen == 1)
    {
        palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
    }

    palDataMgr_DateTime_TempData_Set(&m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo);

    LOG_MSG(db_APP_SCHEDULE, "Unpack Date Time schedule packet to system (%d)\r\n", sizeof(sLanDateTimePacket));
    LOG_MSG(db_APP_SCHEDULE, "Unpack Mode = %d\r\n",  m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucClockMode);

}


void palDataMgr_DateTime_Build_LanPacket(_sDateTime *sDateTimePacket)  //G100_Coda_0038
{
    UINT8 ucWeekdayCount = 0;
    UINT8 ucEventListNum = 0;
    UINT8 ucCount = 0;
    UINT8 ucSubCount = 0;

    //memset((UINT8*)sLanSchudelePacket, 0, sizeof(sLAN_SCHEDULE_PACKET));

    //Get Schedule Mode On/Off
    if(m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucClockMode == 0)
    {
        strcpy(sDateTimePacket->Mode, "Ntp");

        if(m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucUpdateInterval == 0)
        {
            strcpy(sDateTimePacket->Interval, "Hourly");
        }
        else
        {
            strcpy(sDateTimePacket->Interval, "Daily");
        }

        strcpy(sDateTimePacket->NTP, pcNtpServer_Str[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucNtpServer]);

    }
    else //use manual
    {
        strcpy(sDateTimePacket->Mode, "Manual");

        sprintf(sDateTimePacket->Year, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.uwYear);

        sprintf(sDateTimePacket->Month, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMonth);

        sprintf(sDateTimePacket->Day, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDay);

        sprintf(sDateTimePacket->Hour, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucHour);

        sprintf(sDateTimePacket->Minute, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMinute);

        sprintf(sDateTimePacket->Second, "0");

    }

    #if 0
    if(m_STRUCT_DATETIME_Update == FALSE)//HICC2_Doulas_0036
    {
        UINT16 uwYear;
        UINT8 ucMonth;
        UINT8 ucDay;
        UINT8 ucHour;
        UINT8 ucMinute;

        char aucVerString[64];
        time_t sTime;
        struct tm *sTemp;

        time(&sTime);
        sTemp = localtime(&sTime);

        uwYear = (1900 + sTemp->tm_year);  //start at 1900 year
        ucMonth = (1 + sTemp->tm_mon);     //start at 0-11 month
        ucDay = sTemp->tm_mday;            //start at 01-31 day
        ucHour = sTemp->tm_hour;
        ucMinute = sTemp->tm_min;

        LOG_MSG(db_ALWAYS, "########$$$$$$$$$$$$$################\r\n");

        sprintf(sDateTimePacket->Year, "%d", uwYear);

        sprintf(sDateTimePacket->Month, "%d", ucMonth);

        sprintf(sDateTimePacket->Day, "%d", ucDay);

        sprintf(sDateTimePacket->Hour, "%d", ucHour);

        sprintf(sDateTimePacket->Minute, "%d", ucMinute);

        sprintf(sDateTimePacket->Second, "0");
    }
    #endif

    strcpy(sDateTimePacket->Dstzone, sTimeZoneInfoLUT[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone].ucDstStr);

    strcpy(sDateTimePacket->Timezone, sTimeZoneInfoLUT[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone].ucAreaStr);

    if(m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDaylightSavingTime == 1)
    {
        strcpy(sDateTimePacket->DST, "1");
    }
    else
    {
        strcpy(sDateTimePacket->DST, "0");
    }

    LOG_MSG(db_APP_SCHEDULE, "B Mode = %s\r\n", sDateTimePacket->Mode);
    LOG_MSG(db_APP_SCHEDULE, "B Year = %s\r\n", sDateTimePacket->Year);
    LOG_MSG(db_APP_SCHEDULE, "B Month = %s\r\n", sDateTimePacket->Month);
    LOG_MSG(db_APP_SCHEDULE, "B Day = %s\r\n", sDateTimePacket->Day);
    LOG_MSG(db_APP_SCHEDULE, "B Hour = %s\r\n", sDateTimePacket->Hour);
    LOG_MSG(db_APP_SCHEDULE, "B Minute = %s\r\n", sDateTimePacket->Minute);
    LOG_MSG(db_APP_SCHEDULE, "B Second = %s\r\n", sDateTimePacket->Second);
    LOG_MSG(db_APP_SCHEDULE, "B Timezone = %s\r\n", sDateTimePacket->Timezone);
    LOG_MSG(db_APP_SCHEDULE, "B NTP = %s\r\n", sDateTimePacket->NTP);
    LOG_MSG(db_APP_SCHEDULE, "B Interval = %s\r\n", sDateTimePacket->Interval);
    LOG_MSG(db_APP_SCHEDULE, "B DST = %s\r\n", sDateTimePacket->DST);
    LOG_MSG(db_APP_SCHEDULE, "B Dstzone = %s\r\n", sDateTimePacket->Dstzone);

    LOG_MSG(db_APP_SCHEDULE, "Build Time schedule packet to system (%d)\r\n", sizeof(_sDateTime));
}

void palDataMgr_DateTime_TimeZoneStr_Get(char *pcTimeZoneStr)  //G100_Owen_0053
{
    if(m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone < 24)
    {
        sprintf(pcTimeZoneStr, "+%s", sTimeZoneInfoLUT[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone].ucTimeZoneStr);
    }
    else
    {
        sprintf(pcTimeZoneStr, "-%s", sTimeZoneInfoLUT[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone].ucTimeZoneStr);
    }
}

void palDataMgr_DateTime_TimeZoneStr_Set(BOOL bSigned, char *pcTimeZoneStr)  //G100_Owen_0053
{
    UINT8 ucCount = 0;

    if(bSigned == TRUE)
    {
        for(ucCount = 0; ucCount < 24; ucCount++)
        {
            if(strcmp(pcTimeZoneStr, sTimeZoneInfoLUT[ucCount].ucTimeZoneStr) == 0)
            {
                m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone = ucCount;
                break;
            }
        }
    }
    else
    {
        for(ucCount = 24; ucCount < 37; ucCount++)
        {
            if(strcmp(pcTimeZoneStr, sTimeZoneInfoLUT[ucCount].ucTimeZoneStr) == 0)
            {
                m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone = ucCount;
                break;
            }
        }
    }
}

void palDataMgr_DateTime_Build_LanPacket_ResetDefault(void)    //G100_Coda_00110
{
    UINT8 ucWeekdayCount = 0;
    UINT8 ucEventListNum = 0;
    UINT8 ucCount = 0;
    UINT8 ucSubCount = 0;
    UINT16 uwStructID = 0 ;//0 : time

    _sStructPayload sStructPayload;
    _sDateTime sLanDateTime ;
    UINT16 uwYear;
    UINT8 ucMonth;
    UINT8 ucDay;
    UINT8 ucHour;
    UINT8 ucMinute;
    sDATE_TIME_INFO sDateTimeInfo;
    time_t sTime;
    struct tm *sTemp;
    time(&sTime);
    sTemp = localtime(&sTime);


    uwYear = (1900 + sTemp->tm_year);  //start at 1900 year
    ucMonth = (1 + sTemp->tm_mon);     //start at 0-11 month
    ucDay = sTemp->tm_mday;            //start at 01-31 day
    ucHour = sTemp->tm_hour;
    ucMinute = sTemp->tm_min;

    memset((UINT8 *)&sStructPayload, 0, sizeof(_sStructPayload));
    memset((UINT8 *)&sLanDateTime, 0, sizeof(_sDateTime));

    //memset((UINT8*)sLanSchudelePacket, 0, sizeof(sLAN_SCHEDULE_PACKET));

    //Get Schedule Mode On/Off
    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucClockMode = 0;
    strcpy(sLanDateTime.Mode, "Ntp");

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucUpdateInterval = 0;
    strcpy(sLanDateTime.Interval, "Hourly");

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucNtpServer = 0;
    strcpy(sLanDateTime.NTP, pcNtpServer_Str[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucNtpServer]);

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone = DATE_TIME_ZONE_DEFAULT_VALUE;
    strcpy(sLanDateTime.Dstzone, sTimeZoneInfoLUT[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone].ucDstStr);
    strcpy(sLanDateTime.Timezone, sTimeZoneInfoLUT[m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucTimeZone].ucAreaStr);

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDaylightSavingTime = 0;
    strcpy(sLanDateTime.DST, "0");

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.uwYear = uwYear;
    sprintf(sLanDateTime.Year, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.uwYear);

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMonth = ucMonth;
    sprintf(sLanDateTime.Month, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMonth);

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDay = ucDay;
    sprintf(sLanDateTime.Day, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucDay);

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucHour = ucHour;
    sprintf(sLanDateTime.Hour, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucHour);

    m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMinute = ucMinute;
    sprintf(sLanDateTime.Minute, "%d", m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo.ucMinute);


    LOG_MSG(db_APP_SCHEDULE, "RR Mode = %s\r\n", sLanDateTime.Mode);
    LOG_MSG(db_APP_SCHEDULE, "RR Year = %s\r\n", sLanDateTime.Year);
    LOG_MSG(db_APP_SCHEDULE, "RR Month = %s\r\n", sLanDateTime.Month);
    LOG_MSG(db_APP_SCHEDULE, "RR Day = %s\r\n", sLanDateTime.Day);
    LOG_MSG(db_APP_SCHEDULE, "RR Hour = %s\r\n", sLanDateTime.Hour);
    LOG_MSG(db_APP_SCHEDULE, "RR Minute = %s\r\n", sLanDateTime.Minute);
    LOG_MSG(db_APP_SCHEDULE, "RR Second = %s\r\n", sLanDateTime.Second);
    LOG_MSG(db_APP_SCHEDULE, "RR Timezone = %s\r\n", sLanDateTime.Timezone);
    LOG_MSG(db_APP_SCHEDULE, "RR NTP = %s\r\n", sLanDateTime.NTP);
    LOG_MSG(db_APP_SCHEDULE, "RR Interval = %s\r\n", sLanDateTime.Interval);
    LOG_MSG(db_APP_SCHEDULE, "RR DST = %s\r\n", sLanDateTime.DST);
    LOG_MSG(db_APP_SCHEDULE, "RR Dstzone = %s\r\n", sLanDateTime.Dstzone);

    LOG_MSG(db_APP_SCHEDULE, "RR Build Time schedule packet to system (%d)\r\n", sizeof(_sDateTime));

    memcpy((UINT8*)&sStructPayload.Data, (UINT8*)&sLanDateTime, sizeof(_sDateTime));

    palLANProcSturctDataSend(uwStructID, sizeof(_sStructPayload), (void *)&sStructPayload);
    LOG_MSG(db_APP_SCHEDULE, "Reset Time Struct (%d,%d)\r\n", sizeof(_sStructPayload), sizeof(_sDateTime));

    palDataMgr_DateTime_TempData_Set(&m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo);
}

eEXEC_CODE palDataMgr_Access_DateTimeApply(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        (*(UINT8*)pValue) = 0;
    }
    else  //Write Function
    {
        _sStructPayload sStructPayload;
        _sDateTime sLanDateTime ;

        memset((UINT8 *)&sStructPayload, 0, sizeof(_sStructPayload));
        memset((UINT8 *)&sLanDateTime, 0, sizeof(_sDateTime));

        palDataMgr_DateTime_Build_LanPacket(&sLanDateTime);

        memcpy((UINT8*)&sStructPayload.Data, (UINT8*)&sLanDateTime, sizeof(_sDateTime));

        UINT16 uwStructID = 0 ;//0 : time

        palLANProcSturctDataSend(uwStructID, sizeof(_sStructPayload), (void *)&sStructPayload);
        LOG_MSG(db_APP_SCHEDULE, "apply Time Struct (%d,%d)\r\n", sizeof(_sStructPayload), sizeof(_sDateTime));

        palDataMgr_DateTime_TempData_Set(&m_sAppDataMgrInfo.sSystemValues.sDateTimeInfo);
        palLANProcSendToLAN(edcSTRUCT_DATETIME);  //HICC2_Doulas_0035
        palLANProcSendToLAN(edcSTRUCT_DATETIME_TMPDATA);  //HICC2_Doulas_0035
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_DateTimeReset(eDATA_ACCESS_MODE eAccessMode, void *pValue)  //G100_Coda_00110
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        (*(UINT8*)pValue) = 0;
    }
    else  //Write Function
    {
        palDataMgr_DateTime_Build_LanPacket_ResetDefault();
    }

    return eEXEC_CODE_PASS;
}


