eEXEC_CODE palDataMgr_Access_Auto_Focus(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A35G2_Coda_0052
{
     if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = palDataMgr_AutoFocusExecute_Get();
    }
    else  //Write Function
    {
        if( ( ( eAccessMode == edaWRITE_RAM_ONLY_WITH_ACTION ) || ( eAccessMode == edaWRITE_THROUGH_WITH_ACTION ) ) &&
            ( *((UINT8 *)pValue) < eAF_AC_NUMBER ) )
        {
            palDataMgr_AutoFocusExecute_Set(*((UINT8 *)pValue));	//G100_Clare_0026 //A35G2_BRC_Casper_0126
            if( *((UINT8 *)pValue) >= eAF_AC_EXECUTE && *((UINT8 *)pValue) <= eAF_AC_EXECUTE_NO_UIMSG)
            {
                palDataMgr_Camera_OSD_Lock_Set(eOSD_LOCKED);       //G100_Clare_0024, mod

			    if(palDataMgr_IsOsdOpen() == TRUE)
                {
                    palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);
                }
                //G100_Clare_0024, del, set by AP
            }

        }
    }

    return eEXEC_CODE_PASS;
}

