eEXEC_CODE palDataMgr_Access_Auto_Focus_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A35G2_Coda_0052
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sSystemValues.ucAuto_Focus_Status;
    }
    else  //Write Function
    {
        m_sAppDataMgrInfo.sSystemValues.ucAuto_Focus_Status = *((UINT8 *)pValue);

        palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);

        if( m_sAppDataMgrInfo.sSystemValues.ucAuto_Focus_Status == eAF_STATUS_PROCESSING )             //A65_OPTOMA_Doulas_0039 Modify//G100_Clare_0024, mod, start
        {
            if( palDataMgr_Camera_OSD_Lock_Get() == eOSD_NOT_LOCKED )           //G100_Clare_0024, mod
            {
                palDataMgr_Camera_OSD_Lock_Set( eOSD_LOCKED );                  //G100_Clare_0024, mod
            }

            if( palDataMgr_AutoFocusExecute_Get() == eAF_AC_NOT_EXECUTE )
            {
                 palDataMgr_AutoFocusExecute_Set( eAF_AC_EXECUTE_NO_UIMSG );  //from AP
            }

            if( utilWarp_GetOsdPatternType() != PAT_TYPE__OFF )    //G100_Simon_0007
            {
                //Disable warp grid pattern
                palGeo_AdvWarpShowOsdPattern(PAT_TYPE__OFF);
                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAwWarpPattern_Show = 0;
    			palLANProcSendToLAN(edcAW_WARP_PATTERN_SHOW);
            }
        }                                                                       //G100_Clare_0024, mod, end
        else if ( m_sAppDataMgrInfo.sSystemValues.ucAuto_Focus_Status <= eAF_STATUS_TIMEOUT )             //A65_OPTOMA_Doulas_0039 Modify//G100_Clare_0024, mod, release lock when receive status.
        {
            palDataMgr_Camera_OSD_Lock_Set(eOSD_NOT_LOCKED);       //G100_Clare_0024, mod

            //UI Event for draw message or dialog
            if(palDataMgr_AutoFocusExecute_Get() == eAF_AC_EXECUTE ||
               palDataMgr_AutoFocusExecute_Get() == eAF_AC_EXECUTE_NO_CHECK)
            {
                if(m_sAppDataMgrInfo.sSystemValues.ucAuto_Focus_Status == eAF_STATUS_SUCCESS)   //pass
                {
                    palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_COMPLETE, TRUE, NULL);
                }
                else   //fail
                {
                    if(m_sAppDataMgrInfo.sSystemValues.cGroupingAutoFocus != eAF_AC_NOT_EXECUTE)
                    {
                        _sGROUPING_CLIENT_RESULT sGroupStatus = {0};

                        palDataMgr_Access_Group_Auto_Focus_Status(edaREAD, &sGroupStatus);

                        if(sGroupStatus.clientRet != eGCS_STATUS_PROCESSING)
                        {
                            if(sGroupStatus.clientRet == eGCS_STATUS_FUNCTION_FAIL)
                            {
                                INT32 offset = 0;

                                if(m_sAppDataMgrInfo.sSystemValues.sGroupingMenuSearch.ucCnt <= 1)// sGroupingMenuSearch.ucCnt == 1, master only
                                {
                                    palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_FAIL, sGroupStatus.functionRet, NULL);
                                }
                                else
                                {
                                    memcpy(&m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus, &sGroupStatus, sizeof(_sGROUPING_CLIENT_RESULT));
                                    palLANProcSendToLAN(edcGROUP_AUTO_COLOR_MATCH_STATUS); //used ACM datacode

                                    if(sGroupStatus.functionRet < eACM_RESULT_IDLE)
                                    {
                                        offset = eACM_AF_STATUS_PROCESSING;
                                    }

                                    palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, (offset + sGroupStatus.functionRet), NULL);
                                }
                            }
                            else
                            {
                                memcpy(&m_sAppDataMgrInfo.sSystemValues.sGroupingAutoColorMatchStatus, &sGroupStatus, sizeof(_sGROUPING_CLIENT_RESULT));
                                palLANProcSendToLAN(edcGROUP_AUTO_COLOR_MATCH_STATUS);
                                palDataMgr_UI_EventSend(edcUI_EVENT_ACM_CAL_FAIL, sGroupStatus.clientRet, NULL);
                            }
                        }
                    }
                    else
                    {
                        palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_FAIL, m_sAppDataMgrInfo.sSystemValues.ucAuto_Focus_Status, NULL);
                    }
                }
            }

            palDataMgr_AutoFocusExecute_Set(eAF_AC_NOT_EXECUTE);
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_Auto_Wall_Color_Status(eDATA_ACCESS_MODE eAccessMode, void *pValue) //A35G2_Coda_0052 //A35G2_Coda_0055
{
	UINT8 tValue = eAC_APPLY_IDLE;//A35G2_Alan_0017

	UINT8 CurVal = m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Status;
	UINT8 NewVal = *((UINT8*)pValue);

    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = CurVal;
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Status = NewVal;

        if(m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Status == eAWC_STATUS_PROCESSING )        //G100_Clare_0024, mod, start
        {
            palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);

            if( palDataMgr_Camera_OSD_Lock_Get() == eOSD_NOT_LOCKED )           //G100_Clare_0024, mod //A35G2_Coda_0056
            {
                palDataMgr_Camera_OSD_Lock_Set( eOSD_LOCKED );                  //G100_Clare_0024, mod
            }

            if( m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Execute == eAF_AC_NOT_EXECUTE )
            {
                UINT8 ucData = eAF_AC_EXECUTE_NO_UIMSG;  //from AP

                palDataMgr_Access_Auto_Wall_Color(eAccessMode, &ucData);
            }
        }                                                                       //G100_Clare_0024, mod, end
        else if (m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Status <= eAWC_STATUS_TIMEOUT )        //G100_Clare_0024, mod, release lock when receive status.
        {
            //UI Event for draw message or dialog
            if(m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Execute == eAF_AC_EXECUTE)
            {
                if(m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Status == eAF_STATUS_SUCCESS)   //pass
                {
                    //show dialog to view new or previous image
                    palDataMgr_UI_EventSend(edcUI_EVENT_AC_CAL_COMPLETE, TRUE, NULL);
                }
                else   //fail
                {
                    palDataMgr_UI_EventSend(edcUI_EVENT_AC_CAL_FAIL, NewVal, NULL);
                }
            }
            else if(m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Execute == eAF_AC_EXECUTE_NO_CHECK)
            {
                if(m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Status == eAF_STATUS_SUCCESS)   //pass
                {
                    //using the same as auto focus complete message
                    palDataMgr_UI_EventSend(edcUI_EVENT_AF_CAL_COMPLETE, TRUE, NULL);
                }
                else   //fail
                {
                    palDataMgr_UI_EventSend(edcUI_EVENT_AC_CAL_FAIL, NewVal, NULL);
                }
            }

            //AC Apply Set
            if(m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Execute == eAF_AC_EXECUTE ||    //execute from OSD
               m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Execute == eAF_AC_EXECUTE_NO_CHECK)  // execute from CLI
            {
                if(eAF_STATUS_SUCCESS == NewVal)
                {
                    m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Apply = eAC_APPLY_CALIBRATED;
                    palLANProcSendToLAN(edcAC_APPLY);
                }
            }

            m_sAppDataMgrInfo.sSystemValues.ucAuto_Wall_Color_Apply = eAC_APPLY_IDLE;
            palLANProcSendToLAN(edcAC_APPLY);

            #if 0
            if(ucAuto_Wall_Color_Execute == eAF_AC_EXECUTE ||    //execute from OSD
               ucAuto_Wall_Color_Execute == eAF_AC_EXECUTE_NO_CHECK)  // execute from CLI
            {
                if(eAF_STATUS_SUCCESS == NewVal)
                {
                    ucAuto_Wall_Color_Apply = ets_OFF;
                    palLANProcSendToLAN(edcAC_APPLY);
                    ucAuto_Wall_Color_Apply = 0xFF;
                    palLANProcSendToLAN(edcAC_APPLY);
                }
                else
                {
                    ucAuto_Wall_Color_Apply = 0xFF;
                    palLANProcSendToLAN(edcAC_APPLY);
                }
            }
            else if(ucAuto_Wall_Color_Execute == eAF_AC_EXECUTE_NO_UIMSG)
            {
                ucAuto_Wall_Color_Apply = 0xFF;
                palLANProcSendToLAN(edcAC_APPLY);
            }
            #endif

            UINT8 ucData = eAF_AC_NOT_EXECUTE;
            palDataMgr_Access_Auto_Wall_Color(eAccessMode, &ucData);

            ucData = eOSD_NOT_LOCKED;
            palDataMgr_Access_OSD_Lock(eAccessMode, &ucData);



            #if 0
            #ifdef CUSTOM_BARCO
            palDataMgr_UI_EventSend(edcUI_EVENT_AUTO_WALL_COLOR_MSG, TRUE, NULL);
            #endif
            #endif
        }

        #if 0
        #if defined(CUSTOM_CHRISTIE)
        if(eAF_STATUS_SUCCESS == NewVal)
        {
            ucAuto_Wall_Color_Apply = ets_OFF;
            palLANProcSendToLAN(edcAC_APPLY);
        }
////A35G2_Alan_0017    if(palGeo_ApLinkFlag_Get() == 0)
	    if(appGui_UC_Data_Cmd_Flag_Get() || appGui_UC_Data_OSD_Cmd_Flag_Get())//A35G2_Alan_0017
        {
            // Call Message Window
            //appGui_Auto_Wall_Color_Show(*((UINT8 *)pValue));
            palDataMgr_UI_EventSend(edcUI_EVENT_AUTO_WALL_COLOR_STATUS, TRUE, NULL);
        }
        else
        {
            palDataMgr_Access_AC_Apply(edaWRITE_RAM_ONLY_WITH_ACTION,&tValue);//A35G2_Alan_0017
            palLANProcSendToLAN(edcAC_APPLY);//A35G2_Alan_0017
        }
        #endif
        #endif
    }

    return eEXEC_CODE_PASS;
}

void palDataMgr_ADV_WarpingParameterInit(void)			//G100_Doulas_0027
{
	OSD_WARP stADVWarp;

	//init Advance Warp Parameter
	stADVWarp.eGridColor  		= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpGridColor;
	stADVWarp.eBkgColor 		= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpBackgroundColor;
	stADVWarp.eWarpPoint 		= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpGridPoints;
	stADVWarp.bWarpInnerOn 		= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpInner;
	stADVWarp.nWarpSharpness  	= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvWarpSharpness;
	stADVWarp.nOverlapGridNum 	= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlendingOverlapGridNumber;
	stADVWarp.nBlendGamma     	= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlendingGamma;
	stADVWarp.eCursorColor     	= GRID_COLOR__GREEN;  //G100_Simon_0058
	stADVWarp.nBlendWidthL     	= 0;
	stADVWarp.nBlendWidthR     	= 0;
	stADVWarp.nBlendWidthT     	= 0;
	stADVWarp.nBlendWidthB     	= 0;
	//init Black level		//A65_OPTOMA_Doulas_0020
	stADVWarp.stBlackLevel.ucArea  							= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelArea;
	stADVWarp.stBlackLevel.bEnable[BLACKLEVEL_AREA__TOP]  	= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__TOP];
	stADVWarp.stBlackLevel.bEnable[BLACKLEVEL_AREA__BOTTOM] = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelEnable[BLACKLEVEL_AREA__BOTTOM];
	stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__TOP+1][BLACKLEVEL_BT_RED]  	  = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__TOP];
	stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__BOTTOM+1][BLACKLEVEL_BT_RED]  = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelRed[BLACKLEVEL_AREA__BOTTOM];
	stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__TOP+1][BLACKLEVEL_BT_GREEN]   = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__TOP];
	stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__BOTTOM+1][BLACKLEVEL_BT_GREEN]= m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelGreen[BLACKLEVEL_AREA__BOTTOM];
	stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__TOP+1][BLACKLEVEL_BT_BLUE]    = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__TOP];
	stADVWarp.stBlackLevel.pnColor[BLACKLEVEL_AREA__BOTTOM+1][BLACKLEVEL_BT_BLUE] = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBlue[BLACKLEVEL_AREA__BOTTOM];
	stADVWarp.stBlackLevel.ucBoundary     										  = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucAdvBlackLevelBoundary;		//A35G2_Owen_0002 //A65_OPTOMA_Doulas_0239

	halADVWarpSettingSet(stADVWarp);

	//init Basic Warp Parameter
	halWarp_GeometryParameterSet(eWARP_EVENT_KEYSTONE_HV, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzKeystone);
	halWarp_GeometryParameterSet(eWARP_EVENT_PINBARREL_HV, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzPincushion);
	halWarp_GeometryParameterSet(eWARP_EVENT_4C_ALL, (UINT8*)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopLeftHorz);

#ifdef SCALER_C821_C789
    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpAutoFilter == 0)
    {
        halWarping_SetWarp_ManualFilterParameter(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterH,
                                        		 m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterV);
    }
    else
    {
        halWarping_SetWarp_AutoFilterParameter(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpAutoFilter,
                                      		   &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterH,
                                      		   &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterV);
    }
#endif

	halWarp_BlendingParameterSet(eBLENDING_EVENT_ALL, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingTopEnable);
	halWarp_BlendingParameterSet(eBLENDING_EVENT_GAMMA, &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingGamma);

	halBasicWarpSettingSet();
	halBasicBlendSettingSet();
}

