void palDataMgr_Model_ID_Set(void) //A70Gen2_Julie_0004
{
    eRESULT eResult = rcSUCCESS;
	UINT8 cData = 0xFF, cType = MODULE_NA_PLATFORM;
	UINT8 ucString[32] ={0};

    //get Model ID from MCU
	palSysCtrl_ModelID_Get(&cType); //A70Gen2_Julie_0027

	LOG_MSG(db_APP_SYSTEM,"Read MCU model ID %d\r\n", cType);

    if(Syscfg_Value_Get_Typeint(eModelID_DependSN) == TRUE)
    {
    	UINT8 ucSN[32] = {0};
	    palDataMgr_Data_Access(edcSERIAL_NUMBER, edaREAD, ucSN);

    	#ifdef PLATFORM_A70G2
    	{
        	if(ucSN[1] == 'H')
        	{
        		cData = MODULE_15K_PLATFORM;
        	}
        	else if(ucSN[1] == 'S')
        	{
        		cData = MODULE_19K_PLATFORM;
        	}
        	else if(ucSN[1] == 'V')
        	{
        		cData = MODULE_22K_PLATFORM;
        	}
        	else
        	{
        		cData = cType;
        	}
        }
        #elif (PLATFORM_A70LK)
        {
        	if(ucSN[1] == 'H')
        	{
        		cData = MODULE_4K13_PLATFORM;
        	}
        	else if(ucSN[1] == 'V')
        	{
        		cData = MODULE_4K22_PLATFORM;
        	}
        	else
        	{
        		cData = cType;
        	}
        }
        #else
        {
            cData = cType;
        }
        #endif
    }
    else
    {
        cData = cType;
    }

    #ifdef FIXED_MODEL_ID
    cData = MODULE_TYPE_ID1_PLATFORM;  //test only
    #endif

	palSystem_ModelIDSet(cData);

	palDataMgr_Data_Access(edcCUSTOMER_CODE, edaWRITE_THROUGH_WITH_ACTION, &cData); //set custom code
	palDataMgr_Data_Access(edcMODEL_NAME, edaWRITE_THROUGH_WITH_ACTION, &cData); //set model name

	palDataMgr_Data_Access(edcMODEL_NAME, edaREAD, ucString);
	LOG_MSG(db_APP_SYSTEM, "Platform = 0x%02X, Model name = %s\n", cData, ucString);
}

UINT8 palDataMgr_Check_User_Color_Mode(UINT8 ucColor)
{
	UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
	UINT8  ucUserMode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPreUserMode;

	if(ucColor != eCM_PICTURE_SETTINGS_USER)
		return ucColor;
	else
		return ucUserMode;
}

