void palDataMgr_MenuOffsetUpdateForEdgeBlending(void)
{
    UINT8 ucBlendingEnable = 0;

    if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucGeometryEnable)
    {
        if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingLeftEnable)
        {
            ucBlendingEnable |= BLEND_MENU_LEFT_ENABLE;
        }
        if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingRightEnable)
        {
            ucBlendingEnable |= BLEND_MENU_RIGHT_ENABLE;
        }
        if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingTopEnable)
        {
            ucBlendingEnable |= BLEND_MENU_TOP_ENABLE;
        }
        if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingBottomEnable)
        {
            ucBlendingEnable |= BLEND_MENU_BOTTOM_ENABLE;
        }
    }

    m_sAppDataMgrInfo.sSystemValues.ucUIBlendingEnable = ucBlendingEnable;

    if( palGeo_ApLinkFlag_Get() == FALSE ||
       (palGeo_ApLinkFlag_Get() == TRUE && (FALSE == palGeo_IsDraw_OSD(eWDT_BEFORE_WARP)))  //H2PF_Simon_0066
    )
    {
        palDataMgr_UI_EventSend(edcUI_EVENT_MENU_OFFSET_BLENDING, ucBlendingEnable, NULL);
        palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
    }
}

