// ==============================================================================
// DESCRIPTION  : Change the Input Key stting when the current value is different from the target value.
// Params       : eInput_Key => The target value.
// Returns:     : None
//
// Modification History
// --------------------
// 2021/09/03, Tim Chen create //A35G2_BRC_Casper_0060
// --------------------
// ==============================================================================
void palDataMgr_Auto_HDMI_Switch_Change_Input_Key( eSOURCE_KEY_ITEM eInput_Key)
{
    UINT8 ucRetry = 0;
    UINT8 ucInput_Key_Current = eSOURCE_KEY_CHANGE_SOURCE;
    eEXEC_CODE eResult = eEXEC_CODE_FAIL;

    do
    {
        eResult = palDataMgr_Data_Access(edcINPUT_KEY, edaREAD, &ucInput_Key_Current);

        LOG_MSG(db_APP_DATA_MGR, "palDataMgr_AHSW_Change_Input_Key(), Target: %d, Current: %d\r\n", eInput_Key, ucInput_Key_Current);

        if( eResult == eEXEC_CODE_PASS )
        {
            // save original value
            if(palDataMgr_Input_Key_Last_Value_RAM_Get() != ucInput_Key_Current )
            {
                palDataMgr_Input_Key_Last_Value_RAM_Set(ucInput_Key_Current);
                utilDataMgr_CommonSet_CM(eDF_INPUT_KEY_LAST_VALUE, &ucInput_Key_Current);
            }

            if( eInput_Key != ucInput_Key_Current )
            {
                // change setting
                ucInput_Key_Current = (UINT8) eInput_Key;
                // access directly, the input key control is set to prohibited
                palDataMgr_Access_InputKey(edaWRITE_THROUGH_WITH_ACTION,  &ucInput_Key_Current);    //G100_Tim_0078, mod, palDataMgr_Data_Access(edcINPUT_KEY, edaWRITE_THROUGH_WITH_ACTION, &ucInput_Key_Current);
            }
        }
    }while( (eResult != eEXEC_CODE_PASS ) && ( ucRetry < 3 ) );
}


// ==============================================================================
// DESCRIPTION  : Change the 3D Mode stting when the current value is different from the target value.
// Params       : e3D_On_Off => The target value
// Returns:     : None
//
// Modification History
// --------------------
// 2021/09/03, Tim Chen create //A35G2_BRC_Casper_0060
// --------------------
// ==============================================================================
void palDataMgr_Auto_HDMI_Switch_Change_3D_Mode( eTOGGLE_SETTING e3D_On_Off)
{
    UINT8 ucRetry = 0;
    UINT8 uc3D_En_Current = ets_ON;
    eEXEC_CODE eResult = eEXEC_CODE_FAIL;

    do
    {
        eResult = palDataMgr_Data_Access(edc3D_MODE, edaREAD, &uc3D_En_Current);

        LOG_MSG(db_APP_DATA_MGR, "palDataMgr_AHSW_Change_3D_Mode(), Target: %d, Current: %d\r\n", e3D_On_Off, uc3D_En_Current);

        if( eResult == eEXEC_CODE_PASS )
        {
            if( palDataMgr_3D_Mode_Last_Value_RAM_Get() != uc3D_En_Current )
            {
                // save original value
                palDataMgr_3D_Mode_Last_Value_RAM_Set(uc3D_En_Current);
                utilDataMgr_CommonSet_CM(eDF_3D_MODE_LAST_VALUE, &uc3D_En_Current);
            }

            if( e3D_On_Off != uc3D_En_Current )
            {
                // change setting
                uc3D_En_Current = e3D_On_Off;
                // access directly, the input key control is set to prohibited
                palDataMgr_Access_3DMode(edaWRITE_RAM_ONLY_WITH_ACTION, &uc3D_En_Current); //G100_Tim_0078, mod //palDataMgr_Data_Access(edc3D_MODE, edaWRITE_THROUGH_WITH_ACTION, &uc3D_En_Current);
            }
        }
    }while( (eResult != eEXEC_CODE_PASS ) && ( ucRetry < 3 ) );
}


// ==============================================================================
// DESCRIPTION  :  Change some sttings when the Auto HDMI Switch status is changed.
// Params       : ets_ON  => Change
// Params       : ets_OFF => Recovery
// Returns:     : None
//
// Modification History
// --------------------
// 2021/09/03, Tim Chen create //A35G2_BRC_Casper_0060
// --------------------
// ==============================================================================
void palDataMgr_Auto_HDMI_Switch_ReConfig(UINT8 ucStatus)
{
    switch( ucStatus )
    {
        case ets_OFF:                   // recovery
            // Auto Source Auto to AUTO, if the last value is AUTO
            palDataMgr_Auto_HDMI_Switch_Change_Input_Key( palDataMgr_Input_Key_Last_Value_RAM_Get() );

            // 3D Mode to On, if the last value is ON
            palDataMgr_Auto_HDMI_Switch_Change_3D_Mode( palDataMgr_3D_Mode_Last_Value_RAM_Get() );
            break;

        case ets_ON:                    // set
            // Auto Source off ( Change Source )
            palDataMgr_Auto_HDMI_Switch_Change_Input_Key( eSOURCE_KEY_CHANGE_SOURCE );

            // 3D off
            palDataMgr_Auto_HDMI_Switch_Change_3D_Mode( ets_OFF );

            // change main source and sub source
             palDataPath_Auto_HDMI_Switch_Source_Config( eCM_SOURCE_HDMI2 );

            // switch source in environmnent polling, not over here
            break;

        default:
            //illeage vaule, do nothing.
            break;
    }
}


