//G100_Tim_0058, add, start
// ==============================================================================
// DESCRIPTION  : Access and handle the Projection Native Timing function.
// Params       : None
// Returns      : PASS (Get/Set) or Fail (Set only).
//
// Modification History
// --------------------
// 2021/09/01, Tim Chen create //A35G2_BRC_Casper_0060
// --------------------
// ==============================================================================
eEXEC_CODE palDataMgr_Access_Proj_Native_Timing(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    eEXEC_CODE eRet = eEXEC_CODE_PASS;

    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucProj_Native_Timing;// HICC2_Bruce_0022
    }
    else  //Write Function
    {
        //Update RAM
        m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucProj_Native_Timing = *((UINT8*)pValue);// HICC2_Bruce_0022

        //Storage : EEPROM
        if(edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
            utilDataMgr_CommonSet_CM(eDF_PROJ_NATIVE_TIMING, (UINT8*)pValue);
        }

        //Execute Action function
        if(edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
            //G100_Tim_0059, mod, start
            UINT8 ucValue = ( ( m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDMI_EDID_1 & EDID_TYPE_MASK ) << HDMI1_EDID_TYPE2P0_SHIFT ) +
                            ( ( m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDMI_EDID_2 & EDID_TYPE_MASK ) << HDMI2_EDID_TYPE2P0_SHIFT ) +
                            ( ( m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sImageSetting.ucHDBaseT_EDID & EDID_TYPE_MASK ) << HDBASET_EDID_TYPE2P0_SHIFT ); //HICC2_Doulas_0068

            palFrontEndMgr_EDID_SN_Set(eCM_SOURCE_RESERVED, ucValue, m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sCommonSetting.ucProj_Native_Timing, m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucSerialNumber);
            //G100_Tim_0059, mod, end
        }
    }
    return eRet;
}
