// ==============================================================================
// DESCRIPTION: Trigger the ACU calibration to execute or set ending.
// Params: None
// Returns: None
//
// Modification History
// --------------------
// 2021/06/07, Tim Chen create
// --------------------
// ==============================================================================
eEXEC_CODE palDataMgr_Access_ACU_Execute(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    UINT8 CurVal = palDataMgr_ACU_Execute_Get();
    UINT8 NewVal = *((UINT8*)pValue);

    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8*)pValue) = CurVal;
    }
    else  //Write Function
    {
        // start ACU Calibration
        if( ( NewVal >= eACU_EXECUTING && NewVal <= eACU_EXECUTING_NO_UIMSG) &&
            ( palDataMgr_ACU_Status_Get() != eACU_STATUS_PROCESSING ) )
        {
            UINT8 ucData = eACU_STATUS_PROCESSING;

		    if(palDataMgr_IsOsdOpen() == TRUE)
            {
                palDataMgr_UI_EventSend(edcUI_EVENT_OSD_EXIT, TRUE, NULL);
            }

            palDataMgr_ACU_Reset_Set( eACU_RESET_NOT_YET );
            palDataMgr_ACU_Execute_Set( NewVal );
            palDataMgr_Access_ACU_Status(eAccessMode, &ucData);
        }
        // end ACU Calibration
        else if( ( NewVal == eACU_NOT_EXECUTED ) &&
                ( palDataMgr_ACU_Status_Get() != eACU_STATUS_PROCESSING ) )
        {
            palDataMgr_ACU_Execute_Set( NewVal );
        }
        // illegal settings
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }

    return eEXEC_CODE_PASS;
}

eEXEC_CODE palDataMgr_Access_ACU_Apply(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        *((UINT8 *)pValue) = m_sAppDataMgrInfo.sSystemValues.ucACU_Apply;
    }
    else  //Write Function
    {
        m_sAppDataMgrInfo.sSystemValues.ucACU_Apply = *((UINT8 *)pValue);
    }
    return eEXEC_CODE_PASS;
}

