//
// ==============================================================================
// DESCRIPTION:  To reset to default, all of the the ACU settings and data
// Params: None
// Returns: None
//
// Modification History
// --------------------
// 2021/06/07, Tim Chen create
// --------------------
// ==============================================================================
eEXEC_CODE palDataMgr_Access_ACU_Reset(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
	UINT8 tValue = eAC_APPLY_IDLE;

    if(edaREAD == eAccessMode)  //Read Function
    {
        *(UINT8*) pValue = palDataMgr_ACU_Reset_Get();
    }
    else  //Write Function
    {
        if( ( *((UINT8*) pValue ) == ACU_RESET_WRITE_CMD ) &&
            ( palDataMgr_ACU_Execute_Get() != eACU_EXECUTING ) &&               // not allow to reset during processing
            ( palDataMgr_ACU_Status_Get() != eACU_STATUS_PROCESSING )           // not allow to reset during processing
        )
        {
#ifdef CUSTOM_CHRISTIE
        	UINT8 ucACU_Data_Enable = eACU_SET_DATA_DISABLE; //A35G2_Alan_0007
#endif
            UINT8 ucACU_File = eACU_FILE_INVALID;
            UINT8 ucACU_Display_Mode = DISPLAY_MODE_MAX;
            UINT8 ucACU_Target_Select = ACU_TARGET_DEFAULT; //G100_Tim_0048, add

            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_File_Valid = eACU_FILE_INVALID;
            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_Display_Mode= DISPLAY_MODE_MAX;
            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_Target_Select = ACU_TARGET_DEFAULT; //G100_Tim_0048, add
#ifdef CUSTOM_CHRISTIE
            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_Data_Enable = eACU_SET_DATA_DISABLE;//A35G2_Alan_0007
            utilDataMgr_CommonSet_CM( eDF_ACU_DATA_ENABLE, &ucACU_Data_Enable);//A35G2_Alan_0007
#endif
            utilDataMgr_CommonSet_CM( eDF_ACU_FILE_VALID, &ucACU_File);
            utilDataMgr_CommonSet_CM( eDF_ACU_DISPLAY_MODE, &ucACU_Display_Mode);
            utilDataMgr_CommonSet_CM( eDF_ACU_TARGET_SELECT, &ucACU_Target_Select);    //G100_Tim_0048, add

            palDataMgr_ACU_Execute_Set( eACU_NOT_EXECUTED );
            palDataMgr_ACU_Status_Set( eACU_STATUS_NONE );
            palDataMgr_ACU_Target_Select_Set( ACU_TARGET_DEFAULT );
            palDataMgr_ACU_Reset_Set( eACU_RESET_DONE );
			palDataMgr_CU_Data_Enable_Set(FALSE);			//G100_Tim_0024, add
            palLANProcSendToLAN(edcACU_EXECUTE);  //A65_OPTOMA_CL_0001  //A35G2_CDS_CL_0001
            palLANProcSendToLAN(edcACU_STATUS);
            palLANProcSendToLAN(edcACU_TARGET_SEL);
            palLANProcSendToLAN(edcACU_SAVE);
            palLANProcSendToLAN(edcCU_DATA_STATUS);
#ifdef CUSTOM_CHRISTIE //A35G2_Alan_0002
            tValue = eAC_APPLY_IDLE;
			palDataMgr_Access_AC_Apply(edaWRITE_RAM_ONLY_WITH_ACTION,&tValue);//A35G2_Alan_0017
            tValue = eACU_APPLY_IDLE;
			palDataMgr_Access_ACU_Apply(edaWRITE_RAM_ONLY_WITH_ACTION,&tValue);//A35G2_Alan_0017
			palLANProcSendToLAN(edcAC_APPLY);//A35G2_Alan_0017
			palLANProcSendToLAN(edcACU_APPLY);//A35G2_Alan_0017

			palLANProcSendToLAN(edcACU_RESET);
			MS_SLEEP(500);
        	palDataMgr_ACU_Reset_Set( eACU_RESET_NOT_YET );
			palLANProcSendToLAN(edcACU_RESET);				//A35G2_Alan_0002
			MS_SLEEP(100);
			palDataMgr_CU_Data_Enable_Set(eACU_SET_DATA_DISABLE);
            palLANProcSendToLAN(edcCU_DATA_ENABLE);
#endif

        }
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }
    return eEXEC_CODE_PASS;
}

#ifdef ENABLE_ACU_CHECK_DISPLAY_MODE
// ==============================================================================
// Function:
// DESCRIPTION: To verify the ACU calibration mode is the same as the current display mode or not
// Params: None
// Returns: eEXEC_CODE_PASS : The current display modes is same as the display mode during ACU calibration.
// Returns: None
//
// Modification History
// --------------------
// 2021/06/25, Tim Chen create
// --------------------
// ==============================================================================
eEXEC_CODE palDataMgr_ACU_Display_Mode_Check( void )
{
    UINT8 ucACU_Display_Mode = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_Display_Mode;
    UINT8 ucSrc_Display_Mode = DISPLAY_MODE_MAX;
    eEXEC_CODE eExecCode = palDataMgr_Access_PictureSettings( edaREAD, (void*) &ucSrc_Display_Mode );
    eEXEC_CODE eRet = eEXEC_CODE_PASS;

    if( ( ucACU_Display_Mode == DISPLAY_MODE_MAX ) ||       // invalid ACU data
        ( eExecCode == eEXEC_CODE_FAIL ) ||                 // get display mode fail
        ( ucACU_Display_Mode != ucSrc_Display_Mode ) )      // different display modes
    {
        eRet = eEXEC_CODE_FAIL;;
    }

    return (eRet);
}
#endif //ENABLE_ACU_CHECK_DISPLAY_MODE


// ==============================================================================
// DESCRIPTION: Record the he ACU file is valid or not
// Params: None
// Returns: None
//
// Modification History
// --------------------
// 2021/06/07, Tim Chen create
// --------------------
// ==============================================================================
eEXEC_CODE palDataMgr_Access_ACU_Save(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if(edaREAD == eAccessMode)  //Read Function
    {
        *( (UINT8*) pValue ) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_File_Valid;
    }
    else  //Write Function
    {
        if( *( (UINT8*) pValue ) < eACU_FILE_MAX )
        {
            UINT8  ucInputSource = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceSetting.ucInputSourceMain;
            UINT8  ucACU_Display_Mode = m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sSourceDependSetting[ucInputSource].ucPresetMode;

            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_File_Valid = *( (UINT8*) pValue );
            m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_Display_Mode = ucACU_Display_Mode;

            //Storage : EEPROM
            if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
            {
                utilDataMgr_CommonSet_CM( eDF_ACU_FILE_VALID, (UINT8*) pValue );
                utilDataMgr_CommonSet_CM( eDF_ACU_DISPLAY_MODE, &ucACU_Display_Mode);
            }

            //Execute Action function
            if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
            {
            }
            palLANProcSendToLAN(edcCU_DATA_STATUS);  //A65_OPTOMA_CL_0001  //A35G2_CDS_CL_0001
        }
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }
    return eEXEC_CODE_PASS;
}


