//A65_OPTOMA_CL_0001  //A35G2_CDS_CL_0001
eEXEC_CODE palDataMgr_Access_CU_Data_Enable(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
#ifdef CUSTOM_CHRISTIE	//A35G2_Alan_0007 --->
    if(edaREAD == eAccessMode)  //Read Function
    {
		*((UINT8*)pValue) = m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_Data_Enable;//A35G2_Alan_0007
    }
    else  //Write Function
    {
		//Update RAM
		m_sAppDataMgrInfo.sEepSettings.sSystemDefault.ucACU_Data_Enable = *((UINT8*)pValue);
		//Storage : EEPROM
        if (edaWRITE_THROUGH_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_NO_ACTION == eAccessMode)
        {
			utilDataMgr_CommonSet_CM(eDF_ACU_DATA_ENABLE, (UINT8*)pValue);
        }
        //Execute Action function
        if (edaWRITE_RAM_ONLY_WITH_ACTION == eAccessMode || edaWRITE_THROUGH_WITH_ACTION == eAccessMode)
        {
			palDataMgr_CU_Data_Enable_Set(*(UINT8*) pValue);
        }
    }
#else
    if(edaREAD == eAccessMode)  //Read Function
    {
        *(UINT8*) pValue = palDataMgr_CU_Data_Enable_Get();
    }
    else  //Write Function
    {
        palDataMgr_CU_Data_Enable_Set(*(UINT8*) pValue);
    }
#endif	//A35G2_Alan_0007 <---

    palLANProcSendToLAN(edcACU_EXECUTE);
    palLANProcSendToLAN(edcACU_TARGET_SEL);
    palLANProcSendToLAN(edcACU_RESET);

    return eEXEC_CODE_PASS;
}

