// ==============================================================================
// DESCRIPTION:  return the camera status, working means the one of the AF, AWC, ACU is executing.
// Params: None
// Returns: eCAMERA_STATUS : camera is woriking or not.
//
// Modification History
// --------------------
// 2021/08/05, Tim Chen create
// --------------------
// ==============================================================================
eCAMERA_STATUS palDataMgr_Get_Camera_Working_Status(void)
{
    #if (ENABLE_COLOR_UNIFORMITY == TRUE)
        UINT8 ucOSDLock = eOSD_NOT_LOCKED;
        UINT8 ucAF_Status = eAF_STATUS_SUCCESS;
        UINT8 ucAWC_Status = eAF_STATUS_SUCCESS;
        UINT8 ucACU_Status = eACU_STATUS_SUCCESS;
        eCAMERA_STATUS eRet = eCAMERA_STATUS_IDLE;

        //palDataMgr_Data_Access(edcOSD_LOCK, edaREAD, &ucOSDLock);
        ucOSDLock = palDataMgr_Camera_OSD_Lock_Get(); //A65_OPTOMA_Julie_0066
        palDataMgr_Data_Access(edcAUTO_FOCUS_STATUS, edaREAD, &ucAF_Status);
        palDataMgr_Data_Access(edcAUTO_WALL_COLOR_STATUS, edaREAD, &ucAWC_Status);
        palDataMgr_Data_Access(edcACU_STATUS, edaREAD, &ucACU_Status);

        //LOG_MSG(db_HAL_WARPING, "CWK statud <%d %d %d>\n", ucOSDLock, ucAF_Status, ucACU_Status);

        if(( ucOSDLock == eOSD_LOCKED )                         // Not allowed to set command
            && (( ucAF_Status == eAF_STATUS_PROCESSING )        // Auto Focus is executing
                || ( ucAWC_Status == eAWC_STATUS_PROCESSING )   // Auto Wall Color is executing
                || ( ucACU_Status == eACU_STATUS_PROCESSING ) ) // Auto Color Uniformity is executing
        )
        {
            eRet = eCAMERA_STATUS_WORKING;
        }
        return (eRet);
    #else
        return eCAMERA_STATUS_IDLE;
    #endif

}
