    UINT32 ucSource = 0;
    UINT32 ucGeometryEnable = 0;
    UINT8 uc3DMode = 0;
    UINT16 uiItemCondition = 0xFFFF;

    utilDatabase_WriteInformationData(eDI_3D_MODE_CONDITION, DATA_TYPE_UI_DIGIT_16, 0, &uiItemCondition); //A70LK_Jacky_0032

    palDataMgr_Data_Access(edcMAIN_INPUT, edaREAD, &ucSource);
