void palDataMgr_Access_3D_Frame_Sequential_OSDFrmae_Upated(void)
{
    UINT8 uc3D_Enable = 0;
    UINT8 uc3D_Sync_In = eCM_3D_SYNC_TYPE_AUTO;

    palDataMgr_Access_3DEnable(edaREAD, &uc3D_Enable);
    palDataMgr_Access_3DSyncIn(edaREAD, &uc3D_Sync_In);
    if((uc3D_Enable == eCM_3D_FORMAT_FRAME_SEQUENTIAL) && (uc3D_Sync_In == eCM_3D_SYNC_TYPE_EXTERNAL))
    {
        BOOL b3DSyncAvaliable = FALSE;
        BOOL b3DSyncLost = FALSE;
        UINT8 ucdatapath_state = 0;
        eRESULT eResult = rcINVALID;

        eResult = halFormatter_3D_SYNC_InputMonitorGet(&b3DSyncAvaliable,&b3DSyncLost,&ucdatapath_state);
        if((eResult == rcSUCCESS) &&
           (b3DSyncLost == TRUE) &&
           (b3DSyncAvaliable == FALSE))
        {
            UINT8 uc3D_Invert = 0;
            palDataMgr_Access_3DInvert(edaREAD, &uc3D_Invert);
            halFormatter_3D_RefPolaritySet((BOOL)!uc3D_Invert,FALSE,FALSE,FALSE);
            MS_SLEEP(45);
            halFormatter_3D_RefPolaritySet((BOOL)uc3D_Invert,FALSE,FALSE,FALSE);
        }
    }
}


int utilDataMgr_ReadFile_USBtest_periphery(BYTE *cimx, BYTE *cext, BYTE *cddp, BYTE *cksz) //A70Gen2_Julie_0048
{
	FILE *pFile = NULL;
    char cTemp[64] = {'\0'};
    char cStrTemp[64] = {'\0'}, cType[64] = {'\0'}, cString[64] = {'\0'};
	BYTE cData;

	sprintf(cTemp, "/tmp/test_periphery.conf");

	if(access(cTemp,0)==-1)
	{
		return 1;
	}

	pFile = fopen(cTemp, "r");

	if(pFile == NULL)
	{
		return 1;
	}

	while (!feof(pFile))
	{
		if(fgets(cStrTemp,63,pFile) == NULL)
		{
			break;
		}

		if(feof(pFile))
		{
			break;//return 1;
		}

		sscanf(cStrTemp, "%63[^=]=%63[^\n]", cType, cString);

		if((strncmp(cType, "usb_imx", 7) == 0))
		{
			cData = atoi(cString);
			*cimx = cData;
		}
		else if((strncmp(cType, "usb_ext", 7) == 0))
		{
			cData = atoi(cString);
			*cext = cData;
		}
		else if((strncmp(cType, "usb_ddp", 7) == 0))
		{
			cData = atoi(cString);
			*cddp = cData;
		}
		else if((strncmp(cType, "net_ksz", 7) == 0))
		{
			cData = atoi(cString);
			*cksz = cData;
		}
	}

	fclose(pFile);

	return 0;
}


eEXEC_CODE palDataMgr_Access_SystemPower(eDATA_ACCESS_MODE eAccessMode, void *pValue)    //B35G2_Ashton_0008
{
    if(eAccessMode == edaREAD)
    {
        if((palSystem_PowerStateGet() == ePOWER_STATE_STANDBY) || palEnvironment_Fake_Power_Down_Get())
        {
            *((UINT8 *)pValue) = ePOWER_CONTROL_POWEROFF;
        }
        else if(palSystem_PowerStateGet() == ePOWER_STATE_UPGRADE)
        {
            *((UINT8 *)pValue) = ePOWER_CONTROL_UPGRADE;
        }
        else
        {
            *((UINT8 *)pValue) = ePOWER_CONTROL_POWERON;
        }
    }
    else
    {
        if(*((UINT8 *)pValue) == ePOWER_CONTROL_POWERON)
        {
            //LOG_MSG(db_ALWAYS, "(func:%s, line:%d)\r\n", __FUNCTION__, __LINE__);
            //G100_Clare_0055, add, >>>
            if(palEnvironment_Fake_Power_Down_Get())
            {
                palEnvironment_Fake_Power_Down_Set(FALSE);
            }
            else
            //G100_Clare_0055, add, <<<
            {
                palSystem_PowerKey();
            }
        }
        else if((*((UINT8 *)pValue) == ePOWER_CONTROL_POWEROFF) && palSystem_PowerStateGet() != ePOWER_STATE_STANDBY)//G100_Steven_0120 //A35G2_BRC_Casper_0051
        {
            //G100_Clare_0055, add, >>>
            UINT8 ucData = 0 ;
            palDataMgr_Data_Access(edcFAST_POWER_ON, edaREAD, &ucData);
            if (ucData)
            {
                palEnvironment_Fake_Power_Down_Set(TRUE);
            }
            else
            //G100_Clare_0055, add, <<<
            {
                palSystem_PowerDown();
            }
        }
        else if(*((UINT8 *)pValue) == ePOWER_CONTROL_UPGRADE)
        {
            palSystem_FwUpgradeMode(eSYSTEM_UPGRADE_MODE_SET);
        }
        else
        {
            return eEXEC_CODE_FAIL;
        }
    }

    return eEXEC_CODE_PASS;
}



