eEXEC_CODE palDataMgr_UI_EventSend_Debug(eDATA_CODE DataCode, UINT32 IntData, void *VoidData, const char *func, UINT32 LineNum)
{
    LOG_MSG(db_APP_UI_EVENT, "From (%s@%d) send UI Event %d\n", func, LineNum , DataCode);

    eEXEC_CODE eExecRet = eEXEC_CODE_PASS;

    #ifdef H30_NO_WAIT_LENS_CAL
    if(DataCode == edcUI_EVENT_MENUOPEN_LENS_CAL_MSG)
    {
        return eEXEC_CODE_PASS;
    }
    #endif

    if(eFUNC_CONTROL_ENABLE != m_sDataControl_LutTable[m_sDataMgr_Access_LutTable[DataCode].FuncPoint.uiDataControl].Item_Access_Enable())
    {
        return eEXEC_CODE_FAIL;
    }

    if(m_sDataMgr_Access_LutTable[DataCode].FuncPoint.DataMgr_Access != NULL)
    {
        if(m_sDataMgr_Access_LutTable[DataCode].ucDataType >= DATA_TYPE_UI_DIGIT_8 ||
           m_sDataMgr_Access_LutTable[DataCode].ucDataType <= DATA_TYPE_UI_DIGIT_64)
        {
            eExecRet = m_sDataMgr_Access_LutTable[DataCode].FuncPoint.DataMgr_Access(edaWRITE_RAM_ONLY_WITH_ACTION, &IntData);
        }
        else if(m_sDataMgr_Access_LutTable[DataCode].ucDataType == DATA_TYPE_STRUCT)
        {
            if(VoidData == NULL)
            {
                LOG_MSG(db_ALWAYS, "Error: UI Event Structure Data is NULL (datacode %d)\n", DataCode);
                return eEXEC_CODE_FAIL;
            }

            eExecRet = m_sDataMgr_Access_LutTable[DataCode].FuncPoint.DataMgr_Access(edaWRITE_RAM_ONLY_WITH_ACTION, VoidData);
        }
        else
        {
            LOG_MSG(db_ALWAYS, "Error: undefined UI Event Send datatype %d (datacode %d)\n", m_sDataMgr_Access_LutTable[DataCode].ucDataType, DataCode);
            return eEXEC_CODE_FAIL;
        }
    }
    else
    {
        LOG_MSG(db_ALWAYS, "Error:UI Event Send datacode %d function is NULL\n", DataCode);
        return eEXEC_CODE_FAIL;
    }

    if(eExecRet == eEXEC_CODE_PASS)
    {
        //eExecRet = utilIpc_NotifyDatacodeChanged(DataCode);

        palLANProcSendToLAN(DataCode);
    }

    return eExecRet;
}


