eEXEC_CODE palDataMgr_Access_LIGHT_SENSOR_INFO_1(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    INT32 LightSensorInfoType = Syscfg_Value_Get_Typeint(eDC_LightSensorInfoType);

    switch(LightSensorInfoType)
    {
        case eDC_LIGHT_SENSOR_INFO_TYPE_0:
            palDataMgr_Access_ABC_R(eAccessMode, pValue); //HICC2_Doulas_0052 Modify
            break;

        case eDC_LIGHT_SENSOR_INFO_TYPE_1:
            palDataMgr_Access_ABC_WithRLD_R(eAccessMode, pValue);
            break;

        default:
            LOG_MSG(db_ALWAYS, "(func:%s, line:%d) unknown LightSensorInfoType %d\r\n", __FUNCTION__, __LINE__, LightSensorInfoType);
            return eEXEC_CODE_FAIL;
    }

    return eEXEC_CODE_PASS;
}

