void palDataMgr_PIN_Protect_Status(void)
{
    UINT8 ucValue = 0;
    UINT8 ucCurrentPIN[4] = {0}; //G100_Coda_0072

    //G100_Wilsonj_0037 Start
	//PIN_PROTECT_Status = ePASSWORD_PROTECT_UNLOCK;

    //initial pin data	//G100_Coda_0095
	ucValue = 0;	//G100_Coda_0072
	palDataMgr_Data_Access((eDATA_CODE)edcPIN_CODE_EDIT_NUM, edaWRITE_THROUGH_WITH_ACTION, (void*)&ucValue);
    //ucPIN_TRY = ePIN_Current;
	palDataMgr_Data_Access((eDATA_CODE)edcPIN_INFO1, edaWRITE_THROUGH_WITH_ACTION, (void*)&ucValue);
	palDataMgr_Data_Access((eDATA_CODE)edcPIN_INFO2, edaWRITE_THROUGH_WITH_ACTION, (void*)&ucValue);

    //initial system protect status	//G100_Coda_0095
    //palDataMgr_Data_Access(edcSYSTEM_PROTECT_STATUS, edaWRITE_THROUGH_WITH_ACTION, &PIN_PROTECT_Status);

    ucCurrentPIN[0] = ' ';
    ucCurrentPIN[1] = ' ';
    ucCurrentPIN[2] = ' ';
    ucCurrentPIN[3] = ' ';
    palDataMgr_Data_Access((eDATA_CODE)edcENTER_CURRENT_PIN, edaWRITE_THROUGH_WITH_ACTION, (void*)ucCurrentPIN);

    palDataMgr_Data_Access(edcPIN_PROTECT, edaREAD, &ucValue);
    LOG_MSG(db_APP_GUI, "(func:%s, line:%d) edcPIN_PROTECT 1, ucValue = %d\r\n", __FUNCTION__, __LINE__, ucValue);

    if(ucValue)
    {
        UINT32  ucPin_TotalRemainderTime = 0;	//G100_Coda_00100
        UINT8   bcPIN_power_on = FALSE;//H30K_David_0038

        halMCUCtrl_PIN_Power_On_Get(&bcPIN_power_on);//H30K_David_0038

        palDataMgr_Data_Access(edcSECURITY_TIMER, edaREAD, &ucPin_TotalRemainderTime);

		if(bcPIN_power_on == TRUE)//H30K_David_0038
		{
	        ucValue = ePASSWORD_PROTECT_UNLOCK;
	        palDataMgr_Data_Access(edcSYSTEM_PROTECT_STATUS, edaWRITE_RAM_ONLY_NO_ACTION, &ucValue);
			palDataMgr_UI_EVENT_Pin_Protect_Clear();
    	}
        else if(ucPin_TotalRemainderTime == 0)	//ZU860_Clare_0081
        {
            LOG_MSG(db_APP_GUI, "(func:%s, line:%d) edcPIN_PROTECT 2\r\n", __FUNCTION__, __LINE__);
            //PIN_PROTECT_Status = ePASSWORD_PROTECT_LOCKED;

            //palDataMgr_Data_Access(edcSYSTEM_PROTECT_STATUS, edaWRITE_THROUGH_WITH_ACTION, &PIN_PROTECT_Status);

            //palDataMgr_UI_EventSend(edcUI_EVENT_PIN_PROTECT_ENABLE, TRUE, NULL);
            ucValue = ePASSWORD_PROTECT_LOCKED;
            palDataMgr_Data_Access(edcSYSTEM_PROTECT_STATUS, edaWRITE_RAM_ONLY_NO_ACTION, &ucValue);
        }
        else  //H30K_Doulas_0021
        {
            //LOG_MSG(db_ALWAYS, "edcSECURITY_TIMER %x\r\n", ucPin_TotalRemainderTime);
            palDataMgr_Data_Access(edcSECURITY_TIMER, edaWRITE_RAM_ONLY_WITH_ACTION, &ucPin_TotalRemainderTime);
            palLANProcSendToLAN(edcSECURITY_TIMER_MONTH);
            palLANProcSendToLAN(edcSECURITY_TIMER_DAY);
            palLANProcSendToLAN(edcSECURITY_TIMER_HOUR);
            ucValue = ePASSWORD_PROTECT_UNLOCK;
            palDataMgr_Data_Access(edcSYSTEM_PROTECT_STATUS, edaWRITE_RAM_ONLY_NO_ACTION, &ucValue);
        }
	}
    else
    {
        //palDataMgr_UI_EventSend(edcUI_EVENT_PIN_PROTECT_ENABLE, FALSE, NULL);
        ucValue = ePASSWORD_PROTECT_UNLOCK;
        palDataMgr_Data_Access(edcSYSTEM_PROTECT_STATUS, edaWRITE_RAM_ONLY_NO_ACTION, &ucValue);
    }
    //G100_Wilsonj_0037 End
}

