eEXEC_CODE palDataMgr_Access_DataCodeResetToDefault(eDATA_ACCESS_MODE eAccessMode, void *pValue) //HICC2_Doulas_0054
{
    if(edaREAD == eAccessMode)
    {
        *((UINT16*)pValue) = 0;
    }
    else
    {
        eDATA_CODE eDataCode = *((UINT16*)pValue);
        tDATA_CODE ulValue = 0;
        INT8 uiResult = eEXEC_CODE_FAIL;
        UINT8 DataType = DATA_TYPE_NA;

        DataType = palDataMgr_Data_Type(eDataCode);
        if((DataType != DATA_TYPE_UI_DIGIT_8) && (DataType != DATA_TYPE_UI_DIGIT_16) &&
           (DataType != DATA_TYPE_UI_DIGIT_32) && (DataType != DATA_TYPE_I_DIGIT_8) &&
           (DataType != DATA_TYPE_I_DIGIT_16) && (DataType != DATA_TYPE_I_DIGIT_32))
        {
            return eEXEC_CODE_FAIL;
        }

        uiResult = palDataMgr_DataCode_Default_Get(eDataCode,&ulValue);
        //LOG_MSG(db_ALWAYS, "DataCodeResetToDefault = %d,%d,%d\r\n",eDataCode,uiResult,ulValue);
        if(uiResult != eEXEC_CODE_PASS)
        {
            return eEXEC_CODE_FAIL;
        }
        else
        {
            uiResult = m_sDataMgr_Access_LutTable[eDataCode].FuncPoint.DataMgr_Access(eAccessMode, (void*)&ulValue);
            if(palDataMgr_NetworkCommandSkip(eDataCode) == FALSE && uiResult == eEXEC_CODE_PASS)
            {
                palLANProcSendToLAN((UINT16)eDataCode);
                palDataMgr_UI_EventSend(edcUI_EVENT_UPDATE_OSD, TRUE, NULL);
            }
        }
    }

    return eEXEC_CODE_PASS;
}

