void palDataMgr_CheckGroupSupported() // HICC2_Ashton_0003
{
    if(access(PATH_PROJECTOR_GROUP_DEFAULT, F_OK) == 0)  //Support group projector
        m_sAppDataMgrInfo.sSystemValues.cGroupingEnable = TRUE;
    else
        m_sAppDataMgrInfo.sSystemValues.cGroupingEnable = FALSE;
}

BOOL palDataMgr_IsGroupSupported() // HICC2_Ashton_0003
{
    return m_sAppDataMgrInfo.sSystemValues.cGroupingEnable;
}

UINT8 palDataMgr_GroupFunctionProcessed(UINT16 uiDataCode)
{
    UINT16 uiStatus;
    UINT8 ucGroupMode;
    eEXEC_CODE eResult;
    UINT8 ucResult = FALSE;

    if(palDataMgr_IsGroupSupported())
    {
        switch(uiDataCode)
        {
            case edcAUTO_FOCUS:
                {
                    palDataMgr_Data_Access(edcPROJECTOR_GROUP_STATUS, edaREAD, &ucGroupMode);

                    if(ucGroupMode != eCM_GROUP_STATUS_MASTER)
                        return ucResult;

                    eResult = palDataMgr_Data_Access(edcGROUP_EVENT_AUTO_FOCUS, edaREAD, &uiStatus);
                    if((eResult == eEXEC_CODE_PASS) && (uiStatus))
                    {
                        ucResult = TRUE;
                    }
                }
                break;
            case edcAUTO_COLOR_MATCH:
                {
                    palDataMgr_Data_Access(edcPROJECTOR_GROUP_STATUS, edaREAD, &ucGroupMode);

                    if(ucGroupMode != eCM_GROUP_STATUS_MASTER)
                        return ucResult;

                    eResult = palDataMgr_Data_Access(edcGROUP_EVENT_MUTLI_COLOR_MATCH, edaREAD, &uiStatus);
                    if((eResult == eEXEC_CODE_PASS) && (uiStatus))
                    {
                        ucResult = TRUE;
                    }
                }
                break;
        }
    }

    return ucResult;
}

