eEXEC_CODE palDataMgr_NotifyGroupingEvent(sDATABASE_ITEM_DATA_FORMAT sData) // HICC2_Ashton_0040 // HICC2_Ashton_0041 // HICC2_Ashton_0003
{
    UINT16 uiDataCode = sData.uiItemIndex;
    UINT16 uiStatus;
    UINT8 ucGroupMode;
    eEXEC_CODE eResult;
    eEXEC_CODE eReturn = eEXEC_CODE_FAIL;


    if(palDataMgr_IsGroupSupported())
    {
        palDataMgr_Data_Access(edcPROJECTOR_GROUP_STATUS, edaREAD, &ucGroupMode);

        if(ucGroupMode != eCM_GROUP_STATUS_MASTER)
        {
            eReturn = eEXEC_CODE_FAIL;
            return eReturn;
        }

        switch(uiDataCode)
        {
            case edcIMAGE_FREEZE:
                {
                    eResult = palDataMgr_Data_Access(edcGROUP_EVENT_FREEZE, edaREAD, &uiStatus);
                    if((eResult == eEXEC_CODE_PASS) && (uiStatus))
                    {
                        eReturn = eEXEC_CODE_PASS;
                        palDataMgr_Data_Access(edcGROUP_CMD_FREEZE, edaWRITE_RAM_ONLY_NO_ACTION, &sData.uValue.lValue);
                    }
                    MS_SLEEP(34);
                }
                break;
            case edcPICTURE_MUTE:
                {
                    eResult = palDataMgr_Data_Access(edcGROUP_EVENT_SHUTTER, edaREAD, &uiStatus);
                    if((eResult == eEXEC_CODE_PASS) && (uiStatus))
                    {
                        eReturn = eEXEC_CODE_PASS;
                        palDataMgr_Data_Access(edcGROUP_CMD_PICTURE_MUTE, edaWRITE_RAM_ONLY_NO_ACTION, &sData.uValue.lValue);
                    }
                    MS_SLEEP(34);
                }
                break;
            case edcDYNAMIC_BLACK:
                {
                    eResult = palDataMgr_Data_Access(edcGROUP_EVENT_DYNAMIC_BLACK, edaREAD, &uiStatus);
                    if((eResult == eEXEC_CODE_PASS) && (uiStatus))
                    {
                        eReturn = eEXEC_CODE_PASS;
                        palDataMgr_Data_Access(edcGROUP_CMD_DYNAMIC_BLACK, edaWRITE_RAM_ONLY_NO_ACTION, &sData.uValue.lValue);
                    }
                    MS_SLEEP(34);
                }
                break;
            case edcAUTO_FOCUS:
                {
                    eResult = palDataMgr_Data_Access(edcGROUP_EVENT_AUTO_FOCUS, edaREAD, &uiStatus);
                    if((eResult == eEXEC_CODE_PASS) && (uiStatus))
                    {
                        eReturn = eEXEC_CODE_PASS;
                        palDataMgr_Data_Access(edcGROUP_CMD_CAMERA_AUTO_FOCUS, edaWRITE_RAM_ONLY_NO_ACTION, &sData.uValue.lValue);
                    }
                }
                break;
            case edcAUTO_COLOR_MATCH:
                {
                    eResult = palDataMgr_Data_Access(edcGROUP_EVENT_MUTLI_COLOR_MATCH, edaREAD, &uiStatus);
                    if((eResult == eEXEC_CODE_PASS) && (uiStatus))
                    {
                        eReturn = eEXEC_CODE_PASS;
                        palDataMgr_Data_Access(edcGROUP_CMD_CAMERA_AUTO_COLOR, edaWRITE_RAM_ONLY_NO_ACTION, &sData.uValue.lValue);
                    }
                }
                break;
        }
    }


    return eReturn;
}

