UINT8 palDataMgr_AcuSelect_HDR_Gamma_Check(void) //HICC2_Julie_0052
{
    UINT8 ucGamma, ucStatus = FALSE;
    palFormatterMgr_IMG_GammaLutGet(&ucGamma);

    if((palImgMgr_PictureSettings_Get_NotReturnUser(0) == eCM_PICTURE_SETTINGS_HDR) ||
      ((palDataMgr_Control_SourceDepend() != eFUNC_CONTROL_ENABLE) && (ucGamma >= DDP442X_GAMMA_HDR_BRIGHT && ucGamma <= DDP442X_GAMMA_HDR_STANDARD))
      )
    {
        ucStatus = TRUE;
    }

    return ucStatus;
}

