UINT32 utilMath_Bcd2UINT32 (INT32 lNumber, void *pucBcd)//H30K_David_0038
{
    UINT32 ulIndex, ulSum;

    if(lNumber <=0)
    {
        return 0;
}

    if(pucBcd == NULL)
    {
        return 0;
    }

    ulSum = 0;
    for(ulIndex = 0; ulIndex < lNumber; ulIndex++)
    {
        ulSum *= 10;
        ulSum += *((UINT8*)pucBcd+ulIndex)-0x30;

    }

    return ulSum;
}

eEXEC_CODE palDataMgr_AccessADV_WarpControlSet(UINT8 ucAdvWarpControl)
{
    switch(ucAdvWarpControl)
    {
        case WARP_CTRL__ADVANCED:
			{
                palDataMgr_ResetCountSet(__FUNCTION__, 45);
				LOG_MSG(db_HAL_WARPING, "WarpControl Start Adv2\n");
                palGeo_AdvWarpingInit(palSystem_PanelID_Get());
				palDataMgr_WarppingControlAdvanceSet();		//G100_Doulas_0079 Modify
                palDataMgr_ResetCountSet(__FUNCTION__, 0);

                LOG_MSG(db_HAL_WARPING, "WarpControl End Adv2\n");
			}
			break;

		case WARP_CTRL__BASIC:
			{
			    LOG_MSG(db_HAL_WARPING, "WarpControl Start Basic\n");

				palGeo_AdvWarpControl(ucAdvWarpControl);
				//Warping
				palGeo_KeystonePinbarrel4CornerSet(&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzKeystone,
				                                   &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpHorzPincushion,
				                                   (UINT8 *)&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ui4CornerTopLeftHorz);

                if(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpAutoFilter == 0)
                {
                    palGeo_SetWarp_ManualFilter(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterH,
                                                m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterV);
                }
                else
                {
                    palGeo_SetWarp_AutoFilter(m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpAutoFilter,
                                             &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterH,
                                             &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucWarpFilterV);
                }

				//Blending
				{
                    palGeo_EgbParameterGammaSet(&m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingTopEnable,
                                                &m_sAppDataMgrInfo.sEepSettings.sUserSystemSetting.sWarpSetting.ucBlendingGamma);

                    palDataMgr_MenuOffsetUpdateForEdgeBlending();

    			    LOG_MSG(db_HAL_WARPING, "WarpControl End Basic\n");

                }
			}
			break;

        case WARP_CTRL__AP:
            if(CFG_GEO_BEHAVIORTYPE == eGEO_SUPPORT_VISUAL_SUITE ||
               CFG_GEO_BEHAVIORTYPE == eGEO_SUPPORT_CORE_BLEND_AP_AND_BASIC_WARP_NO_MEMORY)    //H2PF_Simon_0102
            {
                m_ucResetCount = 45;    //G100_Doulas_0091
                LOG_MSG(db_HAL_WARPING, "WarpControl Start AP\n");
                palGeo_AdvWarpControl(ucAdvWarpControl);
                palSystem_ApplyAPModeGeoFunc_Event();   //A35G2_Simon_0100

                LOG_MSG(db_HAL_WARPING, "WarpControl End AP\n");
                m_ucResetCount = 0;     //G100_Doulas_0091
            }
            break;

        default:
            LOG_MSG(db_HAL_WARPING, "unknown Warp Control %d\n", ucAdvWarpControl);
            break;
    }

    palGeo_FrameMemoryCheck();  //H2PF_Simon_0131

    return eEXEC_CODE_PASS;
}

//H30K_Tim_0011, add, ***
eEXEC_CODE palDataMgr_Access_OE_SN_1(eDATA_ACCESS_MODE eAccessMode, void *pValue)
{
    if (edaREAD == eAccessMode)  //Read Function
    {
        memcpy( (UINT8 *) pValue, m_sAppDataMgrInfo.sSystemValues.sVERSION.m_OESN1, VERSION_STRING_MAX_LENGTH);
    }
    else  //Write Function
    {
        if(edaWRITE_RAM_ONLY_NO_ACTION == eAccessMode)
        {
            memset(m_sAppDataMgrInfo.sSystemValues.sVERSION.m_OESN1, 0, VERSION_STRING_MAX_LENGTH);
            memcpy(m_sAppDataMgrInfo.sSystemValues.sVERSION.m_OESN1, (UINT8 *) pValue, VERSION_STRING_MAX_LENGTH - 1);
        }
    }

    return eEXEC_CODE_PASS;
}

